def _client_account() -> dict:
    return kv_get("client_account") or {}


def _client_perms_migrated(ca: dict) -> list:
    """Permissions van een klant-account, met een EENMALIGE merge van nieuw toegevoegde
    standaardrechten voor bestaande accounts (op verzoek: nieuwe defaults erven, ook als ze
    eerder niet bestonden). Daarna behoudt het bureau handmatige controle."""
    if not ca:
        return list(CLIENT_PERMS_DEFAULT)
    perms = ca.get("permissions")
    if perms is None:
        return list(CLIENT_PERMS_DEFAULT)
    if ca.get("pass_hash") and int(ca.get("perms_v", 0) or 0) < CLIENT_PERMS_VERSION:
        want = set(perms) | set(CLIENT_PERMS_DEFAULT)
        merged = [p for p in CLIENT_PAGES if p in want]
        ca["permissions"] = merged
        ca["perms_v"] = CLIENT_PERMS_VERSION
        kv_set("client_account", ca)
        return merged
    return perms


def _client_permissions() -> list:
    return _client_perms_migrated(_client_account())


def is_logged_in() -> bool:
    u = session.get("user", "")
    return (u in USERS) or (bool(u) and u == _client_account().get("username"))


def current_role() -> str:
    """'agency' = MHS Media (full access), 'client' = DAM Housing (restricted)."""
    u = session.get("user", "")
    if u in USERS:
        return "agency"
    if u and u == _client_account().get("username"):
        return "client"
    return "guest"


def require_login():
    if not is_logged_in():
        # D1: eerst één stille poging via de centrale MHS-sessie (alleen /admin-GETs,
        # max 1x/10 min via cookie) — teamleden zijn dan zonder klik ingelogd; klanten
        # en mislukte pogingen vallen gewoon door naar /inloggen.
        if (request.path.startswith("/admin") and request.method == "GET"
                and OAUTH_PROXY_SECRET and os.environ.get("OAUTH_REDIRECT_BASE")
                and request.cookies.get("ms_sso_try") != "1"):
            return redirect("/api/auth/team/silent?next=" + urllib.parse.quote(request.path))
        return redirect("/inloggen?next=" + urllib.parse.quote(request.path))
    return None


# ----- security: password hashing, brute-force throttle, rate-limit -----
def client_ip() -> str:
    xff = request.headers.get("X-Forwarded-For", "")
    return (xff.split(",")[0].strip() if xff else "") or request.remote_addr or "unknown"


def hash_password(pw: str) -> str:
    salt = secrets.token_bytes(16)
    dk = hashlib.pbkdf2_hmac("sha256", pw.encode(), salt, 200000)
    return salt.hex() + "$" + dk.hex()


def verify_password(pw: str, stored: str) -> bool:
    try:
        salt_hex, hash_hex = stored.split("$", 1)
        dk = hashlib.pbkdf2_hmac("sha256", pw.encode(), bytes.fromhex(salt_hex), 200000)
        return secrets.compare_digest(dk.hex(), hash_hex)
    except Exception:
        return False


ADMIN_PASS_HASH = os.environ.get("ADMIN_PASS_HASH", "")


def check_password(username: str, pw: str) -> bool:
    """Agency (USERS) resolves: KV hash -> env ADMIN_PASS_HASH -> plaintext.
    Client portal account resolves against its own stored hash."""
    if username in USERS:
        stored = kv_get("auth:pass_hash:" + username)
        if stored:
            return verify_password(pw, stored)
        if ADMIN_PASS_HASH:
            return verify_password(pw, ADMIN_PASS_HASH)
        # compare_digest("", "") is True — zonder deze guard geeft een LEEG
        # wachtwoord (ontbrekende env-var) alsnog toegang.
        wachtwoord = USERS.get(username) or ""
        if not wachtwoord:
            return False
        return secrets.compare_digest(pw, wachtwoord)
    ca = _client_account()
    if username and username == ca.get("username") and ca.get("pass_hash"):
        return verify_password(pw, ca["pass_hash"])
    return False


def _require_agency():
    a = _auth_or_401()
    if a:
        return a
    if current_role() != "agency":
        return jsonify({"error": "Alleen toegankelijk voor MHS Media (agency)"}), 403
    return None


def _require_perm(perm: str):
    """Agency mag alles; een client alleen als 'perm' in z'n toegekende rechten zit.
    Voor read-only endpoints die een klant mag zien mits het juiste recht aanstaat."""
    a = _auth_or_401()
    if a:
        return a
    role = current_role()
    if role == "agency":
        return None
    if role == "client" and perm in _client_permissions():
        return None
    return jsonify({"error": "Geen toegang tot dit onderdeel"}), 403


def _require_perm_any(*perms):
    """Als _require_perm, maar met meerdere geldige rechten. Nodig voor gedeelde bronnen:
    de media-picker wordt ook vanuit pagina's/blog/projecten gebruikt."""
    a = _auth_or_401()
    if a:
        return a
    role = current_role()
    if role == "agency":
        return None
    if role == "client" and any(p in _client_permissions() for p in perms):
        return None
    return jsonify({"error": "Geen toegang tot dit onderdeel"}), 403



LOGIN_MAX_FAILS = 6
LOGIN_WINDOW = 900  # 15 min lockout window


def login_blocked(ip: str) -> bool:
    rec = kv_get("login:fail:" + ip) or {}
    if not rec or (time.time() - rec.get("first", 0)) > LOGIN_WINDOW:
        return False
    return rec.get("count", 0) >= LOGIN_MAX_FAILS


def record_login_fail(ip: str) -> None:
    now = time.time()
    rec = kv_get("login:fail:" + ip) or {}
    if not rec or (now - rec.get("first", 0)) > LOGIN_WINDOW:
        rec = {"first": now, "count": 0}
    rec["count"] = rec.get("count", 0) + 1
    kv_set("login:fail:" + ip, rec)


def clear_login_fails(ip: str) -> None:
    kv_delete("login:fail:" + ip)


SUBMIT_MAX = 5
SUBMIT_WINDOW = 600  # max 5 submissions / 10 min per IP


def submit_rate_limited(ip: str) -> bool:
    rec = kv_get("submit:rate:" + ip) or {}
    if not rec or (time.time() - rec.get("first", 0)) > SUBMIT_WINDOW:
        return False
    return rec.get("count", 0) >= SUBMIT_MAX


def record_submit(ip: str) -> None:
    now = time.time()
    rec = kv_get("submit:rate:" + ip) or {}
    if not rec or (now - rec.get("first", 0)) > SUBMIT_WINDOW:
        rec = {"first": now, "count": 0}
    rec["count"] = rec.get("count", 0) + 1
    kv_set("submit:rate:" + ip, rec)


# ----- helpers for static-site browsing -----
# Pre-built indexes bundled with the function (Vercel excludes wp-content from the
# lambda for size; we read these JSONs instead of scanning the filesystem).
_INDEX_DIR = Path(__file__).resolve().parent / "data"


def _load_index(name: str, default):
    p = _INDEX_DIR / name
    if not p.exists(): return default
    try: return json.loads(p.read_text(encoding="utf-8"))
    except Exception: return default


def list_pages() -> list:
    d = _load_index("pages-index.json", [])
    # Kan {"pages":[...]}-vorm zijn (scaffold-export): itereren over de dict gaf dan de string
    # 'pages' terug en elke pagina-GET zonder KV-record een 500 (Wim 2026-07-20).
    if isinstance(d, dict):
        d = d.get("pages") or []
    return [p for p in d if isinstance(p, dict)]


def sitemap_tree() -> dict:
    # Statisch sitemap-tree.json is op productie leeg (read-only serverless fs). Val terug op
    # de KV-versie die door /api/sitemap/regenerate wordt opgebouwd; en als die er ook nog niet
    # is, bouw 'm live uit de pagina-index zodat de boom nooit zomaar leeg is.
    tree = _load_index("sitemap-tree.json", None)
    if tree and (tree.get("children")):
        return tree
    kv_tree = kv_get("sitemap:tree")
    if kv_tree and kv_tree.get("children"):
        return kv_tree
    return _build_sitemap_tree(_published_sitemap_pages())


def _published_sitemap_pages() -> list[dict]:
    return [p for p in _pages_index()
            if p.get("status", "published") == "published" and p.get("in_sitemap", True)]


def _build_sitemap_tree(pages: list[dict]) -> dict:
    """Nest een platte pagina-index tot een boom op basis van de slug-padsegmenten."""
    root = {"name": "/", "url": "/", "title": "Home", "children": {}}
    for p in pages:
        slug = (p.get("slug") or (p.get("url") or "").strip("/")).strip("/")
        title = p.get("title") or ""
        if not slug:
            if title:
                root["title"] = title
            continue
        node, path = root, ""
        segs = slug.split("/")
        for i, seg in enumerate(segs):
            path = f"{path}/{seg}"
            child = node["children"].get(seg)
            if child is None:
                child = {"name": seg, "url": path + "/", "title": None, "children": {}}
                node["children"][seg] = child
            node = child
            if i == len(segs) - 1:
                node["title"] = title or node.get("title")
    return root


def list_media(subdir="wp-content/uploads") -> list:
    # Het statische media-index.json is op productie leeg (serverless kan niet schrijven);
    # de echte mediabibliotheek leeft in KV (media:index). Val daarop terug zodat de
    # media-picker en AI-beeldcontext dezelfde 335 items zien als de admin-medialijst.
    items = _load_index("media-index.json", [])
    if items:
        return [m for m in items if not _is_placeholder_media(m)]
    return _media_index()


