def slugify(t): return re.sub(r"-+", "-", re.sub(r"\s+", "-", re.sub(r"[^a-z0-9\s-]", "", t.lower().strip()))).strip("-")


def cmd_add_page(args):
    parent = args.get("parent", "/").strip("/")
    name = args.get("name", "").strip()
    if not name: return {"ok": False, "error": "Naam ontbreekt"}
    slug = slugify(name)
    if not slug: return {"ok": False, "error": "Naam levert geen geldige URL slug op"}
    target = ROOT / (parent or "") / slug
    rel = target.relative_to(ROOT)
    if target.exists(): return {"ok": False, "error": f"Pagina /{rel}/ bestaat al"}
    # Serverless filesystem is read-only on Vercel — write to /tmp instead is not visible to next request
    # Store in KV as virtual page
    pages = kv_get("virtual_pages", {}) or {}
    url = f"/{rel}/"
    if url in pages: return {"ok": False, "error": "Pagina bestaat al"}
    pages[url] = {
        "title": name, "intro": args.get("intro") or f"Professioneel {name.lower()} door DAM Housing.",
        "body": args.get("body") or f"Wij verzorgen {name.lower()} op maat. Voor een vrijblijvende offerte neem contact met ons op.",
        "created": _now_iso(),
    }
    kv_set("virtual_pages", pages)
    return {"ok": True, "message": f"Pagina aangemaakt: {url}", "url": url}


def cmd_list_pages(_args):
    p = list_pages()
    vp = kv_get("virtual_pages", {}) or {}
    for url, meta in vp.items():
        p.append({"url": url, "slug": url.strip("/"), "title": meta.get("title", url),
                  "path": "virtual", "size_kb": 0, "modified": meta.get("created", "")})
    return {"ok": True, "data": p, "count": len(p)}


def cmd_delete_page(args):
    page = args.get("page", "").strip("/")
    if not page: return {"ok": False, "error": "Pagina-URL ontbreekt"}
    if page in {"", "contact", "diensten", "over-ons", "projecten"}:
        return {"ok": False, "error": "Hoofdpagina mag niet verwijderd worden"}
    # Try virtual pages first
    url = f"/{page}/"
    vp = kv_get("virtual_pages", {}) or {}
    if url in vp:
        del vp[url]
        kv_set("virtual_pages", vp)
        return {"ok": True, "message": f"Virtuele pagina {url} verwijderd"}
    return {"ok": False, "error": "Statische pagina's kunnen niet via runtime verwijderd worden — bewerk de repo en deploy opnieuw."}


def cmd_edit_text(args):
    return {"ok": False, "error": "Tekst-edits op statische pagina's vereisen een redeploy. Gebruik git/Vercel."}


COMMAND_HANDLERS = {
    "add_page": cmd_add_page, "list_pages": cmd_list_pages,
    "delete_page": cmd_delete_page, "edit_text": cmd_edit_text,
}


def parse_chat(message):
    low = message.lower().strip()
    m = re.search(r"voeg(?:\s+(?:een|de))?\s+pagina\s+(?:toe\s+)?(?:voor|over)\s+(.+?)(?:\s+(?:in|onder)\s+(/\S+))?$", low)
    if m: return {"command": "add_page", "args": {"name": m.group(1).strip(".!? "), "parent": m.group(2) or "/diensten/"}}
    if low.startswith(("maak een pagina", "nieuwe pagina")):
        m = re.search(r"voor\s+(.+)", low)
        if m: return {"command": "add_page", "args": {"name": m.group(1).strip(".!? "), "parent": "/diensten/"}}
    if re.search(r"(toon|laat|geef|alle|lijst)\s+.*(pagina|pages)", low):
        return {"command": "list_pages", "args": {}}
    m = re.search(r"verwijder\s+(?:de\s+)?pagina\s+(\S+)", low)
    if m: return {"command": "delete_page", "args": {"page": m.group(1)}}
    m = re.search(r"(?:wijzig|vervang|verander)\s+['\"]?(.+?)['\"]?\s+(?:naar|in|door)\s+['\"]?(.+?)['\"]?\s+op\s+(?:pagina\s+)?(\S+)", message, re.I)
    if m: return {"command": "edit_text", "args": {"find": m.group(1), "replace": m.group(2), "page": m.group(3)}}
    return {"command": None, "error": "Ik begreep dat commando niet."}


# ----- mailing -----
def _build_field_ctx(lead: dict) -> dict:
    """Build a flat context that can resolve every field shortcode.

    Naast de gestandaardiseerde leadvelden moeten ALLE velden uit het
    JetFormBuilder-offerteformulier hier in — anders blijft [all-fields] in de
    interne melding beperkt tot naam/mail/telefoon en mist de klant precies de
    gegevens waarop hij zijn offerte baseert (auto, service, trouwdatum, adres).
    """
    base = {k: lead.get(k, "") for k in (
        "name", "email", "telefoon", "bedrijfsnaam", "note"
    )}
    for k in OFFERTE_FIELDS:
        base[k] = lead.get(k, "") or ""
    # Datums leesbaar maken in de mail (2026-09-12 -> 12 september 2026).
    for _d in ("trouwdatum", "geboortedatum"):
        if base.get(_d):
            try:
                base[_d] = _nl_date(base[_d])
            except Exception:
                pass
    if base.get("huurvoorwaarden"):
        base["huurvoorwaarden"] = "Ja, akkoord"
    # Bedrijfsgegevens beschikbaar maken in mailsjablonen ([field id="bedrijf"] / [field id="bedrijf_telefoon"]).
    try:
        _co = (get_settings().get("company") or {})
    except Exception:
        _co = {}
    base["bedrijf"] = _co.get("name") or "DAM Housing"
    base["bedrijf_telefoon"] = _co.get("phone") or ""
    # Bouw volledige URL waar de offerte aanvraag vandaan komt
    source = lead.get("source") or "/"
    if source.startswith("http"):
        base["source_url"] = source
    else:
        if not source.startswith("/"): source = "/" + source
        # Niet hardcoden: de site draait inmiddels op het eigen domein, en dit
        # adres staat in élke interne melding ("Aangevraagd via").
        base["source_url"] = (_public_base() or "https://damhousing.nl") + source
    # Add aliases so [field id="field_574f21f"] resolves to ctx["email"]
    for alias, target in FIELD_ID_ALIASES.items():
        base[alias] = base.get(target, "")
    return base


def render_template_text(tpl, ctx, html: bool = False):
    """Render Elementor-style shortcodes + {placeholder} substitutions.

    Supported shortcodes:
      [field id="key"]   → ctx[key] (key may be alias or direct ctx key)
      [all-fields]       → label: value list of populated fields
                           (rendered as a clean HTML <table> if html=True)
    """
    out = tpl or ""
    # [field id="key"] / [field id='key']
    def _field_sub(m): return str(ctx.get(m.group(1), "") or "")
    out = re.sub(r'\[field\s+id=["\']?([^"\'\]\s]+)["\']?\s*\]', _field_sub, out)
    # [all-fields]
    if "[all-fields]" in out:
        _always = ("note",)
        rows = [(label, ctx.get(k, "") or "—") for k, label in FIELD_LABELS.items() if ctx.get(k, "") or k in _always]
        if html:
            block = (
                '<table cellpadding="6" cellspacing="0" border="0" style="border-collapse:collapse;font-family:Poppins,Arial,sans-serif;font-size:14px">'
                + "".join(
                    f'<tr><td style="padding:4px 12px 4px 0;color:#6b7280">{label}</td>'
                    f'<td style="padding:4px 0;color:#111827"><b>{v}</b></td></tr>'
                    for label, v in rows
                )
                + "</table>"
            )
        else:
            block = "\n".join(f"{label}: {v}" for label, v in rows)
        out = out.replace("[all-fields]", block)
    # Plain {placeholders} (backwards compat)
    for k, v in ctx.items():
        out = out.replace("{" + k + "}", str(v or ""))
    return out


_SIG_DEFAULTS = {"customer": False, "company": False, "invoice": True, "quote": True, "appointment": True, "review": True}


def _sig_on(key):
    """Of een bepaald mailtype de e-mailhandtekening krijgt (instelbaar via signature_flags)."""
    flags = get_settings().get("signature_flags") or {}
    return bool(flags.get(key, _SIG_DEFAULTS.get(key, True)))


# De mailbox die het bureau voor alle sites gebruikt. Stond tot 2026-08 als default
# in de code van elke repo (mét wachtwoord) en dus ook in de opslag van elke site.
# Vandaar deze lijst: een site die hierop staat ingesteld heeft geen eigen SMTP,
# maar een kopie van de centrale — en die hoort via de gateway te lopen.
CENTRALE_MAILBOXEN = {"email@mhsmedia.email", "emails@mhsmedia.email"}


def _smtp_klant_eigen(s) -> bool:
    """Heeft deze klant écht een eigen mailserver ingesteld?"""
    if not (s.get("host") and s.get("from_email") and s.get("password")):
        return False
    gebruiker = (s.get("user") or s.get("from_email") or "").strip().lower()
    return gebruiker not in CENTRALE_MAILBOXEN


def _mail_via_gateway(to_addr, subject, body, content_type, from_name, reply_to, cc, bcc, attachments):
    """Verstuurt via de centrale mailbox bij MAIHS. Geeft (ok, melding)."""
    basis = _gateway_origin()
    if not (basis and _gateway_key()):
        return False, "geen gateway geconfigureerd"
    lading = {"to": to_addr, "subject": subject,
              ("html" if content_type == "html" else "text"): body}
    for sleutel, waarde in (("from_name", from_name), ("reply_to", reply_to), ("cc", cc), ("bcc", bcc)):
        if waarde:
            lading[sleutel] = waarde
    if attachments:
        lading["attachments"] = [{"filename": a.get("filename") or "bijlage",
                                  "mime": a.get("mime") or "application/octet-stream",
                                  "data_b64": base64.b64encode(a["data"]).decode()}
                                 for a in attachments if a.get("data")]
    try:
        req = urllib.request.Request(
            basis + "/api/gateway/mail", data=json.dumps(lading).encode(), method="POST",
            headers={"Authorization": "Bearer " + _gateway_key(),
                     "Content-Type": "application/json",
                     "User-Agent": "MAIHS-Gateway-Client/1.0"})
        with urllib.request.urlopen(req, timeout=20) as r:
            r.read()
        return True, "Verzonden via de centrale mailbox"
    except urllib.error.HTTPError as e:
        try:
            reden = e.read().decode("utf-8", "replace")[:200]
        except Exception:
            reden = ""
        return False, f"gateway {e.code} {reden}".strip()
    except Exception as e:
        return False, f"gateway onbereikbaar: {e}"


# ---------------------------------------------------------------------------
# Briefpapier voor de mail
# ---------------------------------------------------------------------------
# De mails gingen als kale HTML-fragmenten de deur uit: zwarte tekst op wit, geen
# logo, geen afzender. Deze schil zet er hetzelfde jasje omheen als het offertevel.
# Mailclients zijn geen browsers: TABELLEN in plaats van flex/grid, alles inline,
# géén externe stylesheet en geen webp (Outlook toont die niet).
_MAIL_SHELL_MARKER = "data-vz-mailshell"


def _mail_logo_url(co: dict, basis: str) -> str:
    """Absolute URL naar de witte wordmark als PNG — een mail heeft geen site-root
    om relatieve paden op te lossen, en webp valt in Outlook weg."""
    url = (co.get("logo_url") or "/dam-logo-whitered.png").strip()
    url = re.sub(r"\.webp$", ".png", url)
    if "-white." not in url:
        url = re.sub(r"(\.[a-z]+)$", r"-white\1", url)
    return url if url.startswith("http") else basis.rstrip("/") + url


def _mail_shell(body_html: str, *, voorkop: str = "") -> str:
    """Zet een mailtekst in het DAM Housing-jasje. `voorkop` is de regel die veel
    clients naast het onderwerp tonen; laat je 'm leeg, dan pakken ze de eerste
    woorden van de body."""
    co = _company()
    basis = (_public_base() or CANONICAL_BASE).rstrip("/")
    logo = _mail_logo_url(co, basis)
    font = "Poppins,'Helvetica Neue',Helvetica,Arial,sans-serif"

    voet = []
    for regel in str(co.get("address", "")).splitlines():
        if regel.strip():
            voet.append(_esc(regel.strip()))
    contact = []
    if co.get("phone"):
        contact.append(f'<a href="tel:{_esc(str(co["phone"]).replace(" ", ""))}" style="color:#7b828c;text-decoration:none">{_esc(co["phone"])}</a>')
    if co.get("email"):
        contact.append(f'<a href="mailto:{_esc(co["email"])}" style="color:#7b828c;text-decoration:none">{_esc(co["email"])}</a>')
    contact.append(f'<a href="{basis}/" style="color:#f07d22;text-decoration:none">{_esc(basis.split("//")[-1])}</a>')

    pre = (f'<div style="display:none;max-height:0;overflow:hidden;opacity:0">{_esc(voorkop)}</div>'
           if voorkop else "")
    return (
        f'<!DOCTYPE html><html lang="nl" {_MAIL_SHELL_MARKER}><head><meta charset="utf-8">'
        '<meta name="viewport" content="width=device-width,initial-scale=1">'
        '<meta name="color-scheme" content="light only">'
        '</head>'
        '<body style="margin:0;padding:0;background:#f1f3f6;-webkit-font-smoothing:antialiased">'
        f'{pre}'
        '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" '
        'style="background:#f1f3f6"><tr><td align="center" style="padding:26px 12px">'
        '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" '
        'style="width:600px;max-width:100%;background:#ffffff;border-radius:12px;overflow:hidden;'
        'box-shadow:0 2px 10px rgba(15,23,42,.06)">'
        f'<tr><td style="background:#1e1b18;padding:22px 28px">'
        f'<img src="{_esc(logo)}" alt="{_esc(co.get("name", "DAM Housing"))}" width="150" '
        'style="display:block;border:0;width:150px;max-width:60%;height:auto"></td></tr>'
        '<tr><td style="height:4px;line-height:4px;font-size:0;background:#f07d22">&nbsp;</td></tr>'
        f'<tr><td style="padding:30px 28px 26px;font-family:{font};font-size:15px;line-height:1.65;'
        f'color:#1f1b18">{body_html}</td></tr>'
        f'<tr><td style="padding:18px 28px 22px;background:#faf7f4;border-top:1px solid #efe7e0;'
        f'font-family:{font};font-size:12px;line-height:1.6;color:#7b828c">'
        f'<strong style="color:#1f1b18">{_esc(co.get("name", "DAM Housing"))}</strong><br>'
        f'{"<br>".join(voet)}{"<br>" if voet else ""}'
        f'{" &middot; ".join(contact)}</td></tr>'
        '</table></td></tr></table></body></html>')


def _in_mail_jasje(body: str) -> str:
    """Wikkelt een HTML-mailtekst in de schil, tenzij het al een compleet
    document is (de rapport-mails bouwen hun eigen pagina)."""
    kop = (body or "").lstrip()[:200].lower()
    if "<!doctype" in kop or "<html" in kop:
        return body
    return _mail_shell(body)


def send_email(to_addr, subject, body, bcc=None, cc=None, reply_to=None, content_type="plain", from_name=None, attachments=None, signature=False):
    s = get_settings()["smtp"]
    if not to_addr:
        return False, "SMTP niet geconfigureerd"
    # Optioneel de ingestelde e-mailhandtekening (HTML) onder de body plakken (klant-mails).
    if signature:
        sig = (get_settings().get("email_signature") or "").strip()
        if sig:
            if content_type != "html":
                body = (body or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\n", "<br>")
                content_type = "html"
            body = body + "<br><br>" + sig
    # Eén jasje om élke HTML-mail: bevestiging, interne melding, offerte, review
    # én de voorbeeldmail uit de admin lopen allemaal hierlangs.
    if content_type == "html":
        body = _in_mail_jasje(body)
    # Zonder eigen mailserver loopt het via de centrale mailbox bij MAIHS. Lukt dat
    # niet, dan alsnog lokaal: een aanvraag mag niet verdwijnen omdat een centrale
    # dienst even weg is. Bij een time-out ná verzending kan dat een dubbele mail
    # geven — dat is het minste kwaad tegenover een verloren lead.
    if not _smtp_klant_eigen(s):
        ok, melding = _mail_via_gateway(to_addr, subject, body, content_type,
                                        from_name or s.get("from_name"), reply_to, cc, bcc, attachments)
        if ok:
            return True, melding
        print(f"[mail] gateway mislukt ({melding}) — terugval op lokale SMTP")
        if not (s.get("host") and s.get("from_email")):
            return False, "SMTP niet geconfigureerd"
    try:
        sub = "html" if content_type == "html" else "plain"
        if attachments:
            msg = MIMEMultipart("mixed")
            _alt = MIMEMultipart("alternative"); _alt.attach(MIMEText(body, sub, "utf-8")); msg.attach(_alt)
            for att in attachments:
                try:
                    _mt = (att.get("mime") or "application/octet-stream").split("/", 1)
                    part = MIMEBase(_mt[0], _mt[1] if len(_mt) > 1 else "octet-stream")
                    part.set_payload(att["data"]); _email_encoders.encode_base64(part)
                    part.add_header("Content-Disposition", "attachment", filename=(att.get("filename") or "bijlage"))
                    msg.attach(part)
                except Exception:
                    pass
        else:
            msg = MIMEMultipart("alternative"); msg.attach(MIMEText(body, sub, "utf-8"))
        msg["Subject"] = subject
        msg["From"] = f'{from_name or s.get("from_name") or "DAM Housing"} <{s["from_email"].strip()}>'
        msg["To"] = to_addr
        cc_list = [x.strip() for x in re.split(r"[,;]+", cc) if x.strip()] if cc else []
        if cc_list:
            msg["Cc"] = ", ".join(cc_list)
        if reply_to:
            msg["Reply-To"] = reply_to
        # Build envelope recipients (To + Cc zichtbaar, Bcc alleen in envelope)
        recipients = [to_addr] + cc_list
        if bcc:
            for b in [x.strip() for x in re.split(r"[,;]+", bcc) if x.strip()]:
                recipients.append(b)
        port = int(s.get("port", 587))
        if port == 465:
            with smtplib.SMTP_SSL(s["host"], port, context=ssl.create_default_context(), timeout=10) as srv:
                if s.get("user"): srv.login(s["user"], s.get("password", ""))
                srv.sendmail(s["from_email"].strip(), recipients, msg.as_string())
        else:
            with smtplib.SMTP(s["host"], port, timeout=10) as srv:
                srv.ehlo()
                if s.get("use_tls", True):
                    srv.starttls(context=ssl.create_default_context()); srv.ehlo()
                if s.get("user"): srv.login(s["user"], s.get("password", ""))
                srv.sendmail(s["from_email"].strip(), recipients, msg.as_string())
        return True, "Verzonden via de eigen mailserver"
    except Exception as e:
        return False, f"SMTP fout: {e}"


def _fetch_attachment(url, name=None, max_bytes=12 * 1024 * 1024):
    """Download een bestand (bv. van Vercel Blob) om als échte mail-bijlage mee te sturen.
    Geeft {filename, data, mime} of None bij fout/te-groot."""
    if not url:
        return None
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "damhousing-mailer/1.0"})
        with urllib.request.urlopen(req, timeout=15) as r:
            clen = r.headers.get("Content-Length")
            if clen and int(clen) > max_bytes:
                return None
            raw = r.read(max_bytes + 1)
            if len(raw) > max_bytes:
                return None
            mime = (r.headers.get("Content-Type") or "").split(";")[0].strip() or "application/octet-stream"
        fname = name or (url.rstrip("/").split("/")[-1].split("?")[0] or "bijlage")
        return {"filename": fname, "data": raw, "mime": mime}
    except Exception as e:
        print(f"attachment fetch error: {e}")
        return None


def process_lead_emails(lead, attachment=None):
    settings = get_settings()
    ctx = _build_field_ctx(lead)
    is_html = lambda t: (t.get("content_type") == "html")
    # ----- Mail 1: company -----
    company_to = (settings.get("company_email") or "").strip()
    if company_to:
        tpl = settings["template_company"]
        c_subj = render_template_text(tpl["subject"], ctx)
        c_body = render_template_text(tpl["body"], ctx, html=is_html(tpl))
        c_reply = render_template_text(settings.get("company_reply_to", ""), ctx) or None
        if attachment:
            _att_note = ('<p style="margin-top:16px;padding-top:12px;border-top:1px solid #e5e7eb;font-family:Poppins,Arial,sans-serif">'
                         '\U0001F4CE <b>De foto/video van de klant zit als bijlage bij deze mail</b> ('
                         + html_escape(lead.get("attachment_name") or attachment.get("filename") or "bestand") + ').')
            if lead.get("attachment_url"):
                _att_note += (' <a href="' + lead["attachment_url"] + '" style="color:#f07d22">Online bekijken</a>')
            c_body += _att_note + '</p>'
        elif lead.get("attachment_url"):
            c_body += ('<p style="margin-top:16px;padding-top:12px;border-top:1px solid #e5e7eb;font-family:Poppins,Arial,sans-serif">'
                       '\U0001F4CE <b>Foto/video van de klant:</b> '
                       '<a href="' + lead["attachment_url"] + '" style="color:#f07d22">' + html_escape(lead.get("attachment_name") or "Bekijk bestand") + '</a></p>')
        elif lead.get("attachment_note"):
            c_body += '<p style="margin-top:16px;color:#b45309;font-family:Poppins,Arial,sans-serif">\U0001F4CE ' + html_escape(lead["attachment_note"]) + '</p>'
        ok, msg = send_email(
            to_addr=company_to, subject=c_subj, body=c_body,
            bcc=settings.get("company_bcc"),
            reply_to=c_reply,
            content_type="html" if is_html(tpl) else "plain",
            from_name=((lead.get("name") or "Nieuwe aanvraag") + " \u00b7 formulier"),
            attachments=([attachment] if attachment else None),
            signature=_sig_on("company"),
        )
        lead.setdefault("emails", []).append({
            "to": "company", "address": company_to, "subject": c_subj, "body": c_body, "reply_to": c_reply,
            "ok": ok, "msg": msg, "ts": _now_iso()
        })
    # ----- Mail 2: customer -----
    raw_to = settings.get("customer_to") or "[field id=\"email\"]"
    customer_to = render_template_text(raw_to, ctx).strip()
    if customer_to and "@" in customer_to:
        tpl = settings["template_customer"]
        u_subj = render_template_text(tpl["subject"], ctx)
        u_body = render_template_text(tpl["body"], ctx, html=is_html(tpl))
        ok, msg = send_email(
            to_addr=customer_to, subject=u_subj, body=u_body,
            bcc=settings.get("customer_bcc"),
            reply_to=render_template_text(settings.get("customer_reply_to", ""), ctx) or None,
            content_type="html" if is_html(tpl) else "plain",
            signature=_sig_on("customer"),
        )
        lead.setdefault("emails", []).append({
            "to": "customer", "address": customer_to, "subject": u_subj, "body": u_body,
            "ok": ok, "msg": msg, "ts": _now_iso()
        })


