@app.route("/inloggen", methods=["GET", "POST"])
def login():
    error = None
    _sso = request.args.get("sso", "")
    if _sso == "denied":
        error = "Dit Google-account is geen geverifieerd @mhsmedia.nl-teamaccount."
    elif _sso == "notconfigured":
        error = "Google-login is nog niet geconfigureerd voor deze site."
    elif _sso == "err":
        error = "Google-login mislukte — probeer opnieuw of log in met je wachtwoord."
    if request.method == "POST":
        ip = client_ip()
        if login_blocked(ip):
            error = "Te veel mislukte pogingen. Probeer over 15 minuten opnieuw."
            return render_template_string(LOGIN_HTML, error=error)
        u = request.form.get("username", "").strip()
        p = request.form.get("password", "")
        # B4: team-wachtwoordlogin kan uitgezet zijn (Google-SSO/passkey verplicht);
        # klant-accounts vallen hier bewust buiten en passkeys lopen niet via dit formulier.
        if u in USERS and kv_get("security:pw_login_disabled") and not os.environ.get("ALLOW_PASSWORD_LOGIN"):
            error = "Wachtwoord-login voor teamleden is uitgeschakeld — log in met Google (MHS) of een passkey."
            return render_template_string(LOGIN_HTML, error=error)
        known = (u in USERS) or (bool(u) and u == _client_account().get("username"))
        if known and check_password(u, p):
            clear_login_fails(ip)
            session.clear()   # nieuwe sessie bij login (anti-fixation)
            session["user"] = u
            return redirect(request.args.get("next") or "/admin/")
        record_login_fail(ip)
        error = "Onjuiste inloggegevens"
    return render_template_string(LOGIN_HTML, error=error)


@app.route("/uitloggen")
def logout():
    session.clear()
    return redirect("/inloggen")


@app.route("/api/me")
def api_me():
    """Public: lets the live site show a 'Beheer' button only to logged-in admins.
    Also returns the role so the admin SPA can hide agency-only tools for clients."""
    role = current_role()
    perms = _client_permissions() if role == "client" else None
    # Teamlid dat via Google inlogde: toon zijn eigen naam + profielfoto linksonder in
    # de admin i.p.v. "admin". Niet tijdens klantweergave (impersonatie) — daar hoort
    # het klantaccount te staan, niet de naam van het teamlid dat meekijkt.
    sso = role == "agency" and not session.get("impersonator") and bool(session.get("sso_email"))
    resp = jsonify({"authed": is_logged_in(), "role": role, "user": session.get("user", ""),
                    "permissions": perms, "cms_locked": bool(kv_get("cms:lock", False)),
                    "impersonating": bool(session.get("impersonator")),
                    "name": _sso_weergavenaam() if sso else "",
                    "email": session.get("sso_email", "") if sso else "",
                    "avatar": session.get("sso_picture", "") if sso else "",
                    # Twee bronnen: de live Google-foto en de centraal gehoste teamfoto.
                    # De admin probeert ze op volgorde en valt daarna terug op de initiaal.
                    "avatar_fallback": _centrale_foto_url(session.get("sso_email")) if sso else "",
                    "avatar_reden": session.get("sso_foto_reden", "") if sso else ""})
    resp.headers["Cache-Control"] = "no-store"
    return resp


@app.route("/api/admin/login-as-client", methods=["POST"])
def api_login_as_client():
    """Agency bekijkt de admin als de klant (met diens beperkte rechten). De originele
    agency-gebruiker wordt onthouden zodat je met één klik terugschakelt."""
    g = _require_agency()
    if g:
        return g
    ca = _client_account()
    if not ca.get("username") or not ca.get("pass_hash"):
        return jsonify({"ok": False, "error": "Er is nog geen klant-account ingesteld."}), 400
    session["impersonator"] = session.get("user", "")
    session["user"] = ca["username"]
    audit_log("client.impersonate.start", ca["username"], f"door {session['impersonator']}")
    return jsonify({"ok": True, "redirect": "/admin/"})


@app.route("/api/stop-impersonation", methods=["POST"])
def api_stop_impersonation():
    """Schakel terug van klant-weergave naar de oorspronkelijke agency-gebruiker."""
    orig = session.get("impersonator")
    if not orig:
        return jsonify({"ok": False, "error": "Niet als klant aan het kijken."}), 400
    audit_log("client.impersonate.stop", session.get("user", ""), f"terug naar {orig}")
    session["user"] = orig
    session.pop("impersonator", None)
    return jsonify({"ok": True, "redirect": "/admin/"})


@app.route("/api/cms-lock", methods=["POST"])
def api_cms_lock():
    """Vergrendel de admin in CMS-only modus. Vergrendelen mag iedereen die is ingelogd;
    ontgrendelen vereist het admin-wachtwoord (zodat een content-editor niet terug naar de CRM kan)."""
    if not is_logged_in():
        return jsonify({"error": "auth"}), 401
    b = request.get_json(silent=True) or {}
    want_lock = bool(b.get("locked"))
    if want_lock:
        kv_set("cms:lock", True)
        audit_log("cms.lock", "", "CMS vergrendeld (alleen-CMS)")
        return jsonify({"locked": True})
    # ontgrendelen -> wachtwoord vereist
    pw = (b.get("password") or "")
    user = session.get("user", "admin")
    if not check_password(user, pw):
        return jsonify({"error": "wachtwoord onjuist"}), 403
    kv_set("cms:lock", False)
    audit_log("cms.unlock", "", "CMS ontgrendeld")
    return jsonify({"locked": False})


@app.route("/api/admin/client-account", methods=["GET", "POST"])
def api_client_account():
    """Agency manages the client portal login (DAM Housing self-service)."""
    g = _require_agency()
    if g:
        return g
    ca = _client_account()
    if request.method == "GET":
        return jsonify({"username": ca.get("username", ""), "is_set": bool(ca.get("pass_hash")),
                        "permissions": _client_perms_migrated(ca),
                        "all_pages": CLIENT_PAGES, "labels": CLIENT_PAGE_LABELS,
                        "defaults": CLIENT_PERMS_DEFAULT})
    d = request.get_json(silent=True) or {}
    username = (d.get("username") or "").strip()
    password = (d.get("password") or "").strip()
    if not username or username in USERS:
        return jsonify({"ok": False, "error": "Ongeldige gebruikersnaam"}), 400
    perms = d.get("permissions")
    if not isinstance(perms, list):
        perms = ca.get("permissions", CLIENT_PERMS_DEFAULT)
    perms = [p for p in perms if p in CLIENT_PAGES]
    rec = {"username": username, "pass_hash": ca.get("pass_hash", ""), "permissions": perms}
    if password:
        if len(password) < 6:
            return jsonify({"ok": False, "error": "Wachtwoord minimaal 6 tekens"}), 400
        rec["pass_hash"] = hash_password(password)
    if not rec["pass_hash"]:
        return jsonify({"ok": False, "error": "Stel een wachtwoord in"}), 400
    kv_set("client_account", rec)
    audit_log("client_account_set", username, "")
    return jsonify({"ok": True, "username": username, "permissions": perms})


# ---------- Klant-uitnodiging: eenmalige link om zelf het account te activeren ----------
# Ryan 2026-07-16: het bureau stuurt geen wachtwoorden meer door; de klant krijgt een
# single-use link (72u geldig) en kiest ZELF een wachtwoord dat aan de eisen voldoet.
INVITE_TTL_HOURS = 72
_PW_MIN_LEN = 8


def _pw_requirements_ok(pw: str, username: str = "") -> str:
    """Lege string = akkoord; anders de reden waarom het wachtwoord niet voldoet."""
    pw = pw or ""
    if len(pw) < _PW_MIN_LEN:
        return f"minimaal {_PW_MIN_LEN} tekens"
    if not re.search(r"[A-Za-z]", pw):
        return "minimaal \u00e9\u00e9n letter"
    if not re.search(r"\d", pw):
        return "minimaal \u00e9\u00e9n cijfer"
    if username and len(username) >= 3 and username.lower() in pw.lower():
        return "mag je gebruikersnaam niet bevatten"
    return ""


@app.route("/api/admin/client-invite", methods=["GET", "POST", "DELETE"])
@app.route("/api/admin/client-invite/", methods=["GET", "POST", "DELETE"])
def api_client_invite():
    g = _require_agency()
    if g:
        return g
    inv = kv_get("client_invite") or {}
    if request.method == "GET":
        active = bool(inv.get("token_hash")) and not inv.get("used") and (inv.get("expires") or "") > _now_iso()
        return jsonify({"active": active, "created": inv.get("created", ""), "expires": inv.get("expires", ""),
                        "used": bool(inv.get("used")), "mailed_to": inv.get("mailed_to", ""),
                        "suggest_email": (get_settings().get("company_email") or "")})
    if request.method == "DELETE":
        kv_delete("client_invite")
        audit_log("client.invite.revoke", "client", "")
        return jsonify({"ok": True})
    body = request.get_json(silent=True) or {}
    token = secrets.token_urlsafe(32)
    expires = (datetime.now() + timedelta(hours=INVITE_TTL_HOURS)).strftime("%Y-%m-%dT%H:%M:%S")
    # Alleen de HASH opslaan: de link zelf is het geheim (lek-veilig, net als wachtwoorden).
    inv = {"token_hash": hash_password(token), "created": _now_iso(), "expires": expires, "used": False}
    url = request.host_url.rstrip("/") + "/klant-account/?t=" + token
    mail_to = (body.get("email") or "").strip()
    if mail_to:
        try:
            send_email(mail_to, "Jouw inlog voor het websitebeheer",
                       "Beste,\n\nVia deze eenmalige link maak je je eigen inlog aan voor het beheer van de website:\n"
                       + url + f"\n\nDe link is {INVITE_TTL_HOURS} uur geldig en werkt precies \u00e9\u00e9n keer. "
                       "Je kiest zelf je gebruikersnaam en wachtwoord.\n\nMet vriendelijke groet,\nMHS Media")
            inv["mailed_to"] = mail_to
        except Exception as e:
            audit_log("client.invite.mail_fail", mail_to, str(e)[:120])
    kv_set("client_invite", inv)
    audit_log("client.invite.create", "client", f"geldig tot {expires}")
    return jsonify({"ok": True, "url": url, "expires": expires, "mailed": bool(inv.get("mailed_to"))})


