def _deent(s):
    """K4: HTML-entities in data-titels (&amp; e.d., WP-migratie-restant) naar leesbare tekst."""
    try:
        from html import unescape
        return unescape(s) if isinstance(s, str) and "&" in s else s
    except Exception:
        return s


