@app.route("/api/leads/<lead_id>/appointment", methods=["POST"])
def api_lead_appointment(lead_id):
    """Plan een afspraak: bewaar meeting + maak Google Calendar-event (met uitnodiging) + stuur custom HTML-mail."""
    # Muteren hoort bij de pipeline: stage wijzigen, toewijzen, notities, mailen,
    # afspraken en verwijderen gebeuren allemaal vanuit de leadkaart daar.
    g = _require_perm("pipeline")
    if g:
        return g
    leads, idx = _find_lead(lead_id)
    if idx == -1: return jsonify({"ok": False, "error": "Niet gevonden"}), 404
    lead = leads[idx]
    d = request.get_json(silent=True) or {}
    date = (d.get("date") or "").strip()
    tm = (d.get("time") or "").strip()
    if not date: return jsonify({"ok": False, "error": "Datum is verplicht"}), 400
    title = (d.get("title") or "Afspraak").strip()
    location = (d.get("location") or "").strip()
    to = (d.get("email") or lead.get("email") or "").strip()
    html = d.get("html") or ""
    duration = int(d.get("duration") or 60)
    now = _now_iso()
    mtg = {"id": uuid.uuid4().hex[:8], "date": date, "time": tm, "title": title,
           "location": location, "email": to, "notes": d.get("notes", ""), "created": now}

    cal_ok, cal_err = False, ""
    tok = google_access_token("calendar")
    if tok and tm:
        try:
            sdt = datetime.strptime(f"{date} {tm}", "%Y-%m-%d %H:%M")
            edt = sdt + timedelta(minutes=duration)
            ev = {"summary": title, "location": location, "description": d.get("notes", ""),
                  "start": {"dateTime": sdt.strftime("%Y-%m-%dT%H:%M:%S"), "timeZone": "Europe/Amsterdam"},
                  "end": {"dateTime": edt.strftime("%Y-%m-%dT%H:%M:%S"), "timeZone": "Europe/Amsterdam"}}
            if to:
                ev["attendees"] = [{"email": to}]
            req = urllib.request.Request(
                "https://www.googleapis.com/calendar/v3/calendars/primary/events?sendUpdates=all",
                data=json.dumps(ev).encode(),
                headers={"Authorization": "Bearer " + tok, "Content-Type": "application/json"}, method="POST")
            with urllib.request.urlopen(req, timeout=15) as r:
                res = json.loads(r.read() or b"{}")
            mtg["calendar_link"] = res.get("htmlLink", "")
            cal_ok = True
        except Exception as e:
            cal_err = str(e)

    mail_ok, mail_err = False, ""
    if to and html:
        try:
            subj = d.get("subject") or f"Bevestiging afspraak — {title}"
            mail_ok, mail_err = send_email(to, subj, html, content_type="html", signature=_sig_on("appointment"))
            lead.setdefault("emails", []).append({"ts": now, "to": to, "subject": subj, "body": html,
                                                  "ok": mail_ok, "direction": "out"})
        except Exception as e:
            mail_err = str(e)

    leads[idx].setdefault("meetings", []).append(mtg)
    leads[idx]["meetings"].sort(key=lambda x: (x.get("date", ""), x.get("time", "")))
    note = f"Afspraak ingepland: {title} ({date} {tm})".strip()
    if cal_ok: note += " · agenda-uitnodiging verstuurd"
    if mail_ok: note += " · bevestigingsmail verstuurd"
    leads[idx].setdefault("history", []).append({"ts": now, "stage": lead.get("stage"),
        "by": session.get("user", "admin"), "note": note})
    save_leads(leads)
    return jsonify({"ok": True, "lead": leads[idx], "calendar": cal_ok, "mail": mail_ok,
                    "warnings": [x for x in [cal_err, mail_err] if x]})


