@app.route("/api/settings", methods=["GET", "PUT"])
def api_settings():
    if require_login(): return jsonify({"error": "auth"}), 401
    if request.method == "GET":
        s = get_settings()
        if s.get("smtp", {}).get("password"): s["smtp"]["password"] = "••••••••"
        # Een klant zonder het 'settings'-recht komt niet bij deze schermen; stuur de
        # geheimen die daar horen dan ook niet mee. Anders leest hij de Anthropic-key
        # gewoon uit deze respons.
        if current_role() == "client" and "settings" not in _client_permissions():
            for k in SETTINGS_SECRET_KEYS:
                s.pop(k, None)
        s = _friendly_field_ids(s)  # toon [field id="email"] i.p.v. ruwe Elementor-id's
        return jsonify(s)
    patch = request.get_json(silent=True) or {}
    if current_role() == "client":
        perms = _client_permissions()
        # Klanten mogen SMTP alleen wijzigen met het 'smtp'-recht (anders door het bureau beheerd).
        if "smtp" in patch and "smtp" not in perms:
            patch.pop("smtp", None)
        # Idem voor de profielkeuze: de picker in de admin verbergt z'n knop al zonder
        # 'gbp_select', maar die keuze wordt hier weggeschreven — zonder deze regel is het
        # recht alleen een verstopte knop en niet echt afgeschermd.
        if "google_business" in patch and "gbp_select" not in perms:
            patch.pop("google_business", None)
        # Zonder 'settings' komt de klant niet bij die schermen. Alleen sleutels
        # weghalen die het bureau beheert is te ruim: alles wat niet in dat lijstje
        # staat (zoals de mailteksten) glipt er dan alsnog door. Daarom andersom —
        # een toelatingslijst van wat hij met zijn eigen rechten mag schrijven.
        if "settings" not in perms:
            for k in SETTINGS_ADMIN_ONLY_KEYS:
                patch.pop(k, None)
        # De mailteksten hangen aan hun eigen recht: zonder 'mails' (of het bredere
        # 'settings') schrijft een klant ze niet, ook niet rechtstreeks op de API.
        if "mails" not in perms and "settings" not in perms:
            for k in SETTINGS_MAIL_KEYS:
                patch.pop(k, None)
        if "voorwaarden" not in perms and "settings" not in perms:
            for k in SETTINGS_TERMS_KEYS:
                patch.pop(k, None)
        if "handtekening" not in perms and "settings" not in perms:
            for k in SETTINGS_SIGNATURE_KEYS:
                patch.pop(k, None)
        if "actiebalk" not in perms and "settings" not in perms:
            for k in SETTINGS_ACTIEBALK_KEYS:
                patch.pop(k, None)
    existing = kv_get("settings", {}) or {}
    # De versie van de voorwaarden is geen veld dat iemand invult maar een afdruk
    # van de tekst zelf: zo kan een acceptatie later aan een exacte tekst worden
    # gekoppeld, ook als Rick 'm daarna nog aanpast.
    if isinstance(patch.get("terms"), dict) and "body" in patch["terms"]:
        patch["terms"]["version"] = _terms_version(patch["terms"].get("body") or "")
        patch["terms"].setdefault("updated", datetime.now().strftime("%Y-%m-%d"))
    for k, v in patch.items():
        if isinstance(v, dict):
            existing.setdefault(k, {}).update({kk: vv for kk, vv in v.items() if vv != "••••••••"})
        else:
            existing[k] = v
    kv_set("settings", existing)
    # Eigen SMTP aan- of uitzetten verandert wat we over onszelf melden.
    if "smtp" in patch:
        _meld_koppelingen_direct()
    return jsonify({"ok": True})


def _parse_bedrag(v) -> float:
    """Accepteer '649', '649.50', '€ 649,50' en '' -> float. Nederlandse komma telt als decimaal."""
    if v in (None, ""):
        return 0.0
    if isinstance(v, (int, float)):
        return round(float(v), 2)
    s = str(v).replace("€", "").replace(" ", "").replace(" ", "").strip()
    if "," in s and "." in s:          # 1.234,50 -> duizendscheiding + decimale komma
        s = s.replace(".", "").replace(",", ".")
    elif "," in s:                      # 649,50
        s = s.replace(",", ".")
    try:
        return round(float(s), 2)
    except (TypeError, ValueError):
        return 0.0


# ---------------------------------------------------------------------------
# TARIEVEN (voeden de AUTOMATISCHE concept-offerte bij elke aanvraag)
#
# De publieke aanvraag-endpoint (api/vz/lead.js, Node) leest exact deze waarden uit
# de kv-sleutel "tarieven" en rekent daarmee de richtprijs uit die de bezoeker
# meteen ziet. Staat er niets, dan valt die terug op de waarden in de code.
# De klant mag dit zien/aanpassen zodra het recht "tarieven" aanstaat.
# ---------------------------------------------------------------------------
TARIEVEN_DEFAULT = {
    "btw_tarief": 21,
    "prijzen_incl_btw": True,
    "vloeren": {
        # De sleutels zijn EXACT de opties uit het offerteformulier (zie
        # api/vz/_tarieven.js); wijkt er één af, dan valt de richtprijs voor die
        # dienst stil weg.
        "Pvc-vloeren":        {"label": "Pvc-vloer leveren en leggen", "per_m2": 55},
        "Vloeren egaliseren": {"label": "Vloer egaliseren",            "per_m2": 22},
        "Vloerverwarming":    {"label": "Vloerverwarming infrezen",    "per_m2": 48},
    },
    "trap": {"label": "Trappenrenovatie", "per_trede": 95, "standaard_treden": 13},
    "extra": {
        "egaliseren":      {"label": "Ondervloer egaliseren",          "per_m2": 22},
        "vloerverwarming": {"label": "Vloerverwarming infrezen",       "per_m2": 48},
        # Plinten gaan per STREKKENDE meter: de omtrek van een kamer loopt niet
        # gelijk met de vloeroppervlakte, dus de m2 overnemen klopt nooit.
        "plinten":         {"label": "Plinten leveren en plaatsen",    "per_m1": 6},
    },
    # Toeslag per m2 bovenop het pvc-tarief: visgraat is meer legwerk dan wildverband.
    # Alles start op 0 zodat er geen bedrag in staat dat niemand heeft gekozen; wat
    # de klant hier invult komt als aparte regel op de offerte.
    "patronen": {
        "Visgraat":                  {"toeslag_m2": 0},
        "Wildverband":               {"toeslag_m2": 0},
        "Hongaarse punt":            {"toeslag_m2": 0},
        "Weense punt":               {"toeslag_m2": 0},
        "Visgraat met band en bies": {"toeslag_m2": 0},
    },
    # Toeslag per m2 op wat er nu ligt. Bij bestaande bouw bepaalt de ondergrond
    # hoeveel voorbereiding eronder zit: over tegels met lijmresten gaat meer werk
    # dan over een gladde dekvloer. Bedragen horen hier en niet in de website-code,
    # want de bezoeker mag ze niet kunnen lezen en Rick moet ze zelf kunnen wijzigen.
    "ondergronden": {
        "Gladde cementdekvloer":                     {"toeslag_m2": 0},
        "Tegelvloer":                                {"toeslag_m2": 8},
        "Lijmresten aanwezig gesloopte tegelvloer":  {"toeslag_m2": 12},
        "Lijmresten aanwezig gesloopte tapijt":      {"toeslag_m2": 6},
        "Gietvloer":                                 {"toeslag_m2": 4},
    },
    # Vaste regels die Rick met één klik in een offerte of factuur zet, in plaats
    # van omschrijving en bedrag elke keer overtypen. Prijzen hier zijn EXCL. btw:
    # dat is ook wat de prijskolom in de offerte-/factuurregels toont.
    "standaardregels": [],
    "voorrijkosten": {"label": "Inmeten en advies aan huis", "bedrag": 0},
    "minimum_opdracht": 750,
    "geldigheid_dagen": 30,
    # Automatische offerte: aanmaken staat aan; automatisch VERSTUREN bewust uit.
    # Zet de klant dat aan, dan gaat de concept-offerte na `verzend_na_minuten`
    # vanzelf naar de klant (de cron /api/cron/offertes doet dat).
    "auto_aanmaken": True,
    "auto_versturen": False,
    "verzend_na_minuten": 15,
    # Aanbetaling bij akkoord. Staat UIT tot de Mollie-keys ingevuld zijn; zolang
    # dat zo is gedraagt de acceptknop zich als voorheen (direct geaccepteerd).
    # 50% is ook de bovengrens uit Ricks eigen voorwaarden voor consumenten.
    "aanbetaling_aan": False,
    "aanbetaling_pct": 50,
}


def _schoon_standaardregels(waarde) -> list:
    """Vaste offerte-/factuurregels uit de admin opschonen. Alles wat geen regel is
    valt weg: zonder omschrijving heeft een regel geen betekenis, en een negatief
    bedrag hoort niet in een tarievenlijst thuis."""
    uit = []
    for r in (waarde if isinstance(waarde, list) else []):
        if not isinstance(r, dict):
            continue
        desc = str(r.get("desc") or "").strip()[:120]
        if not desc:
            continue
        try:
            prijs = round(float(str(r.get("price") or 0).replace(",", ".")), 2)
        except (TypeError, ValueError):
            prijs = 0.0
        uit.append({"desc": desc, "unit": str(r.get("unit") or "").strip()[:12],
                    "price": max(0.0, prijs)})
    return uit[:40]


def get_tarieven() -> dict:
    """Opgeslagen tarieven, aangevuld met de standaardwaarden (zodat een nieuw
    veld nooit ontbreekt na een update van de code)."""
    opgeslagen = kv_get("tarieven") or {}
    t = json.loads(json.dumps(TARIEVEN_DEFAULT))
    for k, v in (opgeslagen.items() if isinstance(opgeslagen, dict) else []):
        if isinstance(v, dict) and isinstance(t.get(k), dict):
            for k2, v2 in v.items():
                if isinstance(v2, dict) and isinstance(t[k].get(k2), dict):
                    t[k][k2].update(v2)
                else:
                    t[k][k2] = v2
        else:
            t[k] = v
    # Plinten gingen eerst per m2 en sinds 2026-08-15 per strekkende meter. Een
    # record van vóór die wijziging draagt nog per_m2; dat bedrag is door de klant
    # ingevuld en moet leidend blijven, anders rekent de site stilletijk verder met
    # de standaardwaarde uit de code terwijl er een eigen tarief staat.
    plint = (t.get("extra") or {}).get("plinten")
    if isinstance(plint, dict) and plint.get("per_m2") is not None:
        plint["per_m1"] = plint.pop("per_m2")
    return t


@app.route("/api/admin/tarieven", methods=["GET", "PUT"])
@app.route("/api/admin/tarieven/", methods=["GET", "PUT"])
def api_tarieven():
    g = _require_perm("tarieven")
    if g:
        return g
    if request.method == "GET":
        return jsonify({"tarieven": get_tarieven(), "default": TARIEVEN_DEFAULT})

    b = request.get_json(silent=True) or {}
    t = get_tarieven()

    def _num(x, oud):
        try:
            return round(float(str(x).replace(",", ".")), 2)
        except (TypeError, ValueError):
            return oud

    for naam, blok in (b.get("vloeren") or {}).items():
        if naam in t["vloeren"] and isinstance(blok, dict):
            t["vloeren"][naam]["per_m2"] = _num(blok.get("per_m2"), t["vloeren"][naam]["per_m2"])
            if blok.get("label"):
                t["vloeren"][naam]["label"] = str(blok["label"])[:120]
    for naam, blok in (b.get("extra") or {}).items():
        if naam in t["extra"] and isinstance(blok, dict):
            eenheid = "per_m1" if "per_m1" in t["extra"][naam] else "per_m2"
            t["extra"][naam][eenheid] = _num(blok.get(eenheid), t["extra"][naam][eenheid])
            if blok.get("label"):
                t["extra"][naam]["label"] = str(blok["label"])[:120]
    if isinstance(b.get("trap"), dict):
        t["trap"]["per_trede"] = _num(b["trap"].get("per_trede"), t["trap"]["per_trede"])
        try:
            t["trap"]["standaard_treden"] = max(1, min(60, int(b["trap"].get("standaard_treden") or t["trap"]["standaard_treden"])))
        except (TypeError, ValueError):
            pass
    for naam, blok in (b.get("patronen") or {}).items():
        if naam in t.get("patronen", {}) and isinstance(blok, dict):
            t["patronen"][naam]["toeslag_m2"] = _num(blok.get("toeslag_m2"), t["patronen"][naam]["toeslag_m2"])
    for naam, blok in (b.get("ondergronden") or {}).items():
        if naam in t.get("ondergronden", {}) and isinstance(blok, dict):
            t["ondergronden"][naam]["toeslag_m2"] = _num(blok.get("toeslag_m2"), t["ondergronden"][naam]["toeslag_m2"])
    if "standaardregels" in b:
        t["standaardregels"] = _schoon_standaardregels(b.get("standaardregels"))
    if isinstance(b.get("voorrijkosten"), dict):
        t["voorrijkosten"]["bedrag"] = _num(b["voorrijkosten"].get("bedrag"), t["voorrijkosten"]["bedrag"])
    if "minimum_opdracht" in b:
        t["minimum_opdracht"] = _num(b.get("minimum_opdracht"), t["minimum_opdracht"])
    if "btw_tarief" in b:
        t["btw_tarief"] = _num(b.get("btw_tarief"), t["btw_tarief"])
    if "geldigheid_dagen" in b:
        try:
            t["geldigheid_dagen"] = max(1, min(365, int(b.get("geldigheid_dagen"))))
        except (TypeError, ValueError):
            pass
    if "auto_aanmaken" in b:
        t["auto_aanmaken"] = bool(b.get("auto_aanmaken"))
    if "auto_versturen" in b:
        t["auto_versturen"] = bool(b.get("auto_versturen"))
    if "verzend_na_minuten" in b:
        try:
            # Minimaal 1 minuut: de cron draait elke 5 minuten, dus korter heeft geen zin.
            t["verzend_na_minuten"] = max(1, min(1440, int(b.get("verzend_na_minuten"))))
        except (TypeError, ValueError):
            pass
    if "aanbetaling_aan" in b:
        t["aanbetaling_aan"] = bool(b.get("aanbetaling_aan"))
    if "aanbetaling_pct" in b:
        try:
            # Boven de 50% mag een ondernemer een consument niet vooruit laten
            # betalen volgens Ricks eigen voorwaarden; die grens zit hier hard in.
            t["aanbetaling_pct"] = max(1, min(50, int(b.get("aanbetaling_pct"))))
        except (TypeError, ValueError):
            pass

    kv_set("tarieven", t)
    audit_log("tarieven.update", "tarieven", "Tarieven voor de automatische offerte bijgewerkt")
    return jsonify({"ok": True, "tarieven": t})


@app.route("/api/admin/verhuur-tarieven", methods=["GET", "PUT"])
@app.route("/api/admin/verhuur-tarieven/", methods=["GET", "PUT"])
def api_verhuur_tarieven():
    """Tarieven die de AUTOMATISCHE concept-offerte voeden.
    Bedragen zijn incl. btw (zoals op de site); de offerte rekent ze terug naar ex-btw."""
    if require_login():
        return jsonify({"error": "auth"}), 401
    if request.method == "GET":
        return jsonify(_verhuur())

    # Tarieven zijn bedrijfsdata van de verhuurder zelf: zowel bureau als klant mogen ze
    # wijzigen (require_login hierboven is de poort).
    body = request.get_json(silent=True) or {}
    cur = _verhuur()

    def rows(key):
        out = []
        for it in (body.get(key) if isinstance(body.get(key), list) else cur.get(key, [])):
            if not isinstance(it, dict):
                continue
            val = str(it.get("value", "")).strip()
            if not val:
                continue
            out.append({"value": val,
                        "label": str(it.get("label", "")).strip() or val,
                        "price": _parse_bedrag(it.get("price"))})
        return out

    try:
        valid_days = max(1, min(365, int(body.get("valid_days", cur.get("valid_days", 30)) or 30)))
    except (TypeError, ValueError):
        valid_days = 30

    new = {
        "btw_rate": _parse_bedrag(body.get("btw_rate", cur.get("btw_rate", 21))) or 21,
        "prices_include_vat": bool(body.get("prices_include_vat", cur.get("prices_include_vat", True))),
        "auto_create": bool(body.get("auto_create", cur.get("auto_create", True))),
        "valid_days": valid_days,
        "cars": rows("cars"),
        "services": rows("services"),
        "notes": str(body.get("notes", cur.get("notes", ""))).strip(),
    }
    existing = kv_get("settings", {}) or {}
    existing["verhuur"] = new
    kv_set("settings", existing)
    audit_log("verhuur.tarieven.update", "settings:verhuur",
              f"{len(new['cars'])} auto's, {len(new['services'])} services")
    return jsonify({"ok": True, "verhuur": new})


@app.route("/api/meta", methods=["GET", "PUT"])
def api_meta():
    if require_login(): return jsonify({"error": "auth"}), 401
    if request.method == "GET":
        url = request.args.get("url")
        if url:
            return jsonify(get_page_meta(url))
        # No url — return summary for all pages
        out = []
        for p in list_pages():
            m = get_page_meta(p["url"])
            out.append({**p, **{k: m.get(k, "") for k in ("title", "description")}})
        return jsonify(out)
    # PUT
    body = request.get_json(silent=True) or {}
    url = body.get("url")
    if not url: return jsonify({"ok": False, "error": "url ontbreekt"}), 400
    updates = {k: v for k, v in body.items() if k in META_PATTERNS}
    result = set_page_meta(url, updates)
    return jsonify(result)


