@app.route("/api/admin/mail-preview", methods=["POST"])
@app.route("/api/admin/mail-preview/", methods=["POST"])
def api_mail_preview():
    """Stuurt een voorbeeld van een mailsjabloon (company/customer) naar een opgegeven adres,
    gerenderd met voorbeeld-aanvraaggegevens. Gebruikt de in het formulier ingevulde (mogelijk
    nog niet-opgeslagen) onderwerp/body, zodat je je wijzigingen kunt testen vóór opslaan."""
    g = _require_agency()
    if g: return g
    d = request.get_json(silent=True) or {}
    to = (d.get("to") or "").strip()
    # render=1: alleen tonen hoe de mail eruit komt te zien (voor het voorbeeld in
    # de admin). Zonder dat wordt hij echt verstuurd en is een adres verplicht.
    alleen_tonen = bool(d.get("render"))
    if not alleen_tonen and (not to or "@" not in to):
        return jsonify({"ok": False, "error": "Vul een geldig e-mailadres in."}), 400
    which = "company" if d.get("which") == "company" else "customer"
    subject = (d.get("subject") or "").strip() or "Voorbeeldmail"
    body = d.get("body") or ""
    is_html = (d.get("content_type") == "html")
    # Voorbeeld-aanvraag zodat shortcodes ([field id="..."], [all-fields]) gevuld worden.
    sample = {"name": "Voorbeeld Klant", "email": to or "klant@voorbeeld.nl", "telefoon": "06 12345678",
              "bedrijfsnaam": "",
              "note": "Dit is een voorbeeld-aanvraag ter controle van de mail.",
              "source": "https://damhousing.nl/"}
    ctx = _build_field_ctx(sample)
    subj = "[VOORBEELD] " + render_template_text(subject, ctx)
    rendered = render_template_text(body, ctx, html=is_html)
    if alleen_tonen:
        # Precies wat send_email er straks van maakt: handtekening + het jasje.
        toon = rendered
        if _sig_on(which):
            sig = (get_settings().get("email_signature") or "").strip()
            if sig:
                if not is_html:
                    toon = html_escape(toon).replace("\n", "<br>")
                toon = toon + "<br><br>" + sig
        elif not is_html:
            toon = html_escape(toon).replace("\n", "<br>")
        return jsonify({"ok": True, "html": _in_mail_jasje(toon), "subject": subj})
    ok, msg = send_email(to_addr=to, subject=subj, body=rendered,
                         content_type="html" if is_html else "plain",
                         signature=_sig_on(which))
    return jsonify({"ok": ok, "message": (msg if ok else None), "error": (None if ok else msg)})


@app.route("/api/smtp-verify", methods=["POST"])
def api_smtp_verify():
    """Test de SMTP-verbinding + login op de opgeslagen instellingen, zonder een mail te sturen."""
    if require_login(): return jsonify({"error": "auth"}), 401
    s = get_settings().get("smtp", {})
    if not s.get("host"):
        return jsonify({"ok": False, "error": "Geen SMTP-host ingesteld"}), 400
    try:
        port = int(s.get("port", 587))
        if port == 465:
            srv = smtplib.SMTP_SSL(s["host"], port, context=ssl.create_default_context(), timeout=8)
        else:
            srv = smtplib.SMTP(s["host"], port, timeout=8)
            srv.ehlo()
            if s.get("use_tls", True):
                srv.starttls(context=ssl.create_default_context()); srv.ehlo()
        if s.get("user"):
            srv.login(s["user"], s.get("password", ""))
        try:
            srv.quit()
        except Exception:
            pass
        return jsonify({"ok": True, "message": "Verbinding én login geslaagd."})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})


