def _public_base() -> str:
    if PUBLIC_SITE_URL:
        return PUBLIC_SITE_URL
    try:
        return request.host_url.rstrip("/")
    except Exception:
        return ""


def _gbp_bestand_is_afbeelding(pad: str) -> bool:
    """Ligt op dit pad ECHT een afbeelding?

    Alleen het content-type telt. De SPA-catch-all beantwoordt élk onbekend pad met
    200 + text/html, dus een statuscheck "vindt" ook bestanden die niet bestaan —
    /projecten/bestaatniet.jpg gaf gewoon 200 (damhousing, 27-08-2026). Uitkomst een week
    in KV, ook een 'nee': dit hangt aan een deploy, niet aan het moment."""
    pad = str(pad or "")
    if not pad:
        return False
    sleutel = "gbp:twin:" + hashlib.sha1(pad.encode("utf-8")).hexdigest()[:16]
    bewaard = kv_get(sleutel)
    if isinstance(bewaard, dict) and (time.time() - float(bewaard.get("t", 0) or 0)) < 7 * 24 * 3600:
        return bool(bewaard.get("ok"))
    ok = False
    try:
        basis = _public_base()
        url = pad if pad.startswith("http") else (basis + pad)
        req = urllib.request.Request(url, method="HEAD",
                                     headers={"User-Agent": "MHS-CMS-fotocheck/1.0"})
        with urllib.request.urlopen(req, timeout=8) as r:
            ok = str(r.headers.get("Content-Type", "")).lower().startswith("image/")
    except Exception:
        ok = False
    kv_set(sleutel, {"t": int(time.time()), "ok": ok})
    return ok


def _gbp_photo_url(url: str) -> str:
    """Google Bedrijfsprofiel accepteert voor posts alleen JPG/PNG. Is de gekozen foto webp
    (of iets anders), zoek dan een JPG/PNG-variant met dezelfde basisnaam.

    Eerst in de mediabibliotheek, daarna op de server zelf: op een site waar de
    bibliotheek uitsluitend webp bevat staat de jpg er wél maar is hij nooit als media
    geregistreerd, en dan zou hier onterecht "geen twin" uitkomen — met als gevolg dat
    élke gegenereerde post zonder foto bleef (damhousing, 27-08-2026)."""
    if not url or url.lower().endswith((".jpg", ".jpeg", ".png")):
        return url
    base = re.sub(r"\.[a-z0-9]+$", "", url, flags=re.I)
    have = {m.get("url", "") for m in list_media() if isinstance(m, dict)}
    for ext in (".jpg", ".jpeg", ".png"):
        if base + ext in have:
            return base + ext
    for ext in (".jpg", ".png"):
        if _gbp_bestand_is_afbeelding(base + ext):
            return base + ext
    return url  # geen twin gevonden — Google geeft dan een nette foutmelding


ANTHROPIC_API_KEY = os.environ.get("ANTHROPIC_API_KEY", "")
ANTHROPIC_MODEL_DEFAULT = "claude-opus-4-8"
# Centrale MAIHS AI-gateway: als deze env-vars gezet zijn loopt tekst-AI via
# software.mhsmedia.nl (één Anthropic-key centraal) i.p.v. een eigen key op deze
# site. Body/response zijn identiek aan Anthropic; alleen URL + auth-header
# verschillen. Niet gezet => legacy-gedrag (eigen ANTHROPIC_API_KEY).
# De centrale gateway heette MAIHS_AI_* toen hij alleen AI deed. Datzelfde token
# bedient inmiddels ook SE Ranking, Google-OAuth, Ads en mail, dus de vloot draait
# op MHS_GATEWAY_*. De oude namen staan nergens meer op Vercel en worden hier niet
# meer gelezen.
#
# De env is een kale origin ("https://host"), maar de normalisatie hieronder
# blijft nodig: ze vangt een afsluitende slash en een per ongeluk meegeplakt pad
# af. Elke aanroep leidt zo de origin af en plakt zijn eigen pad erachter, ook de
# AI-call, die vroeger de env-waarde ongewijzigd als POST-URL gebruikte. Wie de
# env-waarde rechtstreeks als POST-URL neemt, stuurt elke generatie naar de kale
# host.
MHS_GATEWAY_URL = os.environ.get("MHS_GATEWAY_URL", "").strip()
MHS_GATEWAY_KEY = os.environ.get("MHS_GATEWAY_KEY", "").strip()
AI_GATEWAY_PAD = "/api/ai-gateway/messages"


def _gateway_origin() -> str:
    """De MHS-host als kale origin.

    Knipt de origin uit de env-waarde, dus een kale host en een vol pad
    (met of zonder afsluitende slash) leveren exact hetzelfde op."""
    m = re.match(r"^(https?://[^/]+)", MHS_GATEWAY_URL or "")
    return m.group(1) if m else ""


def _gateway_key() -> str:
    """Het gatewaytoken."""
    return MHS_GATEWAY_KEY


def _gateway_aan() -> bool:
    """Staat de centrale gateway aan? Een plek, zodat geen enkel endpoint
    zijn eigen variant van deze check verzint."""
    return bool(_gateway_origin() and _gateway_key())


def _meld_koppelingen_aan_maihs(timeout: int = 15) -> bool:
    """Vertelt MAIHS welke koppelingen op DEZE site aanstaan.

    MAIHS kan dat niet zelf zien: elk Google-refresh-token staat in de KV van de
    klantsite, niet centraal. Zonder deze melding kan het vloot-overzicht alleen
    gokken, en een kolom die altijd hetzelfde toont leer je negeren.

    Faalt stil: dit is rapportage, geen functionaliteit — een onbereikbare gateway
    mag nooit de cron of een adminpagina laten struikelen.
    """
    basis = _gateway_origin()
    if not (basis and _gateway_key()):
        return False
    koppelingen = {"team_sso": bool(kv_get("security:team_sso_seen")),
                   # Of we een eigen mailserver hebben kan MAIHS al helemaal niet zien:
                   # die instelling staat in onze eigen opslag. Zonder deze melding zou
                   # de SMTP-kolom daar een kruisje tonen alsof er iets stuk is.
                   "own_smtp": _smtp_klant_eigen(get_settings().get("smtp", {}))}
    for svc in GOOGLE_SCOPES:
        g = kv_get("google_oauth:" + svc) or {}
        koppelingen[svc] = bool(g.get("refresh_token"))
    try:
        # De focus-zoekwoorden reizen mee: SE Ranking heeft ze nodig en alleen MAIHS
        # heeft die key. De site blijft de bron — hier ingesteld, daar gesynchroniseerd.
        lading = {"integrations": koppelingen}
        try:
            _kw = (_agent_config() or {}).get("focus_keywords") or []
            if isinstance(_kw, list) and _kw:
                lading["focus_keywords"] = [str(k)[:60] for k in _kw][:50]
        except Exception:
            pass
        data = json.dumps(lading).encode()
        req = urllib.request.Request(
            f"{basis}/api/gateway/site-status", data=data, method="POST",
            headers={"Authorization": "Bearer " + _gateway_key(),
                     "Content-Type": "application/json",
                     "User-Agent": "MAIHS-Gateway-Client/1.0"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            r.read()
        return True
    except Exception as e:
        print(f"[maihs-status] melden mislukt: {e}")
        return False


# Kort wachten als iemand zit te kijken: dit is rapportage, en die mag een
# koppelactie of login niet merkbaar ophouden. Faalt het, dan zet de dagelijkse
# cron het alsnog recht.
def _meld_koppelingen_direct() -> None:
    _meld_koppelingen_aan_maihs(timeout=4)


def _meld_koppelingen_zo_nu_en_dan(min_uren: int = 12) -> None:
    """Meldt de koppelingsstand bij het openen van de admin, hooguit eens per N uur.

    De dagelijkse cron was tot nu toe de enige melder, en die draait niet overal —
    een ontbrekend CRON_SECRET is genoeg om hem stil 401 te laten geven. Het
    vlootoverzicht bij MAIHS stond daardoor voor de helft van de sites op "nooit
    gemeld". Dit hangt de melding aan iets dat sowieso gebeurt: iemand die de admin
    opent.

    De teller gaat VOOR de melding om. Anders probeert een onbereikbare gateway het
    bij elke pagina-load opnieuw en betaalt degene die inlogt dat in wachttijd.
    """
    try:
        laatst = float(kv_get("maihs:status:laatst") or 0)
    except Exception:
        laatst = 0.0
    if laatst and (time.time() - laatst) < min_uren * 3600:
        return
    kv_set("maihs:status:laatst", time.time())
    _meld_koppelingen_direct()
# Socket read-timeout voor de Anthropic-call. Houd dit ~5s onder de Vercel
# functie-maxDuration (vercel.json) zodat we een nette foutmelding teruggeven
# i.p.v. dat Vercel de hele functie hard afkapt.
try:
    AI_HTTP_TIMEOUT = int(os.environ.get("AI_HTTP_TIMEOUT", "55") or "55")
except ValueError:
    AI_HTTP_TIMEOUT = 55
# Vangnet tegen onverwacht hoog tokenverbruik (per kalendermaand). Hoog default; via env aan te passen.
try:
    AI_MONTHLY_TOKEN_LIMIT = int(os.environ.get("AI_MONTHLY_TOKEN_LIMIT", "5000000") or "5000000")
except ValueError:
    AI_MONTHLY_TOKEN_LIMIT = 5000000
AUDIT_CAP = 1000
REVISIONS_CAP = 20

# Generated HTML output dir (only writable locally)
GENERATED_DIR = ROOT / ".generated"


def _now_iso() -> str:
    # Tijdzone-bewuste ISO-string (bv. 2026-06-20T07:16:00+02:00) in NL-tijd. De expliciete
    # offset maakt het moment ondubbelzinnig, zodat de frontend het altijd in NL-tijd kan tonen
    # ongeacht de tijdzone van de bezoeker.
    return datetime.now().astimezone().isoformat(timespec="seconds")


def _as_aware(dt: datetime) -> datetime:
    # Maak een (mogelijk naïeve, legacy) datetime tijdzone-bewust door 'm als lokale tijd te lezen.
    return dt if dt.tzinfo else dt.astimezone()


def _auth_or_401():
    """Return a 401 JSON response if not logged in, else None."""
    if not is_logged_in():
        return jsonify({"error": "auth"}), 401
    return None


def _safe_slug(s: str) -> str:
    s = (s or "").strip().strip("/")
    # Allow path-style slugs like 'diensten/stucwerk'
    s = re.sub(r"[^a-z0-9/_-]+", "-", s.lower())
    s = re.sub(r"-+", "-", s).strip("-/")
    return s


def _decode_slug(s: str) -> str:
    """Admin-routes: '__home__' is de alias voor de homepage (echte slug = ''),
    omdat een lege slug in de URL de lijst-route zou raken. Intern blijft de slug '' zodat
    sitemap/serving '/' blijven gebruiken."""
    if (s or "").strip("/") == "__home__":
        return ""
    return _safe_slug(s)


# ---------- audit log ----------
def audit_log(action: str, target: str, summary: str = "", before=None, after=None) -> None:
    try:
        log = kv_get("audit:log", []) or []
        entry = {
            "ts": _now_iso(),
            "user": session.get("user", "system") if session else "system",
            "action": action,
            "target": target,
            "summary": summary,
        }
        if before is not None: entry["before"] = before
        if after is not None: entry["after"] = after
        log.insert(0, entry)
        if len(log) > AUDIT_CAP:
            log = log[:AUDIT_CAP]
        kv_set("audit:log", log)
    except Exception as e:
        print(f"audit_log failed: {e}")


_DEPLOY_DEBOUNCE_SECONDS = 15


def _trigger_deploy(reason: str = "") -> bool:
    """Trigger een Vercel-rebuild via de Deploy Hook zodat KV-edits (in-place HTML,
    blokken, nieuwe pagina's, header/footer) door build_apply.py in de statische
    bestanden worden gebakken en LIVE op de voorkant verschijnen.

    De hook-URL staat als secret in de env-var VERCEL_DEPLOY_HOOK_URL (NOOIT in de repo —
    die zou via git lekken). Fire-and-forget + lichte debounce zodat snel-achter-elkaar
    publiceren coalesceert tot één build. Faalt nooit hard: mag de API-response niet breken."""
    url = os.environ.get("VERCEL_DEPLOY_HOOK_URL", "").strip()
    if not url:
        return False
    try:
        last = kv_get("deploy:last_trigger") or 0
        now = time.time()
        if isinstance(last, (int, float)) and (now - last) < _DEPLOY_DEBOUNCE_SECONDS:
            return True  # een net-getriggerde build pakt deze edit al mee
        kv_set("deploy:last_trigger", now)
        req = urllib.request.Request(
            url, data=b"{}", method="POST",
            headers={"Content-Type": "application/json"})
        urllib.request.urlopen(req, timeout=8).read()
        audit_log("deploy.trigger", "site", (reason or "")[:120])
        return True
    except Exception as e:
        try:
            app.logger.warning("deploy hook faalde: %s", e)
        except Exception:
            print(f"deploy hook faalde: {e}")
        return False


# ---------- pages-index helpers ----------
def _pages_index() -> list[dict]:
    """De paginalijst uit KV, aangevuld met pagina's die alleen nog in de code bestaan.

    De bootstrap is normaal alleen een fallback zolang KV leeg is. Voegen wij later
    een route toe (zoals /diensten), dan zou die op een al ingerichte site nooit
    verschijnen: niet in de paginalijst, niet in de sitemap, niet bewerkbaar — de
    pagina staat dan wél live maar het CMS weet er niets van.

    Wat de klant zelf heeft verwijderd blijft weg (zie `pages:removed`), anders
    komt een weggehaalde pagina bij elke request terug.
    """
    items = kv_get("pages:index", []) or []
    if not _BOOTSTRAP_PAGES_INDEX or not items:
        return items
    bekend = {p.get("slug") for p in items}
    verwijderd = set(kv_get("pages:removed", []) or [])
    ontbreekt = [p for p in _BOOTSTRAP_PAGES_INDEX
                 if p.get("slug") not in bekend and p.get("slug") not in verwijderd]
    return items + ontbreekt if ontbreekt else items


def _save_pages_index(items: list[dict]) -> None:
    kv_set("pages:index", items)


def _upsert_pages_index(page: dict) -> None:
    items = _pages_index()
    slug = page.get("slug")
    score = (kv_get("seo_scores", {}) or {}).get(slug, {}).get("score", 0)
    entry = {
        "slug": slug,
        "title": page.get("title", ""),
        "status": page.get("status", "draft"),
        "template": page.get("template"),
        "locale": page.get("locale", "nl"),
        "updated_at": page.get("updated_at"),
        "seo_score": score,
    }
    idx = next((i for i, x in enumerate(items) if x.get("slug") == slug), -1)
    if idx >= 0:
        items[idx] = entry
    else:
        items.append(entry)
    _save_pages_index(items)


def _remove_from_pages_index(slug: str) -> None:
    items = _pages_index()
    items = [x for x in items if x.get("slug") != slug]
    _save_pages_index(items)


def _default_page(slug: str, title: str, template: str | None = None, locale: str = "nl") -> dict:
    return {
        "slug": slug,
        "title": title,
        "status": "draft",
        "template": template,
        "locale": locale,
        "parent": None,
        "menu_position": 0,
        "scheduled_publish_at": None,
        "author": session.get("user", "admin") if session else "admin",
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
        "published_at": None,
        "meta": {
            "title": title,
            "description": "",
            "canonical": "",
            "robots": "index,follow",
            "og_title": title,
            "og_description": "",
            "og_image": "",
            "twitter_card": "summary_large_image",
            "twitter_image": "",
            "hreflang": [],
            "keyword": "",
            "schema_jsonld": None,
        },
        "content_blocks": [],
    }


def _get_page(slug: str) -> dict | None:
    return kv_get(f"page:{slug}")


def _save_page(page: dict) -> None:
    page["updated_at"] = _now_iso()
    kv_set(f"page:{page['slug']}", page)
    _upsert_pages_index(page)


# ---------- revisions ----------
def _new_rev_id() -> str:
    return uuid.uuid4().hex[:12]


def _push_revision(slug: str, snapshot: dict, summary: str = "") -> str:
    rev_id = _new_rev_id()
    rev = {
        "rev_id": rev_id,
        "page_slug": slug,
        "snapshot": snapshot,
        "author": session.get("user", "admin") if session else "admin",
        "created_at": _now_iso(),
        "summary": summary,
    }
    kv_set(f"page:{slug}:rev:{rev_id}", rev)
    revs = kv_get(f"page:{slug}:revs", []) or []
    revs.insert(0, rev_id)
    # Drop old revisions
    for stale in revs[REVISIONS_CAP:]:
        kv_delete(f"page:{slug}:rev:{stale}")
    revs = revs[:REVISIONS_CAP]
    kv_set(f"page:{slug}:revs", revs)
    return rev_id


# ---------- block rendering ----------
def _esc(s) -> str:
    return (str(s or "")
            .replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            .replace('"', "&quot;").replace("'", "&#39;"))


def _blk_items(v) -> list:
    """list-items: accepteert array óf newline-string (editor-vorm)."""
    if isinstance(v, list):
        return [str(x) for x in v]
    if isinstance(v, str):
        return [ln.strip() for ln in v.splitlines() if ln.strip()]
    return []


def _yt_id(u: str) -> str:
    u = (u or "").strip()
    if not u:
        return ""
    m = re.search(r"(?:v=|youtu\.be/|embed/|shorts/)([\w-]{6,})", u)
    return m.group(1) if m else u


def _vimeo_id(u: str) -> str:
    u = (u or "").strip()
    if not u:
        return ""
    m = re.search(r"vimeo\.com/(?:video/)?(\d+)", u)
    return m.group(1) if m else u


def normalize_block(b: dict) -> dict:
    """Breng een blok naar de canonieke {type, props:{...}}-vorm die render_block() leest.

    Nodig omdat zowel de pagina-editor (platte keys: block.text/url/headline/...) als de
    AI-generator (platte canonieke namen) blokken ZONDER props-object opslaan. Idempotent:
    een al-canoniek blok (met gevulde props) blijft ongemoeid. Render-tijd-only — we
    herschrijven de opslag NIET, zodat de editor de platte vorm kan blijven terug-bewerken.
    """
    if not isinstance(b, dict):
        return {"type": "", "props": {}}
    t = b.get("type", "")
    existing = b.get("props")
    existing = dict(existing) if isinstance(existing, dict) else {}

    def g(*keys, default=""):
        for k in keys:
            v = existing.get(k)
            if v not in (None, "", [], {}):
                return v
        for k in keys:
            v = b.get(k)
            if v not in (None, "", [], {}):
                return v
        return default

    props = dict(existing)
    if t in ("heading-h1", "heading-h2", "heading-h3", "heading-h4", "paragraph", "heading"):
        props["text"] = g("text")
        if t == "heading":
            lvl = g("level") or "h2"
            props["level"] = lvl if lvl in ("h1", "h2", "h3", "h4", "h5", "h6") else "h2"
            props["eyebrow"] = g("eyebrow")
    elif t == "rich-text":
        props["html"] = g("html", "text")
    elif t == "image":
        props["src"] = g("src", "url"); props["alt"] = g("alt")
    elif t == "image-gallery":
        imgs = g("images", default=[]) or []
        props["images"] = [{"src": (i.get("src") or i.get("url") or ""), "alt": i.get("alt", "")}
                           for i in imgs if isinstance(i, dict)]
    elif t in ("button", "link"):
        props["href"] = g("href", "url"); props["text"] = g("text")
    elif t == "button-group":
        btns = g("buttons", default=[]) or []
        props["buttons"] = [{"href": (x.get("href") or x.get("url") or "#"), "text": x.get("text", "")}
                            for x in btns if isinstance(x, dict)]
    elif t in ("list-ul", "list-ol"):
        props["items"] = _blk_items(g("items", default=[]))
    elif t == "hr":
        props = {}
    elif t == "spacer":
        try:
            props["height"] = int(g("height", default=24) or 24)
        except Exception:
            props["height"] = 24
    elif t == "quote":
        props["text"] = g("text"); props["cite"] = g("cite", "author")
    elif t in ("section-1col", "section-2col", "section-3col"):
        children = g("children", default=[]) or []
        norm = []
        for c in children:
            if isinstance(c, list):
                norm.append([normalize_block(x) for x in c])
            elif isinstance(c, dict):
                norm.append([normalize_block(c)])
        props["children"] = norm
    elif t == "video-youtube":
        props["video_id"] = _yt_id(g("video_id", "url"))
    elif t == "video-vimeo":
        props["video_id"] = _vimeo_id(g("video_id", "url"))
    elif t == "embed-iframe":
        props["src"] = g("src", "url")
    elif t == "html-raw":
        props["html"] = g("html", "url", "text")
    elif t == "service-hero":
        props["heading"] = g("heading", "title", "text")
        props["intro"] = g("intro", "subtitle", "subtext")
        props["image"] = g("image", "src", "url")
        props["eyebrow"] = g("eyebrow")
        _u = g("usps", "items", default=[])
        if isinstance(_u, str):
            _u = [x.strip() for x in _u.splitlines() if x.strip()]
        props["usps"] = [str(x).strip() for x in (_u or []) if str(x).strip()]
        _sf = g("show_form", default=True)
        props["show_form"] = _sf if isinstance(_sf, bool) else str(_sf).strip().lower() not in ("false", "0", "nee", "no", "")
    elif t == "cta-banner":
        props["title"] = g("title", "headline")
        props["subtitle"] = g("subtitle", "subtext")
        props["cta_text"] = g("cta_text", "button_text")
        props["cta_href"] = g("cta_href", "button_url")
    elif t == "faq-item":
        props["question"] = g("question"); props["answer"] = g("answer")
    elif t == "steps":
        items = g("items", default=[]) or []
        props["items"] = [{"title": i.get("title", ""), "text": i.get("text", "")}
                          for i in items if isinstance(i, dict)]
    elif t == "stats":
        items = g("items", default=[]) or []
        props["items"] = [{"value": i.get("value", ""), "label": i.get("label", "")}
                          for i in items if isinstance(i, dict)]
    elif t == "faq-group":
        items = g("items", default=[]) or []
        props["items"] = [{"question": i.get("question", ""), "answer": i.get("answer", "")}
                          for i in items if isinstance(i, dict)]
    elif t == "testimonial":
        props["quote"] = g("quote", "text"); props["author"] = g("author", "cite")
    elif t == "icon-box":
        props["icon"] = g("icon"); props["title"] = g("title", "headline"); props["text"] = g("text", "subtext")
    elif t == "contact-form-ref":
        props["form_id"] = g("form_id", default="default")
    elif t == "google-map":
        props["query"] = g("query", "url", default="DAM Housing")
    elif t == "breadcrumb":
        items = g("items", default=[]) or []
        props["items"] = [{"label": i.get("label", ""), "href": i.get("href", "#")}
                          for i in items if isinstance(i, dict)]
    elif t == "table":
        props["rows"] = g("rows", default=[]) or []
    return {"type": t, "props": props}


def normalize_blocks(blocks: list) -> list:
    return [normalize_block(b) for b in (blocks or []) if isinstance(b, dict)]


def _sanitize_html(s: str) -> str:
    """Sta veilige inline-HTML toe (zoals <a>, <strong>, <em>) in AI-gegenereerde tekst, maar
    strip gevaarlijke tags/attributen. Zo rendert een inline-link in een paragraph als echte link
    i.p.v. als platte <a href=…>-tekst, zonder XSS-risico."""
    s = s or ""
    # Ook al-opgeslagen HTML-links toetsen, niet alleen markdown: de AI schreef
    # <a href="/voorstel/">onze voorstelsite</a> als kant-en-klare HTML, en die glipte
    # langs de markdown-controle heen (Ryan, 27-08-2026). Doel bestaat niet of mag niet
    # -> de tekst blijft staan, de link verdwijnt.
    s = re.sub(r'(?is)<a\b[^>]*\bhref\s*=\s*["\']([^"\']+)["\'][^>]*>(.*?)</a\s*>',
               lambda m: m.group(0) if _kv_link_toegestaan(m.group(1)) else m.group(2), s)
    s = re.sub(r'(?is)<\s*(script|style|iframe|object|embed|form)\b.*?<\s*/\s*\1\s*>', '', s)
    s = re.sub(r'(?is)<\s*(script|style|iframe|object|embed|form)\b[^>]*>', '', s)
    s = re.sub(r'(?i)\son\w+\s*=\s*"[^"]*"', '', s)
    s = re.sub(r"(?i)\son\w+\s*=\s*'[^']*'", '', s)
    s = re.sub(r'(?i)javascript:', '', s)
    return s


