@app.route("/api/admin/pages", methods=["GET"])
def api_admin_pages_list():
    """List pages from KV (the new block-based store)."""
    a = _auth_or_401()
    if a: return a
    items = _pages_index()
    status = request.args.get("status")
    template = request.args.get("template")
    q = (request.args.get("q") or "").lower()
    limit = int(request.args.get("limit", 200))
    offset = int(request.args.get("offset", 0))
    if status: items = [x for x in items if x.get("status") == status]
    if template: items = [x for x in items if x.get("template") == template]
    if q: items = [x for x in items if q in (x.get("title", "") + x.get("slug", "")).lower()]
    total = len(items)
    return jsonify({"items": items[offset:offset + limit], "total": total})


@app.route("/api/admin/pages", methods=["POST"])
def api_admin_pages_create():
    a = _auth_or_401()
    if a: return a
    body = request.get_json(silent=True) or {}
    slug = _safe_slug(body.get("slug", ""))
    title = (body.get("title") or "").strip()
    if not slug or not title:
        return jsonify({"error": "slug en title verplicht"}), 400
    if _get_page(slug):
        return jsonify({"error": f"Pagina {slug} bestaat al"}), 409
    template = body.get("template")
    page = _default_page(slug, title, template=template, locale=body.get("locale", "nl"))
    if body.get("parent"): page["parent"] = body["parent"]
    # If template, instantiate
    if template:
        tpl = kv_get(f"template:{template}")
        if tpl:
            vars_ = body.get("variables", {}) or {}
            page["content_blocks"] = _substitute_template(tpl.get("content_blocks") or [], vars_)
            page["meta"].update(_substitute_template_meta(tpl.get("default_meta") or {}, vars_))
    if not page.get("content_blocks"):
        # Starter-inhoud: een lege pagina is een dood spoor in de editor (AI-assistent had niets om
        # op te bouwen, visueel niets te zien). Kop + intro geven de klant een startpunt.
        page["content_blocks"] = [
            {"type": "heading", "level": "h1", "text": title},
            {"type": "paragraph", "text": "Schrijf hier je inhoud - of gebruik de AI-assistent bovenaan het Inhoud-tabblad om in een keer een opzet te laten schrijven."},
        ]
    _save_page(page)
    update_seo_score(page)
    audit_log("page.create", slug, f"Created page '{title}'")
    return jsonify(page), 201


@app.route("/api/admin/pages/<path:slug>", methods=["GET"])
def api_admin_page_get(slug):
    a = _auth_or_401()
    if a: return a
    slug = _decode_slug(slug)
    page = _get_page(slug)
    if not page:
        # Zelf-heling (Wim 2026-07-20): een oude generator liet template-pagina's achter met
        # alleen een dienst-html:-blob (geen pagina-record) — onvindbaar in de pagina-lijst
        # en niet te openen in de editor. Maak het record alsnog aan; de blok-sync doet de rest.
        _seg0, _, _tail = slug.partition("/")
        if _seg0 in ("diensten", "locatie") and _tail:
            _blob = kv_get(f"dienst-html:{_safe_slug(_tail)}") or kv_get(f"dienst-html:{_safe_slug(slug)}")
            if _blob and isinstance(_blob, str):
                _m = re.search(r"<h1[^>]*>(.*?)</h1>", _blob, re.S | re.I)
                _ttl = re.sub(r"<[^>]+>", " ", _m.group(1)) if _m else _tail.replace("-", " ").title()
                page = _default_page(slug, _deent(re.sub(r"\s+", " ", _ttl).strip()), template="dienst-1to1")
                page["status"] = "published"
                _save_page(page)
                audit_log("page.selfheal", slug, "Pagina-record aangemaakt voor bestaande template-pagina (dienst-html zonder record)")
    if not page:
        # Statische (gemigreerde) pagina: nog geen bewerkbare blokken-versie in de store.
        # Geef minimale info terug (titel + gepubliceerd-status) zodat de editor de juiste
        # kop/status toont i.p.v. een lege concept-pagina.
        url = "/" + slug.strip("/") + "/"
        idx = next((p for p in list_pages() if p.get("url") == url or p.get("slug") == slug), None)
        if idx is not None:
            meta = get_page_meta(url)
            return jsonify({"slug": slug, "title": _deent(idx.get("title") or meta.get("title") or slug),
                            "status": "published", "meta": meta, "content_blocks": [],
                            "template": "", "locale": "nl", "menu_position": 0, "_static": True,
                            "design_locked": True})
        return jsonify({"error": "Niet gevonden"}), 404
    # Automatische blok-sync (Ryan 2026-07-17): bij het OPENEN van een vaste pagina de blokken
    # vers reconcilieren met de echte pagina (snapshot/statisch bestand) — geen handmatige
    # "Blokken verversen"-knop meer nodig; drift kan simpelweg niet meer bestaan in de editor.
    if _page_design_locked(slug, page):
        try:
            _base = _locked_base_html(slug)
            if _base and _regen_locked_blocks(slug, _base):
                page = _get_page(slug) or page
        except Exception:
            pass
    if request.args.get("include_draft") == "true":
        draft = kv_get(f"page:{slug}:draft")
        if draft:
            page = {**page, **draft, "has_draft": True}
    if page.get("title"):
        page["title"] = _deent(page["title"])
    _snap_locked = (kv_get(f"page:{slug}:inplace") is not None
                    and page.get("template") not in ("dienst-1to1", "locatie-1to1"))
    # SPA-pagina: de inhoud wordt door de React-app opgebouwd, niet uit blokken.
    # De editor toont daarvoor een uitleg i.p.v. een lege blokken-lijst, en previewt
    # de ECHTE pagina. Zonder deze vlag lijkt de editor kapot (leeg + lege preview).
    _spa = page.get("template") == "react"
    if _spa:
        # Bewerkbare teksten: opgeslagen versie (KV) aangevuld met de originelen uit
        # de seed, zodat nieuwe teksten in de code vanzelf verschijnen en eerder
        # gewijzigde teksten behouden blijven.
        _seed = ((_BOOTSTRAP_PAGES.get(f"page:{slug}") or {}).get("spa_texts") or [])
        _opg = {t.get("key"): t for t in (page.get("spa_texts") or [])
                if isinstance(t, dict) and t.get("key")}
        _lijst = []
        for t in _seed:
            _op = _opg.pop(t.get("key"), None)
            _lijst.append({**t, "text": (_op or {}).get("text") or t.get("original")})
        # Wat overblijft is opgeslagen onder een sleutel die niet meer in de code
        # staat: die tekst is uit de site verdwenen. Niet stilweg weggooien — de
        # editor toont hem als verweesd, zodat je ziet dat de aanpassing niets doet.
        for t in _opg.values():
            if (t.get("text") or "") != (t.get("original") or ""):
                _lijst.append({**t, "orphan": True})
        # Secties: de opgeslagen volgorde van de klant, aangevuld met wat de code
        # kent. Nieuwe secties die wij toevoegen verschijnen zo vanzelf als
        # "beschikbaar", en een sectie die uit de code verdwijnt valt weg.
        _seed_pg = _BOOTSTRAP_PAGES.get(f"page:{slug}") or {}
        _catalogus = list(_seed_pg.get("all_sections") or [])
        _bekend = {s["id"] for s in _catalogus}
        _blokken = [b for b in _spa_blokken(page, _seed_pg)
                    if b.get("type") != "dam-sectie" or b.get("section") in _bekend]
        page = {**page, "spa_texts": _lijst,
                "content_blocks": _blokken,
                "layout_editable": bool(_seed_pg.get("layout_editable")),
                "all_sections": _catalogus}
    return jsonify({**page, "design_locked": _page_design_locked(slug, page),
                    "snapshot_locked": _snap_locked,
                    "spa_page": _spa,
                    "public_url": ("/" + slug) if slug else "/",
                    "blocks_first": slug in (kv_get("pages:blocks_first", []) or [])})


# ---------- in-place bewerken van bestaande (statische) pagina's ----------
# De 116 geëxporteerde pagina's worden door Vercel als statische bestanden geserveerd met
# hun volledige Elementor-opmaak. Om ze bewerkbaar te maken ZONDER het uiterlijk te wijzigen
# laden we de echte pagina-HTML, laten de gebruiker tekst/afbeeldingen in-place aanpassen, en
# bewaren we de aangepaste HTML in KV (page:<slug>:inplace). De opmaak blijft 1-op-1 intact.
def _static_page_file(slug: str) -> Path:
    slug = "" if (slug or "").strip("/") == "__home__" else (slug or "").strip("/")
    return (ROOT / slug / "index.html") if slug else (ROOT / "index.html")


def _page_design_locked(slug: str, page: dict | None = None) -> bool:
    """True als het UITERLIJK van deze pagina vastligt buiten het blokken-record om
    (geïmporteerd statisch bestand, in-place snapshot, of 1-op-1 template). Voor zulke
    pagina's past de save-flow tekst-wijzigingen uit blokken toe op de echte HTML."""
    s = "" if (slug or "").strip("/") == "__home__" else (slug or "").strip("/")
    # Expliciet omgezet naar blokken ("Zet om naar blokken"): de blokken zijn dan de waarheid,
    # ook als er nog een gebakken/bootstrap-versie van deze pagina bestaat. Zonder deze poort
    # regenereerde de pagina-GET de blokken meteen terug uit de oude HTML (Ryan 2026-07-20).
    try:
        if s in (kv_get("pages:blocks_first", []) or []):
            return False
    except Exception:
        pass
    # Een React-route heeft helemaal geen opgeslagen HTML: de blokken zijn daar
    # EXTRA inhoud die de klant zelf toevoegt en dus vrij te bewerken. Zonder deze
    # poort valt hij hieronder in "staat in de bootstrap dus vast design" en krijgt
    # de klant sloten op blokken die hij juist wél mag toevoegen en verslepen.
    if page and page.get("template") == "react":
        return False
    if page and page.get("template") in ("dienst-1to1", "locatie-1to1"):
        return True
    try:
        if kv_get(f"page:{s}:inplace") is not None:
            return True
    except Exception:
        pass
    if f"page:{s}" in _BOOTSTRAP_PAGES:
        return True
    try:
        return _static_page_file(s).exists()
    except Exception:
        return False


@app.route("/api/admin/page-source/<path:slug>", methods=["GET"])
def api_page_source(slug):
    a = _auth_or_401()
    if a: return a
    slug = urllib.parse.unquote(slug or "")
    slug = "" if (slug or "").strip("/") == "__home__" else (slug or "").strip("/")
    edited = kv_get(f"page:{slug}:inplace")
    if edited:
        return jsonify({"html": edited, "edited": True})
    # 1) Probeer het gebundelde statische bestand (snel).
    f = _static_page_file(slug)
    if f.exists():
        try:
            return jsonify({"html": f.read_text(encoding="utf-8", errors="replace"), "edited": False})
        except Exception:
            pass
    # 2) Fallback: haal de live-gepubliceerde pagina op (werkt ook als het bestand niet
    #    in de functie-bundle zit). Zelfde host, dus geen externe afhankelijkheid.
    try:
        live_url = request.host_url.rstrip("/") + "/" + (slug + "/" if slug else "")
        req = urllib.request.Request(live_url, headers={"User-Agent": "damhousing-cms"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            html = resp.read().decode("utf-8", errors="replace")
        if html.strip():
            return jsonify({"html": html, "edited": False})
    except Exception as e:
        return jsonify({"error": f"Kon pagina niet laden: {e}"}), 502
    return jsonify({"error": f"Paginabestand niet gevonden voor /{slug}/"}), 404


# ---------- Visueel -> Inhoud-blokken terug-sync ----------
# Ryan 2026-07-16: een visuele bewerking hoort ook in de blokken-editor zichtbaar te zijn.
# We vergelijken de tekstdragers (koppen/alinea's/lijstitems/knop-teksten) van de oude en
# nieuwe snapshot in documentvolgorde; is de STRUCTUUR gelijk, dan nemen we gewijzigde
# teksten over in de overeenkomstige blokken. Bij structuurverschil doen we niets (nooit
# gokken) — de blokken blijven dan simpelweg de oude inhoud tonen.

_IP_VOID_TAGS = {"br", "img", "input", "hr", "source", "meta", "link", "wbr", "embed",
                 "area", "base", "col", "track", "param"}


class _IpTextCarriers(HTMLParser):
    """Verzamelt (soort, inner-html) van tekstdragers in documentvolgorde. Header/footer-
    subbomen en script/style tellen niet mee (site-breed, geen pagina-blokken)."""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.out = []
        self._stack = []          # open tags (voor diepte)
        self._skip_until = None   # diepte waaronder we alles negeren (header/footer/script/style)
        self._cap = None          # (kind, tag, diepte-bij-start)
        self._buf = []

    def _depth(self):
        return len(self._stack)

    def handle_starttag(self, tag, attrs):
        raw = self.get_starttag_text() or ""
        a = dict(attrs)
        if self._cap:
            if tag not in _IP_VOID_TAGS:
                self._stack.append(tag)
            self._buf.append(raw)
            return
        if self._skip_until is None and (
                tag in ("script", "style", "template")
                or a.get("data-elementor-type") in ("header", "footer")):
            if tag not in _IP_VOID_TAGS:
                self._stack.append(tag)
                self._skip_until = self._depth() - 1
            return
        if tag not in _IP_VOID_TAGS:
            self._stack.append(tag)
        if self._skip_until is not None:
            return
        kind = None
        if tag in ("h1", "h2", "h3", "h4", "h5", "h6"):
            kind = "heading"
        elif tag == "p":
            kind = "paragraph"
        elif tag == "li":
            kind = "li"
        elif tag == "span" and "elementor-button-text" in (a.get("class") or ""):
            kind = "button"
        if kind:
            self._cap = (kind, tag, self._depth() - 1)
            self._buf = []

    def handle_endtag(self, tag):
        if self._stack and self._stack[-1] == tag:
            self._stack.pop()
        elif tag in self._stack:
            while self._stack and self._stack[-1] != tag:
                self._stack.pop()
            if self._stack:
                self._stack.pop()
        if self._skip_until is not None:
            if self._depth() <= self._skip_until:
                self._skip_until = None
            return
        if self._cap:
            kind, ctag, cdepth = self._cap
            if tag == ctag and self._depth() <= cdepth:
                self.out.append((kind, "".join(self._buf).strip()))
                self._cap = None
                self._buf = []
            else:
                self._buf.append(f"</{tag}>")

    def handle_data(self, d):
        if self._cap and self._skip_until is None:
            self._buf.append(d)

    def handle_entityref(self, name):
        if self._cap and self._skip_until is None:
            self._buf.append(f"&{name};")

    def handle_charref(self, name):
        if self._cap and self._skip_until is None:
            self._buf.append(f"&#{name};")


def _ip_text_carriers(html: str) -> list:
    p = _IpTextCarriers()
    try:
        p.feed(html or "")
    except Exception:
        return []
    return p.out


def _ip_norm_text(s: str) -> str:
    s = re.sub(r"<[^>]+>", " ", s or "")
    s = html_unescape(s)
    return re.sub(r"\s+", " ", s).strip().lower()


def _ip_plain(s: str) -> str:
    s = re.sub(r"<[^>]+>", "", s or "")
    return re.sub(r"\s+", " ", html_unescape(s)).strip()


def _sync_blocks_from_inplace(slug: str, old_html: str, new_html: str) -> int:
    """Neem tekst-wijzigingen uit een visuele save over in het blokken-record (en het
    eventuele draft). Returns aantal bijgewerkte blok-velden."""
    page = _get_page(slug)
    if not page or not (page.get("content_blocks") or []):
        return 0
    old_seq = _ip_text_carriers(old_html)
    new_seq = _ip_text_carriers(new_html)
    if not old_seq or [k for k, _ in old_seq] != [k for k, _ in new_seq]:
        return 0
    # Detectie op RAUWE inner-html (zo telt ook een toegevoegde link zonder tekstwijziging);
    # matching naar blokken gebeurt hieronder wel genormaliseerd.
    changed = [(old_seq[i][0], old_seq[i][1], new_seq[i][1])
               for i in range(len(old_seq)) if old_seq[i][1].strip() != new_seq[i][1].strip()]
    if not changed:
        return 0

    def _apply(blocks: list) -> int:
        cnt = 0
        claimed = set()
        for kind, old_inner, new_inner in changed:
            o_n = _ip_norm_text(old_inner)
            for bi, b in enumerate(blocks):
                if not isinstance(b, dict) or bi in claimed:
                    continue
                bt = _blk_norm_type(b.get("type"))
                if kind == "heading" and bt == "heading" and _ip_norm_text(b.get("text")) == o_n:
                    b["text"] = _ip_plain(new_inner)
                elif kind == "paragraph" and bt == "paragraph" and _ip_norm_text(b.get("text")) == o_n:
                    b["text"] = html_unescape(new_inner)
                elif kind == "button" and bt == "button" and _ip_norm_text(b.get("text")) == o_n:
                    b["text"] = _ip_plain(new_inner)
                elif kind == "li" and bt in ("list-ul", "list-ol"):
                    lines = str(b.get("items") or "").split("\n")
                    hit = next((j for j, ln in enumerate(lines) if _ip_norm_text(ln) == o_n), None)
                    if hit is None:
                        continue
                    lines[hit] = _ip_plain(new_inner)
                    b["items"] = "\n".join(lines)
                else:
                    continue
                claimed.add(bi)
                cnt += 1
                break
        return cnt

    updated = _apply(page["content_blocks"])
    if updated:
        _save_page(page)
        draft = kv_get(f"page:{slug}:draft")
        if draft and isinstance(draft, dict) and draft.get("content_blocks"):
            _apply(draft["content_blocks"])
            kv_set(f"page:{slug}:draft", draft)
        audit_log("page.inplace.blocksync", slug, f"{updated} blok(ken) bijgewerkt vanuit visuele bewerking")
    return updated


# ---------- Blokken hergenereren uit de echte pagina (Bewerken -> Inhoud ALTIJD synchroon) ----------
# Ryan 2026-07-16: "als ik bij Bewerken iets aanpas moet het bij Inhoud ook veranderen".
# De diff-sync hierboven dekt alleen nieuwe wijzigingen; bestaande drift (edits van vóór de
# sync) bleef staan. Structurele oplossing: na elke visuele save de content_blocks VOLLEDIG
# hergenereren uit het snapshot, met dezelfde parser als de oorspronkelijke migratie
# (tools/migrate_elementor_to_blocks.py). Inhoud is daarmee per constructie gelijk aan de
# pagina — ook na toevoegen/verwijderen/verplaatsen in de visuele editor.
# Vereist beautifulsoup4 (requirements.txt); zonder bs4 valt dit stil terug op de diff-sync.

_REGEN_CONTENT_TYPES = {"wp-post", "wp-page", "single-page", "single-post", "single"}
_REGEN_INLINE_TAGS = re.compile(r"<(a|strong|em|b|i|span|br|sub|sup|mark|code)\b", re.I)


def _regen_section_blocks(sec, widget_to_blocks, _txt):
    """Herken rijke Elementor-secties en geef ze terug als ÉÉN samengesteld blok i.p.v. losse
    platte blokken. Zonder dit werd 'tekst naast foto' een kop + alinea + zwevende foto en
    verloren gegenereerde pagina's hun opmaak bij het omzetten naar blokken (Wim/Ryan 2026-07-20).
    Returns None als het patroon niet past -> beller valt terug op de widget-loop."""
    import re as _re
    cols = [c for c in sec.find_all(class_="elementor-column", recursive=True)
            if not c.find(class_="elementor-column")]
    if not 2 <= len(cols) <= 4:
        return None

    def _img_src(col):
        img = col.find("img")
        if not img:
            return ""
        return (img.get("data-src") or img.get("src") or "").strip()

    def _col_text(col):
        h = col.find(_re.compile(r"^h[1-6]$"))
        ps = [p for p in col.find_all("p") if _txt(p)]
        lis = [_txt(li) for li in col.find_all("li") if _txt(li)]
        return (_txt(h) if h else ""), [_txt(p) for p in ps], lis

    # A) twee kolommen: één met (alleen) beeld, één met tekst -> feature-row
    if len(cols) == 2:
        pics = [i for i, c in enumerate(cols) if _img_src(c) and not _txt(c)]
        if len(pics) == 1:
            pi = pics[0]
            ti = 1 - pi
            head, paras, bullets = _col_text(cols[ti])
            src = _img_src(cols[pi])
            if src and (head or paras):
                blk = {"type": "feature-row", "heading": head, "text": " ".join(paras[:2]),
                       "image": src, "image_alt": head or "", "flip": pi == 0}
                if bullets:
                    blk["bullets"] = bullets[:7]
                return [blk]

    # A2) één kolom met kop + foto + tekst (de andere kolom leeg): dit is de praktijkvorm op de
    #     oudere gegenereerde dienstpagina's. Platgeslagen wordt de foto een zwevend blok MIDDEN
    #     in de tekst ("raar design", Ryan 2026-07-20) — als feature-row staat beeld nét naast tekst.
    if len(cols) == 2:
        vulled = [c for c in cols if _txt(c) or _img_src(c)]
        if len(vulled) == 1:
            c = vulled[0]
            head, paras, bullets = _col_text(c)
            src = _img_src(c)
            if src and head and paras:
                blk = {"type": "feature-row", "heading": head, "text": " ".join(paras[:2]),
                       "image": src, "image_alt": head, "flip": False}
                if bullets:
                    blk["bullets"] = bullets[:7]
                return [blk]

    # C) reeks icon-box-kaarten in dezelfde sectie -> feature-grid (Ryan 2026-07-20).
    _cards = []
    for w in sec.find_all(class_="elementor-widget"):
        if w.find(class_="elementor-widget"):
            continue
        _cl = " ".join(w.get("class", []))
        if "elementor-widget-icon-box" in _cl or "elementor-widget-image-box" in _cl:
            cont = w.find(class_="elementor-widget-container") or w
            t = _txt(cont.find(class_=_re.compile(r"(icon-box|image-box)-title")))
            d = _txt(cont.find(class_=_re.compile(r"(icon-box|image-box)-description")))
            if t:
                _cards.append({"icon": "check", "title": t, "text": d or ""})
    if len(_cards) >= 3:
        return [{"type": "feature-grid", "columns": min(4, len(_cards)), "items": _cards}]

    # B) 3-4 gelijkvormige kolommen met icoon/kop/tekst -> feature-grid
    if len(cols) >= 3:
        items = []
        for c in cols:
            head, paras, _ = _col_text(c)
            if not head:
                continue
            items.append({"icon": "check", "title": head, "text": (paras[0] if paras else "")})
        if len(items) == len(cols):
            return [{"type": "feature-grid", "columns": min(4, len(items)), "items": items}]
    return None


def _regen_blocks_from_html(html: str):
    """Parseer een pagina-snapshot naar platte content_blocks (zelfde vorm als de migratie).
    Returns list, of None als bs4 ontbreekt of er geen Elementor-content-root is."""
    try:
        from bs4 import BeautifulSoup, NavigableString, Tag  # lazy: pas nodig bij visuele saves
    except Exception:
        return None

    def _txt(el):
        return el.get_text(" ", strip=True) if el else ""

    def _heading_level(container):
        h = container.find(re.compile(r"^h[1-6]$"))
        if h:
            try:
                return min(int(h.name[1]), 4)
            except Exception:
                pass
        return 2

    def frag_to_blocks(raw):
        out = []
        soup = BeautifulSoup(f"<div id='__r'>{raw}</div>", "html.parser")
        root = soup.find(id="__r")
        for node in root.children:
            if isinstance(node, NavigableString):
                t = str(node).strip()
                if t:
                    out.append({"type": "paragraph", "text": t})
                continue
            if not isinstance(node, Tag):
                continue
            tag = node.name.lower()
            if re.match(r"^h[1-6]$", tag):
                out.append({"type": f"heading-h{min(int(tag[1]), 4)}", "text": _txt(node)})
            elif tag == "p":
                # Altijd als tekstblok (Wim: html-raw was onwerkbaar). Inline-opmaak (link/bold)
                # blijft live intact zolang de alinea niet wordt aangepast; bij bewerking pakt
                # de tag-tolerante locked-sync de vervanging op.
                t = _txt(node)
                if t:
                    out.append({"type": "paragraph", "text": t})
            elif tag in ("ul", "ol"):
                items = [_txt(li) for li in node.find_all("li", recursive=False)]
                items = [i for i in items if i]
                if items:
                    out.append({"type": "list-ul" if tag == "ul" else "list-ol", "items": "\n".join(items)})
            elif tag == "blockquote":
                out.append({"type": "quote", "text": _txt(node)})
            elif tag == "img":
                src = node.get("src") or node.get("data-src") or ""
                if src:
                    out.append({"type": "image", "url": src, "alt": node.get("alt", "")})
            elif tag == "hr":
                out.append({"type": "hr"})
            else:
                # Container met herkenbare inhoud? Recursief uitpakken i.p.v. één grote
                # html-raw-brok — dienstpagina's bestonden anders "bijna helemaal uit html".
                if isinstance(node, Tag) and len(node.find_all(re.compile(r"^(h[1-6]|p|ul|ol|img)$"))) >= 2:
                    out.extend(frag_to_blocks(node.decode_contents()))
                    continue
                frag = str(node).strip()
                if frag and (_txt(node) or node.find("img")):
                    out.append({"type": "html-raw", "url": frag})
        return out

    def widget_to_blocks(widget):
        cls = " ".join(widget.get("class", []))
        m = re.search(r"elementor-widget-([\w-]+)", cls)
        wtype = m.group(1) if m else ""
        container = widget.find(class_="elementor-widget-container") or widget
        if wtype == "heading":
            h = container.find(class_="elementor-heading-title") or container.find(re.compile(r"^h[1-6]$"))
            text = _txt(h or container)
            return [{"type": f"heading-h{_heading_level(container)}", "text": text}] if text else []
        if wtype in ("text-editor", "theme-post-content"):
            return frag_to_blocks(container.decode_contents())
        if wtype in ("image", "theme-post-featured-image"):
            img = container.find("img")
            if not img:
                return []
            src = img.get("src") or img.get("data-src") or ""
            return [{"type": "image", "url": src, "alt": img.get("alt", "")}] if src else []
        if wtype == "button":
            a = container.find("a")
            if not a:
                return []
            return [{"type": "button", "text": _txt(a) or "Lees meer", "url": a.get("href", "#")}]
        if wtype == "icon-list":
            items = [_txt(li) for li in container.select(".elementor-icon-list-text")]
            items = [i for i in items if i] or [_txt(li) for li in container.find_all("li")]
            items = [i for i in items if i]
            return [{"type": "list-ul", "items": "\n".join(items)}] if items else []
        if wtype in ("icon-box", "image-box"):
            title = _txt(container.find(class_=re.compile(r"(icon-box|image-box)-title")))
            desc = _txt(container.find(class_=re.compile(r"(icon-box|image-box)-description")))
            # Merk de kaart zodat de naverwerking opeenvolgende icon-boxes tot één feature-grid
            # bundelt; los platgeslagen werd dit een reeks losse h3+alinea (Ryan 2026-07-20).
            if title:
                return [{"type": "heading-h3", "text": title, "_card": True},
                        {"type": "paragraph", "text": desc or "", "_card": True}]
            return [{"type": "paragraph", "text": desc}] if desc else []
        # Sier-/carousel-widgets van Unlimited Elements lekken hun bron-commentaar en scripts als
        # platte tekst ("start Icon Carousel"); bij een blok-reconstructie laten we ze weg.
        if wtype.startswith("ucaddon_") or wtype == "shortcode":
            return []
        if wtype == "divider":
            return [{"type": "hr"}]
        if wtype == "spacer":
            return [{"type": "spacer", "height": 32}]
        if wtype == "video":
            iframe = container.find("iframe")
            src = (iframe.get("src") if iframe else "") or ""
            if "youtube" in src or "youtu.be" in src:
                return [{"type": "video-youtube", "url": src}]
            frag = str(container).strip()
            return [{"type": "html-raw", "url": frag}] if frag else []
        titles = container.select(".bdt-ep-accordion-title, .elementor-tab-title, .elementor-toggle-title")
        contents = container.select(".bdt-ep-accordion-content, .elementor-tab-content, .elementor-toggle-content")
        if titles and contents and len(titles) == len(contents):
            faqs = []
            for ti, co in zip(titles, contents):
                q, a = _txt(ti), _txt(co)
                if q:
                    faqs.append({"type": "faq-item", "question": q, "answer": a})
            if faqs:
                return faqs
        if wtype == "button":
            a = container.find("a")
            if not a:
                return []
            return [{"type": "button", "text": _txt(a) or "Lees meer", "url": a.get("href", "#")}]
        if wtype == "icon-list":
            items = [_txt(li) for li in container.select(".elementor-icon-list-text")]
            items = [i for i in items if i] or [_txt(li) for li in container.find_all("li")]
            items = [i for i in items if i]
            return [{"type": "list-ul", "items": "\n".join(items)}] if items else []
        if wtype in ("icon-box", "image-box"):
            title = _txt(container.find(class_=re.compile(r"(icon-box|image-box)-title")))
            desc = _txt(container.find(class_=re.compile(r"(icon-box|image-box)-description")))
            # Merk de kaart zodat de naverwerking opeenvolgende icon-boxes tot één feature-grid
            # bundelt; los platgeslagen werd dit een reeks losse h3+alinea (Ryan 2026-07-20).
            if title:
                return [{"type": "heading-h3", "text": title, "_card": True},
                        {"type": "paragraph", "text": desc or "", "_card": True}]
            return [{"type": "paragraph", "text": desc}] if desc else []
        # Sier-/carousel-widgets van Unlimited Elements lekken hun bron-commentaar en scripts als
        # platte tekst ("start Icon Carousel"); bij een blok-reconstructie laten we ze weg.
        if wtype.startswith("ucaddon_") or wtype == "shortcode":
            return []
        if wtype == "divider":
            return [{"type": "hr"}]
        if wtype == "spacer":
            return [{"type": "spacer", "height": 32}]
        if wtype == "video":
            iframe = container.find("iframe")
            src = (iframe.get("src") if iframe else "") or ""
            if "youtube" in src or "youtu.be" in src:
                return [{"type": "video-youtube", "url": src}]
            frag = str(container).strip()
            return [{"type": "html-raw", "url": frag}] if frag else []
        titles = container.select(".bdt-ep-accordion-title, .elementor-tab-title, .elementor-toggle-title")
        contents = container.select(".bdt-ep-accordion-content, .elementor-tab-content, .elementor-toggle-content")
        if titles and contents and len(titles) == len(contents):
            faqs = []
            for ti, co in zip(titles, contents):
                q, a = _txt(ti), _txt(co)
                if q:
                    faqs.append({"type": "faq-item", "question": q, "answer": a})
            if faqs:
                return faqs
        if wtype == "button":
            a = container.find("a")
            if a and _txt(a):
                return [{"type": "button", "text": _txt(a), "href": a.get("href", "#")}]
        if _txt(container) or container.find("img") or container.find("iframe"):
            _inner = container.decode_contents().strip()
            # Losse knop-wrapper -> button-blok (geen rauwe HTML).
            _a = container.find("a", class_=re.compile(r"elementor-button"))
            if _a and _txt(_a) and container.find_all(re.compile(r"^(h[1-6]|p|ul|ol|img)$")) == []:
                return [{"type": "button", "text": _txt(_a), "href": _a.get("href", "#")}]
            _ps = container.find_all("p", recursive=False)
            _others = [c for c in container.find_all(True, recursive=False) if c.name != "p"]
            # Alleen alinea's -> tekstblokken (geen rauwe HTML voor puur tekst).
            if _ps and not _others:
                return frag_to_blocks(_inner)
            if len(container.find_all(re.compile(r"^(h[1-6]|p|ul|ol|img)$"))) >= 2:
                return frag_to_blocks(_inner)
            return [{"type": "html-raw", "url": _inner}]
        return []

    soup = BeautifulSoup(html or "", "html.parser")
    root = None
    for el in soup.find_all(attrs={"data-elementor-type": True}):
        if el.get("data-elementor-type") in _REGEN_CONTENT_TYPES:
            root = el
            break
    if root is None:
        cands = [el for el in soup.find_all(class_="elementor")
                 if el.get("data-elementor-type") not in ("header", "footer")]
        root = max(cands, key=lambda e: len(str(e)), default=None)
    if root is None:
        return None
    blocks = []
    _done = set()
    _secs = [s for s in root.find_all(class_="elementor-section")
             if not s.find(class_="elementor-section")]
    for sec in _secs:
        try:
            rich = _regen_section_blocks(sec, widget_to_blocks, _txt)
        except Exception:
            rich = None
        if rich:
            blocks.extend(rich)
            for w in sec.find_all(class_="elementor-widget"):
                _done.add(id(w))
    out = []
    for w in root.find_all(class_="elementor-widget"):
        if not w.find(class_="elementor-widget") and id(w) not in _done:
            out.append(w)
    for w in out:
        try:
            blocks.extend(widget_to_blocks(w))
        except Exception:
            continue
    # Naverwerking: opeenvolgende icon-box-kaarten (h3+p, gemarkeerd met _card) bundelen tot
    # één feature-grid; losse kaarten "verrommelen" de pagina anders (Ryan 2026-07-20).
    merged, i = [], 0
    while i < len(blocks):
        if blocks[i].get("_card"):
            cards, j = [], i
            while j + 1 < len(blocks) and blocks[j].get("_card") and blocks[j + 1].get("_card") \
                    and blocks[j].get("type", "").startswith("heading") and blocks[j + 1].get("type") == "paragraph":
                cards.append({"icon": "check", "title": blocks[j].get("text", ""), "text": blocks[j + 1].get("text", "")})
                j += 2
            if len(cards) >= 3:
                merged.append({"type": "feature-grid", "columns": min(4, len(cards)), "items": cards})
                i = j
                continue
        b = {k: v for k, v in blocks[i].items() if k != "_card"}
        merged.append(b)
        i += 1
    return merged


def _regen_locked_blocks(slug: str, html: str):
    """Vervang het blokken-record door een verse parse van het snapshot. Returns aantal
    gewijzigde records (0 = al synchroon) of None als regeneratie niet kon (geen bs4/root
    of onbetrouwbaar resultaat) — de aanroeper valt dan terug op de diff-sync."""
    page = _get_page(slug)
    if not page:
        return None
    cur = [b for b in (page.get("content_blocks") or []) if isinstance(b, dict)]
    blocks = _regen_blocks_from_html(html)
    if blocks is None:
        return None
    # Sanity: nooit een verdacht leeg resultaat over een gevuld record heen zetten.
    if len(blocks) < max(1, len(cur) // 2):
        return None
    if json.dumps(blocks, sort_keys=True, ensure_ascii=False) == json.dumps(cur, sort_keys=True, ensure_ascii=False):
        return 0
    page["content_blocks"] = blocks
    _save_page(page)
    draft = kv_get(f"page:{slug}:draft")
    if draft and isinstance(draft, dict):
        draft["content_blocks"] = [dict(b) for b in blocks]
        kv_set(f"page:{slug}:draft", draft)
    audit_log("page.inplace.blocks_regen", slug, f"{len(blocks)} blokken hergenereerd uit visuele save")
    return len(blocks)


@app.route("/api/admin/page-inplace/<path:slug>", methods=["POST", "DELETE"])
def api_page_inplace(slug):
    a = _auth_or_401()
    if a: return a
    # encodeURIComponent in de admin stuurt %2F; Werkzeug decodeert dat NIET in <path:> —
    # zonder unquote kwamen snapshots onder een encoded key ("dienst%2F...") terecht die de
    # serve/bake (decoded) nooit vond -> "gepubliceerd maar niet live" (Ryan 2026-07-16).
    slug = urllib.parse.unquote(slug or "")
    slug = "" if (slug or "").strip("/") == "__home__" else (slug or "").strip("/")
    _enc = urllib.parse.quote(slug, safe="")
    if _enc != slug and kv_get(f"page:{_enc}:inplace") is not None:
        # Heling: eerder onder de encoded key opgeslagen snapshot verplaatsen.
        try:
            if kv_get(f"page:{slug}:inplace") is None:
                kv_set(f"page:{slug}:inplace", kv_get(f"page:{_enc}:inplace"))
            kv_delete(f"page:{_enc}:inplace")
            _i = kv_get("page:inplace:index", []) or []
            _i = [x for x in _i if x != _enc] + ([slug] if slug not in _i else [])
            kv_set("page:inplace:index", _i)
        except Exception:
            pass
    idx = kv_get("page:inplace:index", []) or []
    if request.method == "DELETE":
        kv_delete(f"page:{slug}:inplace")
        if slug in idx:
            kv_set("page:inplace:index", [s for s in idx if s != slug])
        audit_log("page.inplace.revert", slug, "Teruggezet naar origineel")
        return jsonify({"ok": True, "reverted": True})
    body = request.get_json(silent=True) or {}
    html = body.get("html") or ""
    if not html.strip():
        return jsonify({"error": "Lege HTML"}), 400
    _old_html = kv_get(f"page:{slug}:inplace")
    if _old_html is None:
        try:
            _f = _static_page_file(slug)
            _old_html = _f.read_text(encoding="utf-8", errors="replace") if _f.exists() else None
        except Exception:
            _old_html = None
    kv_set(f"page:{slug}:inplace", html)
    if slug not in idx:
        kv_set("page:inplace:index", idx + [slug])
    audit_log("page.inplace.save", slug, f"In-place bewerkt ({len(html)//1024}KB)")
    # Terug-sync: Inhoud-blokken gelijktrekken met de visuele werkelijkheid. Voorkeursroute is
    # volledige regeneratie (dekt ook oude drift en structuurwijzigingen); zonder bs4 valt dit
    # terug op de diff-sync (alleen nieuwe tekstwijzigingen).
    _blocks_updated = 0
    try:
        _regen = _regen_locked_blocks(slug, html)
        if _regen is not None:
            _blocks_updated = _regen
        elif _old_html:
            _blocks_updated = _sync_blocks_from_inplace(slug, _old_html, html)
    except Exception as e:
        audit_log("page.inplace.blocksync_fail", slug, str(e)[:200])
    # Direct her-bakken zodat de edit LIVE gaat (build_apply bakt de snapshot in het statische
    # bestand); zonder trigger bleef de wijziging in KV hangen tot een toevallige volgende deploy.
    _deployed = _trigger_deploy(f"in-place save {slug or '__home__'}")
    return jsonify({"ok": True, "size_kb": round(len(html) / 1024, 1), "deploy_triggered": _deployed,
                    "blocks_updated": _blocks_updated})


@app.route("/api/public/baked-edits", methods=["GET"])
@app.route("/api/public/baked-edits/", methods=["GET"])
def api_public_baked_edits():
    """Bouwtijd-export voor tools/build_apply.py: de in-place snapshots + header/footer.
    BEWUST zonder auth: dit is exact de HTML die de site toch al publiek serveert (geen
    secrets); de build-omgeving heeft geen KV-env (Sensitive vars zijn runtime-only) en
    haalt de te bakken edits daarom via de VORIGE productie-deploy op."""
    out = {"inplace": {}, "header": None, "footer": None}
    try:
        for slug in (kv_get("page:inplace:index", []) or []):
            _dslug = urllib.parse.unquote(slug)
            _rec = _get_page(_dslug)
            if _rec and (_rec.get("status") or "published") != "published":
                continue   # concept/ingepland: NIET publiek lekken via de build-export
            h = kv_get(f"page:{slug}:inplace")
            if h:
                # index kan legacy-encoded slugs bevatten (%2F) — genormaliseerd exporteren
                out["inplace"][_dslug] = h
        out["header"] = kv_get("site:header_html")
        out["footer"] = kv_get("site:footer_html")
    except Exception as e:
        return jsonify({"error": str(e)[:200]}), 500
    r = jsonify(out)
    r.headers["Cache-Control"] = "no-store"
    return r


