@app.route("/api/admin/pages/<path:slug>/duplicate", methods=["POST"])
def api_admin_page_duplicate(slug):
    a = _auth_or_401()
    if a: return a
    slug = _decode_slug(slug)
    body = request.get_json(silent=True) or {}
    src = _get_page(slug)
