@app.route("/api/admin/pages/<path:slug>/publish", methods=["POST"])
@app.route("/api/admin/pages/<path:slug>/publish/", methods=["POST"])
def api_admin_page_publish(slug):
    a = _auth_or_401()
    if a: return a
    slug = _decode_slug(slug)
    page = _get_page(slug)
    if not page:
        # Statische / in-place-only pagina: er is geen block-record, maar de visuele
        # (in-place) save heeft de live HTML al in KV gezet (page:<slug>:inplace) en die
        # wordt direct geserveerd. Publiceren is dan al gebeurd -> geef succes terug.
        if kv_get(f"page:{slug}:inplace") or _static_page_file(slug).exists():
            audit_log("page.publish", slug or "__home__", "Publish (in-place/statisch)")
            _dep = _trigger_deploy("publish in-place " + (slug or "__home__"))
            return jsonify({"slug": slug, "published_at": _now_iso(), "inplace": True, "deploy_triggered": _dep})
        return jsonify({"error": "Niet gevonden"}), 404
    # Merge any draft
    draft = kv_get(f"page:{slug}:draft")
    if draft:
        page.update({k: v for k, v in draft.items() if k != "slug"})
    page["status"] = "published"
    page["published_at"] = _now_iso()
    _push_revision(slug, page, summary="publish")
    try:
        html = render_page_html(page)
        ok, url_or_path = write_rendered_html(slug, html)
    except Exception as e:
        # Toon de échte reden i.p.v. een kale 500 → "Publiceren mislukt" zonder uitleg.
        return jsonify({"error": "Publiceren mislukt bij het renderen van de pagina.",
                        "details": str(e)[:300]}), 500
    kv_delete(f"page:{slug}:draft")
    _save_page(page)
    update_seo_score(page)
    audit_log("page.publish", slug, "Publish")
    _dep = _trigger_deploy("publish " + (slug or "__home__"))
    return jsonify({
        "slug": slug, "published_at": page["published_at"],
        "blob_url": url_or_path, "html_size_kb": round(len(html) / 1024, 1),
        "deploy_triggered": _dep,
    })


@app.route("/api/admin/seo/autofill", methods=["POST"])
@app.route("/api/admin/seo/autofill/", methods=["POST"])
def api_admin_seo_autofill():
    """Backfill: laat de AI-SEO helper alle bestaande pagina's/blog-posts/projecten voorzien
    van complete SEO-metadata. Idempotent — bestaande niet-lege velden blijven staan.

    Body: {"kinds":["page","blog","project"] optional, "limit":50 optional, "force":false optional}.
    """
    a = _auth_or_401()
    if a: return a
    body = request.get_json(silent=True) or {}
    kinds = set(body.get("kinds") or ["page", "blog", "project"])
    limit = int(body.get("limit") or 200)
    force = bool(body.get("force") or False)
    done = {"page": 0, "blog": 0, "project": 0, "skipped": 0, "errors": []}

    def _needs_fill(m: dict) -> bool:
        if force:
            return True
        return not (m or {}).get("description") or not (m or {}).get("schema_jsonld")

    if "page" in kinds:
        # list_pages() kan op sommige sites een dict {'pages':[...]} teruggeven i.p.v. een
        # kale list; unwrap defensief zodat de backfill nooit crasht op de slice.
        _pages = list_pages() or []
        if isinstance(_pages, dict):
            _pages = _pages.get('pages') or []
        for row in _pages[:limit]:
            slug = (row.get("slug") if isinstance(row, dict) else row) or ""
            if not slug:
                continue
            pg = _get_page(slug)
            if not pg:
                continue
            if not _needs_fill(pg.get("meta") or {}):
                done["skipped"] += 1
                continue
            try:
                blocks = pg.get("content_blocks") or []
                _txt = _extract_plaintext(pg.get("title", ""), *(str((b or {}).get("props", {}).get("intro", "")) + " "
                                                                  + str((b or {}).get("props", {}).get("html", "")) + " "
                                                                  + str((b or {}).get("props", {}).get("text", ""))
                                                                for b in blocks if isinstance(b, dict)))
                _seo = _ai_seo_autofill("page", pg.get("title", ""), _txt,
                                        hero_image=_first_image_url_in(blocks),
                                        slug=slug, extras={"template": pg.get("template", "")})
                _apply_seo_to_page(pg, _seo)
                _save_page(pg)
                update_seo_score(pg)
                done["page"] += 1
            except Exception as e:
                done["errors"].append(f"page:{slug}: {e}")
    if "blog" in kinds:
        for summ in (get_posts_index() or [])[:limit]:
            slug = summ.get("slug", "")
            post = get_post(slug)
            if not post:
                continue
            if not _needs_fill(post.get("meta") or {}):
                done["skipped"] += 1
                continue
            try:
                _seo = _ai_seo_autofill("blog", post.get("title", ""),
                                        _extract_plaintext(post.get("body", "")),
                                        hero_image=post.get("featured_image") or _first_image_url_in(post.get("body", "")),
                                        slug=slug, extras={"date": post.get("date", "")})
                m = post.setdefault("meta", {})
                for k, mk in (("seo_title", "title"), ("meta_description", "description"),
                              ("focus_keyword", "keyword"), ("og_title", "og_title"),
                              ("og_description", "og_description"), ("og_image", "og_image"),
                              ("twitter_card", "twitter_card"), ("twitter_image", "twitter_image")):
                    if _seo.get(k) and not m.get(mk):
                        m[mk] = _seo[k]
                if _seo.get("schema_jsonld") and not m.get("schema_jsonld"):
                    m["schema_jsonld"] = _seo["schema_jsonld"]
                if _seo.get("breadcrumb_jsonld") and not m.get("breadcrumb_jsonld"):
                    m["breadcrumb_jsonld"] = _seo["breadcrumb_jsonld"]
                save_post(post)
                done["blog"] += 1
            except Exception as e:
                done["errors"].append(f"blog:{slug}: {e}")
    if "project" in kinds:
        projs = get_projects() or []
        for pr in projs[:limit]:
            if isinstance(pr.get("seo"), dict) and pr["seo"].get("meta_description") and not force:
                done["skipped"] += 1
                continue
            try:
                pr["seo"] = _ai_seo_autofill("project", pr.get("title", ""),
                                             _extract_plaintext(pr.get("description", "")),
                                             hero_image=pr.get("image_url", ""),
                                             slug=pr.get("slug", ""),
                                             location=pr.get("location", ""),
                                             extras={"date": pr.get("date", "")})
                done["project"] += 1
            except Exception as e:
                done["errors"].append(f"project:{pr.get('slug','')}: {e}")
        save_projects(projs)
    audit_log("seo.autofill", "site", f"pages={done['page']} blog={done['blog']} project={done['project']}")
    return jsonify({"ok": True, **done})


@app.route("/api/admin/pages/bulk", methods=["POST"])
def api_admin_pages_bulk():
    a = _auth_or_401()
    if a: return a
    body = request.get_json(silent=True) or {}
    slugs = body.get("slugs") or []
    updates = body.get("updates") or {}
    # Hard delete via deze (bewezen routerende) bulk-route i.p.v. een DELETE/POST op een eigen pad
    # met de slug erin — dat werd op Vercel geblokkeerd (platform 403 / foutpagina).
    if body.get("action") == "delete":
        deleted = 0
        for s in slugs:
            try:
                _do_page_delete(s, {})
                deleted += 1
            except Exception:
                pass
        audit_log("pages.bulk", "*", f"Bulk delete {deleted} pages")
        return jsonify({"deleted": deleted})
    updated = 0
    failed = []
    for s in slugs:
        page = _get_page(_safe_slug(s))
        if not page:
            failed.append({"slug": s, "error": "not found"})
            continue
        try:
            if "meta" in updates and isinstance(updates["meta"], dict):
                page.setdefault("meta", {}).update(updates["meta"])
            if "status" in updates:
                page["status"] = updates["status"]
            _save_page(page)
            update_seo_score(page)
            updated += 1
        except Exception as e:
            failed.append({"slug": s, "error": str(e)})
    audit_log("pages.bulk", "*", f"Bulk update {updated} pages")
    return jsonify({"updated": updated, "failed": failed})


@app.route("/api/admin/pages/export", methods=["GET"])
def api_admin_pages_export():
    a = _auth_or_401()
    if a: return a
    fields = (request.args.get("fields") or "slug,title,status,meta.description").split(",")
    items = _pages_index()
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(fields)
    for it in items:
        page = _get_page(it["slug"]) or it
        row = []
        for f in fields:
            if "." in f:
                a_, b_ = f.split(".", 1)
                row.append(((page.get(a_) or {}).get(b_, "")) if isinstance(page.get(a_), dict) else "")
            else:
                row.append(page.get(f, ""))
        writer.writerow(row)
    resp = make_response(buf.getvalue())
    resp.headers["Content-Type"] = "text/csv; charset=utf-8"
    resp.headers["Content-Disposition"] = "attachment; filename=pages.csv"
    return resp


@app.route("/api/admin/pages/import", methods=["POST"])
def api_admin_pages_import():
    a = _auth_or_401()
    if a: return a
    f = request.files.get("file")
    if not f:
        return jsonify({"error": "Geen bestand"}), 400
    created = updated = 0
    errors = []
    try:
        text = f.read().decode("utf-8", errors="replace")
        reader = csv.DictReader(io.StringIO(text))
        for row in reader:
            try:
                slug = _safe_slug(row.get("slug", ""))
                if not slug:
                    errors.append({"row": row, "error": "no slug"}); continue
                page = _get_page(slug)
                if page:
                    if row.get("title"): page["title"] = row["title"]
                    for mk in ("description", "canonical", "robots", "og_image", "keyword"):
                        if row.get(f"meta.{mk}") is not None:
                            page.setdefault("meta", {})[mk] = row[f"meta.{mk}"]
                    _save_page(page); updated += 1
                else:
                    page = _default_page(slug, row.get("title", slug))
                    _save_page(page); created += 1
            except Exception as e:
                errors.append({"row": row, "error": str(e)})
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    audit_log("pages.import", "*", f"Imported csv: +{created} ~{updated}")
    return jsonify({"created": created, "updated": updated, "errors": errors})


@app.route("/api/admin/pages/<path:slug>/preview", methods=["GET"])
def api_admin_page_preview(slug):
    a = _auth_or_401()
    if a: return a
    slug = _decode_slug(slug)
    page = _get_page(slug)
    if not page:
        return Response("Pagina niet gevonden", status=404)
    html = render_page_html(page)
    viewport = request.args.get("viewport", "desktop")
    width = {"mobile": 375, "tablet": 768, "desktop": 1280}.get(viewport, 1280)
    wrapper = (f"<style>body{{margin:0;background:#eee}}.preview{{margin:0 auto;width:{width}px;"
               f"box-shadow:0 8px 24px rgba(0,0,0,.15);background:#fff;min-height:100vh}}</style>"
               f'<div class="preview">{html}</div>')
    return Response(wrapper, mimetype="text/html")


@app.route("/api/admin/pages/<path:slug>/validate", methods=["POST"])
def api_admin_page_validate(slug):
    a = _auth_or_401()
    if a: return a
    slug = _decode_slug(slug)
    page = _get_page(slug)
    if not page:
        return jsonify({"error": "Niet gevonden"}), 404
    res = compute_seo_score(page)
    # Broken-link scan (internal only — synchronous)
    warnings = []
    for b in page.get("content_blocks", []) or []:
        props = b.get("props", {}) or {}
        href = props.get("href")
        if href and href.startswith("/"):
            target = _safe_slug(href)
            if target and not _get_page(target):
                warnings.append({"severity": "warn", "field": "link", "message": f"Interne link {href} bestaat niet"})
    return jsonify({"score": res["score"], "issues": res["issues"], "warnings": warnings})


