@app.route("/api/admin/locatie-template/create", methods=["POST"])
def api_locatie_template_create():
    a = _require_agency()
    if a: return a
    body = request.get_json(silent=True) or {}
    slug_in = (body.get("slug") or "").strip().strip("/")
    if not slug_in: return jsonify({"error": "slug verplicht"}), 400
    for _pfx in ("diensten/", "locatie/"):
        if slug_in.startswith(_pfx):
            slug_in = slug_in[len(_pfx):]
    slug = _safe_slug(slug_in)
    full_slug = f"locatie/{slug}"
    stad = (body.get("stad") or "").strip() or slug.replace("infra-in-", "").replace("-", " ").title()
    dienst_name = (body.get("dienst_name") or f"Infrawerkpraktijk in {stad}").strip()
    meta_desc = (body.get("meta_description") or "").strip()
    sections = body.get("sections") or []
    faq = body.get("faq") or []
    usp_cards = body.get("usp_cards") or []
    hero_image = body.get("hero_image", "")
    seo_data = _extract_seo(body)
    seo_data["seo_canonical"] = (seo_data.get("seo_canonical") or "").strip() or f"{CANONICAL_BASE}/{full_slug}/"

    try:
        html = _render_locatie_html(
            slug=slug, dienst_name=dienst_name, stad=stad,
            meta_description=meta_desc, sections=sections, faq=faq,
            hero_image=hero_image, usp_cards=usp_cards, seo=seo_data,
            bullets=body.get("bullets", []) or [],
        )
    except Exception as e:
        return jsonify({"error": "render failed", "details": str(e)}), 500

    kv_set(f"dienst-html:{slug}", html)
    page = _default_page(full_slug, dienst_name, template="locatie-1to1")
    page["status"] = "draft" if str(body.get("status") or "").lower() == "draft" else "published"
    page["meta"]["description"] = meta_desc
    page["meta"]["canonical"] = seo_data.get("seo_canonical") or f"{CANONICAL_BASE}/locatie/{slug}/"
    page["meta"]["og_title"] = seo_data.get("seo_og_title") or f"{dienst_name} | DAM Housing"
    page["meta"]["og_description"] = seo_data.get("seo_og_description") or meta_desc
    page["meta"]["og_image"] = hero_image
    if seo_data.get("seo_jsonld"):
        try: page["meta"]["schema_jsonld"] = json.loads(seo_data["seo_jsonld"])
        except Exception: pass
    page["locatie_slots"] = {
        "dienst_name": dienst_name, "stad": stad, "meta_description": meta_desc,
        "hero_image": hero_image, "sections": sections, "faq": faq, "usp_cards": usp_cards,
    }
    page["rendered_html_kb"] = round(len(html) / 1024, 1)
    _save_page(page)
    audit_log("locatie.create", full_slug, f"Locatie '{dienst_name}' aangemaakt")
    return jsonify({
        "slug": full_slug, "url": f"/locatie/{slug}/",
        "redirect_admin": f"/admin/#page-editor/{full_slug}",
        "html_kb": round(len(html) / 1024, 1),
    }), 201


def _loads_lenient(raw: str):
    """Tolerante JSON-parse voor AI-output. Verhelpt de gangbare LLM-fouten die json.loads
    breken: code-fences/uitleg eromheen, tekst vóór/na het object, trailing comma's en
    losse newlines/tabs binnen strings (strict=False). Returnt dict/list of None."""
    if not raw:
        return None
    s = raw.strip()
    s = re.sub(r"^```(?:json)?\s*", "", s)
    s = re.sub(r"\s*```$", "", s).strip()
    i, j = s.find("{"), s.rfind("}")
    if i >= 0 and j > i:
        s = s[i:j + 1]
    s2 = re.sub(r",(\s*[}\]])", r"\1", s)  # trailing comma's
    for cand in (s, s2):
        try:
            return json.loads(cand, strict=False)  # strict=False: losse \n/\t in strings toegestaan
        except Exception:
            continue
    # Laatste redmiddel: AFGEKAPTE JSON (model raakte max_tokens) repareren — rewind naar de laatste
    # complete waarde-grens en sluit de open arrays/objecten. Redt zoveel mogelijk i.p.v. alles te lozen.
    repaired = _repair_truncated_json(s)
    if repaired:
        try:
            return json.loads(repaired, strict=False)
        except Exception:
            pass
    return None


def _repair_truncated_json(s):
    """Repareer afgekapte JSON (model raakte max_tokens): sluit een eventueel openstaande string,
    strip een dangling `,`/`:`/halve sleutel, en sluit de nog-open arrays/objecten. Redt zoveel
    mogelijk — ook als de afkap midden in de éérste string-waarde zat."""
    if not s:
        return None
    in_str = esc = False
    stack = []
    for ch in s:
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch in "{[":
            stack.append("}" if ch == "{" else "]")
        elif ch in "}]":
            if stack:
                stack.pop()
    out = s
    if in_str:
        out += '"'                                  # sluit de afgekapte string-waarde
    out = out.rstrip()
    out = re.sub(r"[:,]\s*$", "", out)              # dangling : of , aan het eind
    out = re.sub(r',\s*"[^"]*"\s*$', "", out)       # dangling "sleutel" zonder waarde
    if not stack:
        return None
    return out + "".join(reversed(stack))


@app.route("/api/admin/locatie-template/ai-fill", methods=["POST"])
def api_locatie_template_ai_fill():
    a = _require_agency()
    if a: return a
    if not _ai_configured():
        return jsonify({"error": "Geen Claude API-key ingesteld — vul 'm in bij Instellingen → Integraties → Claude (Anthropic)."}), 503
    body = request.get_json(silent=True) or {}
    stad = (body.get("stad") or "").strip()
    prompt = (body.get("prompt") or "").strip()
    # Als stad ontbreekt maar prompt aanwezig: laat AI stad zelf extraheren
    if not stad and not prompt:
        return jsonify({"error": "stad of prompt verplicht"}), 400
    defaults = _load_locatie_template_defaults()
    ref_sections = defaults.get("sections", [])
    ref_faq = defaults.get("faq", [])
    ref_usp = defaults.get("usp_cards", [])
    target_lengths = [max(40, len((s.get('body') or '').split())) for s in ref_sections[:8]]
    targets_str = ", ".join(f"sec{i+1}: ~{w} wrd" for i, w in enumerate(target_lengths))
    try: available_pages = _ai_context_pages(25)
    except Exception: available_pages = []
    try: available_media = _ai_context_media(20)
    except Exception: available_media = []
    system = (
        "Je schrijft locatie-SEO-content voor DAM Housing (vakkundig vloeren leggen). "
        "Tone: vakkundig, 'u'-vorm, lokaal sterk gericht op de stad. "
        "Returneer STRIKT geldige JSON in deze vorm: "
        "{\"stad\":\"<Stad>\",\"slug\":\"infra-in-<stad>\","
        "\"dienst_name\":\"Infrawerkpraktijk in <Stad>\",\"meta_description\":\"...max 160\","
        "\"hero_image\":\"<URL letterlijk uit de medialijst hieronder>\","
        "\"sections\":[{\"h2\":\"...\",\"body\":\"...met [markdown links](/diensten/x/) waar relevant\","
        "\"image_url\":\"<URL letterlijk uit de medialijst, of leeg>\"} x8],"
        "\"faq\":[{\"q\":\"...\",\"a\":\"...\"} x5],"
        "\"usp_cards\":[{\"h4\":\"...max 30 chars\",\"body\":\"...max 100 chars\"} x3]}. "
        "VERZIN NOOIT EEN AFBEELDINGSPAD: gebruik uitsluitend URL's die letterlijk in "
        "de medialijst hieronder staan, of laat het veld leeg. Een verzonnen pad geeft "
        "een lege hero en een gebroken afbeelding op de gepubliceerde pagina. "
        "Geen markdown code fences. Geen uitleg. "
        "SLUG: lowercase, alleen letters/cijfers/streepjes, vorm 'infra-in-<stadnaam>'. "
        "STAD: als de gebruiker een stad in de prompt noemt, gebruik die exact. "
        "HERO_IMAGE: kies de meest pakkende foto uit media-lijst die past bij infrawerken, of laat leeg. "
        "INTERNE LINKS: scan de body-tekst actief op zinsdelen waarin je een andere bestaande pagina kunt noemen, "
        "en wikkel die in [tekst](/url/) markdown. Max 2 links per sectie, alleen "
        "relevante diensten uit de meegegeven pagina-lijst. "
        "IMAGE_URL per sectie: kies passende foto uit media-lijst, of leeg laten als geen match."
    )
    user_msg = (
        f"Stad: {stad}\n"
        f"Extra context: {prompt or '(geen)'}\n\n"
        "Schrijf 8 secties + 5 FAQ items + 3 USP cards voor een infra-in-stad pagina, in dezelfde stijl als deze referentie:\n"
        f"SECTIONS: {json.dumps(ref_sections, ensure_ascii=False)[:2500]}\n"
        f"FAQ: {json.dumps(ref_faq, ensure_ascii=False)[:1500]}\n"
        f"USP_CARDS (3x): {json.dumps(ref_usp, ensure_ascii=False)}\n\n"
        f"BESCHIKBARE PAGINA'S voor interne links (gebruik in body-tekst waar relevant): "
        f"{json.dumps(available_pages, ensure_ascii=False)[:1800]}\n\n"
        f"BESCHIKBARE MEDIA voor image_url (alleen exact match):\n"
        f"{json.dumps(available_media, ensure_ascii=False)[:1500]}\n\n"
        f"Houd lengtes aan: {targets_str}.\n"
        "Vervang inhoud, behoud opbouw en intent. "
        "Sectie 1 = hero met 'Vloerenbedrijf in <Stad>'. Verwerk lokale referenties (regio, dichtbije steden, prijzen voor de stad). "
        "USP-cards: 3 korte krachtige claims (echte vakmannen, alles onder één dak, ervaring). "
        "BELANGRIJK: in elke sectie waar je een gerelateerde dienst noemt (zoals pvc-vloeren, vloeren egaliseren, trappenrenovatie, vloerverwarming), "
        "wikkel die woorden in markdown links naar de bestaande dienst-pagina's. "
        "Schrijf INHOUDELIJK rijk, geen vulwoorden."
    )
    result = _anthropic_call(
        messages=[{"role": "user", "content": user_msg}],
        system=system,
        max_tokens=6000,
        model="claude-haiku-4-5-20251001",
    )
    if "error" in result:
        return jsonify({"error": "AI-call mislukt", "details": result}), 502
    raw = "".join(b.get("text", "") for b in (result.get("content") or []) if isinstance(b, dict))
    data = _loads_lenient(raw)
    if data is None:
        return jsonify({"error": "Ongeldige JSON van AI", "raw": raw[:400]}), 502
    return jsonify(data)


# Avoid name conflict — use stdlib's html.escape via alias
from html import escape as html_escape  # noqa: E402


def _ai_context_pages(limit: int = 30) -> list:
    """Lijst van pagina's die AI kan gebruiken voor auto-linking in body-tekst."""
    pages = []
    seen = set()
    # Eerst KV/bootstrap pages (de gemigreerde sites)
    for entry in _pages_index()[:limit]:
        slug = entry.get("slug", "")
        title = entry.get("title", "")
        url = f"/{slug}/" if not slug.startswith("/") else slug
        if slug and slug not in seen:
            seen.add(slug)
            pages.append({"title": title, "url": url, "slug": slug})
    # Plus statische pages (uit list_pages bundle)
    for p in list_pages():
        if isinstance(p, dict):
            slug = p.get("slug", ""); title = p.get("title", ""); url = p.get("url", f"/{slug}/")
        else:
            slug = str(p).strip("/"); title = slug.replace("-", " ").title(); url = f"/{slug}/"
        if slug and slug not in seen and len(pages) < limit:
            seen.add(slug)
            pages.append({
                "title": (title or slug).replace(" - DAM Housing", ""),
                "url": url,
                "slug": slug,
            })
    return pages


def _ai_context_media(limit: int = 30) -> list:
    """Lijst van bruikbare media-bestanden (gefilterd op naam-relevantie).

    Let op de item-vorm: media uit KV/bootstrap heeft {url, filename, alt, mime, bytes};
    de oude WP-variant had {url, name, size_kb}. We lezen beide. De oude size_kb-check
    filterde hier maandenlang ÁLLES weg (dat veld bestaat in de KV-vorm niet), waardoor
    de AI nooit een foto te zien kreeg en o.a. GBP-posts stil zonder beeld verschenen.
    Onbekende grootte (bytes 0/ontbrekend, bv. een externe URL) telt daarom als bruikbaar."""
    media = list_media()
    # Filter: alleen content images, geen logos/favicons/thumbnails
    good = []
    seen_names = set()
    for m in media:
        if not isinstance(m, dict): continue
        url = m.get("url", "")
        name = (m.get("name") or m.get("filename") or url.rsplit("/", 1)[-1] or "")
        alt = (m.get("alt") or "")
        ext = (m.get("ext") or m.get("type") or (url.rsplit(".", 1)[-1] if "." in url else "")).lower()
        if ext not in ("jpg", "jpeg", "png", "webp"):
            continue
        ruis = (url + " " + name).lower()
        if any(t in ruis for t in ("logo", "favicon", "gravatar", "icon", "sprite", "placeholder", "avatar")):
            continue
        if "scaled" in name.lower() and "-scaled" in name:
            continue
        # Skip tiny versies (vaak thumbnails) — maar alleen als we de grootte écht kennen
        kb = m.get("size_kb") or ((m.get("bytes") or 0) / 1024)
        if kb and kb < 30:
            continue
        # Dedup: skip als basename al bestaat (verschillende sizes)
        base = re.sub(r"-\d+x\d+", "", name)
        if base in seen_names: continue
        seen_names.add(base)
        good.append({"url": url, "name": name, "alt": alt})
        if len(good) >= limit: break
    return good


def _render_inline_with_links(text: str) -> str:
    """Sta '[text](url)' Markdown-links toe binnen body-tekst. Alle andere HTML wordt escaped.
    Wim selecteert tekst in form → krijgt link-picker → wij injecteren [tekst](url) in textarea.
    Bij render zetten wij dat om naar <a href="url">tekst</a>. Veilig: tekst+url worden escaped.
    """
    if not text:
        return ""
    parts = []
    last_end = 0
    for m in re.finditer(r"\[([^\]]+)\]\(([^)\s]+)\)", text):
        parts.append(html_escape(text[last_end:m.start()]))
        link_text = html_escape(m.group(1))
        link_url = html_escape(m.group(2))
        # Externe URL → target=_blank
        rel_attr = ' target="_blank" rel="noopener"' if link_url.startswith(("http://", "https://")) else ""
        parts.append(f'<a href="{link_url}"{rel_attr} class="ms-inline-link" style="color:#f07d22">{link_text}</a>')
        last_end = m.end()
    parts.append(html_escape(text[last_end:]))
    return "".join(parts)


