def _extract_seo(body: dict) -> dict:
    """Haal alle SEO-veld waardes uit de form body."""
    return {k: body.get(k) for k in [
        "seo_title","seo_keyword","seo_canonical","seo_index","seo_follow","seo_noarchive",
        "seo_og_title","seo_og_description","seo_twitter_card","seo_jsonld","seo_hreflang"
    ] if body.get(k) is not None}


@app.route("/api/admin/dienst-template/create", methods=["POST"])
def api_dienst_template_create():
    """Maak een nieuwe dienst-pagina aan op basis van het infrawerken-design.

    Body: {
      slug: "betoncire",          # → /diensten/betoncire/
      dienst_name: "Betoncire",
      meta_description: "...",
      hero_image: "<URL uit de mediabibliotheek>" (optioneel),
      sections: [{h2, body}, ... max 8]
    }
    Returns: {slug, url, redirect}
    """
    a = _require_agency()
    if a: return a
    body = request.get_json(silent=True) or {}
    slug_in = (body.get("slug") or "").strip().strip("/")
    if not slug_in:
        return jsonify({"error": "slug verplicht"}), 400
    if slug_in.startswith("diensten/"):
        slug_in = slug_in[len("diensten/"):]
    slug = _safe_slug(slug_in)
    full_slug = f"diensten/{slug}"
    dienst_name = (body.get("dienst_name") or slug.replace("-", " ").title()).strip()
    meta_desc = (body.get("meta_description") or "").strip()
    sections = body.get("sections") or []
    hero_image = body.get("hero_image", "")
    if not sections or not isinstance(sections, list):
        return jsonify({"error": "sections verplicht (min 1)"}), 400

    seo_data = _extract_seo(body)
    try:
        html = _render_dienst_html(
            slug=slug,
            dienst_name=dienst_name,
            meta_description=meta_desc,
            sections=sections,
            hero_image=hero_image,
            seo=seo_data,
            bullets=body.get("bullets", []) or [],
        )
    except Exception as e:
        return jsonify({"error": "render failed", "details": str(e)}), 500

    # Opslaan: HTML in KV onder 'dienst-html:<slug>', + page-record voor admin index
    kv_set(f"dienst-html:{slug}", html)
    page = _default_page(full_slug, dienst_name, template="dienst-1to1")
    page["status"] = "published"
    page["meta"]["description"] = meta_desc
    page["meta"]["canonical"] = seo_data.get("seo_canonical") or f"{CANONICAL_BASE}/diensten/{slug}/"
    page["meta"]["og_title"] = seo_data.get("seo_og_title") or f"{dienst_name} - DAM Housing"
    page["meta"]["og_description"] = seo_data.get("seo_og_description") or meta_desc
    page["meta"]["og_image"] = hero_image
    if seo_data.get("seo_jsonld"):
        try: page["meta"]["schema_jsonld"] = json.loads(seo_data["seo_jsonld"])
        except Exception: pass
    # Bewaar de slots zodat we kunnen re-renderen bij latere edits
    page["dienst_slots"] = {
        "dienst_name": dienst_name,
        "meta_description": meta_desc,
        "hero_image": hero_image,
        "sections": sections,
        "seo": seo_data,
    }
    page["rendered_html_kb"] = round(len(html) / 1024, 1)
    _save_page(page)
    audit_log("dienst.create", full_slug, f"Dienst-pagina '{dienst_name}' aangemaakt")

    return jsonify({
        "slug": full_slug,
        "url": f"/diensten/{slug}/",
        "redirect_admin": f"/admin/#page-editor/{full_slug}",
        "html_kb": round(len(html) / 1024, 1),
    }), 201


@app.route("/api/admin/dienst-template/ai-fill", methods=["POST"])
def api_dienst_template_ai_fill():
    """Gebruik Claude om dienst-naam + korte prompt om te zetten in 8 H2+body secties.
    Vult de form-velden zodat Wim alleen nog hoeft te reviewen.
    """
    a = _require_agency()
    if a: return a
    if not _ai_configured():
        return jsonify({"error": "Geen Claude API-key ingesteld — vul 'm in bij Instellingen → Integraties → Claude (Anthropic)."}), 503
    body = request.get_json(silent=True) or {}
    dienst_name = (body.get("dienst_name") or "").strip()
    prompt = (body.get("prompt") or "").strip()
    if not dienst_name and not prompt:
        return jsonify({"error": "dienst_name of prompt verplicht"}), 400

    defaults = _load_dienst_template_defaults()
    reference_sections = defaults.get("sections", [])

    # Bereken doel-woordlengte per sectie op basis van referentie
    target_lengths = []
    for s in reference_sections[:8]:
        wc = len((s.get('body') or '').split())
        target_lengths.append(max(40, wc))  # minimum 40 woorden
    targets_str = ", ".join(f"sectie {i+1}: ~{w} woorden" for i, w in enumerate(target_lengths))
    available_pages = _ai_context_pages(25)
    available_media = _ai_context_media(20)

    system = (
        "Je schrijft SEO-content voor DAM Housing (Nederlands vloerenbedrijf). "
        "Tone: vakkundig, no-nonsense, 'u'-vorm. "
        "Returneer STRIKT geldige JSON in deze vorm: "
        "{\"dienst_name\":\"...\",\"slug\":\"<dienst-naam>\",\"meta_description\":\"max 160 chars\","
        "\"hero_image\":\"<URL letterlijk uit de medialijst hieronder>\","
        "\"sections\":[{\"h2\":\"...\",\"body\":\"paragraaf 1 met [markdown links](/diensten/x/) waar relevant\\n\\nparagraaf 2 (optioneel)\","
        "\"image_url\":\"<URL letterlijk uit de medialijst, of leeg>\"}, ... EXACT 8 items]}. "
        "VERZIN NOOIT EEN AFBEELDINGSPAD: alleen URL's die letterlijk in de medialijst "
        "staan, anders leeg laten. "
        "Geen markdown code-fences. Geen uitleg. Alleen het JSON object. "
        "SLUG: lowercase, alleen letters/cijfers/streepjes, gebruik dienst-naam zonder spaties. "
        "HERO_IMAGE: kies de meest pakkende foto uit media-lijst, of laat leeg. "
        "INTERNE LINKS: scan tijdens schrijven actief op zinsdelen die naar bestaande pagina's verwijzen "
        "(zoals 'stucwerk', 'latex spuiten', 'houtschilderwerk') — wikkel die in [tekst](/url/) markdown. "
        "Max 2 links per sectie, alleen uit de meegegeven pagina-lijst. "
        "IMAGE_URL: kies een afbeelding uit de meegegeven media-lijst als exact passend, anders leeg laten."
    )
    user_msg = (
        f"Dienst: {dienst_name or '(uit prompt)'}\n"
        f"Prompt/context: {prompt or '(geen)'}\n\n"
        f"Schrijf 8 secties voor de dienst-pagina, in dezelfde stijl als deze referentie (vervang inhoud, behoud opbouw en lengte):\n"
        f"{json.dumps(reference_sections, ensure_ascii=False)}\n\n"
        "Houd dezelfde woordaantallen aan als de referentie:\n"
        f"{targets_str}\n\n"
        f"BESCHIKBARE PAGINA'S voor interne links (gebruik in body waar relevant):\n"
        f"{json.dumps(available_pages, ensure_ascii=False)[:1800]}\n\n"
        f"BESCHIKBARE MEDIA voor image_url:\n"
        f"{json.dumps(available_media, ensure_ascii=False)[:1500]}\n\n"
        "Sectie 1 = hero (H2 = dienst-naam + USP). Sectie 2 = subtitel/vraag aan klant. "
        "Sectie 3 = 'Wat is X en hoe werkt het?'. Sectie 4 = 'Strak en modern afgewerkt' (of vergelijkbaar). "
        "Sectie 5 = 'Voordelen van X'. Sectie 6 = 'X voor nieuwbouw/renovatie/etc'. "
        "Sectie 7 = 'Vakwerk dat blijft staan'. Sectie 8 = 'Uw specialist in X'. "
        "BELANGRIJK: noem in elke sectie waar het natuurlijk past gerelateerde diensten (pvc-vloeren, vloeren egaliseren, trappenrenovatie, vloerverwarming) "
        "en wikkel die woorden in markdown links naar hun bestaande dienst-pagina's. "
        "Schrijf INHOUDELIJK rijk, geen vulwoorden."
    )
    result = _anthropic_call(
        messages=[{"role": "user", "content": user_msg}],
        system=system,
        max_tokens=4500,
        model="claude-haiku-4-5-20251001",
    )
    if "error" in result:
        return jsonify({"error": result.get("error") or "AI-call mislukt",
                        "details": result.get("details", "")}), 502
    raw = "".join(b.get("text", "") for b in (result.get("content") or []) if isinstance(b, dict))
    data = _loads_lenient(raw)
    if data is None:
        return jsonify({"error": "Ongeldige JSON van AI", "raw": raw[:400]}), 502
    return jsonify(data)


def _serve_kv_page(full_slug: str):
    """Serveer een gepubliceerde block-pagina uit KV (page:<slug>:html) of render 'm desnoods
    live uit het block-record. Geeft een Response (HTML of redirect) terug, of None als er voor
    deze slug niets gepubliceerd is. Gebruikt de VOLLEDIGE slug (incl. eventueel pad-prefix)."""
    safe = _decode_slug(full_slug).strip("/")
    if not safe:
        return None
    # SPA-pagina's (template "react") staan alleen in het CMS zodat hun SEO-titel/
    # omschrijving beheerd kan worden — hun INHOUD zit in de React-app. Ze hier
    # renderen levert een LEGE pagina op (dat overkwam /contact/ met slash), dus
    # stuur ze door naar de route die de SPA wél serveert.
    _spa = _get_page(safe)
    if isinstance(_spa, dict) and _spa.get("template") == "react":
        doel = "/" + safe
        # Alleen doorsturen naar een ANDER pad; naar jezelf redirecten is een lus.
        # Staan we al op het doelpad, dan hoort de Vercel-rewrite de SPA te serveren.
        if request.path == doel:
            return None
        try:
            if request.query_string:
                doel += "?" + request.query_string.decode("utf-8", "ignore")
        except Exception:
            pass
        return redirect(doel, code=301)
    _is_preview = False
    try:
        _is_preview = bool(request.args.get("preview")) and is_logged_in()
    except Exception:
        _is_preview = False
    if _is_preview:
        _pg = _get_page(safe)
        if _pg:
            try:
                _fresh = render_page_html(_pg)
                if _fresh:
                    _self = (CANONICAL_BASE + "/" + safe + "/") if safe else CANONICAL_BASE + "/"
                    return _no_cdn_cache(Response(_heal_canonical_in_html(_fresh, _self), mimetype="text/html")) if "_no_cdn_cache" in globals() else Response(_heal_canonical_in_html(_fresh, _self), mimetype="text/html")
            except Exception:
                pass
    # Redirects respecteren (zelfde bron als /api/render).
    target_path = f"/{safe}/"
    for r in _redirects_index():
        if r.get("from_path") == target_path:
            return redirect(r.get("to_path"), code=int(r.get("code", 301)))
    html = kv_get(f"page:{safe}:html")
    if not html:
        page = _get_page(safe)
        if page and page.get("status") == "published":
            try:
                html = render_page_html(page)
            except Exception:
                html = None
    if html:
        return Response(html, mimetype="text/html")
    return None


@app.route("/diensten/<path:slug>/", methods=["GET"])
@app.route("/diensten/<path:slug>", methods=["GET"])
def serve_dynamic_dienst(slug):
    """Catch-all voor /diensten/<slug>/ EN /diensten/<parent>/<sub>/: serveert dynamische
    dienst-pagina uit KV. Static files matchen eerst in Vercel routing.
    """
    # 1) 1-op-1 template-dienstpagina (dienst-html:-store, slug zónder 'diensten/'-prefix)
    safe = _safe_slug(slug.rstrip("/"))
    html = kv_get(f"dienst-html:{safe}")
    if html:
        return Response(html, mimetype="text/html")
    # 2) Gewone block-pagina onder /diensten/<...> (page:diensten/<...>:html). Zonder deze
    #    fallback schaduwt deze route block-pagina's onder dit prefix -> 404 na publiceren.
    resp = _serve_kv_page(f"diensten/{slug}")
    return resp if resp is not None else Response("Niet gevonden", status=404, mimetype="text/plain")


@app.route("/locatie/<path:slug>/", methods=["GET"])
@app.route("/locatie/<path:slug>", methods=["GET"])
def serve_dynamic_locatie(slug):
    """Serveert dynamische locatiepagina's: eerst de 1-op-1 template-store (dienst-html:),
    daarna gewone block-pagina's onder /locatie/<...> (page:locatie/<...>:html)."""
    safe = _safe_slug(slug.rstrip("/"))
    html = kv_get(f"dienst-html:{safe}")
    if html:
        return Response(html, mimetype="text/html")
    resp = _serve_kv_page(f"locatie/{slug}")
    return resp if resp is not None else Response("Niet gevonden", status=404, mimetype="text/plain")


def _not_found_page():
    """Nette, gebrande 404 in de site-shell.

    Nodig omdat Flask de catch-all is voor alles buiten de React-routes: een kale
    tekst-404 zou de bezoeker een lege pagina geven. Bewust een ECHTE 404-status
    (geen redirect naar de homepage) — dat is beter voor SEO en eerlijker."""
    body = (
        '<main class="kv-gen" style="max-width:720px;margin:0 auto;padding:80px 24px;text-align:center">'
        '<p style="font-size:13px;font-weight:700;letter-spacing:3px;text-transform:uppercase;'
        'color:#f07d22;margin-bottom:14px">404</p>'
        '<h1 style="font-size:clamp(28px,4vw,44px);font-weight:800;color:#1a1a1a;margin-bottom:14px">'
        'Deze pagina bestaat niet</h1>'
        '<p style="color:#555;font-size:16px;margin-bottom:28px">De pagina is verplaatst of verwijderd. '
        'Ga terug naar de homepage of vraag direct een offerte aan.</p>'
        '<p><a class="vz-cta" href="/">Naar de homepage</a> '
        '<a class="vz-cta" style="background:#1d1d1b" href="/contact">Gratis offerte</a></p>'
        '</main>')
    try:
        shell = _blog_shell_html()
        region = _find_content_region(shell)
        html = shell[:region[0]] + body + shell[region[1]:]
        html = re.sub(r"<title>.*?</title>", "<title>Pagina niet gevonden | DAM Housing</title>",
                      html, count=1, flags=re.S)
        html = html.replace("</head>", '<meta name="robots" content="noindex, follow"></head>', 1)
        return Response(html, status=404, mimetype="text/html")
    except Exception:
        return Response("Niet gevonden", status=404, mimetype="text/plain")


@app.route("/<path:slug>/", methods=["GET"])
@app.route("/<path:slug>", methods=["GET"])
def serve_dynamic_page(slug):
    """Generieke fallback voor élke gepubliceerde block-pagina (bv. /dienst/<x>/, /over-ons/ …).
    Vercel serveert eerst een statisch bestand als dat bestaat; bestaat dat (nog) niet — zoals direct
    na publiceren of vóór de rebuild — dan komt het verzoek hier en serveren we de HTML rechtstreeks
    uit KV (page:<slug>:html). Zo is een gepubliceerde pagina meteen live, los van de static-bake.
    Werkzeug rankt deze route als minst-specifiek, dus alle expliciete routes (api, blog, diensten,
    locatie, factuur, …) gaan vóór."""
    resp = _serve_kv_page(slug)
    return resp if resp is not None else _not_found_page()


@app.route("/api/templates/<name>/bulk-apply", methods=["POST"])
def api_template_bulk_apply(name):
    a = _auth_or_401()
    if a: return a
    t = kv_get(f"template:{name}")
    if not t:
        return jsonify({"error": "Niet gevonden"}), 404
    f = request.files.get("file")
    if not f:
        return jsonify({"error": "Geen CSV"}), 400
    created = []
    failed = []
    try:
        text = f.read().decode("utf-8", errors="replace")
        reader = csv.DictReader(io.StringIO(text))
        for i, row in enumerate(reader):
            try:
                slug = _safe_slug(row.get("slug") or _substitute(t.get("slug_pattern", "{slug}"), row))
                if not slug or _get_page(slug):
                    failed.append({"row": i, "error": f"slug ongeldig of bestaat al: {slug}"}); continue
                title = row.get("title") or row.get("stad") or row.get("dienst") or slug
                page = _default_page(slug, title, template=name)
                page["content_blocks"] = _substitute_template(t.get("content_blocks") or [], row)
                page["meta"].update(_substitute_template_meta(t.get("default_meta") or {}, row))
                _save_page(page)
                update_seo_score(page)
                created.append(slug)
            except Exception as e:
                failed.append({"row": i, "error": str(e)})
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    audit_log("template.bulk_apply", name, f"Created {len(created)}")
    return jsonify({"created": created, "failed": failed})


# ---------- menus ----------
def _header_template_html() -> str:
    """Header-template uit KV; nog nooit opgeslagen -> seed uit de gebakken homepage."""
    h = kv_get("site:header_html", "") or ""
    if h.strip():
        return h
    try:
        f = _static_page_file("")
        if f and os.path.exists(f):
            from bs4 import BeautifulSoup
            soup = BeautifulSoup(open(f, encoding="utf-8", errors="replace").read(), "html.parser")
            el = soup.find(attrs={"data-elementor-type": "header"})
            return str(el) if el else ""
    except Exception:
        pass
    return ""


# Het hoofdmenu zoals het NU op de site staat
# (src/components/layout/Navbar.jsx — Diensten is daar een dropdown).
# Dit is de seed voor de Menu-view én de fallback voor de site zolang er niets in
# KV is opgeslagen — zo staat de Menu-view nooit leeg en verandert er niets aan de
# site tot de klant zelf iets aanpast.
VZ_DEFAULT_MENU = [
    {"label": "Woningaanbod", "url": "/aanbod", "children": []},
    {"label": "Diensten", "url": "/diensten", "children": [
        {"label": "Verkoop", "url": "/verkoop"},
        {"label": "Aankoop", "url": "/aankoop"},
        {"label": "Verhuur", "url": "/verhuur"},
        {"label": "Taxatie", "url": "/taxatie"},
    ]},
    {"label": "Over DAM Housing", "url": "/over-dam-housing", "children": []},
    {"label": "Blog", "url": "/blog", "children": []},
    {"label": "Contact", "url": "/contact", "children": []},
]


def _site_menu_items() -> list:
    """Het actieve hoofdmenu: uit KV zodra de klant het heeft opgeslagen, anders
    het menu dat de React-header nu toont.

    In het DEFAULT-menu blijft 'Blog' weg zolang er geen gepubliceerd artikel is —
    een navigatie-item naar een lege blog is een doodlopende link. Zodra het eerste
    artikel live staat verschijnt het vanzelf. Een door de klant OPGESLAGEN menu
    wordt letterlijk gerespecteerd (dan is het een bewuste keuze)."""
    m = kv_get("menu:main") or {}
    items = m.get("items") if isinstance(m, dict) else None
    if items:
        return items
    items = json.loads(json.dumps(VZ_DEFAULT_MENU))
    try:
        heeft_posts = any(p.get("status") == "published" for p in (get_posts_index() or []))
    except Exception:
        heeft_posts = False
    if not heeft_posts:
        items = [i for i in items if (i.get("url") or "").rstrip("/") != "/blog"]
    return items


