# ---------- SEO overview ----------
@app.route("/api/seo/overview", methods=["GET"])
def api_seo_overview():
    a = _auth_or_401()
    if a: return a
    missing_only = request.args.get("missing_only") == "1"
    # Index-gebaseerd (1 KV-read): GEEN per-pagina _get_page (116 reads → timeout in serverless).
    # Gebruik de gecachte score als die er is, anders een snelle score uit titel/omschrijving.
    scores = kv_get("seo_scores", {}) or {}
    out = []
    for it in _pages_index():
        slug = it.get("slug")
        if slug is None:
            continue
        title = it.get("title") or slug or "Home"          # pagina-titel
        seo_title = it.get("meta_title") or title           # SEO-titel (default = pagina-titel)
        desc = it.get("meta_description")
        if desc is None:
            desc = it.get("description", "")
        desc = desc or ""
        cached = scores.get(slug)
        if cached:
            score = cached.get("score", 0)
            issues = [(i.get("message") if isinstance(i, dict) else str(i)) for i in (cached.get("issues") or [])]
        else:
            score, issues = _quick_seo_score(seo_title, desc)
        if missing_only and score >= 90:
            continue
        out.append({
            "slug": slug,
            "title": title,
            "url": it.get("url") or ("/" + slug + "/" if slug else "/"),
            "status": it.get("status", "published"),
            "meta": {"title": seo_title, "description": desc, "robots": it.get("robots", "index,follow")},
            "score": score,
            "issues": issues,
        })
    return jsonify({"items": out})


