@app.route("/api/seo/ai-meta/<path:slug>", methods=["POST"])
def api_seo_ai_meta(slug):
    """Genereer een SEO-titel + meta-omschrijving op basis van de pagina-inhoud."""
    a = _auth_or_401()
    if a: return a
    slug = _decode_slug(slug)
    page = _get_page(slug) or {}
    idx = next((p for p in _pages_index() if p.get("slug") == slug), {})
    title = page.get("title") or idx.get("title") or slug.replace("-", " ").replace("/", " - ")
    # Verzamel wat zichtbare tekst uit de content-blokken (indien aanwezig).
    parts = []
    for b in (page.get("content_blocks") or []):
        props = b.get("props") or {}
        for k in ("text", "title", "heading", "subtitle"):
            v = props.get(k)
            if isinstance(v, str) and v.strip():
                parts.append(v.strip())
    context = " ".join(parts)[:2500] or title
    system = ("Je bent SEO-specialist voor DAM Housing, een Nederlands vloerenbedrijf dat pvc-vloeren legt, "
              "vloeren egaliseert, trappen renoveert en vloerverwarming infreest (Culemborg, Tiel en regio "
              "Rivierenland). Schrijf in het Nederlands. "
              "Geef ALLEEN geldige JSON terug: {\"title\":\"...\",\"description\":\"...\"}. "
              "title: pakkend, max 60 tekens, met merknaam waar logisch. "
              "description: wervend, 120-155 tekens, met een subtiele call-to-action.")
    user = f"Pagina-URL-slug: /{slug}/\nPagina-titel: {title}\nPagina-inhoud:\n{context}"
    res = _anthropic_call([{"role": "user", "content": user}], system=system, max_tokens=400)
    if res.get("error"):
        return jsonify({"error": res["error"]}), 502
    raw = "".join(c.get("text", "") for c in (res.get("content") or []) if c.get("type") == "text").strip()
    data = _loads_lenient(raw)
    if data is None:
        return jsonify({"error": "AI gaf geen geldige JSON terug"}), 502
    return jsonify({"title": (data.get("title") or "").strip(),
                    "description": (data.get("description") or "").strip()})


@app.route("/api/seo/meta/<path:slug>", methods=["PATCH"])
def api_seo_meta(slug):
    a = _auth_or_401()
    if a: return a
    slug = _decode_slug(slug)
    page = _get_page(slug)
    if not page:
        return jsonify({"error": "Niet gevonden"}), 404
    body = request.get_json(silent=True) or {}
    # schema_jsonld mag expliciet op null gezet worden (wissen); andere velden alleen als ze niet None zijn.
    page.setdefault("meta", {}).update({k: v for k, v in body.items() if v is not None or k == "schema_jsonld"})
    _save_page(page)
    update_seo_score(page)
    # Houd de pagina-index in sync zodat het (index-gebaseerde) SEO-overzicht de wijziging toont.
    if any(k in body for k in ("title", "description", "robots")):
        idx = _pages_index()
        for e in idx:
            if e.get("slug") == slug:
                if "title" in body and body["title"] is not None:
                    e["meta_title"] = body["title"]
                if "description" in body and body["description"] is not None:
                    e["meta_description"] = body["description"]
                if "robots" in body and body["robots"]:
                    e["robots"] = body["robots"]
                break
        _save_pages_index(idx)
    # Schema-status-cache bijwerken zodat het SEO-overzicht 'Ingesteld/Niet' meteen klopt.
    if "schema_jsonld" in body:
        try:
            sl = kv_get("seo:schema_slugs")
            if isinstance(sl, list):
                has = bool(body.get("schema_jsonld"))
                if has and slug not in sl:
                    sl.append(slug); kv_set("seo:schema_slugs", sl)
                elif not has and slug in sl:
                    sl.remove(slug); kv_set("seo:schema_slugs", sl)
        except Exception:
            pass
    audit_log("seo.meta", slug, "meta updated")
    return jsonify({"slug": slug, "meta": page["meta"]})


@app.route("/api/seo/schema-status", methods=["GET"])
def api_seo_schema_status():
    """Welke pagina's hebben structured data (JSON-LD) ingesteld. Gecachet in seo:schema_slugs;
    de eerste keer scant het de page-records (on-demand — niet op het dashboard)."""
    a = _auth_or_401()
    if a: return a
    cached = kv_get("seo:schema_slugs")
    if isinstance(cached, list):
        return jsonify({"slugs": cached})
    slugs = []
    try:
        for key in kv_list("page:"):
            if str(key).count(":") != 1:   # sla page:<slug>:html / :inplace en page:inplace:index over
                continue
            slug = str(key).split(":", 1)[1]
            pg = kv_get(key) or {}
            if (pg.get("meta") or {}).get("schema_jsonld"):
                slugs.append(slug)
    except Exception as e:
        print(f"schema-status scan error: {e}")
    kv_set("seo:schema_slugs", slugs)
    return jsonify({"slugs": slugs})


@app.route("/api/seo/schema-ai", methods=["POST"])
def api_seo_schema_ai():
    """Genereer passende schema.org JSON-LD voor een pagina met AI (optioneel hulpmiddel)."""
    a = _auth_or_401()
    if a: return a
    if not _ai_configured():
        return jsonify({"error": "Geen Claude API-key ingesteld — vul 'm in bij Instellingen → Integraties → Claude (Anthropic)."}), 503
    body = request.get_json(silent=True) or {}
    slug = _decode_slug(body.get("slug", ""))
    page = _get_page(slug) or {}
    title = page.get("title", "") or slug or "Home"
    meta = page.get("meta", {}) or {}
    desc = meta.get("description", "")
    base = CANONICAL_BASE
    url = f"{base}/{slug}/" if slug else base + "/"
    system = (
        "Je genereert geldige schema.org JSON-LD voor een pagina van DAM Housing (vloerenbedrijf in "
        "Culemborg, werkgebied Tiel en regio Rivierenland; tel 06-83897981; info@damhousing.nl). "
        "Kies het meest passende @type: LocalBusiness voor home/contact, Service voor dienst-/locatiepagina's, "
        "Article voor blog, BreadcrumbList of FAQPage waar logisch. Vul echte bedrijfsgegevens en de juiste URL in. "
        "Antwoord UITSLUITEND met het JSON-LD object (geldige JSON) — geen uitleg, geen code-fences."
    )
    user = f"Pagina-titel: {title}\nURL: {url}\nOmschrijving: {desc or '(geen)'}\nGenereer passende schema.org JSON-LD."
    r = _anthropic_call([{"role": "user", "content": user}], system=system, max_tokens=1200, model="claude-haiku-4-5-20251001")
    if r.get("error"):
        return jsonify(r), 502
    raw = "".join(b.get("text", "") for b in (r.get("content") or []) if isinstance(b, dict))
    data = _loads_lenient(raw)
    if data is None:
        return jsonify({"error": "AI gaf geen geldige JSON", "raw": raw[:300]}), 502
    return jsonify({"schema": data})


@app.route("/api/seo/bulk", methods=["POST"])
def api_seo_bulk():
    a = _auth_or_401()
    if a: return a
    body = request.get_json(silent=True) or {}
    slugs = body.get("slugs") or []
    upd = body.get("meta_updates") or {}
    updated = 0
    failed = []
    for s in slugs:
        page = _get_page(_safe_slug(s))
        if not page:
            failed.append({"slug": s, "error": "not found"}); continue
        try:
            page.setdefault("meta", {}).update(upd)
            _save_page(page)
            update_seo_score(page)
            updated += 1
        except Exception as e:
            failed.append({"slug": s, "error": str(e)})
    audit_log("seo.bulk", "*", f"{updated} pages updated")
    return jsonify({"updated": updated, "failed": failed})


# ---------- broken links audit ----------
@app.route("/api/links/audit", methods=["POST"])
def api_links_audit():
    a = _auth_or_401()
    if a: return a
    body = request.get_json(silent=True) or {}
    scope = body.get("scope") or "all"
    pages_to_scan = _pages_index() if scope == "all" else [{"slug": s} for s in scope]
    # Bekende slugs vooraf verzamelen, zodat interne links zonder extra KV-reads te checken zijn.
    known = set()
    for e in (_pages_index() or []):
        known.add(_safe_slug((e.get("slug") or "").lstrip("/")))
    try:
        for sp in list_pages():
            known.add(_safe_slug((sp.get("slug") or sp.get("url") or "").strip("/")))
    except Exception:
        pass
    results = []
    t0 = time.time()
    ext_checked = 0
    EXT_MAX = 25          # cap externe HEAD-checks (elke kost netwerk-tijd)
    TIME_BUDGET = 45      # ruim onder de 60s serverless-limiet -> nooit een 504/timeout
    truncated = False
    for it in pages_to_scan:
        if time.time() - t0 > TIME_BUDGET:
            truncated = True
            break
        slug = it.get("slug") or ""
        if not slug:
            continue
        try:
            page = _get_page(slug)
        except Exception:
            page = None
        if not page:
            continue
        for b in page.get("content_blocks", []) or []:
            props = b.get("props", {}) or {}
            href = props.get("href") or props.get("src")
            if not href or not isinstance(href, str):
                continue
            typ = "internal" if href.startswith("/") else "external"
            status = None
            if typ == "internal":
                status = 200 if _safe_slug(href.strip("/")) in known else 404
            elif href.startswith("http"):
                if ext_checked >= EXT_MAX:
                    continue
                ext_checked += 1
                try:
                    req = urllib.request.Request(href, method="HEAD", headers={"User-Agent": "Mozilla/5.0 (DamHousingLinkCheck)"})
                    with urllib.request.urlopen(req, timeout=3) as r:
                        status = r.status
                except Exception:
                    status = 0
            if status and status >= 400:
                results.append({"page_slug": slug, "link": href, "status_code": status, "type": typ})
    out = {"ran_at": _now_iso(), "results": results, "truncated": truncated}
    kv_set("broken_links:last", out)
    return jsonify(out)


# ---------- AI page chat ----------
def _anthropic_key() -> str:
    """Anthropic API-key: de in de admin ingestelde sleutel (settings.ai.api_key) heeft voorrang,
    met de env-var ANTHROPIC_API_KEY alleen als fallback. Zo bepaalt de klant z'n key in de UI
    en kan een verouderde/foute Vercel env-var de generatie niet stilletjes blokkeren."""
    def _clean(v: str) -> str:
        v = (v or "").strip()
        # Per ongeluk meegeplakte quotes of een 'Bearer '-prefix weghalen — die maken de key ongeldig.
        if len(v) >= 2 and ((v[0] == '"' and v[-1] == '"') or (v[0] == "'" and v[-1] == "'")):
            v = v[1:-1].strip()
        if v.lower().startswith("bearer "):
            v = v[7:].strip()
        return v
    k = _clean((get_settings().get("ai") or {}).get("api_key"))
    if k:
        return k
    return _clean(ANTHROPIC_API_KEY)


def _ai_configured() -> bool:
    """AI is beschikbaar zodra de centrale MAIHS-gateway aanstaat, óf er een eigen Anthropic-key is."""
    return _gateway_aan() or bool(_anthropic_key())


def _anthropic_call(messages: list, system: str = "", max_tokens: int = 2048, model: str = None, timeout: int = None) -> dict:
    _use_gateway = _gateway_aan()
    _key = "" if _use_gateway else _anthropic_key()
    if not _use_gateway and not _key:
        return {"error": "Geen Anthropic API-key ingesteld — vul 'm in bij Instellingen → Integraties → Claude (Anthropic)."}
    # Maand-budget (vangnet): blokkeer als de maandlimiet is bereikt.
    _month = datetime.now().strftime("%Y-%m")
    try:
        _used = int(kv_get("ai:usage:" + _month) or 0)
    except Exception:
        _used = 0
    if AI_MONTHLY_TOKEN_LIMIT and _used >= AI_MONTHLY_TOKEN_LIMIT:
        return {"error": f"AI-maandlimiet bereikt ({_used:,}/{AI_MONTHLY_TOKEN_LIMIT:,} tokens deze maand). "
                          "Verhoog AI_MONTHLY_TOKEN_LIMIT of wacht tot volgende maand."}
    body = {
        "model": model or ANTHROPIC_MODEL_DEFAULT,
        "max_tokens": max_tokens,
        "system": system,
        "messages": messages,
    }
    if _use_gateway:
        _url = _gateway_origin() + AI_GATEWAY_PAD
        # A User-Agent is required: the gateway sits behind Cloudflare, which
        # bans urllib's default "Python-urllib/x" signature (error 1010).
        _headers = {"Content-Type": "application/json", "Authorization": "Bearer " + _gateway_key(),
                    "User-Agent": "MAIHS-AI-Gateway-Client/1.0"}
    else:
        _url = "https://api.anthropic.com/v1/messages"
        _headers = {"Content-Type": "application/json", "x-api-key": _key, "anthropic-version": "2023-06-01"}
    req = urllib.request.Request(
        _url,
        data=json.dumps(body).encode("utf-8"),
        headers=_headers,
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=(timeout or AI_HTTP_TIMEOUT)) as r:
            resp = json.loads(r.read())
        # Verbruik bijhouden (best-effort; exacte telling is niet nodig voor een vangnet).
        try:
            u = resp.get("usage") or {}
            spent = int(u.get("input_tokens", 0)) + int(u.get("output_tokens", 0))
            if spent:
                kv_set("ai:usage:" + _month, _used + spent)
        except Exception:
            pass
        return resp
    except urllib.error.HTTPError as e:
        return {"error": f"HTTP {e.code}", "details": e.read().decode("utf-8", errors="replace")}
    except (TimeoutError, socket.timeout) as e:
        return {"error": "AI-generatie duurde te lang (timeout). Probeer het opnieuw of maak de prompt korter.", "timeout": True}
    except Exception as e:
        # urllib kan een generieke timeout-string geven ("The read operation timed out")
        if "timed out" in str(e).lower():
            return {"error": "AI-generatie duurde te lang (timeout). Probeer het opnieuw of maak de prompt korter.", "timeout": True}
        return {"error": str(e)}


@app.route("/api/page-chat", methods=["POST"])
def api_page_chat():
    a = _require_agency()
    if a: return a
    body = request.get_json(silent=True) or {}
    slug = _safe_slug(body.get("slug", ""))
    msg = (body.get("message") or "").strip()
    current_blocks = body.get("current_blocks") or []
    history = body.get("chat_history") or []
    if not msg:
        return jsonify({"error": "message verplicht"}), 400
    system = (
        "Je bent een AI page editor voor DAM Housing (vloerenbedrijf in Culemborg en regio Rivierenland, NL). "
        "Je krijgt de huidige blokken (JSON) van een pagina en een instructie van de gebruiker. "
        "Geef ALTIJD geldige JSON terug met EXACT deze velden: "
        '{"response": "...", "proposed_changes": [ {"block_index": int, "action": "add|edit|delete|move", "new_value": {...block...}, "new_index": int|null, "rationale": "..."} ] }. '
        "Block-types die geldig zijn: " + ", ".join(b["type"] for b in BLOCK_LIBRARY) + ". "
        "Hou je strikt aan deze types. Voor 'edit' is block_index verplicht. Voor 'add' mag block_index -1 zijn voor 'aan het einde'."
    )
    user_msg = (
        f"Pagina slug: {slug}\n"
        f"Huidige blokken (JSON):\n```json\n{json.dumps(current_blocks, ensure_ascii=False)}\n```\n"
        f"Instructie: {msg}"
    )
    messages = []
    for h in history[-10:]:
        messages.append({"role": h.get("role", "user"), "content": h.get("content", "")})
    messages.append({"role": "user", "content": user_msg})
    resp = _anthropic_call(messages, system=system, max_tokens=3072)
    if resp.get("error"):
        return jsonify({"response": f"AI fout: {resp.get('error')}", "proposed_changes": []}), 200
    # Extract assistant text
    text = ""
    for c in (resp.get("content") or []):
        if c.get("type") == "text":
            text += c.get("text", "")
    parsed: dict = {}
    # Try to find JSON in text
    m = re.search(r"\{[\s\S]*\}", text)
    if m:
        try: parsed = json.loads(m.group(0))
        except Exception: parsed = {}
    response_text = parsed.get("response") or text
    proposed = parsed.get("proposed_changes") or []
    # Validate / clamp
    valid_types = {b["type"] for b in BLOCK_LIBRARY}
    clean = []
    for p in proposed:
        if not isinstance(p, dict): continue
        action = p.get("action")
        if action not in ("add", "edit", "delete", "move"): continue
        nv = p.get("new_value") or {}
        if action in ("add", "edit"):
            if nv.get("type") not in valid_types: continue
        clean.append(p)
    # Persist chat history
    chat = kv_get(f"ai:chat:{slug}", []) or []
    chat.append({"role": "user", "content": msg, "ts": _now_iso(), "proposed_changes": None})
    chat.append({"role": "assistant", "content": response_text, "ts": _now_iso(), "proposed_changes": clean})
    chat = chat[-50:]
    kv_set(f"ai:chat:{slug}", chat)
    return jsonify({"response": response_text, "proposed_changes": clean})


@app.route("/api/page-chat/apply", methods=["POST"])
def api_page_chat_apply():
    a = _require_agency()
    if a: return a
    body = request.get_json(silent=True) or {}
    slug = _safe_slug(body.get("slug", ""))
    accepted_indexes = body.get("accepted_change_ids") or []
    chat = kv_get(f"ai:chat:{slug}", []) or []
    last_proposals = []
    for entry in reversed(chat):
        if entry.get("role") == "assistant" and entry.get("proposed_changes"):
            last_proposals = entry["proposed_changes"]
            break
    if not last_proposals:
        return jsonify({"error": "Geen voorstellen gevonden"}), 400
    page = _get_page(slug)
    if not page:
        return jsonify({"error": "Pagina niet gevonden"}), 404
    blocks = list(page.get("content_blocks") or [])
    # Apply in deterministic order: deletes high-to-low, then moves, then edits, then adds
    accepted = [last_proposals[i] for i in accepted_indexes if 0 <= i < len(last_proposals)]
    deletes = sorted([c for c in accepted if c["action"] == "delete"], key=lambda c: -int(c.get("block_index", 0)))
    edits = [c for c in accepted if c["action"] == "edit"]
    moves = [c for c in accepted if c["action"] == "move"]
    adds = [c for c in accepted if c["action"] == "add"]
    for c in deletes:
        i = int(c.get("block_index", -1))
        if 0 <= i < len(blocks): blocks.pop(i)
    for c in edits:
        i = int(c.get("block_index", -1))
        if 0 <= i < len(blocks) and c.get("new_value"):
            blocks[i] = c["new_value"]
    for c in moves:
        i = int(c.get("block_index", -1))
        ni = int(c.get("new_index", i))
        if 0 <= i < len(blocks) and 0 <= ni < len(blocks):
            blk = blocks.pop(i); blocks.insert(ni, blk)
    for c in adds:
        nv = c.get("new_value")
        if not nv: continue
        ni = c.get("new_index")
        if ni is None or ni < 0 or ni > len(blocks):
            blocks.append(nv)
        else:
            blocks.insert(int(ni), nv)
    page["content_blocks"] = blocks
    _push_revision(slug, page, summary="ai-apply")
    _save_page(page)
    update_seo_score(page)
    audit_log("page.ai_apply", slug, f"Applied {len(accepted)} AI changes")
    return jsonify({"slug": slug, "new_blocks": blocks, "updated_at": page["updated_at"]})


@app.route("/api/page-ai-edit", methods=["POST"])
def api_page_ai_edit():
    """AI-assistent in de pagina-editor: krijgt de huidige content-blokken + een instructie en geeft de
    VOLLEDIGE bijgewerkte blokken-array terug. De editor zet die in de live state (en kan terug naar de
    snapshot vóór de wijziging). Niet persistent — opslaan gebeurt via de normale Publiceer/Opslaan-flow."""
    a = _require_agency()
    if a:
        return a
    if not _ai_configured():
        return jsonify({"ok": False, "error": "Geen Anthropic API-key — vul 'm in bij Instellingen → Integraties → Claude."}), 400
    body = request.get_json(silent=True) or {}
    instruction = (body.get("instruction") or body.get("message") or "").strip()
    blocks = body.get("current_blocks") or []
    if not instruction:
        return jsonify({"ok": False, "error": "Instructie verplicht."}), 400
    # Strip frontend-only velden (_id e.d.) uit de input.
    clean_in = [{k: v for k, v in b.items() if not str(k).startswith("_")} for b in blocks if isinstance(b, dict)]
    valid_types = [b["type"] for b in BLOCK_LIBRARY]
    system = (
        "Je bent een AI page-editor voor DAM Housing (vloerenbedrijf in Culemborg en regio Rivierenland, NL). Je krijgt de huidige "
        "content-blokken van een pagina (JSON-array) en een instructie van de gebruiker. Pas de instructie toe "
        "en geef de VOLLEDIGE bijgewerkte blokken-array terug — behoud blokken die de instructie niet raakt, in "
        "dezelfde volgorde (tenzij om herordening wordt gevraagd). Schrijf in vlot Nederlands, koppen in zinsstijl, "
        "geen em-dashes, geen clichés/marketing-slogans. Interne links mogen inline als <a href=\"/...\">…</a>. "
        "Geldige block-types (gebruik UITSLUITEND deze, met hun bestaande veldvorm): " + ", ".join(valid_types) + ".\n"
        'Antwoord UITSLUITEND met geldig JSON: {"summary":"1 korte zin over wat je wijzigde","blocks":[ {block}, ... ]}. '
        "Geen tekst buiten de JSON."
    )
    if not clean_in:
        # Lege pagina: niets te bewerken -> CREATIE-modus. Gebruikers verwachten dat de AI-assistent
        # dan gewoon een opzet schrijft (Wim 2026-07-16: 'nieuwe pagina maken geeft geen blokken').
        system = (
            "Je bent een AI page-writer voor deze website. De pagina is nog LEEG. Schrijf op basis van "
            "de instructie een complete, natuurlijke pagina-inhoud als content-blokken. Vlot Nederlands, "
            "koppen in zinsstijl, geen em-dashes, geen cliches of marketing-slogans. Gebruik 6-12 blokken "
            "en begin met een heading (level h1).\n"
            "Geldige block-types (gebruik UITSLUITEND deze, met hun bestaande veldvorm): " + ", ".join(valid_types) + ".\n"
            'Antwoord UITSLUITEND met geldig JSON: {"summary":"1 korte zin over wat je schreef","blocks":[ {block}, ... ]}. '
            "Geen tekst buiten de JSON."
        )
    user = (f"Huidige blokken (JSON):\n```json\n{json.dumps(clean_in, ensure_ascii=False)}\n```\n\nInstructie: {instruction}")
    r = _anthropic_call([{"role": "user", "content": user}], system=system,
                        max_tokens=8000, model="claude-haiku-4-5-20251001")
    if r.get("error"):
        return jsonify({"ok": False, "error": r.get("error"), "details": r.get("details", "")}), 502
    txt = "".join(c.get("text", "") for c in (r.get("content") or []))
    data = _loads_lenient(txt)
    new_blocks = (data.get("blocks") if isinstance(data, dict) else (data if isinstance(data, list) else None))
    if not isinstance(new_blocks, list) or not new_blocks:
        # Gaf de AI een geldige JSON met lege blocks + uitleg (bv. 'pagina is leeg'), toon dan die
        # uitleg netjes i.p.v. een technische fout met rauwe JSON-dump.
        _ai_msg = (data.get("summary") if isinstance(data, dict) else "") or ""
        return jsonify({"ok": False, "error": _ai_msg or "AI gaf geen geldige blokken terug. Probeer een duidelijkere instructie.",
                        "details": "" if _ai_msg else txt[:300]}), 502
    vset = set(valid_types)
    out = [b for b in new_blocks if isinstance(b, dict) and b.get("type") in vset]
    if not out:
        return jsonify({"ok": False, "error": "AI gaf geen geldige block-types terug.", "details": txt[:200]}), 502
    summary = (data.get("summary") if isinstance(data, dict) else "") or "Content aangepast."
    audit_log("page.ai_edit", _safe_slug(body.get("slug", "")), instruction[:120])
    return jsonify({"ok": True, "blocks": out, "summary": summary})


# ---------- traffic tracking ----------
TRACKING_PATHS_CAP = 200  # max unieke paden per dag
TRACKING_RETENTION_DAYS = 90


def _today_bucket() -> str:
    return datetime.now().strftime("%Y%m%d")


def _bump_counter(key: str, by: int = 1) -> int:
    val = (kv_get(key) or 0)
    if not isinstance(val, int):
        try: val = int(val)
        except: val = 0
    val += by
    kv_set(key, val)
    return val


@app.route("/api/track", methods=["POST", "OPTIONS"])
def api_track():
    """Cookie-loze first-party traffic tracker. Geen PII opgeslagen, alleen counters.
    Body: {type: 'pageview'|'click', path?, kind?, target?}
    """
    if request.method == "OPTIONS":
        return ("", 204, {"Access-Control-Allow-Origin": "*",
                           "Access-Control-Allow-Methods": "POST,OPTIONS",
                           "Access-Control-Allow-Headers": "Content-Type"})
    data = request.get_json(silent=True) or {}
    typ = (data.get("type") or "").lower().strip()
    if typ not in ("pageview", "click"):
        return jsonify({"ok": False, "error": "Onbekend type"}), 400
    today = _today_bucket()
    if typ == "pageview":
        path = (data.get("path") or "/").strip()
        # Normaliseer: max 200 chars, geen query/fragment
        path = path.split("?")[0].split("#")[0][:200]
        # Skip admin/api paths
        if path.startswith(("/admin", "/api", "/inloggen", "/uitloggen", "/wp-")):
            return ("", 204)
        # Per-pagina totaal + per dag
        _bump_counter(f"stat:pv:total:{path}")
        _bump_counter(f"stat:pv:day:{today}:{path}")
        _bump_counter(f"stat:pv:total")
        _bump_counter(f"stat:pv:day:{today}")
    else:  # click
        kind = (data.get("kind") or "").strip().lower()
        target = (data.get("target") or "").strip()[:200]
        if kind not in ("email", "phone", "route", "external", "form_open"):
            return jsonify({"ok": False, "error": "Onbekend kind"}), 400
        _bump_counter(f"stat:click:total:{kind}")
        _bump_counter(f"stat:click:day:{today}:{kind}")
        if target:
            _bump_counter(f"stat:click:target:{kind}:{target}")
    return ("", 204)


def _list_pageview_paths() -> list:
    """Return geaggregeerde top-pagina lijst uit KV."""
    keys = kv_list("stat:pv:total:")
    paths = []
    for k in keys:
        # k zou kunnen zijn 'stat:pv:total:/diensten/stucwerk/' OF safe-encoded
        raw = k
        # Strip prefix
        if raw.startswith("stat:pv:total:"):
            path = raw[len("stat:pv:total:"):]
        else:
            # safe-encoded variant: replaceback
            safe_prefix = _safe_kv_filename("stat:pv:total:")
            if raw.startswith(safe_prefix):
                path = raw[len(safe_prefix):].replace("_", "/")  # rough
            else:
                continue
        count = kv_get(f"stat:pv:total:{path}", 0) or 0
        if isinstance(count, int) and count > 0:
            paths.append({"path": path, "views": count})
    paths.sort(key=lambda x: x["views"], reverse=True)
    return paths


def _daily_views_chart(days: int = 14) -> list:
    """Per-dag totale pageviews + afgeronde formulier-aanvragen voor laatste N dagen."""
    leads_by_day = {}
    for l in (get_leads() or []):
        c = (l.get("created") or "")[:10]
        if c:
            leads_by_day[c] = leads_by_day.get(c, 0) + 1
    out = []
    for i in range(days - 1, -1, -1):
        d = datetime.now() - timedelta(days=i)
        bucket = d.strftime("%Y%m%d")
        views = kv_get(f"stat:pv:day:{bucket}", 0) or 0
        out.append({"date": d.strftime("%d-%m"),
                    "views": int(views) if isinstance(views, int) else 0,
                    "leads": leads_by_day.get(d.strftime("%Y-%m-%d"), 0)})
    return out


def _click_breakdown() -> dict:
    """Return per-kind klik-totalen + top-targets per kind."""
    kinds = ["email", "phone", "route", "external", "form_open"]
    out = {}
    for kind in kinds:
        total = kv_get(f"stat:click:total:{kind}", 0) or 0
        # Top targets
        target_keys = kv_list(f"stat:click:target:{kind}:")
        targets = []
        for k in target_keys:
            if k.startswith(f"stat:click:target:{kind}:"):
                t = k[len(f"stat:click:target:{kind}:"):]
            else:
                safe_p = _safe_kv_filename(f"stat:click:target:{kind}:")
                if k.startswith(safe_p):
                    t = k[len(safe_p):]
                else:
                    continue
            c = kv_get(f"stat:click:target:{kind}:{t}", 0) or 0
            if isinstance(c, int) and c > 0:
                targets.append({"target": t, "count": c})
        targets.sort(key=lambda x: x["count"], reverse=True)
        out[kind] = {"total": int(total) if isinstance(total, int) else 0, "top": targets[:5]}
    return out


@app.route("/api/stats/range", methods=["GET"])
def api_stats_range():
    """Aggregeer pageviews/clicks/top-pagina's over een datumbereik (from/to = YYYY-MM-DD)."""
    a = _auth_or_401()
    if a:
        return a
    today = datetime.now()

    def _parse(s, dflt):
        try:
            return datetime.strptime(s, "%Y-%m-%d")
        except Exception:
            return dflt

    frm = _parse(request.args.get("from", ""), today)
    to = _parse(request.args.get("to", ""), today)
    if to < frm:
        frm, to = to, frm
    days = (to - frm).days + 1
    if days > 370:
        frm = to - timedelta(days=369)
        days = 370
    kinds = ["email", "phone", "route", "external", "form_open"]
    clicks = {k: 0 for k in kinds}
    # Aanvragen (leads) per dag op basis van hun created-datum binnen het bereik.
    leads_by_day = {}
    for l in get_leads():
        cs = (l.get("created") or "")[:10]
        if cs:
            leads_by_day[cs] = leads_by_day.get(cs, 0) + 1
    leads_total = 0
    series, paths, pv_total = [], {}, 0
    want_paths = days <= 92  # vermijd duizenden kv_list-calls bij lange ranges
    d = frm
    while d <= to:
        bucket = d.strftime("%Y%m%d")
        iso = d.strftime("%Y-%m-%d")
        v = kv_get(f"stat:pv:day:{bucket}", 0) or 0
        v = int(v) if isinstance(v, int) else 0
        pv_total += v
        ld = leads_by_day.get(iso, 0)
        leads_total += ld
        series.append({"date": d.strftime("%d-%m"), "iso": iso, "views": v, "leads": ld})
        for k in kinds:
            c = kv_get(f"stat:click:day:{bucket}:{k}", 0) or 0
            clicks[k] += int(c) if isinstance(c, int) else 0
        if want_paths:
            prefix = f"stat:pv:day:{bucket}:"
            for pk in kv_list(prefix):
                if pk.startswith(prefix):
                    path = pk[len(prefix):]
                else:
                    sp = _safe_kv_filename(prefix)
                    path = pk[len(sp):].replace("_", "/") if pk.startswith(sp) else None
                if not path:
                    continue
                cnt = kv_get(f"stat:pv:day:{bucket}:{path}", 0) or 0
                if isinstance(cnt, int) and cnt > 0:
                    paths[path] = paths.get(path, 0) + cnt
        d += timedelta(days=1)
    top = sorted(([{"path": p, "views": c} for p, c in paths.items()]), key=lambda x: x["views"], reverse=True)[:10]
    # Vorige, even lange periode (voor de trend +/- t.o.v. vorige periode).
    prev_from = frm - timedelta(days=days)
    prev_to = frm - timedelta(days=1)
    prev_pv, prev_conv, prev_leads = 0, 0, 0
    pd = prev_from
    while pd <= prev_to:
        pb = pd.strftime("%Y%m%d")
        pv = kv_get(f"stat:pv:day:{pb}", 0) or 0
        prev_pv += int(pv) if isinstance(pv, int) else 0
        for k in ("email", "phone", "route"):
            cc = kv_get(f"stat:click:day:{pb}:{k}", 0) or 0
            prev_conv += int(cc) if isinstance(cc, int) else 0
        prev_leads += leads_by_day.get(pd.strftime("%Y-%m-%d"), 0)
        pd += timedelta(days=1)
    return jsonify({"from": frm.strftime("%Y-%m-%d"), "to": to.strftime("%Y-%m-%d"), "days": days,
                    "pageviews": pv_total, "leads": leads_total, "series": series,
                    "clicks": clicks, "conversions": sum(clicks[k] for k in ("email", "phone", "route")),
                    "top_pages": top,
                    "prev": {"pageviews": prev_pv, "leads": prev_leads, "conversions": prev_conv}})


# ---------- dashboard ----------
@app.route("/api/dashboard/stats", methods=["GET"])
def api_dashboard_stats():
    a = _auth_or_401()
    if a: return a
    items = _pages_index()
    by_status = {"published": 0, "draft": 0, "trashed": 0, "scheduled": 0}
    for it in items:
        by_status[it.get("status", "draft")] = by_status.get(it.get("status", "draft"), 0) + 1
    leads = get_leads()
    open_leads = [l for l in leads if l.get("stage") not in ("closed", "lost")]
    closed_leads = [l for l in leads if l.get("stage") == "closed"]
    lost_leads = [l for l in leads if l.get("stage") == "lost"]
    media = _media_index()
    media_bytes = sum(m.get("bytes", 0) for m in media)
    scores = kv_get("seo_scores", {}) or {}
    avg_score = int(sum(s.get("score", 0) for s in scores.values()) / max(1, len(scores))) if scores else 0
    # Echte wekelijkse SEO-score-historie (geen sample-data): upsert deze week en houd de laatste 12.
    seo_history = []
    try:
        if scores:
            hist = kv_get("seo:score:weeks") or {}
            hist[datetime.now().strftime("%Y-W%V")] = avg_score
            hist = dict(sorted(hist.items())[-12:])
            kv_set("seo:score:weeks", hist)
            seo_history = [{"label": "wk " + w.split("-W")[-1], "score": s} for w, s in sorted(hist.items())]
    except Exception:
        seo_history = []
    broken = (kv_get("broken_links:last") or {}).get("results", [])
    sitemap_meta = kv_get("sitemap:meta", {}) or {}
    settings = get_settings()
    try: avg_value = int(settings.get("avg_quote_value") or 0)
    except: avg_value = 0
    # Per-stage breakdown met value
    stage_breakdown = {}
    for l in leads:
        st = l.get("stage", "ontvangen")
        if st not in stage_breakdown: stage_breakdown[st] = {"count": 0, "value": 0}
        stage_breakdown[st]["count"] += 1
        stage_breakdown[st]["value"] += avg_value
    # Traffic stats
    total_pv = kv_get("stat:pv:total", 0) or 0
    today_pv = kv_get(f"stat:pv:day:{_today_bucket()}", 0) or 0
    top_pages = _list_pageview_paths()[:10]
    daily_chart = _daily_views_chart(14)
    clicks = _click_breakdown()
    # Aanvragen-overzicht met datums + dagen in pipeline. Gebruik de ECHTE (instelbare) stage-labels
    # uit de pipeline-definitie, niet een losse hardcoded map (anders loopt 't uit de pas).
    stage_labels = {s["id"]: s["label"] for s in get_stages()}
    requests_overview = []
    now = datetime.now().astimezone()
    for l in leads:
        created_str = l.get("created", "")
        history = l.get("history", []) or []
        # Tijd in current stage = sinds laatste history entry. _as_aware voorkomt een crash bij
        # het aftrekken van een tijdzone-bewuste now en een (legacy) naïeve opgeslagen timestamp.
        try:
            current_stage_since = _as_aware(datetime.fromisoformat(history[-1]["ts"]) if history else datetime.fromisoformat(created_str))
        except Exception:
            current_stage_since = now
        try:
            created_dt = _as_aware(datetime.fromisoformat(created_str))
        except Exception:
            created_dt = now
        days_in_stage = max(0, (now - current_stage_since).days)
        days_total = max(0, (now - created_dt).days)
        requests_overview.append({
            "id": l.get("id"),
            "name": l.get("name") or "(geen naam)",
            "email": l.get("email") or "",
            "telefoon": l.get("telefoon") or "",
            "pakket": l.get("pakket") or "",
            "stage": l.get("stage") or "ontvangen",
            "stage_label": stage_labels.get(l.get("stage") or "ontvangen", l.get("stage") or "ontvangen"),
            "created": created_str,
            "days_total": days_total,
            "days_in_stage": days_in_stage,
            "stuck": days_in_stage >= 7 and l.get("stage") not in ("closed", "lost"),
            "value": avg_value if l.get("stage") not in ("lost",) else 0,
        })
    requests_overview.sort(key=lambda x: x["created"], reverse=True)
    return jsonify({
        "pages": by_status,
        "leads": {"open": len(open_leads), "total": len(leads), "closed": len(closed_leads), "lost": len(lost_leads)},
        "media": {"count": len(media), "bytes": media_bytes},
        "avg_seo_score": avg_score,
        "seo_history": seo_history,
        "seo_pending": len(kv_get("seo:pending", []) or []),
        "broken_links_count": len(broken),
        "sitemap": {
            "last_generated": sitemap_meta.get("last_generated"),
            "urls_count": sitemap_meta.get("urls_count", 0),
        },
        "revenue": {
            "avg_value": avg_value,
            "closed_total": avg_value * len(closed_leads),
            "open_pipeline": avg_value * len(open_leads),
            "lost_total": avg_value * len(lost_leads),
            "stage_breakdown": stage_breakdown,
        },
        "requests": requests_overview,
        "traffic": {
            "total_pageviews": int(total_pv) if isinstance(total_pv, int) else 0,
            "today_pageviews": int(today_pv) if isinstance(today_pv, int) else 0,
            "top_pages": top_pages,
            "daily_chart": daily_chart,
            "clicks": clicks,
        },
    })


@app.route("/api/audit-log", methods=["GET"])
def api_audit_log():
    a = _auth_or_401()
    if a: return a
    log = kv_get("audit:log", []) or []
    user = request.args.get("user")
    action = request.args.get("action")
    fr = request.args.get("from")
    to = request.args.get("to")
    limit = int(request.args.get("limit", 50))
    items = log
    if user: items = [x for x in items if x.get("user") == user]
    if action: items = [x for x in items if action in (x.get("action") or "")]
    if fr: items = [x for x in items if x.get("ts", "") >= fr]
    if to: items = [x for x in items if x.get("ts", "") <= to]
    return jsonify({"items": items[:limit], "total": len(items)})


# ---------- integrations health ----------
@app.route("/api/integrations/health", methods=["GET"])
def api_integrations_health():
    a = _auth_or_401()
    if a: return a
    # KV check
    kv_ok = False
    try:
        kv_ok = kv_set("__health__", _now_iso()) and (kv_get("__health__") is not None)
    except Exception: kv_ok = False
    # Blob check
    blob_ok = bool(BLOB_TOKEN)
    blob_latency = None
    if blob_ok:
        t = time.time()
        ok, _ = blob_put("health-check.txt", b"ok", "text/plain")
        blob_ok = ok
        blob_latency = int((time.time() - t) * 1000)
    # Kan deze site mailen? Eigen SMTP óf de centrale mailbox via de gateway.
    s = get_settings().get("smtp", {})
    smtp_ok = bool(_smtp_klant_eigen(s) or _gateway_aan()
                   or (s.get("host") and s.get("from_email")))
    return jsonify({
        "blob": {"ok": blob_ok, "latency_ms": blob_latency},
        "kv": {"ok": kv_ok},
        "ai": {"ok": bool(_gateway_aan() or _anthropic_key()), "model": ANTHROPIC_MODEL_DEFAULT},
        "smtp": {"ok": smtp_ok},
    })


@app.route("/api/ai-test", methods=["POST"])
def api_ai_test():
    a = _require_agency()
    if a: return a
    prompt = (request.get_json(silent=True) or {}).get("prompt") or "Zeg in 1 zin hallo."
    resp = _anthropic_call(
        [{"role": "user", "content": prompt}],
        system="Antwoord kort en in het Nederlands.",
        max_tokens=200,
    )
    if resp.get("error"):
        _msg = resp.get("error")
        if resp.get("details"):
            _msg = f"{_msg} — {str(resp.get('details'))[:200]}"
        return jsonify({"ok": False, "response": _msg, "model": ANTHROPIC_MODEL_DEFAULT, "tokens": 0}), 200
    text = "".join(c.get("text", "") for c in (resp.get("content") or []) if c.get("type") == "text")
    usage = resp.get("usage") or {}
    return jsonify({
        "ok": True, "response": text, "model": resp.get("model", ANTHROPIC_MODEL_DEFAULT),
        "tokens": usage.get("input_tokens", 0) + usage.get("output_tokens", 0),
    })


# ---------- users ----------
def _hash_pw(pw: str) -> str:
    return hashlib.sha256(pw.encode("utf-8")).hexdigest()


@app.route("/api/users", methods=["GET"])
def api_users_list():
    a = _auth_or_401()
    if a: return a
    users = kv_get("users", []) or []
    return jsonify({"items": [{"username": u.get("username"), "role": u.get("role", "editor"),
                               "created_at": u.get("created_at")} for u in users]})


@app.route("/api/users", methods=["POST"])
def api_users_create():
    a = _auth_or_401()
    if a: return a
    body = request.get_json(silent=True) or {}
    username = (body.get("username") or "").strip()
    password = body.get("password") or ""
    role = body.get("role", "editor")
    if not username or not password:
        return jsonify({"error": "username & password verplicht"}), 400
    users = kv_get("users", []) or []
    if any(u.get("username") == username for u in users):
        return jsonify({"error": "Bestaat al"}), 409
    users.append({"username": username, "password_hash": _hash_pw(password),
                  "role": role, "created_at": _now_iso()})
    kv_set("users", users)
    audit_log("user.create", username, f"Aangemaakt rol={role}")
    return jsonify({"username": username, "role": role}), 201


@app.route("/api/users/<username>", methods=["DELETE"])
def api_users_delete(username):
    a = _auth_or_401()
    if a: return a
    users = kv_get("users", []) or []
    new_users = [u for u in users if u.get("username") != username]
    if len(new_users) == len(users):
        return jsonify({"error": "Niet gevonden"}), 404
    kv_set("users", new_users)
    audit_log("user.delete", username, "verwijderd")
    return jsonify({"deleted": True})


# ---------- public render proxy ----------
@app.route("/api/render/<path:slug>", methods=["GET"])
def api_render_page(slug):
    slug = _decode_slug(slug)
    # Check redirects first
    target_path = f"/{slug}/"
    for r in _redirects_index():
        if r.get("from_path") == target_path:
            return redirect(r.get("to_path"), code=int(r.get("code", 301)))
    # Serve generated HTML if any
    html = kv_get(f"page:{slug}:html")
    if not html:
        page = _get_page(slug)
        if not page or page.get("status") not in ("published",):
            return Response("Niet gevonden", status=404)
        html = render_page_html(page)
    return Response(html, mimetype="text/html")


