def _blog_page(title, description, canonical, body_html, og_image="", robots="index,follow") -> str:
    head = ('<!DOCTYPE html><html lang="nl"><head><meta charset="UTF-8">'
            + VZ_CONSENT_HEAD
            + '<meta name="viewport" content="width=device-width, initial-scale=1">'
            + f'<title>{_esc(title)}</title>'
            + f'<meta name="description" content="{_esc(description)}">'
            + f'<meta name="robots" content="{_esc(robots)}">'
            + (f'<link rel="canonical" href="{_esc(canonical)}">' if canonical else "")
            + f'<meta property="og:title" content="{_esc(title)}"><meta property="og:type" content="article">'
            + (f'<meta property="og:image" content="{_esc(og_image)}">' if og_image else "")
            + f'<link rel="icon" href="/favicon.png">'
            + '<link rel="preconnect" href="https://fonts.googleapis.com">'
            + '<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap" rel="stylesheet">'
            + '<style>' + BLOG_CSS + '</style></head><body>' + VZ_GTM_NOSCRIPT)
    return head + _blog_header() + body_html + _blog_footer() + '</body></html>'


def render_blog_index_html(posts: list) -> str:
    base = "https://bungy.nl" if False else CANONICAL_BASE
    if posts:
        cards = []
        for p in posts:
            img = p.get("featured_image") or ""
            imgstyle = f' style="background-image:url(\'{_esc(img)}\')"' if img else ""
            cards.append(
                f'<a class="bl-card" href="/blog/{_esc(p["slug"])}/">'
                f'<div class="bl-card-img"{imgstyle}></div>'
                '<div class="bl-card-body">'
                f'<span class="bl-card-date">{_esc(_nl_date(p.get("date","")))}</span>'
                f'<h3>{_esc(p.get("title",""))}</h3>'
                f'<p>{_esc(p.get("excerpt",""))}</p>'
                '<span class="bl-readmore">Lees verder &rarr;</span>'
                '</div></a>')
        grid = '<div class="bl-grid">' + "".join(cards) + '</div>'
    else:
        grid = '<div class="bl-empty">Er zijn nog geen blogartikelen.</div>'
    body = ('<section class="bl-hero"><h1>Blog</h1>'
            '<p>Tips, weetjes en nieuws over pvc-vloeren, egaliseren, trappenrenovatie en vloerverwarming.</p></section>'
            f'<div class="bl-index-wrap">{grid}</div>')
    title = "Blog | DAM Housing"
    desc = "Tips, weetjes en nieuws over pvc-vloeren, egaliseren, trappenrenovatie en vloerverwarming van DAM Housing."
    canon = f"{base}/blog/"
    # Toon de NORMALE site-header/footer door de index in de echte homepage-shell te plaatsen.
    try:
        out = _render_blog_index_in_shell(body, title, desc, canon)
        if out:
            return out
    except Exception as e:
        print("blog index shell render fout:", e)
    return _blog_page(title, desc, canon, body)


# Alleen de artikel-/content-gescopede regels uit BLOG_CSS (geen globale body/a/*-regels en
# geen .bl-header/.bl-footer/.bl-index), zodat we ze veilig in de site-shell kunnen injecteren
# zonder de echte header/footer te vervuilen.
BLOG_ARTICLE_CSS = "\n".join(
    l for l in BLOG_CSS.splitlines()
    if any(k in l for k in (".bl-wrap", ".bl-article", ".bl-meta", ".bl-feat", ".bl-content", ".bl-back")))

_BLOG_SHELL: dict = {}
_BLOG_CONTENT_TYPES = ("wp-page", "wp-post", "single-page", "single-post", "single")


# ---------------------------------------------------------------------------
# SITE-SHELL
#
# Deze site is GEEN WordPress-export maar een React/Vite-SPA: `index.html` in de
# repo-root is de Vite-template met een lege `<div id="root">`. Die is dus
# ONBRUIKBAAR als shell — React zou de server-gerenderde content bij het mounten
# meteen overschrijven. Daarom bouwen we de shell hier zelf, 1-op-1 in de stijl
# van de React-componenten (KitHeader/KitFooter): zelfde kleuren (#f07d22 op
# #1d1d1b), zelfde Inter-typografie, zelfde navigatie en footer.
#
# De shell houdt bewust dezelfde structuur aan als een Elementor-export
# (`data-elementor-type="wp-page"` + `<title>`/description/canonical), zodat
# _find_content_region() en alle bestaande shell-renderers (blog, blog-index,
# blok-pagina's, projectpagina's) ongewijzigd blijven werken.
# ---------------------------------------------------------------------------
