def _blog_shell_html() -> str:
    """De site-shell (header/footer/typografie) waarin server-gerenderde pagina's landen.

    LET OP: lees hier NIET `ROOT/index.html` (zoals bij een WP-export) — dat is de
    Vite-template van de React-SPA en bevat geen echte header/footer.

    De navigatie werd hier vroeger per render uit het CMS-menu ingevuld. Sinds
    27-08-2026 monteert de shell de ECHTE Navbar en Footer uit de React-bundel, zodat
    een CMS-pagina niet langer een eigen, afwijkende balk krijgt. Die navigatie komt
    dus uit de code van de site; de Menu-view in de admin stuurt hem niet meer aan."""
    if "h" not in _BLOG_SHELL:
        _BLOG_SHELL["h"] = VZ_SHELL_HTML
    return _BLOG_SHELL["h"]


def _find_content_region(html: str):
    """(start, end) van het content-blok (data-elementor-type=wp-page/...) tussen header en footer."""
    for et in _BLOG_CONTENT_TYPES:
        mi = html.find(f'data-elementor-type="{et}"')
        if mi < 0:
            continue
        start = html.rfind("<div", 0, mi)
        if start < 0:
            continue
        depth = 0
        for m in re.finditer(r"<(/?)div\b", html[start:]):
            depth += -1 if m.group(1) else 1
            if depth == 0:
                close = html.find(">", start + m.end())
                return (start, close + 1) if close > 0 else None
    return None


def _blog_article_html(post: dict) -> str:
    feat = post.get("featured_image") or ""
    feat_tag = f'<img class="bl-feat" src="{_esc(feat)}" alt="{_esc(post.get("title",""))}">' if feat else ""
    author = post.get("author") or "DAM Housing"
    # Visueel (in-place) bewerkte versie wint; anders blok-bewust (content_blocks); anders body.
    blocks = post.get("content_blocks") or []
    override = kv_get(f"post:{post.get('slug','')}:inplace")
    content_html = override if override else (render_blocks(blocks) if blocks else post.get("body", ""))
    return (
        '<article class="bl-wrap bl-article">'
        '<a class="bl-back" href="/blog/">&larr; Alle artikelen</a>'
        f'<h1>{_esc(post.get("title",""))}</h1>'
        f'<div class="bl-meta">{_esc(_nl_date(post.get("date","")))} &middot; {_esc(author)}</div>'
        f'{feat_tag}'
        f'<div class="bl-content">{content_html}</div>'
        '</article>' + _blog_offerte_cta())


def _render_blog_in_shell(post: dict) -> str:
    """Render het artikel in de echte site-shell (normale header/footer + opmaak)."""
    shell = _blog_shell_html()
    if not shell:
        return ""
    region = _find_content_region(shell)
    if not region:
        return ""
    new_content = '<div data-elementor-type="wp-page" class="elementor">' + _blog_article_html(post) + '</div>'
    html = shell[:region[0]] + new_content + shell[region[1]:]
    base = CANONICAL_BASE
    meta = post.get("meta", {}) or {}
    title = meta.get("title") or f'{post.get("title","")} | DAM Housing'
    desc = meta.get("description") or post.get("excerpt", "")
    canon = meta.get("canonical") or f'{base}/blog/{post.get("slug","")}/'
    html = re.sub(r"<title>.*?</title>", lambda _m: f"<title>{_esc(title)}</title>", html, count=1, flags=re.S)
    if re.search(r'<meta\s+name="description"', html):
        html = re.sub(r'<meta\s+name="description"[^>]*>', f'<meta name="description" content="{_esc(desc)}">', html, count=1)
    else:
        html = html.replace("</head>", f'<meta name="description" content="{_esc(desc)}"></head>', 1)
    if re.search(r'<link[^>]+rel="canonical"', html):
        html = re.sub(r'<link[^>]+rel="canonical"[^>]*>', f'<link rel="canonical" href="{_esc(canon)}">', html, count=1)
    html = html.replace("</head>", "<style>" + BLOG_ARTICLE_CSS + "</style></head>", 1)
    html = html.replace("</body>", _KV_REVEAL + "</body>", 1)
    return html


BLOG_INDEX_CSS = "\n".join(
    l for l in BLOG_CSS.splitlines()
    if any(k in l for k in (".bl-hero", ".bl-grid", ".bl-card", ".bl-readmore", ".bl-index-wrap", ".bl-empty")))


def _render_blog_index_in_shell(body_html: str, title: str, desc: str, canon: str) -> str:
    """Render de blog-index in de echte site-shell (normale header/footer + opmaak)."""
    shell = _blog_shell_html()
    if not shell:
        return ""
    region = _find_content_region(shell)
    if not region:
        return ""
    new_content = '<div data-elementor-type="wp-page" class="elementor">' + body_html + '</div>'
    html = shell[:region[0]] + new_content + shell[region[1]:]
    html = re.sub(r"<title>.*?</title>", lambda _m: f"<title>{_esc(title)}</title>", html, count=1, flags=re.S)
    if re.search(r'<meta\s+name="description"', html):
        html = re.sub(r'<meta\s+name="description"[^>]*>', f'<meta name="description" content="{_esc(desc)}">', html, count=1)
    else:
        html = html.replace("</head>", f'<meta name="description" content="{_esc(desc)}"></head>', 1)
    if re.search(r'<link[^>]+rel="canonical"', html):
        html = re.sub(r'<link[^>]+rel="canonical"[^>]*>', f'<link rel="canonical" href="{_esc(canon)}">', html, count=1)
    html = html.replace("</head>", "<style>" + BLOG_INDEX_CSS + "</style></head>", 1)
    return html


def _render_blog_standalone(post: dict) -> str:
    base = CANONICAL_BASE
    meta = post.get("meta", {}) or {}
    feat = post.get("featured_image") or ""
    return _blog_page(
        meta.get("title") or f'{post.get("title","")} | DAM Housing',
        meta.get("description") or post.get("excerpt", ""),
        meta.get("canonical") or f'{base}/blog/{post.get("slug","")}/',
        _blog_article_html(post), og_image=meta.get("og_image") or feat,
        robots=meta.get("robots", "index,follow"))


def render_blog_post_html(post: dict) -> str:
    # Toon de NORMALE site-header/footer door het artikel in de echte homepage-shell te
    # plaatsen; valt fail-safe terug op de losse blog-pagina als de shell niet bruikbaar is.
    try:
        out = _render_blog_in_shell(post)
        if out:
            return out
    except Exception as e:
        print("blog shell render fout:", e)
    return _render_blog_standalone(post)


# ----- posts storage -----
def get_posts_index() -> list:
    return kv_get("posts:index") or []


def _post_summary(p: dict) -> dict:
    return {"slug": p["slug"], "title": p.get("title", ""), "status": p.get("status", "draft"),
            "date": p.get("date", ""), "excerpt": p.get("excerpt", ""),
            "featured_image": p.get("featured_image", ""), "updated_at": p.get("updated_at", "")}


def get_post(slug: str):
    return kv_get(f"post:{_safe_slug(slug)}")


def save_post(p: dict) -> None:
    p["slug"] = _safe_slug(p["slug"])
    p["updated_at"] = _now_iso()
    kv_set(f"post:{p['slug']}", p)
    idx = [x for x in get_posts_index() if x.get("slug") != p["slug"]]
    idx.append(_post_summary(p))
    idx.sort(key=lambda x: (x.get("date", ""), x.get("updated_at", "")), reverse=True)
    kv_set("posts:index", idx)


def delete_post(slug: str) -> None:
    slug = _decode_slug(slug)
    kv_delete(f"post:{slug}")
    kv_set("posts:index", [x for x in get_posts_index() if x.get("slug") != slug])


def _push_post_revision(slug: str, snapshot: dict, summary: str = "") -> str:
    rev_id = _new_rev_id()
    kv_set(f"post:{slug}:rev:{rev_id}", {
        "rev_id": rev_id, "post_slug": slug, "snapshot": snapshot,
        "author": (session.get("user", "admin") if session else "admin"),
        "created_at": _now_iso(), "summary": summary,
    })
    revs = kv_get(f"post:{slug}:revs", []) or []
    revs.insert(0, rev_id)
    for stale in revs[REVISIONS_CAP:]:
        kv_delete(f"post:{slug}:rev:{stale}")
    kv_set(f"post:{slug}:revs", revs[:REVISIONS_CAP])
    return rev_id


# ----- admin endpoints -----
@app.route("/api/admin/posts", methods=["GET", "POST"])
def api_posts():
    a = _require_perm("blog")
    if a: return a
    if request.method == "GET":
        return jsonify({"posts": get_posts_index()})
    d = request.get_json(silent=True) or {}
    title = (d.get("title") or "Nieuw blogartikel").strip()
    slug = _safe_slug(d.get("slug") or slugify(title) or uuid.uuid4().hex[:8])
    if get_post(slug):
        slug = f"{slug}-{uuid.uuid4().hex[:4]}"
    post = {"slug": slug, "title": title, "status": "draft",
            "date": d.get("date") or datetime.now().strftime("%Y-%m-%d"),
            "excerpt": d.get("excerpt", ""), "body": d.get("body", ""),
            "content_blocks": d.get("content_blocks") or [],
            "featured_image": d.get("featured_image", ""), "author": d.get("author") or "DAM Housing",
            "meta": d.get("meta") or {}, "created": _now_iso()}
    save_post(post)
    audit_log("post_create", slug, title)
    return jsonify({"ok": True, "post": post})


@app.route("/api/admin/posts/<path:slug>", methods=["GET", "PUT", "DELETE"])
def api_post_detail(slug):
    a = _require_perm("blog")
    if a: return a
    safe = _safe_slug(slug)
    p = get_post(safe)
    if request.method == "GET":
        if not p: return jsonify({"error": "Niet gevonden"}), 404
        return jsonify({"post": p})
    if request.method == "DELETE":
        delete_post(safe)
        audit_log("post_delete", safe, "")
        return jsonify({"ok": True})
    if not p:
        return jsonify({"error": "Niet gevonden"}), 404
    _push_post_revision(safe, json.loads(json.dumps(p)), "save")
    d = request.get_json(silent=True) or {}
    for k in ("title", "excerpt", "body", "content_blocks", "featured_image", "author", "date", "status", "meta"):
        if k in d:
            p[k] = d[k]
    new_slug = _safe_slug(d.get("slug") or safe)
    if new_slug and new_slug != safe:
        kv_delete(f"post:{safe}")
        kv_set("posts:index", [x for x in get_posts_index() if x.get("slug") != safe])
        p["slug"] = new_slug
    save_post(p)
    audit_log("post_update", p["slug"], p.get("title", ""))
    return jsonify({"ok": True, "post": p})


@app.route("/api/admin/posts/<path:slug>/publish", methods=["POST"])
@app.route("/api/admin/posts/<path:slug>/publish/", methods=["POST"])
def api_post_publish(slug):
    a = _require_perm("blog")
    if a: return a
    p = get_post(slug)
    if not p:
        return jsonify({"error": "Niet gevonden"}), 404
    p["status"] = "draft" if p.get("status") == "published" else "published"
    if p["status"] == "published" and not p.get("date"):
        p["date"] = datetime.now().strftime("%Y-%m-%d")
    save_post(p)
    _trigger_deploy("blog publish " + str(slug))
    return jsonify({"ok": True, "status": p["status"]})


@app.route("/api/admin/posts/<path:slug>/revisions", methods=["GET"])
def api_post_revisions(slug):
    a = _require_perm("blog")
    if a: return a
    slug = _safe_slug(slug)
    ids = (kv_get(f"post:{slug}:revs", []) or [])[:int(request.args.get("limit", 20))]
    items = []
    for rev_id in ids:
        rev = kv_get(f"post:{slug}:rev:{rev_id}")
        if rev:
            items.append({"rev_id": rev["rev_id"], "author": rev.get("author"),
                          "created_at": rev.get("created_at"), "summary": rev.get("summary")})
    return jsonify({"items": items})


@app.route("/api/admin/posts/<path:slug>/restore", methods=["POST"])
@app.route("/api/admin/posts/<path:slug>/restore/", methods=["POST"])
def api_post_restore(slug):
    a = _require_perm("blog")
    if a: return a
    slug = _safe_slug(slug)
    rev_id = (request.get_json(silent=True) or {}).get("rev_id")
    rev = kv_get(f"post:{slug}:rev:{rev_id}")
    if not rev:
        return jsonify({"error": "Revisie niet gevonden"}), 404
    cur = get_post(slug)
    if cur:
        _push_post_revision(slug, json.loads(json.dumps(cur)), f"pre-restore from {rev_id}")
    snap = rev.get("snapshot") or {}
    snap["slug"] = slug
    save_post(snap)
    audit_log("post.restore", slug, f"Restored {rev_id}")
    return jsonify({"ok": True, "restored_from": rev_id})


# ---------- blog Visueel (in-place) bewerken ----------
@app.route("/api/admin/post-source/<path:slug>", methods=["GET"])
def api_post_source(slug):
    """Volledige gerenderde blogpagina (shell + artikel) om visueel te bewerken.
    Bevat de in-place override als die er is (zodat je verder bewerkt vanaf je laatste versie)."""
    a = _require_perm("blog")
    if a: return a
    p = get_post(_safe_slug(slug))
    if not p:
        return jsonify({"error": "Niet gevonden"}), 404
    return jsonify({"html": render_blog_post_html(p)})


@app.route("/api/admin/post-inplace/<path:slug>", methods=["POST", "DELETE"])
def api_post_inplace(slug):
    a = _require_perm("blog")
    if a: return a
    slug = _safe_slug(slug)
    if request.method == "DELETE":
        kv_delete(f"post:{slug}:inplace")
        audit_log("post.inplace.revert", slug, "Terug naar blokken")
        return jsonify({"ok": True, "reverted": True})
    html = (request.get_json(silent=True) or {}).get("html") or ""
    if not html.strip():
        return jsonify({"error": "Lege inhoud"}), 400
    kv_set(f"post:{slug}:inplace", html)
    audit_log("post.inplace.save", slug, f"Visueel bewerkt ({len(html)//1024}KB)")
    return jsonify({"ok": True})


def _blog_eigen_fotos(body: str, media: list) -> str:
    """Vervangt elke foto in een gegenereerd artikel door een foto van de site zelf.

    De prompt vraagt al om alleen URL's uit de meegegeven lijst, maar een taalmodel dat een
    foto "nodig heeft" verzint er anders gewoon een — in de praktijk een stockfoto van een
    fotobank. Dat is niet het werk van de klant, het kan zomaar verdwijnen, en het staat op
    een pagina die wij publiceren. Dus dwingen we het hier af: onbekende bron eruit, eigen
    foto ervoor in de plaats. Is er geen eigen foto meer over, dan verdwijnt de afbeelding
    helemaal — liever geen foto dan die van iemand anders.
    """
    eigen = [str(m.get("url") or "") for m in (media or []) if m.get("url")]
    toegestaan = set(eigen)
    gebruikt = set()

    def bron(tag: str) -> str:
        m = re.search(r"""src\s*=\s*["']([^"']+)["']""", tag, re.I)
        return m.group(1) if m else ""

    # Eerst de foto's die al goed staan reserveren, anders pakt de vervanger er één die
    # verderop in het artikel al gebruikt wordt.
    for tag in re.findall(r"<img\b[^>]*>", body, re.I):
        if bron(tag) in toegestaan:
            gebruikt.add(bron(tag))

    def vervang(m) -> str:
        tag = m.group(0)
        if bron(tag) in toegestaan:
            return tag
        vrij = next((u for u in eigen if u not in gebruikt), "")
        if not vrij:
            return ""
        gebruikt.add(vrij)
        return re.sub(r"""(src\s*=\s*["'])[^"']*(["'])""", lambda k: k.group(1) + vrij + k.group(2),
                      tag, count=1)

    uit = re.sub(r"<img\b[^>]*>", vervang, body, flags=re.I)
    return re.sub(r"""\ssrcset\s*=\s*["'][^"']*["']""", "", uit, flags=re.I)


def _ai_generate_post(topic):
    """Genereer een rijk vormgegeven blogartikel met AI. Returns (draft_dict, None) of (None, {error,code}).
    draft_dict = {title, excerpt, body(HTML), meta_description}. Gedeeld door de HTTP-endpoint én de
    autonome SEO-motor (die maakt er daarna een gepubliceerde post van)."""
    if not _ai_configured():
        return None, {"error": "Geen Claude API-key ingesteld — vul 'm in bij Instellingen → Integraties → Claude (Anthropic).", "code": 503}
    topic = (topic or "").strip()
    if not topic:
        return None, {"error": "Onderwerp verplicht", "code": 400}
    # Echte foto's meegeven zodat de AI ze kan inbedden (placeholders zijn al weggefilterd).
    _media = [m for m in _ai_context_media(24) if m.get("url", "").lower().endswith((".jpg", ".jpeg", ".png", ".webp"))][:16]
    def _bdesc(m):
        dd = (m.get("alt") or m.get("name") or "").rsplit(".", 1)[0].replace("-", " ").replace("_", " ").strip()
        return dd or "foto"
    img_list = "\n".join(f"- {m['url']}  → {_bdesc(m)}" for m in _media if m.get("url"))
    _pages = _ai_context_pages(25)
    page_list = "\n".join(f"- {p.get('url')}  ({p.get('title','')})" for p in _pages if p.get("url"))
    system = (
        "Je bent een Nederlandse SEO-copywriter én webdesigner voor DAM Housing, dat pvc-vloeren legt, "
        "vloeren egaliseert, trappen renoveert en vloerverwarming infreest (Culemborg, Tiel en regio Rivierenland). "
        "Schrijf een behulpzaam, deskundig én RIJK VORMGEGEVEN blogartikel van 600-900 woorden. "
        "De 'body' is HTML die direct op de site getoond wordt. Maak er een uniek, modern magazine-achtig artikel "
        "van met inline-styles (merkkleur #f07d22 als accent, lichte tint #fce8d5 voor vlakken) — NIET alleen kale "
        "alinea's. Wissel de secties visueel af en kies per artikel een andere combinatie, o.a.:\n"
        "- Een korte, pakkende intro-alinea die de zoekintentie meteen adresseert (waar zoekt de lezer naar?).\n"
        "- Geef ELKE <h2> een uniek id in kebab-case (bv. <h2 id=\"schimmel-voorkomen\">); GEEN <h1>; korte, vlotte alinea's.\n"
        "- DIRECT NA de intro een 'Belangrijkste punten'-blok (TL;DR): "
        '<div style=\"background:#fce8d5;border-radius:12px;padding:16px 20px;margin:18px 0\"><strong>Belangrijkste punten</strong><ul style=\"margin:10px 0 0;padding-left:18px\">…</ul></div> '
        "met 3-5 bullets van de kernpunten, waarbij ELKE bullet een jump-link is naar de bijbehorende sectie "
        '(<a href=\"#sectie-id\">korte kernzin</a>). Goed voor mobiele lezers én Google AI-overviews.\n'
        "- MINSTENS 2 foto's uit de fotolijst hieronder, ingebed als "
        '<img src=\"<EXACTE-URL>\" alt=\"...\" style=\"width:100%;border-radius:14px;margin:20px 0;display:block\">. '
        "Kies foto's die INHOUDELIJK bij de tekst passen (lees de omschrijving achter de pijl). Gebruik ALLEEN URL's "
        "uit de lijst, exact overgenomen, en niet twee keer dezelfde.\n"
        "- Eén opvallend tip/weetje-blok: "
        '<div style=\"background:#fce8d5;border-left:4px solid #f07d22;border-radius:10px;padding:16px 20px;margin:20px 0\"><strong><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#f07d22\" stroke-width=\"2\" style=\"vertical-align:-3px;margin-right:6px\"><path d=\"M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7c.6.5 1 1.3 1 2.1h6c0-.8.4-1.6 1-2.1A7 7 0 0 0 12 2z\"/></svg>Tip:</strong> …</div>\n'
        "- Waar passend een genummerd stappenplan met gestylde stappen, elk bijv.: "
        '<div style=\"display:flex;gap:14px;align-items:flex-start;margin:14px 0\"><span style=\"flex-shrink:0;width:30px;height:30px;border-radius:50%;background:#f07d22;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700\">1</span><div>…</div></div>\n'
        "- Waar passend een 2-koloms vergelijking/'voor &amp; na' (<div style=\"display:flex;gap:16px;flex-wrap:wrap\">…</div>) "
        'of een quote-blok (<blockquote style=\"border-left:4px solid #f07d22;padding:6px 18px;margin:20px 0;font-style:italic;color:#475569\">…</blockquote>).\n'
        "- Een <ul> met praktische punten.\n"
        "- INTERNE LINKS (belangrijk voor SEO): verwerk 2-3 links naar relevante BESTAANDE pagina's uit de paginalijst "
        "hieronder, als <a href=\"/pad/\">natuurlijke ankertekst</a> binnen lopende zinnen. Gebruik de paden EXACT uit de lijst.\n"
        "- EXTERNE LINK (SEO): voeg minstens 1 link toe naar een gezaghebbende, relevante externe bron "
        "(bv. een Wikipedia-artikel of een brancheorganisatie), als <a href=\"https://...\" target=\"_blank\" rel=\"noopener\">ankertekst</a>.\n"
        "- SLUIT AF met een korte conclusie-alinea (<h2 id=\"conclusie\">) die de kernpunten samenvat en de lezer een logische vervolgstap geeft.\n"
        "- ANKERTEKST: gebruik in ÁLLE links (intern + extern) natuurlijke, beschrijvende ankertekst die zegt waar de link heen gaat — NOOIT 'klik hier'/'lees meer'.\n"
        "- Voeg ZELF GEEN offerte-knop of afsluitende CTA toe: onder het artikel staat al automatisch een offerte-blok.\n"
        "Gebruik GEEN emoji's in de tekst, koppen of blokken. Wil je een icoon, gebruik dan UITSLUITEND een eenvoudige inline-SVG (zoals bij het tip-blok hierboven). "
        "Gebruik gewone streepjes (-) in plaats van lange streepjes (— of –). "
        "Varieer de opmaak per artikel zodat niet elk artikel er hetzelfde uitziet. Schrijf natuurlijk, lokaal en concreet. "
        "KOPPEN ÉN TITEL IN NEDERLANDSE ZINSSTIJL: alleen het eerste woord + eigennamen met een hoofdletter "
        "(dus 'Pvc-vloer laten leggen: wat kost het', NIET 'Pvc-vloer Laten Leggen: Wat Kost Het' — Engelse title-case is FOUT; geldt voor de TITEL én elke <h2>). "
        "Vermijd holle AI-clichés (essentieel, cruciaal, naadloos, in de wereld van, ontdek, in dit artikel). "
        "Antwoord EXACT in dit formaat — GEEN JSON, geen code-fences, geen extra tekst eromheen:\n"
        "TITEL: <pakkende titel>\n"
        "EXCERPT: <korte samenvatting, max 160 tekens>\n"
        "META: <meta-omschrijving, max 160 tekens>\n"
        "===BODY===\n"
        "<hier de volledige, opgemaakte HTML zoals hierboven, met ingebedde <img>>")
    user_msg = (f"Schrijf een blogartikel over: {topic}"
                + (("\n\nBeschikbare foto's (formaat: URL → omschrijving — gebruik er minstens 2, inhoudelijk passend):\n" + img_list) if img_list else "")
                + (("\n\nBestaande pagina's voor interne links (pad — titel):\n" + page_list) if page_list else ""))
    # Haiku: fors sneller dan Sonnet/Opus, zodat een rijk artikel ruim binnen de ~55s blijft
    # (Sonnet bij 4096 tokens zat tegen de timeout). Het delimiter-formaat hieronder breekt NIET
    # als de output toch wordt afgekapt (i.t.t. JSON), en vangt Haiku's JSON-quirks op.
    r = _anthropic_call([{"role": "user", "content": user_msg}],
                        system=system, max_tokens=4096, model="claude-haiku-4-5-20251001")
    if r.get("error"):
        return None, {"error": r.get("error"), "details": r.get("details", ""), "code": 502}
    txt = "".join(b.get("text", "") for b in r.get("content", []))

    def _grab(label):
        mm = re.search(r"^\s*" + label + r"\s*:\s*(.+)$", txt, re.M | re.I)
        return mm.group(1).strip() if mm else ""

    parts = re.split(r"={2,}\s*BODY\s*={2,}", txt, maxsplit=1, flags=re.I)
    if len(parts) > 1:
        body = re.sub(r"^```(?:html)?\s*|\s*```$", "", parts[1].strip()).strip()
        title = _grab("TITEL") or _grab("TITLE") or topic
        excerpt = _grab("EXCERPT")
        meta = _grab("META") or excerpt
    else:
        # Fallback: model gaf toch JSON terug.
        jm = re.search(r"\{.*\}", txt, re.S)
        data0 = {}
        if jm:
            try:
                data0 = json.loads(jm.group(0))
            except Exception:
                data0 = {}
        title = data0.get("title") or topic
        excerpt = data0.get("excerpt") or ""
        meta = data0.get("meta_description") or excerpt
        body = data0.get("body") or ""
    if not body or len(body) < 40:
        return None, {"error": "AI gaf geen bruikbare inhoud", "details": txt[:300], "code": 502}
    # Foto's uit de eigen medialijst afdwingen — de instructie in de prompt is geen garantie.
    body = _blog_eigen_fotos(body, _media)
        # AI-SEO auto-fill (Wim 2026-07-15): geef het draft-object volledige SEO mee.
    seo_meta = {}
    try:
        _seo = _ai_seo_autofill("blog", title, _extract_plaintext(body),
                                hero_image=_first_image_url_in(body),
                                slug=slugify(title), extras={"date": datetime.now().strftime("%Y-%m-%d")})
        seo_meta = {
            "title": _seo.get("seo_title", ""),
            "description": _seo.get("meta_description", "") or meta,
            "keyword": _seo.get("focus_keyword", ""),
            "og_title": _seo.get("og_title", ""),
            "og_description": _seo.get("og_description", ""),
            "og_image": _seo.get("og_image", ""),
            "twitter_card": _seo.get("twitter_card", "summary_large_image"),
            "twitter_image": _seo.get("twitter_image", ""),
            "schema_jsonld": _seo.get("schema_jsonld"),
            "breadcrumb_jsonld": _seo.get("breadcrumb_jsonld"),
        }
    except Exception as _e:
        try: app.logger.warning("AI-SEO autofill (blog) faalde: %s", _e)
        except Exception: pass
    return {"title": title, "excerpt": excerpt, "body": body,
            "meta_description": meta, "meta": seo_meta,
            "featured_image": _first_image_url_in(body)}, None


@app.route("/api/admin/posts/ai-generate", methods=["POST"])
def api_post_ai_generate():
    """Dunne wrapper rond _ai_generate_post(): genereert een blog-concept uit een onderwerp."""
    a = _require_agency()
    if a: return a
    draft, err = _ai_generate_post((request.get_json(silent=True) or {}).get("topic") or "")
    if err:
        out = {"error": err.get("error", "AI-aanroep mislukt")}
        if err.get("details"):
            out["details"] = err["details"]
        return jsonify(out), err.get("code", 502)
    return jsonify({"ok": True, "draft": draft})


def _ai_blog_topics(n=8, theme="", avoid=None):
    """Laat AI n zoekwoord-gerichte blogonderwerpen bedenken (en bestaande vermijden). Returns lijst strings."""
    if not _ai_configured():
        return []
    n = max(1, min(12, int(n or 8)))
    existing = list(avoid) if avoid is not None else [p.get("title", "") for p in (get_posts_index() or [])][:30]
    system = (
        "Je bent een Nederlandse SEO-strateeg voor DAM Housing (vloerenbedrijf: pvc-vloeren, vloeren "
        "egaliseren, trappenrenovatie en vloerverwarming). Bedenk pakkende, zoekwoord-gerichte blogonderwerpen "
        "die klanten daadwerkelijk googelen (informatief en lokaal/transactioneel). "
        f'Antwoord UITSLUITEND met JSON: {{"topics": ["onderwerp 1", ...]}} met precies {n} korte, concrete onderwerpen, zonder nummering.')
    user = f"Bedenk {n} nieuwe blogonderwerpen" + (f" rond: {theme[:200]}" if theme else "") + "."
    if any(existing):
        user += "\nVermijd onderwerpen die al bestaan:\n" + "\n".join(f"- {t}" for t in existing if t)
    r = _anthropic_call([{"role": "user", "content": user}], system=system, max_tokens=700)
    if r.get("error"):
        return []
    txt = "".join(b.get("text", "") for b in r.get("content", []))
    m = re.search(r"\{.*\}", txt, re.S)
    try:
        topics = (json.loads(m.group(0)) if m else {}).get("topics") or []
    except json.JSONDecodeError:
        topics = []
    return [str(t).strip() for t in topics if str(t).strip()][:n]


@app.route("/api/admin/posts/ai-topics", methods=["POST"])
def api_post_ai_topics():
    """AI stelt blogonderwerpen voor (optioneel rond een thema). Dunne wrapper rond _ai_blog_topics()."""
    a = _require_agency()
    if a: return a
    if not _ai_configured():
        return jsonify({"error": "Geen Claude API-key ingesteld — vul 'm in bij Instellingen → Integraties → Claude (Anthropic)."}), 503
    theme = ((request.get_json(silent=True) or {}).get("theme") or "").strip()[:200]
    return jsonify({"ok": True, "topics": _ai_blog_topics(8, theme)})


@app.route("/api/admin/pages/ai-ideas", methods=["POST"])
def api_pages_ai_ideas():
    """AI stelt nieuwe pagina's voor: lijst van {title, prompt-briefing}."""
    a = _require_agency()
    if a: return a
    if not _ai_configured():
        return jsonify({"error": "Geen Claude API-key ingesteld — vul 'm in bij Instellingen → Integraties → Claude (Anthropic)."}), 503
    d = request.get_json(silent=True) or {}
    theme = (d.get("theme") or "").strip()[:200]
    parent_slug = _safe_slug(d.get("parent_slug") or "")
    all_pages = _ai_context_pages(60)
    # Bij een parent: scope de suggesties op die tak (zusterpagina's) zodat ze passen bij wat er al staat.
    if parent_slug:
        siblings = [p for p in all_pages if (p.get("url") or "").strip("/").startswith(parent_slug + "/")]
        existing = [p.get("title", "") for p in (siblings or all_pages)]
    else:
        existing = [p.get("title", "") for p in all_pages]
    system = (
        "Je bent een SEO/contentstrateeg voor DAM Housing (vakkundig vloeren leggen). Bedenk nuttige nieuwe "
        "webpagina's die nog kunnen ontbreken (dienst- of locatiepagina's met zoekvolume en conversiekans). "
        'Antwoord UITSLUITEND met JSON: {"ideas":[{"title":"...","prompt":"korte briefing van wat er op de pagina moet komen"}, ...]} '
        "met precies 4 items, Nederlands, concreet.")
    user = "Bedenk 4 paginavoorstellen"
    if parent_slug:
        user += (f" die als SUBPAGINA onder /{parent_slug}/ passen — in dezelfde categorie en stijl als de bestaande "
                 f"pagina's in die tak. Beschrijf elke 'prompt' als een subpagina onder /{parent_slug}/")
    elif theme:
        user += f" rond: {theme}"
    user += "."
    if any(existing):
        lbl = ("Bestaande pagina's in deze tak (sluit erop aan, niet dupliceren):" if parent_slug
               else "Bestaande pagina's (niet dupliceren):")
        user += "\n" + lbl + "\n" + "\n".join(f"- {t}" for t in existing if t)
    # Haiku i.p.v. het trage default-model (Opus): suggesties zijn een simpele JSON-taak; Haiku
    # is snel en geeft betrouwbaar geldige JSON terug (Opus gaf hier wisselvallig lege output).
    r = _anthropic_call([{"role": "user", "content": user}], system=system, max_tokens=900,
                        model="claude-haiku-4-5-20251001")
    if r.get("error"): return jsonify({"error": r.get("error"), "details": r.get("details", "")}), 502
    txt = "".join(b.get("text", "") for b in r.get("content", []))
    # Lenient parsen (```json-fences/trailing comma's). Accepteer zowel {"ideas":[...]} als een kale array.
    parsed = _loads_lenient(txt)
    raw_ideas = parsed.get("ideas") if isinstance(parsed, dict) else None
    if not raw_ideas:
        # Fallback: een kale JSON-array [ {...}, ... ] uit de tekst halen (_loads_lenient mangelt arrays).
        m = re.search(r"\[\s*\{.*\}\s*\]", txt, re.S)
        if m:
            try:
                raw_ideas = json.loads(re.sub(r",(\s*[}\]])", r"\1", m.group(0)))
            except Exception:
                raw_ideas = []
    raw_ideas = raw_ideas or []
    ideas = []
    for i in (raw_ideas or []):
        if not isinstance(i, dict):
            continue
        title = str(i.get("title", "")).strip()
        prompt_txt = str(i.get("prompt", i.get("description", ""))).strip()
        if title or prompt_txt:
            ideas.append({"title": title or prompt_txt[:60], "prompt": prompt_txt or title})
        if len(ideas) >= 4:
            break
    return jsonify({"ok": True, "ideas": ideas})


