def render_project_page(p: dict) -> str:
    """Render een projectdetailpagina in de echte site-shell (normale header/footer + opmaak)."""
    base = CANONICAL_BASE
    title = p.get("title", "Project")
    loc = (p.get("location") or "").strip()
    date = _nl_date(p.get("date", "")) if p.get("date") else ""
    desc = (p.get("description") or "").strip().replace("—", "-").replace("–", "-")
    img = (p.get("image_url") or "").strip()
    meta = " · ".join([x for x in (loc, date) if x])
    feat = (f'<img src="{_esc(img)}" alt="{_esc(title)}" style="width:100%;max-height:380px;object-fit:cover;border-radius:18px;display:block;margin:10px 0 30px">' if img else "")
    paras = "".join(f"<p>{_esc(par.strip())}</p>" for par in re.split(r"\n{2,}", desc) if par.strip())
    chips = ""
    if loc:
        chips = ('<div style="margin:12px 0 2px">'
                 '<span style="display:inline-flex;align-items:center;gap:6px;background:#fce8d5;color:#a8470f;'
                 'border-radius:999px;padding:7px 15px;font-weight:600;font-size:.85rem;line-height:1">'
                 '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0z"/><circle cx="12" cy="10" r="3"/></svg>'
                 f'<span>{_esc(loc)}</span></span></div>')
    body = (
        '<article class="bl-wrap bl-article">'
        '<a class="bl-back" href="/projecten/">&larr; Alle projecten</a>'
        f'{chips}'
        f'<h1>{_esc(title)}</h1>'
        + (f'<div class="bl-meta">{_esc(date)}</div>' if date else "")
        + feat
        + (f'<div class="bl-content">{paras}</div>' if paras else "")
        + _blog_offerte_cta()
        + '</article>'
    )
    desc_meta = (desc[:157] + "…") if len(desc) > 158 else (desc or (f"Project van DAM Housing" + (f" in {loc}" if loc else "") + "."))
    canon = f"{base}/projecten/{_project_slug(p)}/"
    page_title = f"{title} | Projecten | DAM Housing"
    shell = _blog_shell_html()
    region = _find_content_region(shell) if shell else None
    if shell and region:
        html = shell[:region[0]] + '<div data-elementor-type="wp-page" class="elementor">' + body + '</div>' + shell[region[1]:]
        html = re.sub(r"<title>.*?</title>", lambda _m: f"<title>{_esc(page_title)}</title>", html, count=1, flags=re.S)
        if re.search(r'<meta\s+name="description"', html):
            html = re.sub(r'<meta\s+name="description"[^>]*>', f'<meta name="description" content="{_esc(desc_meta)}">', html, count=1)
        else:
            html = html.replace("</head>", f'<meta name="description" content="{_esc(desc_meta)}"></head>', 1)
        if re.search(r'<link[^>]+rel="canonical"', html):
            html = re.sub(r'<link[^>]+rel="canonical"[^>]*>', f'<link rel="canonical" href="{_esc(canon)}">', html, count=1)
        html = html.replace("</head>", "<style>" + BLOG_ARTICLE_CSS + "</style></head>", 1)
        return html
    return _blog_page(page_title, desc_meta, canon, body, og_image=img)


@app.route("/projecten/<path:slug>/", methods=["GET"])
@app.route("/projecten/<path:slug>", methods=["GET"])
def serve_project_page(slug):
    """Projectdetailpagina uit de CMS-store; bestaat de slug niet, dan 301 naar /projecten.

    Er hebben negentien projecten van een ANDERE klant op /projecten/<slug>/ gestaan
    (bootstrap-seed uit de bronrepo). Die zijn uit de store gehaald, maar ze zijn wél
    geïndexeerd geweest. Een 404 gooit die bezoekers en signalen weg; de portfolio van
    DAM Housing staat op /projecten, dus daar sturen we ze permanent heen. Dat geldt meteen
    voor élke onbekende projectslug — een dode projectlink hoort thuis in het overzicht,
    niet op een foutpagina. De redirect zit hier en niet in vercel.json, omdat
    /projecten/(.*) daar al naar deze function wordt gerewrite: een redirect-regel
    ervóór zou ook de echte projectpagina's uit de admin onbereikbaar maken."""
    safe = _safe_slug(slug.rstrip("/"))
    for p in get_projects():
        if p.get("status", "published") != "published" and not is_logged_in():
            continue
        if _project_slug(p) == safe:
            return Response(render_project_page(p), mimetype="text/html")
    return redirect("/projecten", code=301)


# ==================== FACTUREN / INVOICES ====================
def get_invoices_index() -> list:
    return kv_get("invoices:index") or []


def get_invoice(iid: str):
    return kv_get(f"invoice:{iid}")


def _invoice_totals(inv: dict) -> dict:
    lines = inv.get("lines", []) or []
    subtotal = 0.0
    for l in lines:
        try:
            subtotal += float(l.get("qty", 0)) * float(l.get("price", 0))
        except (TypeError, ValueError):
            pass
    rate = float(inv.get("btw_rate", 21) or 0)
    btw = round(subtotal * rate / 100, 2)
    return {"subtotal": round(subtotal, 2), "btw": btw, "total": round(subtotal + btw, 2)}


def _next_invoice_number() -> str:
    year = datetime.now().year
    ctr = kv_get("invoice:counter") or {}
    seq = int(ctr.get(str(year), 0)) + 1
    ctr[str(year)] = seq
    kv_set("invoice:counter", ctr)
    return f"{year}-{seq:03d}"


def _inv_summary(inv: dict) -> dict:
    t = _invoice_totals(inv)
    cl = inv.get("client", {}) or {}
    return {"id": inv["id"], "number": inv.get("number", ""), "date": inv.get("date", ""),
            "due_date": inv.get("due_date", ""), "status": inv.get("status", "concept"),
            "client_name": cl.get("name", ""), "client_email": cl.get("email", ""),
            "total": t["total"], "btw": t["btw"], "subtotal": t["subtotal"], "lead_id": inv.get("lead_id", "")}


def save_invoice(inv: dict) -> None:
    kv_set(f"invoice:{inv['id']}", inv)
    idx = [x for x in get_invoices_index() if x.get("id") != inv["id"]]
    idx.append(_inv_summary(inv))
    idx.sort(key=lambda x: (x.get("date", ""), x.get("number", "")), reverse=True)
    kv_set("invoices:index", idx)


def delete_invoice(iid: str) -> None:
    kv_delete(f"invoice:{iid}")
    kv_set("invoices:index", [x for x in get_invoices_index() if x.get("id") != iid])


def _company() -> dict:
    return (get_settings().get("company") or {})


def _business_profile() -> dict:
    """Branche-profiel uit de instellingen (multi-tenant — niets hardcoded in de AI-prompts).
    Regio wordt uit het adres afgeleid als die niet expliciet is gezet."""
    co = _company()
    name = (co.get("name") or "het bedrijf").strip()
    sector = (co.get("sector") or "").strip()
    region = (co.get("region") or "").strip()
    service_area = (co.get("service_area") or "").strip()
    addr = (co.get("address") or "").strip()
    if not region and addr:
        # "Straat 42, 2901 KD Utrecht" -> "Utrecht"
        tail = addr.split(",")[-1].strip()
        region = re.sub(r"^\d{4}\s?[A-Za-z]{2}\s*", "", tail).strip() or tail
    return {"name": name, "sector": sector, "region": region, "service_area": service_area,
            "address": addr, "phone": (co.get("phone") or "").strip(),
            "email": (co.get("email") or "").strip()}


def _seo_business_context() -> str:
    """Korte, mensvriendelijke beschrijving van het bedrijf voor in een AI-prompt."""
    b = _business_profile()
    parts = [b["name"]]
    if b["sector"]:
        parts.append(b["sector"])
    if b["region"]:
        parts.append(f"regio {b['region']}")
    base = ", ".join(parts)
    if b["service_area"]:
        base += f" (werkgebied {b['service_area']})"
    return base


def _seo_known_paths() -> set:
    """Alle echte, publieke content-paden (pagina's + blogposts), genormaliseerd met trailing slash."""
    paths = set()
    for p in _pages_index():
        slug = (p.get("slug") or "").strip("/")
        paths.add(("/" + slug + "/") if slug else "/")
    try:
        for post in (get_posts_index() or []):
            s = (post.get("slug") or "").strip("/")
            if s:
                paths.add("/blog/" + s + "/")
    except Exception:
        pass
    return paths


def _seo_traffic_views() -> dict:
    """Genormaliseerde {pad: views} uit eigen tracking, GEFILTERD op echte content-paden.
    Voorkomt dat de ruwe `_`->`/`-terugmap (admin/api/foutpaden) de strategie vervuilt."""
    known = _seo_known_paths()
    out = {}
    for t in (_list_pageview_paths() or []):
        raw = (t.get("path") or "").strip()
        if not raw:
            continue
        norm = raw if raw.startswith("/") else "/" + raw
        norm = norm if norm.endswith("/") else norm + "/"
        if norm in known:
            out[norm] = out.get(norm, 0) + int(t.get("views") or 0)
    return out


def _seo_priority(score, views: int) -> float:
    """Deterministische prioriteit: hoe lager de score en hoe meer verkeer, hoe hoger.
    (100 - score) x log10(views + 10). Reproduceerbaar tussen runs (geen AI-gok)."""
    try:
        sc = int(score)
    except Exception:
        sc = 0
    headroom = max(0, 100 - sc)
    return round(headroom * math.log10(max(0, views) + 10), 1)


def _seo_gsc_signals(days: int = 90) -> dict:
    """Search Console-signalen voor de strategie. ALTIJD graceful: {connected:False} als de site
    niet gekoppeld is of de API faalt — de strategie blijft dan op eigen data draaien."""
    try:
        site = (get_settings().get("search_console") or {}).get("site", "")
        if not site:
            return {"connected": False}
        to = datetime.now().strftime("%Y-%m-%d")
        frm = (datetime.now() - timedelta(days=days)).strftime("%Y-%m-%d")
        byq, err = _sc_query(site, frm, to, ["query"], timeout=8)   # kort: mag de strategie-timeout niet opeten
        if err:
            return {"connected": False, "error": err}
        striking = []
        for row in (byq.get("rows") or []):
            pos = float(row.get("position", 0) or 0)
            impr = int(row.get("impressions", 0) or 0)
            # "Striking distance": bijna op pagina 1 (positie ~5-15) met echte vertoningen.
            if 4.5 <= pos <= 15.5 and impr > 0:
                striking.append({"query": row["keys"][0], "clicks": int(row.get("clicks", 0)),
                                 "impressions": impr, "position": round(pos, 1)})
        striking.sort(key=lambda x: x["impressions"], reverse=True)
        return {"connected": True, "striking": striking[:15]}
    except Exception as e:
        return {"connected": False, "error": str(e)}


def _seo_page_queries(days: int = 90) -> dict:
    """{pad: {clicks, impressions, ctr, top_queries[]}} uit Search Console (dim page+query).
    Leeg dict als niet verbonden/fout — voor CTR-gedreven meta-herschrijving."""
    try:
        site = (get_settings().get("search_console") or {}).get("site", "")
        if not site:
            return {}
        to = datetime.now().strftime("%Y-%m-%d")
        frm = (datetime.now() - timedelta(days=days)).strftime("%Y-%m-%d")
        rows_pq, err = _sc_query(site, frm, to, ["page", "query"], timeout=8)
        if err:
            return {}
        agg = {}
        for row in (rows_pq.get("rows") or []):
            keys = row.get("keys") or ["", ""]
            try:
                path = urllib.parse.urlparse(keys[0]).path or "/"
            except Exception:
                path = keys[0]
            path = path if path.endswith("/") else path + "/"
            d = agg.setdefault(path, {"clicks": 0, "impressions": 0, "_q": []})
            d["clicks"] += int(row.get("clicks", 0) or 0)
            d["impressions"] += int(row.get("impressions", 0) or 0)
            d["_q"].append((keys[1], int(row.get("impressions", 0) or 0)))
        for path, d in agg.items():
            d["ctr"] = round(d["clicks"] / d["impressions"], 3) if d["impressions"] else 0.0
            d["top_queries"] = [q for q, _ in sorted(d["_q"], key=lambda x: x[1], reverse=True)[:3]]
            del d["_q"]
        return agg
    except Exception:
        return {}


def _eur(v) -> str:
    """Bedrag in Nederlandse notatie: € 1.234,56 — zoals op Ricks eigen papier."""
    try:
        n = float(v or 0)
    except (TypeError, ValueError):
        n = 0.0
    heel, _, cent = f"{abs(n):,.2f}".partition(".")
    return f"{'-' if n < 0 else ''}€ {heel.replace(',', '.')},{cent}"


def _aantal(v) -> str:
    """1.0 -> 1, 40.5 -> 40,5. Een aantal van '1,00' leest als een bedrag."""
    try:
        n = float(v or 0)
    except (TypeError, ValueError):
        return _esc(v)
    return (f"{n:.2f}".rstrip("0").rstrip(".") or "0").replace(".", ",")


def _aantal_met_eenheid(aantal, eenheid) -> str:
    """"145 m\u00b2" in de kolom Aantal. De maat die de klant opgaf hoort daar, niet
    tussen haakjes achter de omschrijving (wens van Rick, 2026-08-15)."""
    eenheid = str(eenheid or "").strip()
    return f"{_aantal(aantal)} {eenheid}".strip()


def _doc_logo(co: dict) -> str:
    """Het documentpapier is wit; de diap-wordmark valt daarop volledig weg.
    Staat die in de instellingen, dan pakken we de donkere tegenhanger."""
    url = (co.get("logo_url") or "/dam-logo.png").strip()
    return url.replace("-white.", ".") if "-white." in url else url


