def _doc_regels(doc: dict) -> str:
    rijen = ""
    for l in (doc.get("lines") or []):
        try:
            aantal = float(l.get("qty", 0) or 0)
            prijs = float(l.get("price", 0) or 0)
        except (TypeError, ValueError):
            aantal, prijs = 0.0, 0.0
        oms = _esc(str(l.get("desc", ""))).replace("\n", "<br>")
        rijen += (f'<tr><td>{oms}</td><td class="r">{_aantal_met_eenheid(aantal, l.get("unit"))}</td>'
                  f'<td class="r">{_eur(prijs)}</td><td class="r">{_eur(aantal * prijs)}</td></tr>')
    return rijen or '<tr><td colspan="4" style="color:#9aa2ae">Nog geen regels</td></tr>'


# ---------------------------------------------------------------------------
# Hetzelfde document als PDF (stdlib — geen PDF-library op de serverless build)
# ---------------------------------------------------------------------------
# Breedtes uit de Helvetica-metrics (tekens 32..126, duizendsten van de fontgrootte).
# Nodig omdat bedragen RECHTS uitgelijnd staan: zonder echte breedtes schuift de
# kolom per regel een paar punten op en oogt de tabel scheef.
_HELV_W = [278, 278, 355, 556, 556, 889, 667, 191, 333, 333, 389, 584, 278, 333, 278, 278,
           556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 278, 278, 584, 584, 584, 556,
           1015, 667, 667, 722, 722, 667, 611, 778, 722, 278, 500, 667, 556, 833, 722, 778,
           667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 278, 278, 278, 469, 556,
           333, 556, 556, 500, 556, 556, 278, 556, 556, 222, 222, 500, 222, 833, 556, 556,
           556, 556, 333, 500, 278, 556, 500, 722, 500, 500, 500, 334, 260, 334, 584]
_HELVB_W = [278, 333, 474, 556, 556, 889, 722, 238, 333, 333, 389, 584, 278, 333, 278, 278,
            556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 333, 333, 584, 584, 584, 611,
            975, 722, 722, 722, 722, 667, 611, 778, 722, 278, 556, 722, 611, 833, 722, 778,
            667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 333, 278, 333, 584, 556,
            333, 556, 611, 556, 611, 556, 333, 611, 611, 278, 278, 556, 278, 889, 611, 611,
            611, 611, 389, 556, 333, 611, 556, 778, 556, 556, 500, 389, 280, 389, 584]


# Tekens buiten ASCII die wél op het vel staan. Zonder deze maten valt alles op
# 556 terug en schuift een rechts uitgelijnde cel met "145 m\u00b2" een paar punt op.
_HELV_EXTRA = {"\u00b9": 333, "\u00b2": 333, "\u00b3": 333, "\u20ac": 556, "\u00b7": 278,
               "\u2019": 222, "\u2014": 1000, "\u2013": 556}


def _pdf_breedte(tekst: str, grootte: float, vet: bool = False) -> float:
    tabel = _HELVB_W if vet else _HELV_W
    totaal = 0
    for ch in str(tekst):
        code = ord(ch)
        if 32 <= code <= 126:
            totaal += tabel[code - 32]
        else:
            totaal += _HELV_EXTRA.get(ch, 556)
    return totaal * grootte / 1000.0


def _pdf_esc(tekst: str) -> str:
    return str(tekst).replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def _pdf_logo() -> tuple:
    """De JPEG-wordmark naast dit bestand → (bytes, breedte, hoogte) of None.
    JPEG omdat een PDF die rechtstreeks slikt (DCTDecode); PNG zou uitpakken en
    her-comprimeren vergen, en dat is een library die we hier niet hebben."""
    pad = os.path.join(os.path.dirname(os.path.abspath(__file__)), "assets", "logo.jpg")
    try:
        with open(pad, "rb") as f:
            raw = f.read()
    except OSError:
        return None
    # Afmetingen uit de SOF-marker halen (geen PIL op de serverless runtime).
    i = 2
    while i < len(raw) - 9:
        if raw[i] != 0xFF:
            i += 1
            continue
        marker, blok = raw[i + 1], int.from_bytes(raw[i + 2:i + 4], "big")
        if 0xC0 <= marker <= 0xCF and marker not in (0xC4, 0xC8, 0xCC):
            hoogte = int.from_bytes(raw[i + 5:i + 7], "big")
            breedte = int.from_bytes(raw[i + 7:i + 9], "big")
            return raw, breedte, hoogte
        i += 2 + blok
    return None


def _pdf_bestand(paginas: list, logo=None) -> bytes:
    """Zet contentstreams om in een compleet PDF-bestand: fonts, (optioneel) de
    logo-afbeelding, de paginaboom en een byte-exacte xref-tabel. Die offsets
    moeten kloppen tot op de byte — een verschoven tabel opent in macOS Preview
    vaak nog wel en elders niet."""
    objs = {1: b"<< /Type /Catalog /Pages 2 0 R >>",
            3: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
            4: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"}
    nr, kids = 5, []
    beeld = ""
    if logo:
        raw, lb, lh = logo
        objs[nr] = (("<< /Type /XObject /Subtype /Image /Width %d /Height %d /ColorSpace /DeviceRGB "
                     "/BitsPerComponent 8 /Filter /DCTDecode /Length %d >>\nstream\n" % (lb, lh, len(raw))).encode()
                    + raw + b"\nendstream")
        beeld = " /XObject << /Im0 %d 0 R >>" % nr
        nr += 1
    for blok in paginas:
        inhoud = ("\n".join(blok)).encode("cp1252", "replace")
        cnr, pnr = nr, nr + 1
        nr += 2
        objs[cnr] = b"<< /Length %d >>\nstream\n" % len(inhoud) + inhoud + b"\nendstream"
        objs[pnr] = (("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] "
                      "/Resources << /Font << /F1 3 0 R /F2 4 0 R >>%s >> /Contents %d 0 R >>"
                      % (beeld, cnr)).encode())
        kids.append(pnr)
    objs[2] = ("<< /Type /Pages /Count %d /Kids [%s] >>"
               % (len(kids), " ".join("%d 0 R" % k for k in kids))).encode()

    uit = b"%PDF-1.4\n"
    offsets, hoogste = {}, max(objs)
    for n in range(1, hoogste + 1):
        if n in objs:
            offsets[n] = len(uit)
            uit += ("%d 0 obj\n" % n).encode() + objs[n] + b"\nendobj\n"
    xref = len(uit)
    uit += ("xref\n0 %d\n" % (hoogste + 1)).encode() + b"0000000000 65535 f \n"
    for n in range(1, hoogste + 1):
        uit += (("%010d 00000 n \n" % offsets[n]).encode() if n in offsets else b"0000000000 65535 f \n")
    uit += ("trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF" % (hoogste + 1, xref)).encode()
    return uit


def _document_pdf_bytes(doc: dict, *, soort: str, meta: list) -> bytes:
    """Bouwt het offerte-/factuurvel als PDF: dezelfde indeling als het HTML-vel,
    zodat de klant hetzelfde document downloadt als hij op het scherm ziet."""
    co = _company()
    t = _invoice_totals(doc)
    cl = doc.get("client") or {}
    PB, PH, M = 595.28, 841.89, 56.0
    RECHTS = PB - M
    ORANJE, INKT, GRIJS, WIT = "0.941 0.490 0.133", "0.12 0.11 0.09", "0.48 0.51 0.55", "1 1 1"

    paginas, ops = [], []
    st = {"y": PH - M}

    def tekst(txt, x, y, grootte=10, kleur=INKT, vet=False, rechts_op=None):
        if rechts_op is not None:
            x = rechts_op - _pdf_breedte(txt, grootte, vet)
        ops.append(f"BT /{'F2' if vet else 'F1'} {grootte} Tf {kleur} rg "
                   f"1 0 0 1 {x:.2f} {y:.2f} Tm ({_pdf_esc(txt)}) Tj ET")

    def vlak(x, y, b, h, kleur):
        ops.append(f"{kleur} rg {x:.2f} {y:.2f} {b:.2f} {h:.2f} re f")

    def lijn(x1, y, x2, kleur=GRIJS, dikte=0.5):
        ops.append(f"{kleur} RG {dikte} w {x1:.2f} {y:.2f} m {x2:.2f} {y:.2f} l S")

    def nieuwe_pagina():
        paginas.append(ops[:])
        ops.clear()
        st["y"] = PH - M

    # ---- kop: logo links, afzender rechts ----
    logo = _pdf_logo()
    y = PH - M - 18
    if logo:
        _, lb, lh = logo
        breedte = 150.0
        hoogte = breedte * lh / lb
        ops.append(f"q {breedte:.2f} 0 0 {hoogte:.2f} {M:.2f} {(y - hoogte + 12):.2f} cm /Im0 Do Q")
    else:
        tekst(co.get("name", "DAM Housing").upper(), M, y, 20, INKT, True)

    ry = PH - M - 10
    tekst(co.get("name", "DAM Housing"), 0, ry, 11, INKT, True, rechts_op=RECHTS)
    ry -= 14
    for regel in str(co.get("address", "")).splitlines():
        if regel.strip():
            tekst(regel.strip(), 0, ry, 9, GRIJS, rechts_op=RECHTS)
            ry -= 12
    if co.get("phone"):
        tekst("t " + str(co["phone"]), 0, ry, 9, GRIJS, rechts_op=RECHTS); ry -= 12
    if co.get("email"):
        tekst(str(co["email"]), 0, ry, 9, GRIJS, rechts_op=RECHTS); ry -= 12

    st["y"] = min(ry, PH - M - 74) - 6
    vlak(M, st["y"], RECHTS - M, 2, ORANJE)
    st["y"] -= 40

    # ---- klant links, soort + gegevens rechts ----
    boven = st["y"]
    tekst(f"{soort.upper()} VOOR", M, boven, 8, GRIJS)
    y = boven - 16
    tekst(cl.get("name", ""), M, y, 11, INKT, True); y -= 14
    for regel in str(cl.get("address", "")).splitlines():
        if regel.strip():
            tekst(regel.strip(), M, y, 10, INKT); y -= 13
    if cl.get("email"):
        tekst(str(cl["email"]), M, y, 10, INKT); y -= 13
    if cl.get("phone"):
        tekst(str(cl["phone"]), M, y, 10, INKT); y -= 13

    mx = M + 300
    tekst(soort.upper(), mx, boven - 6, 22, INKT, True)
    my = boven - 34
    for label, waarde in meta:
        if not waarde:
            continue
        tekst(str(label), mx, my, 9.5, GRIJS)
        tekst(str(waarde), 0, my, 9.5, INKT, True, rechts_op=RECHTS)
        my -= 15

    st["y"] = min(y, my) - 24

    # ---- regels ----
    KOL_AANTAL, KOL_PRIJS, KOL_TOTAAL = M + 330, M + 405, RECHTS

    def tabelkop():
        vlak(M, st["y"] - 6, RECHTS - M, 24, INKT)
        tekst("OMSCHRIJVING", M + 10, st["y"] + 1, 8, WIT, True)
        tekst("AANTAL", 0, st["y"] + 1, 8, WIT, True, rechts_op=KOL_AANTAL)
        tekst("PRIJS", 0, st["y"] + 1, 8, WIT, True, rechts_op=KOL_PRIJS)
        tekst("TOTAAL", 0, st["y"] + 1, 8, WIT, True, rechts_op=KOL_TOTAAL - 10)
        st["y"] -= 26

    tabelkop()
    for regel in (doc.get("lines") or []):
        try:
            aantal = float(regel.get("qty", 0) or 0)
            prijs = float(regel.get("price", 0) or 0)
        except (TypeError, ValueError):
            aantal, prijs = 0.0, 0.0
        oms = str(regel.get("desc", ""))
        # Omschrijvingen zijn lang ("Pvc-vloer leggen incl. materiaal (40 m2 …)");
        # afkappen zou de klant informatie onthouden, dus we breken af op woorden.
        maxb = KOL_AANTAL - M - 60
        stukken, huidig = [], ""
        for woord in oms.split():
            proef = (huidig + " " + woord).strip()
            if _pdf_breedte(proef, 10) <= maxb or not huidig:
                huidig = proef
            else:
                stukken.append(huidig); huidig = woord
        stukken.append(huidig)
        if st["y"] - (len(stukken) * 13 + 30) < M + 60:
            nieuwe_pagina(); tabelkop()
        tekst(stukken[0], M + 10, st["y"], 10)
        tekst(_aantal_met_eenheid(aantal, regel.get("unit")), 0, st["y"], 10, INKT, rechts_op=KOL_AANTAL)
        tekst(_eur(prijs), 0, st["y"], 10, INKT, rechts_op=KOL_PRIJS)
        tekst(_eur(aantal * prijs), 0, st["y"], 10, INKT, rechts_op=KOL_TOTAAL - 10)
        for extra in stukken[1:]:
            st["y"] -= 13
            tekst(extra, M + 10, st["y"], 10)
        st["y"] -= 12
        lijn(M, st["y"], RECHTS, "0.91 0.92 0.93")
        st["y"] -= 16

    # ---- totalen ----
    tarief = float(doc.get("btw_rate", 21) or 0)
    tarief_txt = f"{tarief:.0f}" if float(tarief).is_integer() else f"{tarief:.1f}".replace(".", ",")
    st["y"] -= 6
    for label, bedrag, vet in (("Subtotaal", t["subtotal"], False),
                               (f"BTW {tarief_txt}%", t["btw"], False)):
        tekst(label, M + 330, st["y"], 10, INKT, vet)
        tekst(_eur(bedrag), 0, st["y"], 10, INKT, vet, rechts_op=RECHTS)
        st["y"] -= 16
    st["y"] -= 2
    lijn(M + 325, st["y"] + 8, RECHTS, INKT, 1.2)
    st["y"] -= 6
    tekst("Totaal", M + 330, st["y"], 13, INKT, True)
    tekst(_eur(t["total"]), 0, st["y"], 13, ORANJE, True, rechts_op=RECHTS)
    st["y"] -= 34

    # ---- toelichting ----
    for alinea in str(doc.get("notes", "")).split("\n"):
        if not alinea.strip():
            st["y"] -= 6
            continue
        woorden, huidig = alinea.split(), ""
        for woord in woorden:
            proef = (huidig + " " + woord).strip()
            if _pdf_breedte(proef, 9) <= RECHTS - M or not huidig:
                huidig = proef
            else:
                if st["y"] < M + 50:
                    nieuwe_pagina()
                tekst(huidig, M, st["y"], 9, GRIJS); st["y"] -= 12
                huidig = woord
        if st["y"] < M + 50:
            nieuwe_pagina()
        tekst(huidig, M, st["y"], 9, GRIJS); st["y"] -= 12

    # ---- voet op elke pagina ----
    voet = " \u00b7 ".join(x for x in (
        ("IBAN " + str(co.get("iban", ""))) if co.get("iban") else "",
        ("BTW " + str(co.get("btw", ""))) if co.get("btw") else "",
        ("KvK " + str(co.get("kvk", ""))) if co.get("kvk") else "") if x)
    paginas.append(ops[:])
    if voet:
        for blok in paginas:
            blok.append(f"0.91 0.92 0.93 RG 0.5 w {M:.2f} {M + 22:.2f} m {RECHTS:.2f} {M + 22:.2f} l S")
            blok.append(f"BT /F1 8 Tf {GRIJS} rg 1 0 0 1 "
                        f"{(PB - _pdf_breedte(voet, 8)) / 2:.2f} {M + 8:.2f} Tm ({_pdf_esc(voet)}) Tj ET")

    return _pdf_bestand(paginas, logo)


def _pdf_respons(data: bytes, bestandsnaam: str):
    return Response(data, mimetype="application/pdf", headers={
        "Content-Disposition": f'attachment; filename="{bestandsnaam}"',
        "Cache-Control": "no-store"})


def _doc_acties(actie: str, pdf_url: str, terms_url: str = "") -> str:
    """De knoppenrij onder het document. De downloadknop staat er altijd: een vel
    op het scherm is prettig, maar de klant wil 'm ook kunnen bewaren of doorsturen."""
    if not pdf_url:
        return actie
    knop = (f'<a class="dl" href="{_esc(pdf_url)}" download>'
            '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
            'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
            '<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/>'
            '<line x1="12" y1="15" x2="12" y2="3"/></svg>Download als PDF</a>')
    if terms_url:
        knop += (f'<a class="vw" href="{_esc(terms_url)}" target="_blank" rel="noopener">'
                 'Algemene voorwaarden</a>')
    if actie:
        # De bestaande knop staat al in een .actie-blok; die openen we en vullen aan.
        return actie.replace("</div>", knop + "</div>", 1)
    return f'<div class="actie">{knop}</div>'


def _render_document_html(doc: dict, *, soort: str, meta: list, actie: str = "",
                          stempel: str = "", banner: str = "", slotregel: str = "",
                          pdf_url: str = "", terms_url: str = "") -> str:
    """Offerte en factuur delen hetzelfde briefpapier; alleen de kop, het
    gegevensblok en de knop eronder verschillen."""
    co = _company()
    t = _invoice_totals(doc)
    cl = doc.get("client") or {}
    tarief = float(doc.get("btw_rate", 21) or 0)
    tarief_txt = f"{tarief:.0f}" if float(tarief).is_integer() else f"{tarief:.1f}".replace(".", ",")

    afz = []
    for regel in str(co.get("address", "")).splitlines():
        if regel.strip():
            afz.append(_esc(regel.strip()))
    if co.get("phone"):
        afz.append("t " + _esc(co["phone"]))
    if co.get("email"):
        afz.append(_esc(co["email"]))

    aan = [f'<strong>{_esc(cl.get("name", ""))}</strong>']
    for regel in str(cl.get("address", "")).splitlines():
        if regel.strip():
            aan.append(_esc(regel.strip()))
    if cl.get("email"):
        aan.append(_esc(cl["email"]))
    if cl.get("phone"):
        aan.append(_esc(cl["phone"]))

    meta_rijen = "".join(f"<tr><th>{_esc(k)}</th><td>{_esc(v)}</td></tr>" for k, v in meta if v)
    voet = [x for x in (
        ("IBAN " + str(co.get("iban", ""))) if co.get("iban") else "",
        ("BTW " + str(co.get("btw", ""))) if co.get("btw") else "",
        ("KvK " + str(co.get("kvk", ""))) if co.get("kvk") else "",
    ) if x]

    return (
        '<!DOCTYPE html><html lang="nl"><head><meta charset="UTF-8">'
        '<meta name="viewport" content="width=device-width, initial-scale=1">'
        f'<title>{_esc(soort)} {_esc(doc.get("number", ""))} — {_esc(co.get("name", "DAM Housing"))}</title>'
        '<meta name="robots" content="noindex,nofollow">'
        '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>'
        '<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap" rel="stylesheet">'
        f'<style>{_DOC_CSS}</style></head><body><div class="sheet">{banner}'
        f'<header class="kop"><img src="{_esc(_doc_logo(co))}" alt="{_esc(co.get("name", "DAM Housing"))}">'
        f'<div class="afzender"><strong>{_esc(co.get("name", "DAM Housing"))}</strong>'
        f'{"<br>".join(afz)}</div></header>'
        f'<div class="adressering"><div class="aan"><div class="lbl">{_esc(soort)} voor</div>{"<br>".join(aan)}</div>'
        f'<div class="docblok"><h1>{_esc(soort)}</h1><table class="meta">{meta_rijen}</table></div></div>'
        '<table class="regels"><thead><tr><th>Omschrijving</th><th class="r">Aantal</th>'
        '<th class="r">Prijs</th><th class="r">Totaal</th></tr></thead>'
        f'<tbody>{_doc_regels(doc)}</tbody></table>'
        f'<div class="onder">{stempel}'
        f'<div class="totalen"><div class="rij"><span>Subtotaal</span><span>{_eur(t["subtotal"])}</span></div>'
        f'<div class="rij"><span>BTW {tarief_txt}%</span><span>{_eur(t["btw"])}</span></div>'
        f'<div class="rij eind"><span>Totaal</span><span>{_eur(t["total"])}</span></div></div></div>'
        f'{_doc_acties(actie, pdf_url, terms_url)}'
        f'{("<div class=notitie>" + _esc(doc.get("notes", "")) + "</div>") if doc.get("notes") else ""}'
        f'{("<div class=notitie>" + _esc(slotregel) + "</div>") if slotregel else ""}'
        f'{("<footer class=voet><span>" + "</span><span>".join(_esc(x) for x in voet) + "</span></footer>") if voet else ""}'
        '</div></body></html>')


# ---------------------------------------------------------------------------
# Algemene voorwaarden
# ---------------------------------------------------------------------------
# Rick levert de tekst, wij zetten er zijn briefpapier omheen. Bewust gegenereerd
# en niet als los geupload bestand: zo staat het logo er gegarandeerd op, kan hij
# de tekst zelf bijwerken, en kunnen we bij een akkoord vastleggen WELKE versie
# gold. Een handtekening onder "de voorwaarden" zonder te weten welke tekst dat
# was, bewijst niets.


def _terms_version(body: str) -> str:
    """Korte afdruk van de tekst. Verandert de tekst, dan verandert de versie."""
    return hashlib.sha256((body or "").strip().encode("utf-8")).hexdigest()[:10]


def get_terms() -> dict:
    t = dict(get_settings().get("terms") or {})
    t.setdefault("body", "")
    t["version"] = t.get("version") or _terms_version(t["body"])
    return t


def _terms_blokken(body: str) -> list:
    """Platte tekst -> renderblokken. Een regel die met 'Artikel' begint is een kop,
    een regel met een opsommingsteken een bullet, de rest een alinea."""
    blokken = []
    for regel in (body or "").splitlines():
        kaal = regel.strip()
        if not kaal:
            continue
        if kaal.lower().startswith("artikel "):
            blokken.append(("kop", kaal))
        elif kaal[0] in "*\u2022-\u2013":
            blokken.append(("bullet", kaal.lstrip("*\u2022-\u2013 ").strip()))
        else:
            blokken.append(("alinea", kaal))
    return blokken


def render_terms_html() -> str:
    co = _company()
    t = get_terms()
    inhoud = ""
    for soort, tekst in _terms_blokken(t["body"]):
        if soort == "kop":
            inhoud += f'<h2>{_esc(tekst)}</h2>'
        elif soort == "bullet":
            inhoud += f'<li>{_esc(tekst)}</li>'
        else:
            inhoud += f'<p>{_esc(tekst)}</p>'
    inhoud = inhoud.replace("<li>", "<ul><li>", 1) if "<li>" in inhoud else inhoud
    # Losse <li>'s netjes in lijstjes groeperen zonder een parser: sluit de lijst
    # zodra er een kop of alinea volgt.
    for tag in ("<h2>", "<p>"):
        inhoud = inhoud.replace("</li>" + tag, "</li></ul>" + tag)
    if inhoud.rstrip().endswith("</li>"):
        inhoud += "</ul>"
    inhoud = inhoud.replace("<p><ul>", "<ul>")
    css = _DOC_CSS + (
        ".sheet h2{font-size:15px;margin:26px 0 8px;letter-spacing:.02em}"
        ".sheet p{margin:0 0 10px}.sheet ul{margin:0 0 12px;padding-left:18px}"
        ".sheet li{margin:0 0 6px}"
        ".vw-kop{font-size:26px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;margin:26px 0 4px}"
        ".vw-versie{color:#8b93a0;font-size:11.5px;margin-bottom:10px}")
    return (
        '<!DOCTYPE html><html lang="nl"><head><meta charset="UTF-8">'
        '<meta name="viewport" content="width=device-width, initial-scale=1">'
        f'<title>Algemene voorwaarden — {_esc(co.get("name", "DAM Housing"))}</title>'
        '<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap" rel="stylesheet">'
        f'<style>{css}</style></head><body><div class="sheet">'
        f'<header class="kop"><img src="{_esc(_doc_logo(co))}" alt="{_esc(co.get("name", "DAM Housing"))}">'
        f'<div class="afzender"><strong>{_esc(co.get("name", "DAM Housing"))}</strong>'
        + "<br>".join(_esc(r.strip()) for r in str(co.get("address", "")).splitlines() if r.strip())
        + '</div></header>'
        f'<div class="vw-kop">Algemene voorwaarden</div>'
        f'<div class="vw-versie">Versie {_esc(t["version"])}'
        + (f' &middot; bijgewerkt {_esc(_nl_date(t.get("updated", "")))}' if t.get("updated") else "")
        + '</div>'
        f'{inhoud}'
        '<footer class="voet"><span>' + "</span><span>".join(
            _esc(x) for x in (
                ("IBAN " + str(co.get("iban", ""))) if co.get("iban") else "",
                ("BTW " + str(co.get("btw", ""))) if co.get("btw") else "",
                ("KvK " + str(co.get("kvk", ""))) if co.get("kvk") else "") if x)
        + '</span></footer></div></body></html>')


def _terms_pdf_bytes() -> bytes:
    """De voorwaarden als PDF, op hetzelfde papier als de offerte. Zelfde
    handgeschreven aanpak als _document_pdf_bytes — er staat geen PDF-engine op
    de serverless build."""
    co = _company()
    t = get_terms()
    PB, PH, M = 595.28, 841.89, 56.0
    RECHTS = PB - M
    ORANJE, INKT, GRIJS = "0.941 0.490 0.133", "0.12 0.11 0.09", "0.48 0.51 0.55"

    paginas, ops = [], []
    st = {"y": PH - M}

    def tekst(txt, x, y, grootte=10, kleur=INKT, vet=False):
        ops.append(f"BT /{'F2' if vet else 'F1'} {grootte} Tf {kleur} rg "
                   f"1 0 0 1 {x:.2f} {y:.2f} Tm ({_pdf_esc(txt)}) Tj ET")

    def nieuwe_pagina():
        paginas.append(ops[:])
        ops.clear()
        st["y"] = PH - M

    def ruimte(nodig):
        if st["y"] - nodig < M + 40:
            nieuwe_pagina()

    def alinea(txt, grootte, kleur, vet=False, inspring=0.0, opsomming=False):
        maxb = RECHTS - M - inspring
        woorden, regel = str(txt).split(), ""
        regels = []
        for woord in woorden:
            proef = (regel + " " + woord).strip()
            if _pdf_breedte(proef, grootte, vet) <= maxb or not regel:
                regel = proef
            else:
                regels.append(regel); regel = woord
        regels.append(regel)
        for i, r in enumerate(regels):
            ruimte(grootte + 4)
            if opsomming and i == 0:
                tekst("\u2022", M + inspring - 10, st["y"], grootte, GRIJS)
            tekst(r, M + inspring, st["y"], grootte, kleur, vet)
            st["y"] -= grootte + 3.5

    # kop van het vel
    logo = _pdf_logo()
    if logo:
        _, lb, lh = logo
        breedte = 150.0
        hoogte = breedte * lh / lb
        ops.append(f"q {breedte:.2f} 0 0 {hoogte:.2f} {M:.2f} {(PH - M - hoogte):.2f} cm /Im0 Do Q")
        st["y"] = PH - M - hoogte - 16
    else:
        tekst(co.get("name", "DAM Housing").upper(), M, PH - M - 14, 20, INKT, True)
        st["y"] = PH - M - 40
    ops.append(f"{ORANJE} rg {M:.2f} {st['y']:.2f} {(RECHTS - M):.2f} 2 re f")
    st["y"] -= 34

    tekst("ALGEMENE VOORWAARDEN", M, st["y"], 20, INKT, True)
    st["y"] -= 18
    regel = f"Versie {t['version']}"
    if t.get("updated"):
        regel += f" \u00b7 bijgewerkt {_nl_date(t.get('updated', ''))}"
    tekst(regel, M, st["y"], 9, GRIJS)
    st["y"] -= 22

    for soort, txt in _terms_blokken(t["body"]):
        if soort == "kop":
            st["y"] -= 8
            ruimte(30)
            alinea(txt, 12, INKT, vet=True)
            st["y"] -= 4
        elif soort == "bullet":
            alinea(txt, 9.5, INKT, inspring=14, opsomming=True)
            st["y"] -= 3
        else:
            alinea(txt, 9.5, INKT)
            st["y"] -= 4

    voet = " \u00b7 ".join(x for x in (
        ("IBAN " + str(co.get("iban", ""))) if co.get("iban") else "",
        ("BTW " + str(co.get("btw", ""))) if co.get("btw") else "",
        ("KvK " + str(co.get("kvk", ""))) if co.get("kvk") else "") if x)
    paginas.append(ops[:])
    for nr, blok in enumerate(paginas, 1):
        blok.append(f"0.91 0.92 0.93 RG 0.5 w {M:.2f} {M + 22:.2f} m {RECHTS:.2f} {M + 22:.2f} l S")
        onder = f"{voet}   \u00b7   pagina {nr} van {len(paginas)}" if voet else f"pagina {nr} van {len(paginas)}"
        blok.append(f"BT /F1 8 Tf {GRIJS} rg 1 0 0 1 "
                    f"{(PB - _pdf_breedte(onder, 8)) / 2:.2f} {M + 8:.2f} Tm ({_pdf_esc(onder)}) Tj ET")

    return _pdf_bestand(paginas, logo)


@app.route("/algemene-voorwaarden", methods=["GET"])
@app.route("/algemene-voorwaarden/", methods=["GET"])
def serve_terms():
    return Response(render_terms_html(), mimetype="text/html")


@app.route("/algemene-voorwaarden.pdf", methods=["GET"])
def serve_terms_pdf():
    co = _company()
    naam = f"Algemene-voorwaarden-{(co.get('name') or 'DAM Housing').replace(' ', '-')}.pdf"
    return _pdf_respons(_terms_pdf_bytes(), naam)


def _terms_bijlage() -> dict:
    """De voorwaarden als mailbijlage. Geeft None als er geen tekst staat — een
    lege PDF meesturen is erger dan geen bijlage."""
    t = get_terms()
    if not (t.get("body") or "").strip():
        return None
    try:
        return {"filename": "Algemene-voorwaarden.pdf", "data": _terms_pdf_bytes(),
                "mime": "application/pdf"}
    except Exception as e:
        print(f"voorwaarden-bijlage mislukt: {e}")
        return None


def render_invoice_html(inv: dict) -> str:
    t = _invoice_totals(inv)
    betaald = inv.get("status") == "betaald"
    mol = inv.get("mollie", {}) or {}
    actie = ""
    if not betaald and mol.get("url"):
        actie = (f'<div class="actie"><a href="{_esc(mol["url"])}">'
                 f'Betaal nu {_eur(t["total"])} via iDEAL</a></div>')
    iban = _company().get("iban", "")
    return _render_document_html(
        inv, soort="Factuur",
        meta=[("Factuurnummer", inv.get("number", "")),
              ("Factuurdatum", _nl_date(inv.get("date", ""))),
              ("Vervaldatum", _nl_date(inv.get("due_date", "")))],
        actie=actie,
        pdf_url=f'/factuur/{inv.get("id", "")}/pdf',
        stempel='<div class="stempel">BETAALD</div>' if betaald else "",
        slotregel=(f"Betaling binnen de vervaltermijn o.v.v. factuurnummer {inv.get('number','')} "
                   f"naar IBAN {iban}.") if iban and not betaald else "")


@app.route("/api/admin/invoices", methods=["GET", "POST"])
def api_invoices():
    a = _require_perm("invoices")
    if a: return a
    if request.method == "GET":
        return jsonify({"invoices": get_invoices_index()})
    d = request.get_json(silent=True) or {}
    iid = uuid.uuid4().hex[:12]
    inv = {"id": iid, "number": _next_invoice_number(),
           "date": d.get("date") or datetime.now().strftime("%Y-%m-%d"),
           "due_date": d.get("due_date", ""), "status": "concept",
           "client": d.get("client") or {"name": "", "email": "", "address": ""},
           "lead_id": d.get("lead_id", ""), "lines": d.get("lines") or [],
           "btw_rate": d.get("btw_rate", 21), "notes": d.get("notes", ""),
           "mollie": {}, "created": _now_iso()}
    save_invoice(inv)
    audit_log("invoice_create", inv["number"], (inv["client"] or {}).get("name", ""))
    return jsonify({"ok": True, "invoice": inv})


@app.route("/api/admin/invoices/<iid>", methods=["GET", "PUT", "DELETE"])
def api_invoice_detail(iid):
    a = _require_perm("invoices")
    if a: return a
    inv = get_invoice(iid)
    if request.method == "GET":
        if not inv: return jsonify({"error": "Niet gevonden"}), 404
        return jsonify({"invoice": inv, "totals": _invoice_totals(inv)})
    if request.method == "DELETE":
        delete_invoice(iid); return jsonify({"ok": True})
    if not inv: return jsonify({"error": "Niet gevonden"}), 404
    d = request.get_json(silent=True) or {}
    for k in ("date", "due_date", "client", "lead_id", "lines", "btw_rate", "notes", "status"):
        if k in d: inv[k] = d[k]
    save_invoice(inv)
    return jsonify({"ok": True, "invoice": inv, "totals": _invoice_totals(inv)})


@app.route("/api/admin/invoices/<iid>/status", methods=["POST"])
def api_invoice_status(iid):
    a = _require_perm("invoices")
    if a: return a
    inv = get_invoice(iid)
    if not inv: return jsonify({"error": "Niet gevonden"}), 404
    st = (request.get_json(silent=True) or {}).get("status", "")
    if st in ("concept", "verzonden", "betaald"):
        inv["status"] = st; save_invoice(inv)
    return jsonify({"ok": True, "status": inv["status"]})


def _mollie_key() -> tuple:
    """(key, modus) uit Instellingen. Geen key = de betaalflow blijft uit."""
    mol = get_settings().get("mollie") or {}
    modus = mol.get("mode", "test")
    return (mol.get("api_key_live") if modus == "live" else mol.get("api_key_test")), modus


def _mollie_payment(bedrag: float, omschrijving: str, redirect_url: str, metadata: dict,
                    methode: str = "") -> tuple:
    """Maakt een betaling bij Mollie. Geeft (ok, resultaat-dict of foutmelding).
    De webhook-URL wijst naar onze eigen route: zonder webhook hoor je nooit dat
    er betaald is, want de klant komt lang niet altijd terug op de bedanktpagina."""
    key, modus = _mollie_key()
    if not key:
        return False, f"Geen Mollie {modus}-key ingevuld (Instellingen \u2192 Facturen)"
    basis = _public_base() or CANONICAL_BASE
    body = {"amount": {"currency": "EUR", "value": f"{bedrag:.2f}"},
            "description": omschrijving[:255],
            "redirectUrl": redirect_url,
            "webhookUrl": f"{basis.rstrip('/')}/api/mollie/webhook",
            "metadata": metadata}
    if methode:
        body["method"] = methode
    try:
        req = urllib.request.Request("https://api.mollie.com/v2/payments",
                                     data=json.dumps(body).encode(),
                                     headers={"Authorization": f"Bearer {key}",
                                              "Content-Type": "application/json"},
                                     method="POST")
        with urllib.request.urlopen(req, timeout=15) as r:
            res = json.loads(r.read())
    except urllib.error.HTTPError as e:
        return False, f"Mollie HTTP {e.code}: {e.read().decode('utf-8', 'replace')[:200]}"
    except Exception as e:
        return False, str(e)
    return True, {"payment_id": res.get("id", ""),
                  "url": (res.get("_links", {}).get("checkout", {}) or {}).get("href", ""),
                  "status": res.get("status", ""), "mode": modus}


def _mollie_status(payment_id: str) -> str:
    """Haalt de stand van een betaling ZELF op bij Mollie. De webhook-body zegt
    alleen welk id er iets deed; wat er gebeurde vraag je na bij de bron, anders
    kan iedereen die de URL kent een offerte op betaald zetten."""
    key, _ = _mollie_key()
    if not (key and payment_id):
        return ""
    try:
        req = urllib.request.Request(f"https://api.mollie.com/v2/payments/{urllib.parse.quote(payment_id)}",
                                     headers={"Authorization": f"Bearer {key}"})
        with urllib.request.urlopen(req, timeout=15) as r:
            return (json.loads(r.read()) or {}).get("status", "")
    except Exception as e:
        print(f"mollie status ophalen mislukt: {e}")
        return ""


@app.route("/api/admin/invoices/<iid>/mollie", methods=["POST"])
def api_invoice_mollie(iid):
    a = _require_perm("invoices")
    if a: return a
    inv = get_invoice(iid)
    if not inv: return jsonify({"error": "Niet gevonden"}), 404
    t = _invoice_totals(inv)
    basis = _public_base() or CANONICAL_BASE
    ok, res = _mollie_payment(t["total"], f"Factuur {inv.get('number','')}",
                              f"{basis.rstrip('/')}/factuur/{iid}/", {"invoice_id": iid})
    if not ok:
        return jsonify({"ok": False, "error": res}), 502
    inv["mollie"] = res
    inv["status"] = "verzonden"
    save_invoice(inv)
    return jsonify({"ok": True, "url": res.get("url", "")})


@app.route("/factuur/<iid>/", methods=["GET"])
@app.route("/factuur/<iid>", methods=["GET"])
def serve_invoice(iid):
    inv = get_invoice(iid)
    if not inv:
        return Response("Factuur niet gevonden", status=404, mimetype="text/plain")
    return Response(render_invoice_html(inv), mimetype="text/html")


@app.route("/factuur/<iid>/pdf", methods=["GET"])
def serve_invoice_pdf(iid):
    inv = get_invoice(iid)
    if not inv:
        return Response("Factuur niet gevonden", status=404, mimetype="text/plain")
    pdf = _document_pdf_bytes(inv, soort="Factuur", meta=[
        ("Factuurnummer", inv.get("number", "")),
        ("Factuurdatum", _nl_date(inv.get("date", ""))),
        ("Vervaldatum", _nl_date(inv.get("due_date", "")))])
    return _pdf_respons(pdf, f"Factuur-{inv.get('number', iid)}.pdf")


# ============ OFFERTES (quotes) — apart document, los van facturen ============
def get_quotes_index() -> list:
    return kv_get("quotes:index") or []


def get_quote(qid: str):
    return kv_get(f"quote:{qid}")


def _next_quote_number() -> str:
    year = datetime.now().year
    ctr = kv_get("quote:counter") or {}
    seq = int(ctr.get(str(year), 0)) + 1
    ctr[str(year)] = seq
    kv_set("quote:counter", ctr)
    return f"OFF-{year}-{seq:03d}"


def _quote_summary(q: dict) -> dict:
    t = _invoice_totals(q)
    cl = q.get("client", {}) or {}
    return {"id": q["id"], "number": q.get("number", ""), "date": q.get("date", ""),
            "valid_until": q.get("valid_until", ""), "status": q.get("status", "concept"),
            "client_name": cl.get("name", ""), "client_email": cl.get("email", ""),
            "total": t["total"], "btw": t["btw"], "subtotal": t["subtotal"],
            "lead_id": q.get("lead_id", ""), "converted_invoice": q.get("converted_invoice", "")}


def save_quote(q: dict) -> None:
    kv_set(f"quote:{q['id']}", q)
    idx = [x for x in get_quotes_index() if x.get("id") != q["id"]]
    idx.append(_quote_summary(q))
    idx.sort(key=lambda x: (x.get("date", ""), x.get("number", "")), reverse=True)
    kv_set("quotes:index", idx)


def delete_quote(qid: str) -> None:
    kv_delete(f"quote:{qid}")
    kv_set("quotes:index", [x for x in get_quotes_index() if x.get("id") != qid])


# ============ AUTOMATISCHE OFFERTE bij een aanvraag ============
# De klant wilde "sneller offertes sturen i.p.v. alles handmatig overnemen". Daarom rolt
# er bij elke formulier-aanvraag automatisch een CONCEPT-offerte uit, met de klantgegevens,
# de gekozen auto/service en een berekende prijs uit de tarieventabel. De klant checkt 'm
# en verstuurt met één klik — bewust géén automatische verzending, zodat een afwijkende
# aanvraag (verre locatie, bijzondere wens) nooit ongezien de deur uit gaat.

def _verhuur() -> dict:
    """Tarieven uit de instellingen, met de defaults als vangnet."""
    s = get_settings().get("verhuur") or {}
    base = json.loads(json.dumps(DEFAULT_SETTINGS["verhuur"]))
    base.update({k: v for k, v in s.items() if v not in (None, "")})
    for key in ("cars", "services"):
        if not isinstance(base.get(key), list) or not base[key]:
            base[key] = DEFAULT_SETTINGS["verhuur"][key]
    return base


def _tarief_lookup(items: list, value: str, label: str = ""):
    """Zoek een tariefregel op opgeslagen waarde, anders op (hoofdletterloos) label."""
    value = (value or "").strip()
    label = (label or "").strip().lower()
    for it in items or []:
        if value and str(it.get("value", "")).strip() == value:
            return it
    for it in items or []:
        if label and str(it.get("label", "")).strip().lower() == label:
            return it
    return None


def _ex_vat(amount: float, rate: float, incl: bool) -> float:
    """Reken een incl-btw bedrag terug naar ex-btw, zodat het offerte-eindtotaal
    exact op het op de site getoonde incl-btw bedrag uitkomt."""
    try:
        amount = float(amount or 0)
    except (TypeError, ValueError):
        return 0.0
    if not incl:
        return round(amount, 2)
    return round(amount / (1.0 + (float(rate or 0) / 100.0)), 2)


# Welke dienstkeuze hetzelfde werk dekt als een aangevinkt extra (anti-dubbeltelling).
# Let op: dit zijn de labels die het formulier stuurt (src/lib/diensten.js).
EXTRA_IS_HOOFDDIENST = {
    "egaliseren": ("Vloeren egaliseren",),
    "vloerverwarming": ("Vloerverwarming",),
}


def _dh_quote_lines(t: dict, lead: dict):
    """Offerteregels uit de tarieventabel (Instellingen -> Tarieven), op basis van wat
    de bezoeker in het formulier invulde. Retourneert (regels_incl_btw, samenvatting)."""
    def _getal(v, maximum):
        try:
            return max(0.0, min(float(str(v).replace(",", ".")), maximum))
        except (TypeError, ValueError):
            return 0.0

    m2 = _getal(lead.get("oppervlakte"), 5000)
    treden = int(_getal(lead.get("treden"), 60))
    dienst = (lead.get("dienst") or "").strip()
    extras = {k: str(lead.get(k, "")).lower() in ("1", "true", "ja", "yes")
              for k in ("egaliseren", "vloerverwarming", "plinten")}

    # Elke regel: (omschrijving, aantal, eenheid, stuksprijs incl. btw). Het AANTAL
    # is wat de klant heeft ingevuld — die hoort in de kolom Aantal en niet tussen
    # haakjes achter de omschrijving (Rick, 2026-08-15). Regels zonder maat
    # (voorrijkosten, minimum) krijgen aantal 1 en geen eenheid.
    regels = []
    vloer = (t.get("vloeren") or {}).get(dienst)
    if vloer and m2 > 0:
        regels.append((vloer.get("label", dienst), m2, "m\u00b2", float(vloer.get("per_m2") or 0)))

    trap = t.get("trap") or {}
    if dienst == "Trappenrenovatie" or treden > 0:
        n = treden or int(trap.get("standaard_treden") or 13)
        regels.append((trap.get("label", "Trappenrenovatie"), n,
                       "trede" if n == 1 else "treden", float(trap.get("per_trede") or 0)))

    patroon = (lead.get("patroon") or "").strip()
    toeslag = ((t.get("patronen") or {}).get(patroon) or {})
    if vloer and m2 > 0 and float(toeslag.get("toeslag_m2") or 0) > 0:
        regels.append((f"Toeslag {patroon.lower()}", m2, "m\u00b2", float(toeslag["toeslag_m2"])))

    # Alleen bij bestaande bouw: bij nieuwbouw ligt er per definitie nog niets.
    ondergrond = (lead.get("ondergrond") or "").strip()
    grond_toeslag = ((t.get("ondergronden") or {}).get(ondergrond) or {})
    if vloer and m2 > 0 and float(grond_toeslag.get("toeslag_m2") or 0) > 0:
        regels.append((f"Voorbereiding ondergrond ({ondergrond.lower()})", m2, "m\u00b2",
                       float(grond_toeslag["toeslag_m2"])))

    plint = (t.get("extra") or {}).get("plinten") or {}
    plint_m1 = _getal(lead.get("plinten_m1"), 2000)
    if extras.get("plinten") and plint_m1 > 0:
        regels.append((plint.get("label", "Plinten"), plint_m1, "m\u00b9", float(plint.get("per_m1") or 0)))

    for sleutel in ("egaliseren", "vloerverwarming"):
        # Een extra dat al de hoofddienst is, niet dubbel rekenen.
        if not extras.get(sleutel) or m2 <= 0:
            continue
        # Is het extra al de gekozen hoofddienst, dan niet dubbel rekenen. De namen
        # komen 1-op-1 uit src/lib/diensten.js (aanvraagLabel), dus die staan hier
        # expliciet: een hernoemde dienst mag geen stille dubbeltelling opleveren.
        if dienst in EXTRA_IS_HOOFDDIENST.get(sleutel, ()):
            continue
        e = (t.get("extra") or {}).get(sleutel) or {}
        regels.append((e.get("label", sleutel), m2, "m\u00b2", float(e.get("per_m2") or 0)))

    if not regels:
        return [], {}

    voorrij = t.get("voorrijkosten") or {}
    if float(voorrij.get("bedrag") or 0) > 0:
        regels.append((voorrij.get("label", "Voorrijkosten"), 1, "", float(voorrij["bedrag"])))

    subtotaal = round(sum(aantal * prijs for _, aantal, _, prijs in regels), 2)
    minimum = float(t.get("minimum_opdracht") or 0)
    minimum_toegepast = subtotaal < minimum
    if minimum_toegepast:
        # Verschil als aparte regel, zodat de klant ziet waar het bedrag vandaan komt.
        regels.append(("Minimum opdrachtbedrag", 1, "", round(minimum - subtotaal, 2)))

    return regels, {"subtotaal": subtotaal, "minimum_toegepast": minimum_toegepast,
                    "totaal_incl": round(max(subtotaal, minimum), 2)}


def _adresregel(lead: dict) -> str:
    """Straat, postcode en plaats als één regel voor op het offertevel. Half
    ingevuld mag geen losse komma's opleveren, dus lege delen vallen weg."""
    straat = (lead.get("straat") or "").strip()
    plaats = " ".join(x for x in ((lead.get("postcode") or "").strip(),
                                  (lead.get("woonplaats") or "").strip()) if x)
    return ", ".join(x for x in (straat, plaats) if x)


def _autoquote_for_lead(lead: dict) -> str:
    """Maak een concept-offerte bij een verse aanvraag, gerekend met de tarieven uit
    Instellingen -> Tarieven. Retourneert het offerte-id ('' = niets gedaan).
    Faalt NOOIT hard: een probleem hier mag een binnengekomen aanvraag nooit blokkeren."""
    t = get_tarieven()
    if not t.get("auto_aanmaken", True):
        return ""

    rate = float(t.get("btw_tarief", 21) or 0)
    incl = bool(t.get("prijzen_incl_btw", True))
    raw_lines, samenvatting = _dh_quote_lines(t, lead)
    if not raw_lines:
        return ""   # geen herkenbare dienst/maten -> niets aannemen

    # Van incl. btw (zoals de tarieven zijn ingevoerd) naar de ex-btw-stuksprijs die
    # op het vel staat. Per regel los afronden laat het totaal een cent afwijken;
    # daarom een LOPEND RESTANT: elke regel corrigeert wat de vorige aan afronding
    # heeft laten liggen, zodat de som van de regels precies uitkomt.
    lines, running_incl, running_ex = [], 0.0, 0.0
    for desc, aantal, eenheid, stuksprijs_incl in raw_lines:
        aantal = float(aantal or 0) or 1.0
        running_incl += aantal * stuksprijs_incl
        target_ex = _ex_vat(running_incl, rate, incl)
        regel_ex = target_ex - running_ex
        # De klant leest prijs x aantal = totaal, dus de STUKSPRIJS staat op het vel
        # en het regeltotaal volgt daaruit. Andersom (regeltotaal delen door het
        # aantal en beide tonen) klopt bij 145 m2 al gauw een euro niet.
        price = round(regel_ex / aantal, 2)
        running_ex = round(running_ex + price * aantal, 2)
        lines.append({"desc": desc, "qty": round(aantal, 2), "unit": eenheid,
                      "price": price, "incl": round(aantal * stuksprijs_incl, 2)})

    detail = []
    for key, lbl in (("dienst", "Dienst"), ("vloer", "Gekozen vloer"), ("bouwtype", "Nieuwbouw/bestaande bouw"),
                     ("ondergrond", "Huidige ondergrond"), ("straat", "Straat en huisnummer"),
                     ("omvang", "Omvang"), ("oppervlakte", "Oppervlakte (m\u00b2)"),
                     ("patroon", "Legpatroon"), ("plinten_m1", "Plinten (m\u00b9)"),
                     ("treden", "Traptreden"), ("postcode", "Postcode"), ("woonplaats", "Woonplaats")):
        if lead.get(key):
            detail.append(f"{lbl}: {lead[key]}")
    if lead.get("note"):
        detail.append(f"Bericht van de klant: {lead['note']}")
    notes = "Richtprijs op basis van de door u opgegeven gegevens. Definitieve prijs na inmeten aan huis."
    if detail:
        notes += "\n\n" + "\n".join(detail)

    today = datetime.now()
    try:
        valid_days = int(t.get("geldigheid_dagen", 30) or 30)
    except (TypeError, ValueError):
        valid_days = 30

    q = {
        "id": uuid.uuid4().hex[:12],
        "number": _next_quote_number(),
        "date": today.strftime("%Y-%m-%d"),
        "valid_until": (today + timedelta(days=valid_days)).strftime("%Y-%m-%d"),
        "status": "concept",
        "client": {"name": lead.get("name", ""), "email": lead.get("email", ""),
                   "phone": lead.get("telefoon", ""),
                   # Het adres hoort bij de klantgegevens op het vel, niet alleen in
                   # de toelichting eronder: het bepaalt waar we heen rijden.
                   "address": _adresregel(lead)},
        "lines": lines,
        "btw_rate": rate,
        "notes": notes,
        "lead_id": lead.get("id", ""),
        "created": _now_iso(),
        "auto_generated": True,
    }
    save_quote(q)
    lead["quote_id"] = q["id"]
    lead["quote_number"] = q["number"]
    # Het bedrag in het dashboard komt uit de regels van de offerte zelf: door het
    # afronden op stuksprijzen kan de richtprijs er een paar cent naast zitten, en
    # dan zou het dashboard iets anders zeggen dan het document.
    lead["quote_total"] = _invoice_totals(q)["total"]
    return q["id"]


def render_quote_html(q: dict, accepted_msg: bool = False) -> str:
    st = q.get("status", "concept")
    dep = q.get("deposit") or {}
    dep_status = dep.get("status", "")
    actie = ""
    if st in ("concept", "verzonden"):
        # Openstaande aanbetaling? Dan is de vraag niet meer "wilt u akkoord gaan"
        # maar "maak het af" — met dezelfde betaallink, zodat een afgebroken
        # betaling geen doodlopende weg is.
        if dep_status in ("open", "pending", "failed", "expired", "canceled"):
            actie = (f'<div class="actie"><a href="/offerte/{_esc(q.get("id", ""))}/aanbetalen">'
                     f'Aanbetaling voldoen ({_eur(dep.get("amount", 0))})</a></div>')
        else:
            actie = ('<div class="actie"><a href="/offerte/' + _esc(q.get("id", ""))
                     + '/accepteren">Offerte accepteren</a></div>')
    stempel = ""
    if st == "geaccepteerd":
        stempel = '<div class="stempel">GEACCEPTEERD</div>'
    elif st == "afgewezen":
        stempel = '<div class="stempel" style="border-color:#dc2626;color:#dc2626">AFGEWEZEN</div>'

    if accepted_msg and st == "geaccepteerd":
        banner = ('<div class="banner">Bedankt! Je hebt deze offerte geaccepteerd. '
                  'We nemen zo snel mogelijk contact met je op.</div>')
    elif dep_status == "paid":
        banner = (f'<div class="banner">Bedankt! We hebben je aanbetaling van '
                  f'{_eur(dep.get("amount", 0))} ontvangen — de opdracht staat vast.</div>')
    elif dep_status in ("open", "pending"):
        banner = ('<div class="banner" style="background:#fef3c7;border-color:#fcd34d;color:#92400e">'
                  f'Je akkoord is genoteerd. De opdracht is definitief zodra de aanbetaling van '
                  f'{_eur(dep.get("amount", 0))} binnen is.</div>')
    elif dep_status in ("failed", "expired", "canceled"):
        banner = ('<div class="banner" style="background:#fee2e2;border-color:#fca5a5;color:#991b1b">'
                  'De betaling is niet afgerond. Je akkoord staat genoteerd; rond de aanbetaling '
                  'hieronder af, dan is de opdracht definitief.</div>')
    else:
        banner = ""
    return _render_document_html(
        q, soort="Offerte",
        meta=[("Offertenummer", q.get("number", "")),
              ("Offertedatum", _nl_date(q.get("date", ""))),
              ("Geldig tot", _nl_date(q.get("valid_until", "")))],
        actie=actie, stempel=stempel, banner=banner,
        slotregel=_offerte_slotregel(q),
        pdf_url=f'/offerte/{q.get("id", "")}/pdf',
        terms_url="/algemene-voorwaarden.pdf")


def _offerte_slotregel(q: dict) -> str:
    """De voorwaardenregel onder de offerte: vooraf de waarschuwing dat akkoord
    ook akkoord met de voorwaarden is, achteraf het bewijs dat het gebeurd is."""
    akk = q.get("terms_accepted") or {}
    if akk.get("at"):
        wanneer = _nl_date((akk.get("at") or "")[:10])
        return (f"Akkoord met de algemene voorwaarden (versie {akk.get('version', '')}) "
                f"gegeven op {wanneer}.")
    if q.get("status") in ("concept", "verzonden"):
        return ("Door deze offerte te accepteren ga je akkoord met onze algemene voorwaarden. "
                "Je vindt ze via de link hierboven en als bijlage bij de offertemail.")
    return ""


@app.route("/api/admin/quotes", methods=["GET", "POST"])
def api_quotes():
    a = _require_perm_any("offertes", "pipeline")
    if a: return a
    if request.method == "GET":
        return jsonify({"quotes": get_quotes_index()})
    d = request.get_json(silent=True) or {}
    qid = uuid.uuid4().hex[:12]
    q = {"id": qid, "number": _next_quote_number(),
         "date": d.get("date") or datetime.now().strftime("%Y-%m-%d"),
         "valid_until": d.get("valid_until", ""), "status": "concept",
         "client": d.get("client") or {"name": "", "email": "", "address": ""},
         "lead_id": d.get("lead_id", ""), "lines": d.get("lines") or [],
         "btw_rate": d.get("btw_rate", 21), "notes": d.get("notes", ""),
         "created": _now_iso()}
    save_quote(q)
    audit_log("quote_create", q["number"], (q["client"] or {}).get("name", ""))
    return jsonify({"ok": True, "quote": q})


@app.route("/api/admin/quotes/<qid>", methods=["GET", "PUT", "DELETE"])
def api_quote_detail(qid):
    a = _require_perm("offertes")
    if a: return a
    q = get_quote(qid)
    if request.method == "GET":
        if not q: return jsonify({"error": "Niet gevonden"}), 404
        return jsonify({"quote": q, "totals": _invoice_totals(q)})
    if request.method == "DELETE":
        delete_quote(qid); return jsonify({"ok": True})
    if not q: return jsonify({"error": "Niet gevonden"}), 404
    d = request.get_json(silent=True) or {}
    for k in ("date", "valid_until", "client", "lead_id", "lines", "btw_rate", "notes", "status"):
        if k in d: q[k] = d[k]
    save_quote(q)
    return jsonify({"ok": True, "quote": q, "totals": _invoice_totals(q)})


@app.route("/api/admin/quotes/<qid>/status", methods=["POST"])
def api_quote_status(qid):
    a = _require_perm("offertes")
    if a: return a
    q = get_quote(qid)
    if not q: return jsonify({"error": "Niet gevonden"}), 404
    st = (request.get_json(silent=True) or {}).get("status", "")
    if st in ("concept", "verzonden", "geaccepteerd", "afgewezen"):
        q["status"] = st; save_quote(q)
    return jsonify({"ok": True, "status": q["status"]})


def _offerte_mail_body(q: dict, basis: str, tekst: str = "") -> str:
    """De offertemail: korte tekst, een knop naar het offertevel en de kernregels
    eronder. `tekst` = een eigen bericht uit het verzenddialoog (platte tekst)."""
    cl = q.get("client") or {}
    t = _invoice_totals(q)
    url = f"{basis.rstrip('/')}/offerte/{_esc(q.get('id', ''))}/"
    if tekst.strip():
        inhoud = "<p style=\"margin:0 0 18px\">" + _esc(tekst).replace("\n", "<br>") + "</p>"
    else:
        inhoud = (
            f'<p style="margin:0 0 14px">Beste {_esc(cl.get("name", ""))},</p>'
            '<p style="margin:0 0 14px">Bedankt voor je aanvraag. Hierbij onze offerte '
            f'<strong>{_esc(q.get("number", ""))}</strong>. Je kunt \'m hieronder bekijken en '
            'meteen akkoord geven.</p>')
    knop = (f'<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:22px 0">'
            f'<tr><td style="background:#f07d22;border-radius:8px">'
            f'<a href="{url}" style="display:inline-block;padding:14px 30px;color:#ffffff;'
            f'font-weight:600;font-size:15px;text-decoration:none">Bekijk je offerte</a>'
            f'</td></tr></table>')
    feiten = (
        '<table role="presentation" cellpadding="0" cellspacing="0" border="0" '
        'style="width:100%;border-top:1px solid #efe7e0;margin-top:6px;font-size:14px">'
        f'<tr><td style="padding:12px 0 2px;color:#7b828c">Offertenummer</td>'
        f'<td style="padding:12px 0 2px;text-align:right"><strong>{_esc(q.get("number", ""))}</strong></td></tr>'
        f'<tr><td style="padding:2px 0;color:#7b828c">Totaal incl. btw</td>'
        f'<td style="padding:2px 0;text-align:right"><strong>{_eur(t["total"])}</strong></td></tr>'
        + (f'<tr><td style="padding:2px 0;color:#7b828c">Geldig tot</td>'
           f'<td style="padding:2px 0;text-align:right"><strong>{_esc(_nl_date(q.get("valid_until", "")))}</strong></td></tr>'
           if q.get("valid_until") else "")
        + '</table>')
    voorwaarden = (
        f'<p style="margin:16px 0 0;font-size:13px;color:#7b828c">Onze '
        f'<a href="{basis.rstrip("/")}/algemene-voorwaarden.pdf" style="color:#f07d22">algemene voorwaarden</a> '
        'zitten als bijlage bij deze mail. Ga je akkoord met de offerte, dan ga je ook '
        'akkoord met die voorwaarden.</p>')
    slot = ('<p style="margin:18px 0 0;font-size:13px;color:#7b828c">Dit is een richtprijs op basis '
            'van je opgave. Na het inmeten aan huis ontvang je de definitieve offerte. '
            'Werkt de knop niet? Open dan '
            f'<a href="{url}" style="color:#f07d22">{url}</a></p>')
    return inhoud + knop + feiten + voorwaarden + slot


@app.route("/api/admin/quotes/<qid>/send", methods=["POST"])
def api_quote_send(qid):
    a = _require_perm("offertes")
    if a: return a
    q = get_quote(qid)
    if not q: return jsonify({"ok": False, "error": "Niet gevonden"}), 404
    to = ((q.get("client") or {}).get("email") or "").strip() or _lead_email(q.get("lead_id"))
    if not to: return jsonify({"ok": False, "error": "Klant heeft geen e-mailadres"}), 400
    co = _company()
    base = "https://" + (request.host or "damhousing.nl")
    d = request.get_json(silent=True) or {}
    _st = get_settings()
    subject = d.get("subject") or f"Offerte {q.get('number','')} van {co.get('name','DAM Housing')}"
    body = _offerte_mail_body(q, base, d.get("body") or "")
    cc = d.get("cc") if d.get("cc") is not None else (_st.get("invoice_send_cc") or "")
    bcc = d.get("bcc") if d.get("bcc") is not None else (_st.get("invoice_send_bcc") or "")
    try:
        ok, msg = send_email(to, subject, body, cc=cc, bcc=bcc,
                             content_type="html", signature=_sig_on("quote"),
                             attachments=[a for a in (_terms_bijlage(),) if a])
    except Exception as e:
        ok, msg = False, str(e)
    if ok and q.get("status") == "concept":
        q["status"] = "verzonden"; save_quote(q)
    return jsonify({"ok": ok, "error": None if ok else msg})


def _stuur_offerte(q: dict) -> tuple:
    """Stuurt een offerte naar de klant met dezelfde tekst als de handmatige knop.
    Retourneert (gelukt, melding). Zet de status op 'verzonden' bij succes."""
    to = ((q.get("client") or {}).get("email") or "").strip() or _lead_email(q.get("lead_id"))
    if not to:
        return False, "klant heeft geen e-mailadres"
    co = _company()
    st = get_settings()
    basis = _public_base() or "https://damhousing.nl"
    onderwerp = f"Offerte {q.get('number','')} van {co.get('name','DAM Housing')}"
    bericht = _offerte_mail_body(q, basis)
    try:
        ok, msg = send_email(to, onderwerp, bericht,
                             cc=st.get("invoice_send_cc") or "",
                             bcc=st.get("invoice_send_bcc") or "",
                             content_type="html", signature=_sig_on("quote"),
                             attachments=[a for a in (_terms_bijlage(),) if a])
    except Exception as e:
        ok, msg = False, str(e)
    if ok:
        q["status"] = "verzonden"
        q["auto_sent"] = _now_iso()
        save_quote(q)
    return ok, msg


def _verstuur_rijpe_offertes() -> dict:
    """Stuurt automatisch aangemaakte CONCEPT-offertes die lang genoeg klaarstaan.
    Zo krijgt Rick de tijd om een offerte nog te corrigeren of tegen te houden."""
    t = get_tarieven()
    if not t.get("auto_versturen"):
        return {"actief": False, "verstuurd": 0}
    try:
        minuten = max(1, int(t.get("verzend_na_minuten") or 15))
    except (TypeError, ValueError):
        minuten = 15

    grens = datetime.now().astimezone() - timedelta(minutes=minuten)
    verstuurd, mislukt = [], []
    for rij in (get_quotes_index() or []):
        if rij.get("status") != "concept":
            continue
        q = get_quote(rij.get("id"))
        # Alleen wat de motor zelf maakte; handmatige concepten blijven van de klant.
        if not q or not q.get("auto_generated") or q.get("auto_sent"):
            continue
        try:
            gemaakt = _as_aware(datetime.fromisoformat(q.get("created") or ""))
        except (TypeError, ValueError):
            continue
        if gemaakt > grens:
            continue          # nog binnen de bedenktijd
        ok, msg = _stuur_offerte(q)
        (verstuurd if ok else mislukt).append(q.get("number", ""))
        if ok:
            audit_log("offerte.auto_verstuurd", q.get("number", ""),
                      f"Automatisch verstuurd na {minuten} minuten")
        else:
            print(f"auto-offerte {q.get('number','')} mislukt: {msg}")
    return {"actief": True, "na_minuten": minuten,
            "verstuurd": len(verstuurd), "nummers": verstuurd, "mislukt": mislukt}


@app.route("/api/cron/offertes", methods=["GET", "POST"])
@app.route("/api/cron/offertes/", methods=["GET", "POST"])
def api_cron_offertes():
    """Draait elke 5 minuten (vercel.json). Auth: cron-secret of een ingelogde agency."""
    geheim = os.environ.get("CRON_SECRET", "")
    kop = (request.headers.get("Authorization") or "").replace("Bearer ", "").strip()
    if not (geheim and secrets.compare_digest(kop, geheim)) and current_role() != "agency":
        return jsonify({"error": "auth"}), 401
    try:
        return jsonify({"ok": True, **_verstuur_rijpe_offertes()})
    except Exception as e:
        print(f"cron offertes: {e}")
        return jsonify({"ok": False, "error": str(e)[:200]}), 500


