def _aanbetaling_bedrag(q: dict, t: dict) -> tuple:
    """(bedrag incl. btw, percentage) van de aanbetaling."""
    try:
        pct = max(1, min(50, int(t.get("aanbetaling_pct") or 50)))
    except (TypeError, ValueError):
        pct = 50
    return round(_invoice_totals(q)["total"] * pct / 100.0, 2), pct


def _leg_akkoord_vast(q: dict):
    """Wie accepteert, gaat akkoord met de voorwaarden. Vastleggen WELKE versie dat
    was, plus tijdstip en IP — anders is 'hij ging akkoord' een bewering zonder
    onderbouwing."""
    t = get_terms()
    q["terms_accepted"] = {
        "at": _now_iso(),
        "version": t.get("version", ""),
        "ip": (request.headers.get("x-forwarded-for", "").split(",")[0].strip()
               or request.remote_addr or ""),
    }


def _start_aanbetaling(q: dict, bedrag: float, pct: int) -> tuple:
    """Maakt een verse betaling voor de aanbetaling. Geeft (ok, resultaat/fout)."""
    basis = _public_base() or CANONICAL_BASE
    qid = q.get("id", "")
    return _mollie_payment(bedrag, f"Aanbetaling {pct}% offerte {q.get('number','')}",
                           f"{basis.rstrip('/')}/offerte/{qid}/", {"quote_id": qid},
                           methode="ideal")


@app.route("/offerte/<qid>/aanbetalen", methods=["GET", "POST"])
def serve_quote_deposit(qid):
    """De betaalknop op het offertevel.

    Niet rechtstreeks naar de opgeslagen checkout-URL linken: een betaling die is
    mislukt, verlopen of geannuleerd is bij Mollie definitief, en die URL stuurt de
    klant dan meteen terug naar de offerte. Voor hem lijkt het alsof de knop niets
    doet. Een betaling die nog openstaat mag je wél hergebruiken — dan is dit
    gewoon "verder waar je gebleven was"."""
    q = get_quote(qid)
    if not q:
        return Response("Offerte niet gevonden", status=404, mimetype="text/plain")
    dep = q.get("deposit") or {}
    if dep.get("status") == "paid":
        return redirect(f"/offerte/{qid}/")

    # Nog een geldige betaling? Daar dan heen — maar eerst bij Mollie navragen,
    # want onze opgeslagen stand kan achterlopen.
    if dep.get("url") and dep.get("payment_id"):
        stand = _mollie_status(dep["payment_id"]) or dep.get("status", "")
        if stand in ("open", "pending"):
            return redirect(dep["url"])
        if stand and stand != dep.get("status"):
            _pas_aanbetaling_toe(q, stand)
            if stand == "paid":
                return redirect(f"/offerte/{qid}/")

    t = get_tarieven()
    bedrag, pct = _aanbetaling_bedrag(q, t)
    key, _modus = _mollie_key()
    if not (key and bedrag > 0):
        return redirect(f"/offerte/{qid}/")
    ok, res = _start_aanbetaling(q, bedrag, pct)
    if not ok:
        q["deposit"] = {"pct": pct, "amount": bedrag, "status": "failed", "error": str(res)[:200]}
        save_quote(q)
        print(f"nieuwe aanbetaling mislukt voor {qid}: {res}")
        return redirect(f"/offerte/{qid}/")
    q["deposit"] = {"pct": pct, "amount": bedrag, **res}
    save_quote(q)
    audit_log("offerte.aanbetaling_opnieuw", q.get("number", ""),
              f"Nieuwe betaallink aangemaakt ({_eur(bedrag)})")
    return redirect(res.get("url") or f"/offerte/{qid}/")


@app.route("/offerte/<qid>/accepteren", methods=["GET", "POST"])
def serve_quote_accept(qid):
    q = get_quote(qid)
    if not q:
        return Response("Offerte niet gevonden", status=404, mimetype="text/plain")
    if q.get("status") not in ("concept", "verzonden"):
        return Response(render_quote_html(q, accepted_msg=(q.get("status") == "geaccepteerd")),
                        mimetype="text/html")

    _leg_akkoord_vast(q)
    q["accept_intent_at"] = _now_iso()

    t = get_tarieven()
    bedrag, pct = _aanbetaling_bedrag(q, t)
    key, _modus = _mollie_key()

    # Zonder aanbetaling (uit, geen key, of geen bedrag) is akkoord meteen akkoord —
    # precies zoals het werkte voordat de betaalstap bestond.
    if not (t.get("aanbetaling_aan") and key and bedrag > 0):
        q["status"] = "geaccepteerd"
        save_quote(q)
        audit_log("offerte.geaccepteerd", q.get("number", ""), "Klant akkoord (zonder aanbetaling)")
        return Response(render_quote_html(q, accepted_msg=True), mimetype="text/html")

    # Mét aanbetaling blijft de offerte op 'verzonden' staan: pas als het geld
    # binnen is, is de opdracht definitief. Een klant die de betaling afbreekt
    # staat dan zichtbaar op 'wacht op aanbetaling' in plaats van als opdracht.
    ok, res = _start_aanbetaling(q, bedrag, pct)
    if not ok:
        # Betaallink lukt niet? Dan het akkoord niet laten verdampen: vastleggen
        # dat de klant ja zei en Rick het laten oplossen.
        q["deposit"] = {"pct": pct, "amount": bedrag, "status": "failed", "error": str(res)[:200]}
        save_quote(q)
        print(f"aanbetaling aanmaken mislukt voor {qid}: {res}")
        return Response(render_quote_html(q, accepted_msg=True), mimetype="text/html")

    q["deposit"] = {"pct": pct, "amount": bedrag, **res}
    # Geen concept meer: de klant heeft 'm gezien en geaccepteerd, alleen het geld
    # moet nog binnen. Blijft hij op 'concept' staan, dan pakt de auto-verstuurcron
    # hem op en krijgt de klant zijn eigen offerte nog een keer toegestuurd.
    if q.get("status") == "concept":
        q["status"] = "verzonden"
    save_quote(q)
    audit_log("offerte.aanbetaling", q.get("number", ""),
              f"Klant akkoord, aanbetaling {pct}% ({_eur(bedrag)}) aangemaakt")
    return redirect(res.get("url") or f"/offerte/{qid}/")


def _pas_aanbetaling_toe(q: dict, status: str) -> bool:
    """Verwerkt een betaalstatus op een offerte. Retourneert of er iets veranderde.
    Eén plek voor zowel de webhook als de terugkeerpagina — twee routes die
    hetzelfde moeten doen lopen anders vroeg of laat uit elkaar."""
    dep = q.get("deposit") or {}
    if not status or dep.get("status") == status:
        return False
    dep["status"] = status
    if status == "paid":
        dep.setdefault("paid_at", _now_iso())
        q["status"] = "geaccepteerd"
        audit_log("offerte.aanbetaling_voldaan", q.get("number", ""),
                  f"Aanbetaling {_eur(dep.get('amount', 0))} ontvangen")
    q["deposit"] = dep
    save_quote(q)
    return True


def _ververs_aanbetaling(q: dict):
    """Vraagt bij Mollie na hoe het met een openstaande aanbetaling staat.

    Mollie stuurt zijn webhook en de klant tegelijk terug, dus op de bedankpagina
    is de webhook vaak nét niet verwerkt: de klant heeft betaald en leest dan dat
    we nog op zijn geld wachten. Bij het openen van de offerte daarom zelf even
    navragen."""
    dep = q.get("deposit") or {}
    if not dep.get("payment_id") or dep.get("status") == "paid":
        return
    try:
        status = _mollie_status(dep["payment_id"])
    except Exception as e:
        print(f"aanbetaling verversen mislukt: {e}")
        return
    if status:
        _pas_aanbetaling_toe(q, status)


@app.route("/api/mollie/webhook", methods=["POST"])
@app.route("/api/mollie/webhook/", methods=["POST"])
def api_mollie_webhook():
    """Mollie meldt hier dat er iets met een betaling gebeurde. De body bevat
    alleen een id; de status vragen we zelf op. Altijd 200 terug — een foutcode
    laat Mollie eindeloos opnieuw proberen, ook als het aan onze kant ligt."""
    pid = (request.form.get("id") or (request.get_json(silent=True) or {}).get("id") or "").strip()
    if not pid:
        return jsonify({"ok": True, "note": "geen id"}), 200
    status = _mollie_status(pid)
    if not status:
        return jsonify({"ok": True, "note": "status onbekend"}), 200

    for rij in (get_quotes_index() or []):
        q = get_quote(rij.get("id"))
        dep = (q or {}).get("deposit") or {}
        if not q or dep.get("payment_id") != pid:
            continue
        _pas_aanbetaling_toe(q, status)   # idempotent: tweede melding verandert niets
        return jsonify({"ok": True, "quote": q.get("number", ""), "status": status}), 200

    # Ook facturen lopen via deze webhook.
    for rij in (get_invoices_index() or []):
        inv = get_invoice(rij.get("id"))
        mol = (inv or {}).get("mollie") or {}
        if not inv or mol.get("payment_id") != pid:
            continue
        mol["status"] = status
        if status == "paid" and inv.get("status") != "betaald":
            inv["status"] = "betaald"
            audit_log("factuur.betaald", inv.get("number", ""), "Betaling ontvangen via Mollie")
        inv["mollie"] = mol
        save_invoice(inv)
        return jsonify({"ok": True, "invoice": inv.get("number", ""), "status": status}), 200

    return jsonify({"ok": True, "note": "niet gevonden"}), 200


@app.route("/api/admin/quotes/<qid>/aanbetaling-voldaan", methods=["POST"])
def api_quote_deposit_paid(qid):
    """Handmatig als voldaan markeren — voor de klant die overmaakt in plaats van
    iDEAL te gebruiken. Zonder deze uitweg blijft zo'n opdracht eeuwig wachten."""
    a = _require_perm("offertes")
    if a: return a
    q = get_quote(qid)
    if not q: return jsonify({"ok": False, "error": "Niet gevonden"}), 404
    dep = q.get("deposit") or {}
    dep.update({"status": "paid", "paid_at": _now_iso(), "handmatig": True})
    q["deposit"] = dep
    q["status"] = "geaccepteerd"
    save_quote(q)
    audit_log("offerte.aanbetaling_handmatig", q.get("number", ""), "Aanbetaling handmatig als voldaan gemarkeerd")
    return jsonify({"ok": True, "quote": q})


