# ==================== GOOGLE OAUTH (multi-tenant per klant) ====================
# .strip() vangt per ongeluk meegeplakte spaties/regeleindes/quotes uit de env-waarde af
# (een veelvoorkomende oorzaak van Google's "invalid_client / OAuth client not found").
GOOGLE_CLIENT_ID = (os.environ.get("GOOGLE_CLIENT_ID", "") or "").strip().strip('"').strip("'")
GOOGLE_CLIENT_SECRET = (os.environ.get("GOOGLE_CLIENT_SECRET", "") or "").strip().strip('"').strip("'")

# integratie-id -> Google OAuth scope
GOOGLE_SCOPES = {
    "analytics": "https://www.googleapis.com/auth/analytics.readonly",
    "search_console": "https://www.googleapis.com/auth/webmasters.readonly",
    "calendar": "https://www.googleapis.com/auth/calendar.events",
    "gmail": "https://www.googleapis.com/auth/gmail.modify https://www.googleapis.com/auth/gmail.settings.basic",
    "google_business": "https://www.googleapis.com/auth/business.manage",
    "google_ads": "https://www.googleapis.com/auth/adwords",
}


import hmac

OAUTH_PROXY_SECRET = (os.environ.get("OAUTH_PROXY_SECRET", "") or "").strip()


def _oauth_origin() -> str:
    """Publieke https-origin van DEZE site — waar de centrale proxy de callback naartoe terugstuurt."""
    return "https://" + (request.host or "")


def _make_proxy_state(origin: str, service: str, nonce: str) -> str:
    """HMAC-ondertekende state met de herkomst erin, te lezen door de centrale OAuth-proxy."""
    payload = base64.urlsafe_b64encode(
        json.dumps({"o": origin, "s": service, "n": nonce}, separators=(",", ":")).encode()
    ).rstrip(b"=").decode()
    sig = base64.urlsafe_b64encode(
        hmac.new(OAUTH_PROXY_SECRET.encode(), payload.encode(), hashlib.sha256).digest()
    ).rstrip(b"=").decode()
    return payload + "." + sig


# ---------- Centrale OAuth-client via de MAIHS-gateway ----------
# Hetzelfde clientpaar stond in de env van negentien sites: roteren betekende
# negentien projecten langs. Het secret blijft nu bij MAIHS; hier is alleen de
# (publieke) client-id nodig om de bezoeker naar Google te sturen, en de
# uitwisseling loopt via /api/gateway/google-oauth/token.
#
# Eigen env wint, maar alleen als PAAR. Een site met een eigen client-id en een
# centraal secret levert 'unauthorized_client' op, en een mislukte refresh markeert
# integraties als ontkoppeld — dus liever helemaal het een of helemaal het ander.

def _eigen_google_client() -> bool:
    return bool(GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET)


# Ophogen maakt de cache in één klap leeg bij de volgende deploy. Nodig gebleken:
# toen de centrale Google-client bij MAIHS werd rechtgezet, bleef deze site de oude
# client-id gebruiken en was er geen manier om dat af te dwingen behalve wachten.
_GATEWAY_CONFIG_KEY = "gateway:config:v2"


def _gateway_config(cache_uren: int = 1) -> dict:
    """Centrale instellingen (Google-client-id, Ads) bij MAIHS, gecachet in KV.

    Kort cachen, en dat is een bewuste keuze: een verouderde client-id is erger dan
    een extra verzoek. Autorisaties die onder de verkeerde OAuth-client worden
    aangemaakt zijn niet te repareren zonder de klant opnieuw te laten koppelen.

    Bij een storing valt hij terug op de laatst opgehaalde waarden: een korte
    hapering bij MAIHS mag geen inlog- of integratiepagina platleggen."""
    basis = _gateway_origin()
    if not (basis and _gateway_key()):
        return {}
    bewaard = kv_get(_GATEWAY_CONFIG_KEY)
    if isinstance(bewaard, dict) and (time.time() - float(bewaard.get("t", 0) or 0)) < cache_uren * 3600:
        return bewaard.get("data") or {}
    try:
        req = urllib.request.Request(
            basis + "/api/gateway/config",
            headers={"Authorization": "Bearer " + _gateway_key(),
                     "User-Agent": "MAIHS-Gateway-Client/1.0"})
        with urllib.request.urlopen(req, timeout=10) as r:
            data = json.loads(r.read().decode("utf-8") or "{}")
    except Exception as e:
        print(f"[gateway] config ophalen mislukt: {e}")
        return (bewaard.get("data") or {}) if isinstance(bewaard, dict) else {}
    kv_set(_GATEWAY_CONFIG_KEY, {"t": int(time.time()), "data": data})
    return data if isinstance(data, dict) else {}


def _google_client_id() -> str:
    if _eigen_google_client():
        return GOOGLE_CLIENT_ID
    return str(_gateway_config().get("google_client_id") or "").strip()


def _google_token_exchange(velden: dict) -> dict:
    """Wisselt een code of refresh-token in bij Google.

    Met een eigen clientpaar rechtstreeks (ongewijzigd), anders via MAIHS dat het
    centrale secret toevoegt. De gateway geeft Google's status en body onveranderd
    door, zodat de bestaande afhandeling van invalid_grant blijft werken."""
    if _eigen_google_client():
        data = urllib.parse.urlencode({**velden, "client_id": GOOGLE_CLIENT_ID,
                                       "client_secret": GOOGLE_CLIENT_SECRET}).encode()
        req = urllib.request.Request("https://oauth2.googleapis.com/token", data=data, method="POST")
    else:
        basis = _gateway_origin()
        if not (basis and _gateway_key()):
            raise RuntimeError("Google OAuth niet geconfigureerd: geen eigen client en geen gateway")
        req = urllib.request.Request(
            basis + "/api/gateway/google-oauth/token",
            data=json.dumps(velden).encode(), method="POST",
            headers={"Authorization": "Bearer " + _gateway_key(),
                     "Content-Type": "application/json",
                     "User-Agent": "MAIHS-Gateway-Client/1.0"})
    with urllib.request.urlopen(req, timeout=20) as r:
        return json.loads(r.read())


def _oauth_redirect_base() -> str:
    """Waar Google de callback naartoe stuurt: de centrale proxy. Afleidbaar uit de
    AI-gateway-URL, dus die env hoeft niet apart per site gezet te worden."""
    return (os.environ.get("OAUTH_REDIRECT_BASE", "") or _gateway_origin() or "").rstrip("/")


def _google_redirect_uri() -> str:
    # Vaste, geregistreerde base verdient voorrang: voorkomt redirect_uri_mismatch op
    # wisselende Vercel-preview-hosts en www/non-www. Valt alleen terug op de live host,
    # waarbij www -> non-www genormaliseerd wordt (alleen de apex staat in Google geregistreerd).
    base = _oauth_redirect_base() or (PUBLIC_SITE_URL or "").rstrip("/")
    if not base:
        host = (request.host or "damhousing.vercel.app")
        if host.startswith("www."):
            host = host[4:]
        base = "https://" + host
    return base + "/api/oauth/google/callback"


@app.route("/api/oauth/google/start")
def oauth_google_start():
    if require_login():
        return redirect("/inloggen")
    client_id = _google_client_id()
    if not client_id:
        return Response("Google OAuth niet geconfigureerd (geen client-id, ook niet via de gateway).", status=500, mimetype="text/plain")
    service = request.args.get("service", "")
    scope = GOOGLE_SCOPES.get(service)
    if not scope:
        return Response("Onbekende dienst", status=400, mimetype="text/plain")
    nonce = secrets.token_urlsafe(24)
    # Centrale proxy actief (OAUTH_PROXY_SECRET + OAUTH_REDIRECT_BASE) -> herkomst ondertekend in de
    # state zodat de proxy de code naar DEZE site terugstuurt; anders de directe (legacy) flow.
    if OAUTH_PROXY_SECRET and _oauth_redirect_base():
        state = _make_proxy_state(_oauth_origin(), service, nonce)
    else:
        state = nonce
    session["oauth_state"] = state
    session["oauth_service"] = service
    params = {
        "client_id": client_id,
        "redirect_uri": _google_redirect_uri(),
        "response_type": "code",
        "scope": "openid email " + scope,
        "access_type": "offline",
        "include_granted_scopes": "true",
        "prompt": "consent",
        "state": state,
    }
    return redirect("https://accounts.google.com/o/oauth2/v2/auth?" + urllib.parse.urlencode(params))


# ---------- Passkeys (WebAuthn): wachtwoordloos inloggen voor team én klant ----------
# Ryan 2026-07-17. Registratie gebeurt door de INGELOGDE gebruiker (admin of klant) op het
# eigen apparaat; inloggen kan daarna zonder wachtwoord. Verificatie low-level met de
# fido2-primitieven (CBOR/COSE) — lazy geïmporteerd zodat de site ook draait zonder de lib.

def _prj_rowify(html):
    """Bundel <img> + volgende alinea's tot een twee-koloms rij (om-en-om), i.p.v. floats
    met lege gaten. Alleen content-afbeeldingen (na de img-voor-alinea-swap); idempotent."""
    if 'class="prj-row' in html:   # alleen echte markup telt — de CSS bevat ook ".prj-row"
        return html
    _cnt = {"i": 0}

    def _wrap(m):
        _cnt["i"] += 1
        rev = " prj-rev" if _cnt["i"] % 2 == 0 else ""
        return ('<div class="prj-row' + rev + '"><div class="prj-txt">' + m.group(2)
                + '</div><figure class="prj-fig">' + m.group(1) + "</figure></div>")

    return re.sub(r"(<img[^>]+>)((?:\s*<p>(?:(?!</p>).){40,}?</p>){1,4})", _wrap, html)


def _md_heal_html(html: str) -> str:
    """Heel Markdown-restanten in al-gerenderde/gesnapshotte HTML (serve- en bake-tijd):
    <p>## Kop</p> -> echte kop, [tekst](url) -> link, **x** -> strong. Alleen patronen die in
    legitieme HTML niet voorkomen; idempotent."""
    if html and "kv-hero-cta" in html:
        # Tekstomloop: content-afbeelding vóór z'n alinea zetten zodat de float tekst omarmt.
        html = re.sub(r'(<p>(?:(?!</p>).){40,}?</p>)\s*(<img[^>]+>)', r"\2\1", html)
        html = _prj_rowify(html)
    if not html or ("##" not in html and "](" not in html and "**" not in html):
        return html
    def _hd(m):
        lvl = min(len(m.group(1)), 4)
        return f"<h{lvl}>{m.group(2).strip()}</h{lvl}>"
    html = re.sub(r"<p>\s*(#{2,4})\s+([^<]+?)\s*</p>", _hd, html)
    html = re.sub(r"\[([^\]<>\n]+)\]\((https?://[^)\s<]+|/[^)\s<]*)\)", r'<a href="\2">\1</a>', html)
    html = re.sub(r"\*\*([^*<\n]+)\*\*", r"<strong>\1</strong>", html)
    return html


# Paden waar een gegenereerde pagina NOOIT naartoe mag linken, ook niet als ze
# bestaan. Het verkoopvoorstel stond op 27-08-2026 in een AI-tekst als "[offerte
# aanvragen](/voorstel/)": een intern document van het bureau, met prijzen, op de
# klantsite. De pagina is inmiddels weg, maar de regel blijft -- een generator die
# een pad verzint moet hier tegenaan lopen en niet tegen toeval.
KV_LINK_VERBODEN = ("/voorstel", "/admin", "/inloggen", "/uitloggen", "/api/",
                    "/klant-account", "/factuur/", "/offerte/", "/review")


def _kv_link_toegestaan(href: str) -> bool:
    """Mag deze link op een gegenereerde pagina staan?

    Extern, mailto, tel en ankers: ja. Intern: alleen paden die de site echt kent
    (gepubliceerde pagina's, blogposts, de vaste React-routes). Een verzonnen pad
    is geen 404 op deze site maar de homepage -- de SPA vangt het op -- dus je ziet
    nooit dat het fout is."""
    h = str(href or "").strip()
    if not h or h.startswith(("http://", "https://", "mailto:", "tel:", "#")):
        return True
    if not h.startswith("/"):
        return False
    kaal = "/" + h.split("?")[0].split("#")[0].strip("/")
    if any(kaal == v.rstrip("/") or kaal.startswith(v) for v in KV_LINK_VERBODEN):
        return False
    if kaal == "/":
        return True
    try:
        if kaal.startswith("/blog"):
            slug = kaal[len("/blog"):].strip("/")
            if not slug:
                return True
            return any((p.get("slug") or "") == slug and p.get("status") == "published"
                       for p in (get_posts_index() or []))
        bekend = {"/" + (p.get("slug") or "").strip("/")
                  for p in (_pages_index() or [])
                  if p.get("status", "published") == "published"}
        bekend |= {r[0].rstrip("/") or "/" for r in _SPA_ROUTES}
        return kaal in bekend
    except Exception:
        # Kunnen we het niet vaststellen, dan laten we de link staan: een bestaande
        # link wegstrepen door een storing is erger dan een enkele dode link.
        return True


def _md_inline(t: str) -> str:
    """Heel Markdown-restanten uit AI-tekst op render-tijd: [tekst](url) -> <a>, **x** -> <strong>.
    (AI-beschrijvingen bevatten soms rauwe Markdown; die stond letterlijk op de pagina.)"""
    def _link(m):
        tekst, url = m.group(1), m.group(2)
        # Bestaat het doel niet (of mag het niet), dan blijft de tekst staan zonder link.
        # Een dode link is op een SPA-site onzichtbaar: hij landt gewoon op de homepage.
        return f'<a href="{url}">{tekst}</a>' if _kv_link_toegestaan(url) else tekst
    t = re.sub(r"\[([^\]]+)\]\((https?://[^)\s]+|/[^)\s]*)\)", _link, t or "")
    t = re.sub(r"\*\*([^*\n]+)\*\*", r"<strong>\1</strong>", t)
    return t


def _md_plain(t: str) -> str:
    t = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", t or "")
    return t.replace("**", "").strip()


def _pk_rp_id() -> str:
    host = (request.host or "").split(":")[0].lower()
    return host[4:] if host.startswith("www.") else host


def _pk_origins() -> set:
    rp = _pk_rp_id()
    return {f"https://{rp}", f"https://www.{rp}"}


def _pk_store() -> list:
    return kv_get("passkeys:index", []) or []


def _pk_save(items: list):
    kv_set("passkeys:index", items)


def _pk_current_user():
    u = session.get("user", "")
    return u if u else None


@app.route("/api/auth/passkey/list", methods=["GET"])
@app.route("/api/auth/passkey/list/", methods=["GET"])
def api_passkey_list():
    a = _auth_or_401()
    if a: return a
    u = _pk_current_user()
    items = [{"id": p["id"], "name": p.get("name", "Passkey"), "created": p.get("created", "")}
             for p in _pk_store() if p.get("user") == u]
    return jsonify({"ok": True, "items": items})


@app.route("/api/auth/passkey/<cid>", methods=["DELETE"])
@app.route("/api/auth/passkey/<cid>/", methods=["DELETE"])
def api_passkey_delete(cid):
    a = _auth_or_401()
    if a: return a
    u = _pk_current_user()
    items = _pk_store()
    keep = [p for p in items if not (p.get("id") == cid and p.get("user") == u)]
    if len(keep) == len(items):
        return jsonify({"error": "Passkey niet gevonden"}), 404
    _pk_save(keep)
    audit_log("passkey.delete", u or "?", cid[:12])
    return jsonify({"ok": True})


@app.route("/api/auth/passkey/register/begin", methods=["POST"])
@app.route("/api/auth/passkey/register/begin/", methods=["POST"])
def api_passkey_register_begin():
    a = _auth_or_401()
    if a: return a
    u = _pk_current_user()
    challenge = secrets.token_bytes(32)
    session["pk_reg_challenge"] = base64.urlsafe_b64encode(challenge).rstrip(b"=").decode()
    rp = _pk_rp_id()
    exclude = [{"type": "public-key", "id": p["id"]} for p in _pk_store() if p.get("user") == u]
    return jsonify({"ok": True, "publicKey": {
        "challenge": session["pk_reg_challenge"],
        "rp": {"id": rp, "name": rp},
        "user": {"id": base64.urlsafe_b64encode(("user:" + u).encode()).rstrip(b"=").decode(),
                 "name": u, "displayName": u},
        "pubKeyCredParams": [{"type": "public-key", "alg": -7}, {"type": "public-key", "alg": -257}],
        "excludeCredentials": exclude,
        "authenticatorSelection": {"userVerification": "preferred", "residentKey": "preferred"},
        "timeout": 60000,
    }})


def _pk_websafe_decode(v: str) -> bytes:
    v = (v or "").replace("+", "-").replace("/", "_")
    return base64.urlsafe_b64decode(v + "=" * (-len(v) % 4))


@app.route("/api/auth/passkey/register/complete", methods=["POST"])
@app.route("/api/auth/passkey/register/complete/", methods=["POST"])
def api_passkey_register_complete():
    a = _auth_or_401()
    if a: return a
    try:
        from fido2.webauthn import CollectedClientData, AttestationObject
        from fido2 import cbor
    except Exception:
        return jsonify({"error": "Passkey-ondersteuning is niet geïnstalleerd op de server (fido2)."}), 501
    u = _pk_current_user()
    d = request.get_json(silent=True) or {}
    try:
        ccd = CollectedClientData(_pk_websafe_decode(d.get("clientDataJSON", "")))
        att = AttestationObject(_pk_websafe_decode(d.get("attestationObject", "")))
    except Exception:
        return jsonify({"error": "Ongeldige passkey-data."}), 400
    want = session.pop("pk_reg_challenge", "")
    got = base64.urlsafe_b64encode(ccd.challenge).rstrip(b"=").decode()
    if not want or not secrets.compare_digest(got, want):
        return jsonify({"error": "Challenge klopt niet — probeer opnieuw."}), 400
    if ccd.type != "webauthn.create" or ccd.origin not in _pk_origins():
        return jsonify({"error": "Herkomst klopt niet."}), 400
    ad = att.auth_data
    if ad.rp_id_hash != hashlib.sha256(_pk_rp_id().encode()).digest() or not ad.is_user_present():
        return jsonify({"error": "Verificatie mislukt."}), 400
    cred = ad.credential_data
    if not cred:
        return jsonify({"error": "Geen credential ontvangen."}), 400
    cid = base64.urlsafe_b64encode(cred.credential_id).rstrip(b"=").decode()
    items = [p for p in _pk_store() if p.get("id") != cid]
    items.append({"id": cid, "user": u,
                  "name": (d.get("name") or "").strip()[:60] or "Passkey",
                  "public_key": base64.urlsafe_b64encode(cbor.encode(dict(cred.public_key))).rstrip(b"=").decode(),
                  "sign_count": int(getattr(ad, "counter", 0) or 0),
                  "created": _now_iso()})
    _pk_save(items)
    audit_log("passkey.register", u or "?", cid[:12])
    return jsonify({"ok": True})


@app.route("/api/auth/passkey/login/begin", methods=["POST"])
@app.route("/api/auth/passkey/login/begin/", methods=["POST"])
def api_passkey_login_begin():
    items = _pk_store()
    if not items:
        return jsonify({"error": "Er zijn nog geen passkeys ingesteld op deze site."}), 404
    challenge = secrets.token_bytes(32)
    session["pk_login_challenge"] = base64.urlsafe_b64encode(challenge).rstrip(b"=").decode()
    return jsonify({"ok": True, "publicKey": {
        "challenge": session["pk_login_challenge"],
        "rpId": _pk_rp_id(),
        "allowCredentials": [{"type": "public-key", "id": p["id"]} for p in items],
        "userVerification": "preferred",
        "timeout": 60000,
    }})


@app.route("/api/auth/passkey/login/complete", methods=["POST"])
@app.route("/api/auth/passkey/login/complete/", methods=["POST"])
def api_passkey_login_complete():
    try:
        from fido2.webauthn import CollectedClientData, AuthenticatorData
        from fido2.cose import CoseKey
        from fido2 import cbor
    except Exception:
        return jsonify({"error": "Passkey-ondersteuning is niet geïnstalleerd op de server (fido2)."}), 501
    d = request.get_json(silent=True) or {}
    cid = (d.get("credentialId") or "").rstrip("=")
    rec = next((p for p in _pk_store() if p.get("id") == cid), None)
    if not rec:
        return jsonify({"error": "Onbekende passkey."}), 400
    want = session.pop("pk_login_challenge", "")
    try:
        ccd = CollectedClientData(_pk_websafe_decode(d.get("clientDataJSON", "")))
        ad = AuthenticatorData(_pk_websafe_decode(d.get("authenticatorData", "")))
        sig = _pk_websafe_decode(d.get("signature", ""))
    except Exception:
        return jsonify({"error": "Ongeldige passkey-data."}), 400
    got = base64.urlsafe_b64encode(ccd.challenge).rstrip(b"=").decode()
    if not want or not secrets.compare_digest(got, want):
        return jsonify({"error": "Challenge klopt niet — probeer opnieuw."}), 400
    if ccd.type != "webauthn.get" or ccd.origin not in _pk_origins():
        return jsonify({"error": "Herkomst klopt niet."}), 400
    if ad.rp_id_hash != hashlib.sha256(_pk_rp_id().encode()).digest() or not ad.is_user_present():
        return jsonify({"error": "Verificatie mislukt."}), 400
    try:
        key = CoseKey.parse(cbor.decode(_pk_websafe_decode(rec["public_key"])))
        key.verify(_pk_websafe_decode(d.get("authenticatorData", "")) + ccd.hash, sig)
    except Exception:
        audit_log("passkey.login_fail", rec.get("user", "?"), cid[:12])
        return jsonify({"error": "Handtekening ongeldig."}), 400
    new_count = int(getattr(ad, "counter", 0) or 0)
    if new_count and rec.get("sign_count") and new_count <= int(rec["sign_count"]):
        audit_log("passkey.counter_anomaly", rec.get("user", "?"), cid[:12])
        return jsonify({"error": "Passkey-teller klopt niet (mogelijke kloon) — gebruik je wachtwoord en verwijder deze passkey."}), 400
    items = _pk_store()
    for p in items:
        if p.get("id") == cid:
            p["sign_count"] = new_count
            p["last_used"] = _now_iso()
    _pk_save(items)
    u = rec.get("user") or ""
    if u != "admin":
        ca = _client_account()
        if not ca.get("username") or ca.get("username") != u:
            return jsonify({"error": "Dit account bestaat niet meer — vraag een nieuwe uitnodiging aan."}), 400
    session.clear()   # nieuwe sessie bij login (anti-fixation)
    session["user"] = u
    audit_log("passkey.login", u, "Ingelogd met passkey")
    return jsonify({"ok": True, "redirect": "/admin/"})


# ---------- Team-SSO: inloggen met het @mhsmedia.nl Google-account ----------
# Ryan 2026-07-17: één "Inloggen met Google"-knop op alle sites i.p.v. losse wachtwoorden.
# Alleen geverifieerde @mhsmedia.nl-accounts krijgen (agency-)toegang. Hergebruikt de
# bestaande geregistreerde redirect-URI + centrale OAuth-proxy (state met herkomst).
TEAM_SSO_DOMAIN = "mhsmedia.nl"
# Alleen Google's eigen avatar-hosts. De foto-URL komt uit een token dat we niet zelf
# maken (stille SSO) en belandt in een <img> in de admin; een vreemde host zou dus een
# tracking-pixel of erger kunnen zijn.
TEAM_SSO_FOTO_HOSTS = ("googleusercontent.com", "google.com", "gstatic.com")
# Ruim boven een echte avatar-URL (die van Ryan is er 400+ met een lang ALV-token) en
# nog steeds klein genoeg voor de sessiecookie, die boven ~4093 bytes stil wegvalt.
TEAM_SSO_FOTO_MAX = 1024


def _veilige_profielfoto(url) -> str:
    """Geef de URL terug als het een https-avatar van Google is, anders een lege string."""
    url = (url or "").strip()
    if not url.lower().startswith("https://"):
        return ""
    # Bewust weigeren i.p.v. afkappen. Een afgekapte URL ziet er geldig uit, geeft een
    # 404 en verdwijnt dan geruisloos achter de onerror-terugval — precies de bug die
    # de foto op 2026-08-25 onzichtbaar hield.
    if len(url) > TEAM_SSO_FOTO_MAX:
        return ""
    try:
        host = urllib.parse.urlsplit(url).hostname or ""
    except Exception:
        return ""
    host = host.lower()
    if not any(host == h or host.endswith("." + h) for h in TEAM_SSO_FOTO_HOSTS):
        return ""
    return url


def _foto_reden(rauw, veilig) -> str:
    """Waarom is er geen Google-profielfoto? Een lege cirkel ziet er hetzelfde uit of
    Google niets meestuurde of wij de URL weigerden — en dat verschil bepaalt waar je
    moet zoeken. Zonder deze reden kostte dat drie rondes heen en weer."""
    if veilig:
        return ""
    rauw = (rauw or "").strip()
    if not rauw:
        return "geen-foto-van-google"
    if len(rauw) > TEAM_SSO_FOTO_MAX:
        return f"geweigerd-lengte-{len(rauw)}"
    return "geweigerd-host"


def _centrale_foto_url(email) -> str:
    """Conventie-URL van de centraal gehoste teamfoto, dezelfde bron als de
    rapport-ondertekening (MAIHS public/team/<voornaam>.jpg).

    Nodig omdat de stille auto-login — de weg die je bijna altijd neemt, want /admin/
    stuurt je erheen — van de centrale omgeving alleen een e-mailbewijs krijgt en dus
    geen Google-foto. Geen HEAD-check hier: de admin probeert de bronnen op volgorde en
    het mislukken van een <img> is die controle al, zonder extra verzoek per paginalading.
    """
    naam = (session.get("sso_name") or "").strip()
    # Liefst uit de Google-naam, net als de rapport-ondertekening: een adres als
    # r.tuijp@ zou anders "r" opleveren. Zonder naam het adres, tot de eerste scheiding
    # (marjolein.jansen@ is marjolein, niet marjoleinjansen).
    ruw = naam.split()[0] if naam else re.split(r"[._+-]", str(email or "").split("@")[0])[0]
    voornaam = re.sub(r"[^a-z]", "", ruw.lower())
    return f"https://software.mhsmedia.nl/team/{voornaam}.jpg" if voornaam else ""


def _sso_weergavenaam() -> str:
    """Naam voor linksonder in de admin: de Google-naam, anders het e-mailadres netjes
    afgeleid (ryan@mhsmedia.nl -> Ryan). Nooit "admin" als we weten wie er inlogde."""
    naam = (session.get("sso_name") or "").strip()
    if naam:
        return naam[:80]
    email = (session.get("sso_email") or "").strip()
    if not email:
        return ""
    lokaal = re.split(r"[+@]", email)[0]
    delen = [d for d in re.split(r"[._-]+", lokaal) if d]
    return " ".join(d[:1].upper() + d[1:] for d in delen)[:80] or email


@app.route("/api/auth/team/start")
@app.route("/api/auth/team/start/")
def team_sso_start():
    client_id = _google_client_id()
    if not client_id:
        return redirect("/inloggen?sso=notconfigured")
    nonce = secrets.token_urlsafe(24)
    if OAUTH_PROXY_SECRET and _oauth_redirect_base():
        state = _make_proxy_state(_oauth_origin(), "teamlogin", nonce)
    else:
        state = nonce
    session["team_oauth_state"] = state
    params = {
        "client_id": client_id,
        "redirect_uri": _google_redirect_uri(),
        "response_type": "code",
        # `profile` erbij: zonder dat scope geeft Google geen naam en geen foto terug
        # en blijft de admin linksonder "admin" tonen.
        "scope": "openid email profile",
        "prompt": "select_account",
        "hd": TEAM_SSO_DOMAIN,   # hint: toon alleen mhsmedia-accounts (server-side alsnog gecheckt)
        "state": state,
    }
    return redirect("https://accounts.google.com/o/oauth2/v2/auth?" + urllib.parse.urlencode(params))


def _team_sso_finish():
    session.pop("team_oauth_state", None)
    code = request.args.get("code", "")
    if not code:
        return redirect("/inloggen?sso=err")
    try:
        tok = _google_token_exchange({"code": code, "redirect_uri": _google_redirect_uri(),
                                      "grant_type": "authorization_code"})
        ur = urllib.request.Request("https://www.googleapis.com/oauth2/v2/userinfo",
                                    headers={"Authorization": "Bearer " + tok.get("access_token", "")})
        with urllib.request.urlopen(ur, timeout=10) as r:
            info = json.loads(r.read())
    except Exception:
        return redirect("/inloggen?sso=err")
    email = (info.get("email") or "").strip().lower()
    verified = bool(info.get("verified_email", info.get("email_verified", False)))
    hd = (info.get("hd") or "").strip().lower()
    if not email or not verified or not email.endswith("@" + TEAM_SSO_DOMAIN) or (hd and hd != TEAM_SSO_DOMAIN):
        audit_log("team.sso.denied", email or "onbekend", "geen geverifieerd @mhsmedia.nl-account")
        return redirect("/inloggen?sso=denied")
    # Teamlid bewezen -> agency-sessie (zelfde rechten als het admin-account); e-mail voor audit.
    session.clear()   # nieuwe sessie bij login (anti-fixation)
    session["user"] = "admin"
    session["sso_email"] = email
    session["sso_name"] = (info.get("name") or info.get("given_name") or "").strip()[:80]
    session["sso_picture"] = _veilige_profielfoto(info.get("picture"))
    session["sso_foto_reden"] = _foto_reden(info.get("picture"), session["sso_picture"])
    audit_log("team.sso.login", email, "Ingelogd via Google (team-SSO)")
    _eerste_keer = not kv_get("security:team_sso_seen")
    kv_set("security:team_sso_seen", True)   # guardrail-bewijs: SSO werkt aantoonbaar op deze site
    # Alleen de eerste geslaagde SSO verandert er iets aan wat we melden; daarna
    # zou elke login onnodig op de gateway staan wachten.
    if _eerste_keer:
        _meld_koppelingen_direct()
    return redirect("/admin/")


@app.route("/api/admin/security/password-login", methods=["GET", "POST"])
@app.route("/api/admin/security/password-login/", methods=["GET", "POST"])
def api_admin_security_password_login():
    """B4 (Ryan 2026-07-18): teamwachtwoord-login aan/uit. Uitzetten kan pas als Google-
    login geconfigureerd is EN minstens een team-SSO-login slaagde (anti-buitensluiten);
    noodklep = env ALLOW_PASSWORD_LOGIN=1. Klant-login/passkeys blijven altijd werken."""
    a = _auth_or_401()
    if a:
        return a
    if current_role() == "client":
        return jsonify({"error": "Alleen voor teamleden."}), 403
    google_ok = bool(_google_client_id())
    sso_seen = bool(kv_get("security:team_sso_seen"))
    if request.method == "POST":
        b = request.get_json(silent=True) or {}
        want = bool(b.get("disabled"))
        if want and not google_ok:
            return jsonify({"error": "Google-login is nog niet geconfigureerd voor deze site — uitzetten zou je buitensluiten."}), 400
        if want and not sso_seen:
            return jsonify({"error": "Nog geen geslaagde Google-teamlogin gezien op deze site. Log eerst zelf een keer in via Google en zet de wachtwoord-login daarna uit."}), 400
        kv_set("security:pw_login_disabled", want)
        audit_log("security.pw_login", session.get("sso_email") or session.get("user", ""),
                  "Team-wachtwoordlogin " + ("uitgeschakeld" if want else "weer ingeschakeld"))
        return jsonify({"ok": True, "disabled": want})
    return jsonify({"disabled": bool(kv_get("security:pw_login_disabled")),
                    "google_configured": google_ok, "sso_seen": sso_seen,
                    "override": bool(os.environ.get("ALLOW_PASSWORD_LOGIN"))})


def _silent_sso_available(base: str) -> bool:
    """Bestaat /api/sso/check op de centrale omgeving? (10 min gecachet.) Voorkomt dat we
    bezoekers naar een 404 sturen zolang MAIHS de route nog niet deployde of down is."""
    if os.environ.get("SILENT_SSO") == "1":
        return True
    ok = kv_get("sso:central_ok")
    if isinstance(ok, dict) and time.time() - ok.get("t", 0) < 600:
        return bool(ok.get("ok"))
    good = False
    # FAIL-CLOSED: alleen expliciet bewijs dat de route bestaat telt — 400 ("Invalid state")
    # of een 302/307 (niet gevolgd). Een WAF-challenge (403) of 404 = niet beschikbaar;
    # dan blijft de gewone login gewoon werken. Noodschakelaar: env SILENT_SSO=1.
    class _NoRedir(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *a, **k):
            return None
    try:
        req = urllib.request.Request(base + "/api/sso/check", headers={"User-Agent": "Mozilla/5.0 (MAIHS-health)"})
        with urllib.request.build_opener(_NoRedir()).open(req, timeout=3) as r:
            good = r.status in (302, 307, 400)
    except urllib.error.HTTPError as e:
        good = e.code in (302, 307, 400)
    except Exception:
        good = False
    try:
        kv_set("sso:central_ok", {"ok": good, "t": int(time.time())})
    except Exception:
        pass
    return good


@app.route("/api/auth/team/silent")
@app.route("/api/auth/team/silent/")
def team_sso_silent_start():
    """D1: stille team-login — check bij de centrale MAIHS-omgeving of daar al een
    @mhsmedia.nl-sessie leeft; zo ja logt de callback je hier automatisch in."""
    nxt = request.args.get("next") or "/admin/"
    if not nxt.startswith("/") or nxt.startswith("//"):
        nxt = "/admin/"
    base = (os.environ.get("OAUTH_REDIRECT_BASE") or "").rstrip("/")
    if not (OAUTH_PROXY_SECRET and base) or not _silent_sso_available(base):
        return redirect("/inloggen?next=" + urllib.parse.quote(nxt))
    nonce = secrets.token_urlsafe(16)
    session["team_silent_nonce"] = nonce
    session["team_silent_next"] = nxt
    payload = base64.urlsafe_b64encode(json.dumps(
        {"o": _oauth_origin(), "s": "teamsilent", "n": nonce, "t": int(time.time())},
        separators=(",", ":")).encode()).rstrip(b"=").decode()
    sig = base64.urlsafe_b64encode(hmac.new(OAUTH_PROXY_SECRET.encode(), payload.encode(),
                                            hashlib.sha256).digest()).rstrip(b"=").decode()
    resp = redirect(f"{base}/api/sso/check?state={payload}.{sig}")
    # Loop-guard: max 1 stille poging per 10 min, ook als de callback nooit terugkomt.
    resp.set_cookie("ms_sso_try", "1", max_age=600, secure=bool(os.environ.get("VERCEL") or os.environ.get("VERCEL_ENV")), httponly=True, samesite="Lax")
    return resp


@app.route("/api/auth/team/silent/callback")
@app.route("/api/auth/team/silent/callback/")
def team_sso_silent_callback():
    nxt = session.pop("team_silent_next", "/admin/")
    nonce = session.pop("team_silent_nonce", "")
    tok = request.args.get("token", "")
    if not tok or request.args.get("none"):
        return redirect("/inloggen?next=" + urllib.parse.quote(nxt))
    try:
        pay, sig = tok.split(".", 1)
        want = base64.urlsafe_b64encode(hmac.new(OAUTH_PROXY_SECRET.encode(), pay.encode(),
                                                 hashlib.sha256).digest()).rstrip(b"=").decode()
        if not (OAUTH_PROXY_SECRET and secrets.compare_digest(sig, want)):
            raise ValueError("sig")
        d = json.loads(base64.urlsafe_b64decode(pay + "=" * (-len(pay) % 4)))
        email = str(d.get("e") or "").lower()
        # nm/pi zijn optioneel: oudere centrale omgevingen sturen alleen het e-mailbewijs.
        stille_naam = str(d.get("nm") or "").strip()[:80]
        stille_foto = str(d.get("pi") or "")
        if not nonce or d.get("n") != nonce:
            raise ValueError("nonce")
        if abs(time.time() - int(d.get("t") or 0)) > 180:
            raise ValueError("verlopen")
        if not email.endswith("@" + TEAM_SSO_DOMAIN):
            raise ValueError("domein")
    except Exception:
        audit_log("team.sso.silent.denied", "-", "ongeldig silent-token")
        return redirect("/inloggen?next=" + urllib.parse.quote(nxt))
    session.clear()   # nieuwe sessie bij login (anti-fixation)
    session["user"] = "admin"
    session["sso_email"] = email
    session["sso_name"] = stille_naam
    session["sso_picture"] = _veilige_profielfoto(stille_foto)
    session["sso_foto_reden"] = ("stille-login-zonder-foto" if not stille_foto
                                 else _foto_reden(stille_foto, session["sso_picture"]))
    kv_set("security:team_sso_seen", True)
    audit_log("team.sso.silent", email, "Automatisch ingelogd via de centrale MHS-sessie")
    return redirect(nxt)


@app.route("/api/oauth/google/callback")
def oauth_google_callback():
    # Team-SSO-tak (publiek): dit IS de login, dus geen require_login. Herkenning via de
    # eigen sessie-state; timing-safe vergeleken.
    _tstate = session.get("team_oauth_state") or ""
    if _tstate and secrets.compare_digest(request.args.get("state", ""), _tstate):
        return _team_sso_finish()
    if require_login():
        return redirect("/inloggen")
    err = request.args.get("error")
    if err:
        return redirect("/admin/?g=" + urllib.parse.quote(err) + "#settings")
    if request.args.get("state") != session.get("oauth_state"):
        return redirect("/admin/?g=state_mismatch#settings")
    code = request.args.get("code", "")
    if not code:
        return redirect("/admin/?g=no_code#settings")
    try:
        tok = _google_token_exchange({"code": code, "redirect_uri": _google_redirect_uri(),
                                      "grant_type": "authorization_code"})
    except urllib.error.HTTPError as e:
        return redirect("/admin/?g=token_" + str(e.code) + "#settings")
    except Exception:
        return redirect("/admin/?g=token_error#settings")
    svc = session.get("oauth_service", "")
    okey = "google_oauth:" + svc if svc else "google_oauth"
    g = kv_get(okey) or {"scopes": []}
    if tok.get("refresh_token"):
        g["refresh_token"] = tok["refresh_token"]
    g["access_token"] = tok.get("access_token", "")
    g["expiry"] = (datetime.now() + timedelta(seconds=int(tok.get("expires_in", 3600)))).isoformat(timespec="seconds")
    granted = (tok.get("scope", "") or "").split()
    g["scopes"] = sorted(set((g.get("scopes") or []) + granted))
    try:
        ur = urllib.request.Request("https://www.googleapis.com/oauth2/v2/userinfo",
                                    headers={"Authorization": "Bearer " + g["access_token"]})
        with urllib.request.urlopen(ur, timeout=10) as r:
            g["email"] = json.loads(r.read()).get("email", "")
    except Exception:
        pass
    kv_set(okey, g)
    if svc:
        conns = kv_get("integrations") or {}
        conns[svc] = {"connected": True, "account": g.get("email", ""), "via": "google",
                      "at": _now_iso()}
        kv_set("integrations", conns)
    _meld_koppelingen_direct()
    return redirect("/admin/?g=ok&svc=" + svc + "#settings")


def google_access_token(service=None, fallback=True):
    """Geldig access token voor een dienst (per-service, met optionele fallback op de oude gedeelde token).
    fallback=False forceert de per-service koppeling — zodat een feed (zoals de agenda) niet stilletjes
    een oude, gedeelde token van een ander account gebruikt terwijl die dienst 'niet gekoppeld' toont."""
    key = "google_oauth:" + service if service else "google_oauth"
    g = kv_get(key) or {}
    if fallback and not g.get("refresh_token") and service:
        g = kv_get("google_oauth") or {}
        key = "google_oauth"
    if not g.get("refresh_token"):
        return None
    try:
        exp = datetime.fromisoformat(g.get("expiry", "")) if g.get("expiry") else None
    except Exception:
        exp = None
    if g.get("access_token") and exp and exp > datetime.now() + timedelta(seconds=60):
        return g["access_token"]
    try:
        tok = _google_token_exchange({"refresh_token": g["refresh_token"],
                                      "grant_type": "refresh_token"})
    except urllib.error.HTTPError as e:
        # invalid_grant = de klant heeft de toegang ingetrokken of het token is verlopen:
        # dan klopt 'niet gekoppeld' en zetten we dat ook zo neer. invalid_client en
        # unauthorized_client betekenen iets heel anders — dán is ónze clientconfiguratie
        # verkeerd, en zou ontkoppelen elke integratie op de site wissen terwijl de klant
        # niets deed. Die laten we dus met rust. Netwerkfouten raken de status ook niet.
        try:
            body = e.read().decode("utf-8", "replace")
        except Exception:
            body = ""
        if "invalid_client" in body or "unauthorized_client" in body:
            print("[oauth] clientconfiguratie klopt niet — koppelingen ongemoeid gelaten")
        if service and e.code in (400, 401) and "invalid_grant" in body:
            try:
                conns = kv_get("integrations") or {}
                if isinstance(conns.get(service), dict):
                    conns[service] = {**conns[service], "connected": False}
                    kv_set("integrations", conns)
            except Exception:
                pass
        return None
    except Exception:
        return None
    g["access_token"] = tok.get("access_token", "")
    g["expiry"] = (datetime.now() + timedelta(seconds=int(tok.get("expires_in", 3600)))).isoformat(timespec="seconds")
    kv_set(key, g)
    return g["access_token"]


@app.route("/api/oauth/google/status")
def oauth_google_status():
    a = _auth_or_401()
    if a:
        return a
    service = request.args.get("service", "")
    if service:
        g = kv_get("google_oauth:" + service) or {}
    else:
        g = kv_get("google_oauth") or {}
        for _svc in GOOGLE_SCOPES:
            gg = kv_get("google_oauth:" + _svc)
            if gg and gg.get("refresh_token"):
                g = gg
                break
    return jsonify({"connected": bool(g.get("refresh_token")), "email": g.get("email", ""),
                    "scopes": g.get("scopes", []), "configured": bool(_google_client_id())})


# ==================== GOOGLE ADS DATA ====================
# Developer-token en MCC horen bij het bureau, niet bij de klant: ze zijn op elke site
# hetzelfde. Eigen env wint nog steeds; anders komen ze van de centrale gateway.
GOOGLE_ADS_DEVELOPER_TOKEN = os.environ.get("GOOGLE_ADS_DEVELOPER_TOKEN", "")
GOOGLE_ADS_LOGIN_CUSTOMER_ID = os.environ.get("GOOGLE_ADS_LOGIN_CUSTOMER_ID", "")
# Google bumpt de Ads API ~elk kwartaal en sunset oude versies → probeer recente eerst,
# onthoud de werkende in KV. Env GOOGLE_ADS_API_VERSION forceert één versie.
GOOGLE_ADS_API_VERSIONS = [os.environ.get("GOOGLE_ADS_API_VERSION", "")] + ["v21", "v20", "v19", "v22", "v18", "v17"]
GOOGLE_ADS_API_VERSIONS = [v for v in GOOGLE_ADS_API_VERSIONS if v]


def _ads_gateway() -> dict:
    cfg = _gateway_config().get("google_ads")
    return cfg if isinstance(cfg, dict) else {}


def _ads_developer_token() -> str:
    return (GOOGLE_ADS_DEVELOPER_TOKEN or str(_ads_gateway().get("developer_token") or "")).strip()


def _ads_login_customer_id() -> str:
    return (GOOGLE_ADS_LOGIN_CUSTOMER_ID or str(_ads_gateway().get("login_customer_id") or "")).strip()


def _ads_version():
    return kv_get("google_ads_version") or GOOGLE_ADS_API_VERSIONS[0]


def _ads_version_candidates():
    cur = _ads_version()
    return [cur] + [v for v in GOOGLE_ADS_API_VERSIONS if v != cur]


def _ads_headers(login_customer_id=""):
    tok = google_access_token("google_ads")
    if not tok:
        return None, "Niet (meer) verbonden met Google — koppel Google Ads opnieuw."
    dev_token = _ads_developer_token()
    if not dev_token:
        return None, "Google Ads developer-token ontbreekt (in te stellen bij MAIHS → Gateways)."
    h = {"Authorization": "Bearer " + tok, "developer-token": dev_token,
         "Content-Type": "application/json"}
    lcid = (login_customer_id or _ads_login_customer_id() or "").replace("-", "")
    if lcid:
        h["login-customer-id"] = lcid
    return h, None


def _ads_err(code, raw):
    if code == 403:
        return ("Geen toegang tot dit Google Ads-account met het gekoppelde Google-account. "
                "Kies een ander account, of verbind Google Ads opnieuw (Instellingen → Integraties) met het "
                "Google-account dat toegang heeft (bijv. je manager-account). Details: " + (raw or "")[:180])
    if code == 401:
        return "Google-koppeling verlopen — verbind Google Ads opnieuw. " + (raw or "")[:120]
    return f"Google Ads API {code}: {(raw or '')[:250]}"


def _ads_search(customer_id, query, login_customer_id=""):
    h, err = _ads_headers(login_customer_id)
    if err:
        return None, err
    cid = (customer_id or "").replace("-", "")
    res, last = None, ""
    for v in _ads_version_candidates():
        url = f"https://googleads.googleapis.com/{v}/customers/{cid}/googleAds:searchStream"
        try:
            req = urllib.request.Request(url, data=json.dumps({"query": query}).encode(), headers=h, method="POST")
            with urllib.request.urlopen(req, timeout=30) as r:
                res = json.loads(r.read())
            kv_set("google_ads_version", v)
            break
        except urllib.error.HTTPError as e:
            last = _ads_err(e.code, e.read().decode('utf-8', 'replace'))
            if e.code == 404:
                continue
            return None, last
        except Exception as e:
            last = str(e)
    if res is None:
        return None, last or "Geen werkende Google Ads API-versie."
    rows = []
    for batch in (res if isinstance(res, list) else [res]):
        rows.extend(batch.get("results", []))
    return rows, None


def _ads_list_accessible():
    """Return (ids, error). Probeert API-versies tot een werkt."""
    h, err = _ads_headers()
    if err:
        return None, err
    last = ""
    for v in _ads_version_candidates():
        url = f"https://googleads.googleapis.com/{v}/customers:listAccessibleCustomers"
        try:
            req = urllib.request.Request(url, headers=h)
            with urllib.request.urlopen(req, timeout=20) as r:
                res = json.loads(r.read())
            kv_set("google_ads_version", v)
            return [rn.split("/")[-1] for rn in res.get("resourceNames", [])], None
        except urllib.error.HTTPError as e:
            last = _ads_err(e.code, e.read().decode('utf-8', 'replace'))
            if e.code == 404:
                continue
            return None, last
        except Exception as e:
            last = str(e)
    return None, "Geen werkende Google Ads API-versie gevonden. Laatste fout: " + last


@app.route("/api/google-ads/accounts")
def api_ads_accounts():
    a = _auth_or_401()
    if a:
        return a
    ids, err = _ads_list_accessible()
    if ids is None:
        return jsonify({"ok": False, "error": err}), 400
    accounts = []
    for cid in ids:
        name, manager = cid, False
        rows, e = _ads_search(cid, "SELECT customer.id, customer.descriptive_name, customer.manager FROM customer LIMIT 1", login_customer_id=cid)
        if rows:
            c = rows[0].get("customer", {})
            name = c.get("descriptiveName") or cid
            manager = bool(c.get("manager"))
        accounts.append({"id": cid, "name": name, "manager": manager})
    return jsonify({"ok": True, "accounts": accounts})


@app.route("/api/google-ads/clients")
def api_ads_clients():
    a = _auth_or_401()
    if a:
        return a
    mgr = request.args.get("manager", "").replace("-", "")
    if not mgr:
        return jsonify({"ok": False, "error": "manager ontbreekt"}), 400
    q = ("SELECT customer_client.id, customer_client.descriptive_name, customer_client.manager, "
         "customer_client.level FROM customer_client WHERE customer_client.level <= 1")
    rows, err = _ads_search(mgr, q, login_customer_id=mgr)
    if err:
        return jsonify({"ok": False, "error": err}), 400
    clients = []
    for r in rows:
        cc = r.get("customerClient", {})
        cid = str(cc.get("id", ""))
        if not cid or cid == mgr:
            continue
        clients.append({"id": cid, "name": cc.get("descriptiveName") or cid, "manager": bool(cc.get("manager"))})
    return jsonify({"ok": True, "clients": clients})


@app.route("/api/google-ads/campaigns")
def api_ads_campaigns():
    a = _auth_or_401()
    if a:
        return a
    cid = request.args.get("customer_id", "")
    if not cid:
        return jsonify({"ok": False, "error": "customer_id ontbreekt"}), 400
    lcid = request.args.get("login_customer_id", "")
    today = datetime.now()
    frm = request.args.get("from") or today.replace(day=1).strftime("%Y-%m-%d")
    to = request.args.get("to") or today.strftime("%Y-%m-%d")
    q = ("SELECT campaign.id, campaign.name, campaign.status, campaign_budget.amount_micros, "
         "metrics.cost_micros, metrics.impressions, metrics.clicks, metrics.conversions, "
         "metrics.conversions_value FROM campaign "
         f"WHERE segments.date BETWEEN '{frm}' AND '{to}'")
    rows, err = _ads_search(cid, q, login_customer_id=lcid)
    if err:
        return jsonify({"ok": False, "error": err}), 400
    camps = {}
    for r in rows:
        c = r.get("campaign", {})
        m = r.get("metrics", {})
        bud = r.get("campaignBudget", {})
        k = c.get("id")
        if k not in camps:
            camps[k] = {"id": k, "name": c.get("name", ""), "status": c.get("status", ""),
                        "daily_budget": int(bud.get("amountMicros", 0)) / 1e6,
                        "cost": 0.0, "impressions": 0, "clicks": 0, "conversions": 0.0, "conv_value": 0.0}
        camps[k]["cost"] += int(m.get("costMicros", 0)) / 1e6
        camps[k]["impressions"] += int(m.get("impressions", 0))
        camps[k]["clicks"] += int(m.get("clicks", 0))
        camps[k]["conversions"] += float(m.get("conversions", 0))
        camps[k]["conv_value"] += float(m.get("conversionsValue", 0))
    out = sorted(camps.values(), key=lambda x: x["cost"], reverse=True)
    for c in out:
        c["cost"] = round(c["cost"], 2)
        c["conv_value"] = round(c["conv_value"], 2)
        c["conversions"] = round(c["conversions"], 1)
        c["roas"] = round(c["conv_value"] / c["cost"], 2) if c["cost"] else 0
    totals = {"cost": round(sum(c["cost"] for c in out), 2), "clicks": sum(c["clicks"] for c in out),
              "impressions": sum(c["impressions"] for c in out),
              "conversions": round(sum(c["conversions"] for c in out), 1),
              "conv_value": round(sum(c["conv_value"] for c in out), 2),
              "monthly_budget": round(sum(c["daily_budget"] for c in out) * 30.4, 2)}
    totals["roas"] = round(totals["conv_value"] / totals["cost"], 2) if totals["cost"] else 0
    return jsonify({"ok": True, "campaigns": out, "totals": totals, "from": frm, "to": to})


# ==================== GOOGLE BUSINESS PROFILE (GMB) ====================
def _gbp_get(url):
    tok = google_access_token("google_business")
    if not tok:
        return None, "Niet (meer) verbonden met Google — koppel Bedrijfsprofiel opnieuw."
    try:
        # Accept-Language: zonder taalvoorkeur zet Google de ENGELSE automatische
        # vertaling van reviews voorop; met nl blijft Nederlands Nederlands.
        req = urllib.request.Request(url, headers={"Authorization": "Bearer " + tok,
                                                   "Accept-Language": "nl"})
        with urllib.request.urlopen(req, timeout=25) as r:
            return json.loads(r.read() or b"{}"), None
    except urllib.error.HTTPError as e:
        return None, f"Google API {e.code}: {e.read().decode('utf-8', 'replace')[:300]}"
    except Exception as e:
        return None, str(e)


def _gbp_fmt_addr(a):
    if not a:
        return ""
    parts = list(a.get("addressLines", []) or [])
    line2 = " ".join(x for x in [a.get("postalCode", ""), a.get("locality", "")] if x)
    if line2:
        parts.append(line2)
    return ", ".join(parts)


def _gbp_scope(req_account=None, req_location=None):
    """Bepaalt welke (account, location) de huidige gebruiker MAG opvragen — tenant-isolatie.
    Het Google-account van MHS heeft toegang tot álle klant-profielen, dus we mogen NOOIT
    blind een door de client meegestuurde account/location vertrouwen.

    - Klant (client-rol): hard vastgezet op de gekoppelde vestiging uit de instellingen.
      Meegestuurde args worden genegeerd → een klant kan geen ander bedrijfsprofiel opvragen.
    - Agency (MHS): mag de meegestuurde vestiging gebruiken (beheert alle klanten),
      met de gekoppelde vestiging als fallback.

    Returns (account, location, error_response_or_None). account = 'accounts/123',
    location = 'locations/456' (de volledige resource-namen)."""
    pinned = (get_settings().get("google_business") or {})
    p_acc, p_loc = (pinned.get("account") or ""), (pinned.get("location") or "")
    if current_role() == "agency":
        acc, loc = (req_account or p_acc), (req_location or p_loc)
        if not acc or not loc:
            return None, None, (jsonify({"ok": False, "error": "Geen vestiging gekoppeld"}), 400)
        return acc, loc, None
    if not p_acc or not p_loc:
        return None, None, (jsonify({"ok": False, "error": "Geen vestiging gekoppeld voor dit account"}), 403)
    return p_acc, p_loc, None


@app.route("/api/gbp/locations")
def api_gbp_locations():
    a = _auth_or_401()
    if a:
        return a
    # Standaard (de GBP-pagina) toont ALLEEN de gekoppelde vestiging — geen lijst met andere
    # bedrijven van het MHS-account. De volledige lijst is enkel beschikbaar voor de agency
    # via de setup-picker (?all=1), zodat MHS de vestiging kan kiezen/wijzigen in Integraties.
    if not (request.args.get("all") == "1" and current_role() == "agency"):
        p = get_settings().get("google_business") or {}
        if p.get("location") and p.get("account"):
            return jsonify({"ok": True, "locations": [{
                "account": p.get("account"), "name": p.get("location"),
                "title": p.get("name") or "Mijn bedrijfsprofiel",
                "address": "", "phone": "", "website": "", "category": "", "maps_uri": "", "description": ""}]})
        return jsonify({"ok": True, "locations": []})
    # Business Profile API's hebben een ZEER lage default quota (vaak 1/min of 0 tot je quota
    # aanvraagt). Cache de locaties 1 uur zodat we de quota niet opstoken, en val op de cache
    # terug bij een 429.
    cache = kv_get("gbp:locations:cache")
    now = datetime.now()
    if cache and cache.get("at"):
        try:
            if datetime.fromisoformat(cache["at"]) > now - timedelta(hours=1):
                return jsonify({"ok": True, "locations": cache.get("locations", []), "cached": True})
        except Exception:
            pass
    accts, err = _gbp_get("https://mybusinessaccountmanagement.googleapis.com/v1/accounts")
    if err:
        if "429" in err and cache:
            return jsonify({"ok": True, "locations": cache.get("locations", []), "cached": True, "warning": "quota"})
        if "429" in err:
            err = ("Google Business Profile-quota bereikt. De Business Profile API heeft standaard "
                   "een zeer lage limiet — vraag quota/toegang aan in de Google Cloud Console "
                   "(Business Profile API → Quotas). " + err)
        return jsonify({"ok": False, "error": err}), 400
    mask = "name,title,storefrontAddress,phoneNumbers,websiteUri,categories,profile,regularHours,metadata"
    out = []
    for acc in (accts.get("accounts") or []):
        accname = acc.get("name", "")
        locs, lerr = _gbp_get(f"https://mybusinessbusinessinformation.googleapis.com/v1/{accname}/locations?readMask={mask}&pageSize=100")
        if lerr:
            continue
        for loc in (locs.get("locations") or []):
            cat = ((loc.get("categories") or {}).get("primaryCategory") or {}).get("displayName", "")
            out.append({
                "account": accname, "name": loc.get("name", ""), "title": loc.get("title", ""),
                "address": _gbp_fmt_addr(loc.get("storefrontAddress")),
                "phone": (loc.get("phoneNumbers") or {}).get("primaryPhone", ""),
                "website": loc.get("websiteUri", ""), "category": cat,
                "maps_uri": (loc.get("metadata") or {}).get("mapsUri", ""),
                "description": (loc.get("profile") or {}).get("description", ""),
            })
    kv_set("gbp:locations:cache", {"at": now.isoformat(timespec="seconds"), "locations": out})
    return jsonify({"ok": True, "locations": out})


