# ===================== GBP AI content-strategie & planning =====================
# AI genereert maandelijkse post-voorstellen -> goedkeuringsqueue (agency) -> geplande
# publicatie naar Google Bedrijfsprofiel (scheduler) -> klant ziet alleen geplande/geplaatste
# posts (geen AI/scheduler-knoppen). State in KV: gbp:strategy, gbp:queue, gbp:strategy:lastrun.

_GBP_STAR_MAP = {"ONE": 1, "TWO": 2, "THREE": 3, "FOUR": 4, "FIVE": 5}


def _gbp_parse_time(s):
    """RFC3339-tijdstempel van Google ('2026-08-20T10:00:00Z') -> aware datetime, of None."""
    try:
        s = str(s or "").strip()
        if not s:
            return None
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        d = datetime.fromisoformat(s)
        return d if d.tzinfo else d.replace(tzinfo=timezone.utc)
    except Exception:
        return None


def _gbp_review_origineel(comment: str) -> str:
    """Wat de klant ZELF schreef. Google vertaalt reviews automatisch en levert dan
    '(Translated by Google) ... (Original) ...' als één veld — zonder uitpakken belandt
    Googles vertaling als 'letterlijk citaat' in een post. Een origineel in een andere
    taal is prima; de vertaling nooit."""
    t = str(comment or "").strip()
    for marker in ("(Original)", "(Origineel)"):
        i = t.find(marker)
        if i >= 0:
            return t[i + len(marker):].strip()
    for marker in ("(Translated by Google)", "(Vertaald door Google)"):
        if t.startswith(marker):
            # Zeldzaam: wél een vertaal-prefix, geen origineel-blok — dan is de
            # vertaling het beste dat we hebben.
            return t[len(marker):].strip()
    return t


def _gbp_all_reviews(force: bool = False) -> list:
    """Alle Google-reviews van de gekoppelde vestiging, genormaliseerd en gepagineerd.

    De Business Profile API heeft een lage quota, dus 12 uur cache in KV
    (gbp:reviews:cache). force=True (de autoreply-tick) haalt altijd vers op:
    reageren op basis van een verouderde lijst zou dubbel of te laat reageren."""
    if not force:
        cache = kv_get("gbp:reviews:cache")
        try:
            if cache and cache.get("at") and datetime.fromisoformat(cache["at"]) > datetime.now() - timedelta(hours=12):
                return cache.get("reviews") or []
        except Exception:
            pass
    gb = get_settings().get("google_business") or {}
    acc, loc = (gb.get("account") or "").split("/")[-1], (gb.get("location") or "").split("/")[-1]
    if not acc or not loc:
        return []
    out, token = [], ""
    for _ in range(5):  # max 5 pagina's à 50 reviews — genoeg, en quota-vriendelijk
        url = (f"https://mybusiness.googleapis.com/v4/accounts/{acc}/locations/{loc}/reviews?pageSize=50"
               + (f"&pageToken={token}" if token else ""))
        data, err = _gbp_get(url)
        if err or not isinstance(data, dict):
            break
        for rv in (data.get("reviews") or []):
            out.append({
                "author": (rv.get("reviewer") or {}).get("displayName", "Anoniem"),
                "stars": _GBP_STAR_MAP.get(rv.get("starRating", ""), 0),
                "comment": _gbp_review_origineel(rv.get("comment")),
                "time": rv.get("createTime", ""),
                "reply": ((rv.get("reviewReply") or {}).get("comment", "") or ""),
                "id": rv.get("reviewId", "") or rv.get("name", "").split("/")[-1],
            })
        token = data.get("nextPageToken") or ""
        if not token:
            break
    if out:
        kv_set("gbp:reviews:cache", {"at": datetime.now().isoformat(timespec="seconds"), "reviews": out})
    return out


def _gbp_site_context(max_chars: int = 6000) -> str:
    """Alle échte sitecontent als feitenbron voor de AI (op deze React-site: de
    t()-teksten per pagina). Zo schrijft de generator over wat er werkelijk op de
    site staat in plaats van te gokken — de belangrijkste rem op hallucineren."""
    try:
        delen = []
        try:
            delen.append("Bedrijf: " + _seo_business_context())
        except Exception:
            pass
        for p in _pages_index():
            if p.get("status", "published") != "published":
                continue
            slug = (p.get("slug") or "").strip("/")
            pg = _get_page(slug) or {}
            teksten = []
            for t in (pg.get("spa_texts") or []):
                if isinstance(t, dict):
                    s = (t.get("text") or t.get("original") or "").strip()
                    if len(s) > 2:
                        teksten.append(s)
            if not teksten:
                continue
            titel = (p.get("title") or slug or "home").strip()
            delen.append(("## " + titel + "\n" + " | ".join(teksten))[:1400])
        return "\n\n".join(delen)[:max_chars]
    except Exception:
        return ""


def _gbp_reviews_context(max_n: int = 30, max_chars: int = 4000) -> str:
    """Echte klantreviews als AI-context — uitsluitend om letterlijk uit te citeren."""
    try:
        regels = []
        for rv in _gbp_all_reviews()[:max_n]:
            tekst = (rv.get("comment") or "").strip()
            regel = f"- {rv.get('author', 'Anoniem')} ({rv.get('stars', 0)} sterren, {str(rv.get('time', ''))[:10]}): "
            regel += ('"' + tekst[:240] + '"') if tekst else "(alleen een sterbeoordeling, geen tekst)"
            regels.append(regel)
        return "\n".join(regels)[:max_chars]
    except Exception:
        return ""


def _gbp_seo_focus(max_chars: int = 1600) -> str:
    """Waar de SEO-autopilot deze maand aan werkt, als sturing voor de GBP-posts —
    zo versterken site en profiel hetzelfde onderwerp in dezelfde weken.

    Leest ALLEEN bestaande caches/config: de kansen-cache (striking distance), de
    focus-zoekwoorden en het maandplan. Bewust niet de kansen-HERBOUWfunctie
    aanroepen: die kan een verse opbouw met GSC/SE Ranking/AI-calls triggeren,
    en dat hoort niet in het pad van de uurlijkse GBP-cron."""
    try:
        regels = []
        try:
            fk = [str(k).strip() for k in (_agent_config() or {}).get("focus_keywords") or [] if str(k).strip()]
            if fk:
                regels.append("Focus-zoekwoorden van het bureau: " + ", ".join(fk[:10]))
        except Exception:
            pass
        for o in ((kv_get("seo:opportunities") or {}).get("items") or [])[:6]:
            if not isinstance(o, dict) or not o.get("query"):
                continue
            r = f"- Bijna-winnaar in Google: \"{o['query']}\" (positie {round(float(o.get('position', 0) or 0))})"
            if o.get("page"):
                r += f", doelpagina {o['page']}"
            regels.append(r)
        for t in ((kv_get("seo:plan") or {}).get("queue") or []):
            if isinstance(t, dict) and t.get("kind") in ("page", "blog") and t.get("title"):
                pad = ("/blog/" if t["kind"] == "blog" else "/") + str(t.get("slug") or "").strip("/") + "/"
                regels.append(f"- Deze maand op de site: {t['title']} ({pad})")
        return "\n".join(regels)[:max_chars]
    except Exception:
        return ""


def _gbp_is_echt_citaat(post_text: str, reviews: list) -> bool:
    """Bevat de post een letterlijk fragment uit een échte review? De harde grens
    tegen nepreviews: een 'review van de maand'-post zonder woordelijk citaat uit
    een bestaande review mag NOOIT door — liever een post minder dan een verzonnen
    klantuitspraak op het profiel."""
    def _norm(s):
        return re.sub(r"\s+", " ", str(s or "").lower()).strip()
    p = _norm(post_text)
    if not p:
        return False
    for rv in (reviews or []):
        c = _norm((rv or {}).get("comment") or "")
        if len(c) < 20:
            continue
        if c in p:
            return True
        # Schuivend venster: de AI citeert vaak een middenstuk van een langere review.
        for i in range(0, max(1, len(c) - 39), 20):
            if c[i:i + 40] in p:
                return True
    return False


def _gbp_utm_url(url: str, campagne: str = "") -> str:
    """Meetbare post-knoppen: utm_source=gbp op links naar de EIGEN site, zodat het
    bedrijfsprofiel als eigen kanaal in de Marketing-attributie verschijnt. Externe
    links en al-getagde links blijven ongemoeid."""
    try:
        u = str(url or "")
        if not u or "utm_source=" in u or u.startswith("#"):
            return u
        base = _public_base()
        if not (u.startswith("/") or (base and u.startswith(base))):
            return u
        frag = ""
        if "#" in u:
            u, frag = u.split("#", 1)
            frag = "#" + frag
        sep = "&" if "?" in u else "?"
        camp = re.sub(r"[^A-Za-z0-9_-]", "", str(campagne or "post"))[:40] or "post"
        return f"{u}{sep}utm_source=gbp&utm_medium=post&utm_campaign={camp}{frag}"
    except Exception:
        return url


def _gbp_geocode(adres: str):
    """Adres -> (lat, lng) via Nominatim/OSM, of None. Wordt hooguit eens per 30 dagen
    aangeroepen (de latlng-cache), dus ruim binnen de gebruiksvoorwaarden; een
    identificerende User-Agent is daar verplicht."""
    try:
        url = ("https://nominatim.openstreetmap.org/search?format=json&limit=1&q="
               + urllib.parse.quote(adres, safe=""))
        req = urllib.request.Request(url, headers={"User-Agent": "MHS-CMS-geotag/1.0 (info@mhsmedia.nl)"})
        with urllib.request.urlopen(req, timeout=8) as r:
            uit = json.loads(r.read() or b"[]")
        if uit and uit[0].get("lat") and uit[0].get("lon"):
            return float(uit[0]["lat"]), float(uit[0]["lon"])
    except Exception:
        pass
    return None


def _gbp_latlng():
    """Coördinaten van de gekoppelde vestiging, of None. Eén keer per 30 dagen bij de
    Business Information API opgehaald; ook 'geen coördinaten' wordt gecachet, anders
    hamert élke post-build opnieuw op de schaarse quota."""
    cache = kv_get("gbp:latlng:cache") or {}
    try:
        if cache.get("at"):
            leeftijd = datetime.now() - datetime.fromisoformat(cache["at"])
            if cache.get("lat") is not None and cache.get("lng") is not None:
                if leeftijd < timedelta(days=30):        # een vestiging verhuist zelden
                    return (cache["lat"], cache["lng"])
            elif leeftijd < timedelta(hours=1):
                # Negatief kort cachen: geen quota-hamer per post-build, maar één
                # tijdelijke API-hapering mag de geotagging geen maand vergiftigen.
                return None
    except Exception:
        pass
    gb = get_settings().get("google_business") or {}
    loc = (gb.get("location") or "").strip()
    if not loc:
        return None
    lat = lng = None
    fout = ""
    try:
        data, err = _gbp_get(f"https://mybusinessbusinessinformation.googleapis.com/v1/{loc}?readMask=latlng,storefrontAddress")
        if not err and isinstance(data, dict):
            ll = data.get("latlng") or data.get("latLng") or {}
            lat, lng = ll.get("latitude"), ll.get("longitude")
            if lat is None or lng is None:
                # Service-area-profielen (bedrijf aan huis) krijgen van Google géén
                # latlng terug, ook mét vestigingsadres — dan geocoderen we dat adres
                # zelf, eens per 30 dagen (de cache hieronder).
                adres = _gbp_fmt_addr(data.get("storefrontAddress"))
                gc = _gbp_geocode(adres) if adres else None
                if gc:
                    lat, lng = gc
                else:
                    fout = ("geen latlng in het antwoord"
                            + (f"; geocode van '{adres[:60]}' mislukt" if adres else "; geen adres"))
        else:
            fout = str(err or "leeg antwoord")
    except Exception as e:
        fout = str(e)
    kv_set("gbp:latlng:cache", {"at": datetime.now().isoformat(timespec="seconds"),
                                "lat": lat, "lng": lng, "err": fout[:200]})
    return (lat, lng) if (lat is not None and lng is not None) else None


def _gbp_geo_exif_tiff(lat: float, lng: float, orientation: int = 0) -> bytes:
    """Little-endian TIFF/EXIF-blob met een GPS-IFD (en optioneel de orientatie).
    Stdlib-only — geen PIL/piexif op de serverless build."""
    def rat(n, d=1):
        return struct.pack("<II", int(n), int(d))

    def dms(v):
        v = abs(float(v))
        d = int(v)
        rest = (v - d) * 60
        m = int(rest)
        s = round((rest - m) * 60 * 10000)
        return rat(d) + rat(m) + rat(s, 10000)

    n0 = 1 + (1 if orientation else 0)
    g = 8 + 2 + n0 * 12 + 4                 # offset van de GPS-IFD
    lat_off = g + 2 + 5 * 12 + 4            # rationals ná de GPS-IFD
    lng_off = lat_off + 24
    uit = b"II" + struct.pack("<HI", 42, 8)
    uit += struct.pack("<H", n0)
    if orientation:
        uit += struct.pack("<HHI", 0x0112, 3, 1) + struct.pack("<HH", int(orientation), 0)
    uit += struct.pack("<HHII", 0x8825, 4, 1, g)     # GPSInfo-pointer
    uit += struct.pack("<I", 0)
    uit += struct.pack("<H", 5)
    uit += struct.pack("<HHI", 0x0000, 1, 4) + bytes([2, 3, 0, 0])            # GPSVersionID
    uit += struct.pack("<HHI", 0x0001, 2, 2) + (b"N" if lat >= 0 else b"S") + b"\x00\x00\x00"
    uit += struct.pack("<HHII", 0x0002, 5, 3, lat_off)
    uit += struct.pack("<HHI", 0x0003, 2, 2) + (b"E" if lng >= 0 else b"W") + b"\x00\x00\x00"
    uit += struct.pack("<HHII", 0x0004, 5, 3, lng_off)
    uit += struct.pack("<I", 0)
    uit += dms(lat) + dms(lng)
    return uit


def _gbp_jpeg_orientatie(data: bytes) -> int:
    """Orientation-tag uit een bestaand EXIF-blok (0 = geen). Die mag bij het vervangen
    van het blok niet verloren gaan, anders ligt een foto ineens op z'n kant."""
    try:
        i, n = 2, len(data)
        while i + 4 <= n and data[i] == 0xFF:
            marker = data[i + 1]
            if marker in (0xDA, 0xD9):
                break
            seglen = int.from_bytes(data[i + 2:i + 4], "big")
            if marker == 0xE1 and data[i + 4:i + 10] == b"Exif\x00\x00":
                t = data[i + 10:i + 2 + seglen]
                bo = "little" if t[:2] == b"II" else "big"
                ifd = int.from_bytes(t[4:8], bo)
                cnt = int.from_bytes(t[ifd:ifd + 2], bo)
                for e in range(cnt):
                    p = ifd + 2 + e * 12
                    if int.from_bytes(t[p:p + 2], bo) == 0x0112:
                        return int.from_bytes(t[p + 8:p + 10], bo)
                return 0
            i += 2 + seglen
    except Exception:
        pass
    return 0


def _gbp_geo_tag_image(data: bytes, lat, lng):
    """Zet de vestigings-coördinaten als EXIF-GPS in een JPEG (APP1) of PNG (eXIf-chunk).
    None = niet te taggen; de aanroeper serveert dan gewoon het origineel."""
    try:
        if lat is None or lng is None:
            return None
        if data[:2] == b"\xff\xd8":
            tiff = _gbp_geo_exif_tiff(lat, lng, _gbp_jpeg_orientatie(data))
            payload = b"Exif\x00\x00" + tiff
            app1 = b"\xff\xe1" + (len(payload) + 2).to_bytes(2, "big") + payload
            # Bestaand Exif-APP1 vervalt (wij vervangen 'm, orientatie reist mee);
            # alle overige segmenten blijven onaangeroerd.
            rest, i, n = b"", 2, len(data)
            while i + 4 <= n and data[i] == 0xFF:
                marker = data[i + 1]
                if marker in (0xDA, 0xD9):
                    break
                seglen = int.from_bytes(data[i + 2:i + 4], "big")
                if not (marker == 0xE1 and data[i + 4:i + 10] == b"Exif\x00\x00"):
                    rest += data[i:i + 2 + seglen]
                i += 2 + seglen
            return data[:2] + app1 + rest + data[i:]
        if data[:8] == b"\x89PNG\r\n\x1a\n":
            tiff = _gbp_geo_exif_tiff(lat, lng)
            chunk = (len(tiff).to_bytes(4, "big") + b"eXIf" + tiff
                     + (zlib.crc32(b"eXIf" + tiff) & 0xFFFFFFFF).to_bytes(4, "big"))
            # Een bestaande eXIf-chunk vervalt, net als het Exif-APP1 hierboven. Zonder dat
            # kreeg een PNG er bij elke ronde één bij, en dat gebeurt echt: de upload tagt
            # en de GBP-route tagt bij het serveren nog een keer. De PNG-spec staat er
            # hoogstens één toe en lezers pakken willekeurig de eerste of de laatste
            # (27-08-2026, aan het licht gekomen door het script twee keer te draaien).
            uit, i, n = bytearray(data[:8]), 8, len(data)
            ingevoegd = compleet = False
            while i + 12 <= n:
                lengte = int.from_bytes(data[i:i + 4], "big")
                einde = i + 12 + lengte
                if einde > n:
                    return None            # kapotte chunk-keten: liever niets doen
                soort = data[i + 4:i + 8]
                if soort != b"eXIf":
                    uit += data[i:einde]
                    if soort == b"IHDR":   # de eXIf-chunk hoort vóór de beelddata
                        uit += chunk
                        ingevoegd = True
                if soort == b"IEND":
                    compleet = True
                i = einde
            # Rommel ná IEND komt voor en mag blijven; een bestand dat IEND helemaal niet
            # haalt is afgekapt, en daar blijven we vanaf.
            uit += data[i:]
            return bytes(uit) if (ingevoegd and compleet) else None
    except Exception:
        return None
    return None


def _gbp_media_source_url(url: str) -> str:
    """Absolute foto-URL voor een Google-post — via onze geotag-route als dat kan,
    zodat de foto met EXIF-coördinaten van de vestiging bij Google aankomt (lokale
    SEO). Kan het niet (geen coördinaten, geen jpg/png), dan gewoon de directe URL."""
    mu = _gbp_photo_url(url)  # webp -> jpg/png-twin
    if mu.startswith("/"):
        mu = _public_base() + mu
    try:
        base = _public_base()
        if ("/api/gbp/foto" not in mu and base.startswith("http")
                and mu.lower().split("?")[0].endswith((".jpg", ".jpeg", ".png"))
                and _gbp_latlng()):
            return base + "/api/gbp/foto?src=" + urllib.parse.quote(mu, safe="")
    except Exception:
        pass
    return mu


@app.route("/api/gbp/foto")
@app.route("/api/gbp/foto/")
def api_gbp_foto():
    """Publiek (Google haalt de postfoto hier op): serveert een foto uit de eigen
    mediabibliotheek met EXIF-GPS-coördinaten van de vestiging (lokale SEO).

    Twee harde regels: dit is GEEN open proxy (alleen bibliotheek-foto's), en falen
    is voor Google onzichtbaar — alles wat niet te taggen valt wordt een 302 naar
    het origineel, zodat een post nooit zonder foto komt te zitten."""
    src = (request.args.get("src") or "").strip()
    if not src:
        return jsonify({"ok": False, "error": "src ontbreekt"}), 400
    toegestaan = set()
    try:
        for m in list_media():
            if isinstance(m, dict) and m.get("url"):
                u = m["url"]
                toegestaan.add(u)
                if u.startswith("/"):
                    toegestaan.add(_public_base() + u)
    except Exception:
        pass
    if src not in toegestaan:
        return jsonify({"ok": False, "error": "Onbekende foto"}), 404
    try:
        ll = _gbp_latlng()
    except Exception:
        ll = None
    if not ll:
        return redirect(src, 302)
    try:
        req = urllib.request.Request(src, headers={"User-Agent": "Mozilla/5.0 (MHS-CMS geotag)"})
        with urllib.request.urlopen(req, timeout=10) as r:
            data = r.read(3_800_000 + 1)
        if len(data) > 3_800_000:
            return redirect(src, 302)   # te groot voor de serverless-respons
        getagd = _gbp_geo_tag_image(data, ll[0], ll[1])
        if not getagd:
            return redirect(src, 302)
        resp = make_response(getagd)
        resp.headers["Content-Type"] = ("image/png" if getagd[:8] == b"\x89PNG\r\n\x1a\n"
                                        else "image/jpeg")
        resp.headers["Cache-Control"] = "public, max-age=86400"
        return resp
    except Exception:
        return redirect(src, 302)


def _gbp_build_localpost_body(d: dict) -> dict:
    """Bouw de Google localPost-body uit een post-dict (zelfde velden als /api/gbp/posts POST)."""
    summary = (d.get("summary") or "").strip()
    topic = (d.get("topic_type") or "STANDARD").upper()
    body = {"languageCode": "nl", "topicType": topic}
    if summary:
        body["summary"] = summary
    if d.get("media_url"):
        body["media"] = [{"mediaFormat": "PHOTO", "sourceUrl": _gbp_media_source_url(d["media_url"])}]
    if topic in ("EVENT", "OFFER"):
        def _pd(s):
            try:
                y, m, da = str(s).split("-"); return {"year": int(y), "month": int(m), "day": int(da)}
            except Exception:
                return None
        def _pt(s):
            try:
                h, mi = str(s).split(":")[:2]; return {"hours": int(h), "minutes": int(mi)}
            except Exception:
                return None
        ev_body = {"title": (d.get("event_title") or summary[:58] or "Aanbieding")}
        sched = {}
        if _pd(d.get("start_date")): sched["startDate"] = _pd(d.get("start_date"))
        if _pd(d.get("end_date")): sched["endDate"] = _pd(d.get("end_date"))
        if _pt(d.get("start_time")): sched["startTime"] = _pt(d.get("start_time"))
        if _pt(d.get("end_time")): sched["endTime"] = _pt(d.get("end_time"))
        if sched: ev_body["schedule"] = sched
        body["event"] = ev_body
        if topic == "OFFER":
            offer = {}
            if d.get("coupon_code"): offer["couponCode"] = d["coupon_code"]
            if d.get("redeem_url"): offer["redeemOnlineUrl"] = d["redeem_url"]
            if d.get("terms"): offer["termsConditions"] = d["terms"]
            if offer: body["offer"] = offer
    if topic != "OFFER" and d.get("cta_url"):
        body["callToAction"] = {"actionType": d.get("cta_type", "LEARN_MORE"),
                                "url": _gbp_utm_url(d["cta_url"], d.get("id") or "post")}
    return body


def _gbp_publish_post(acc_full: str, loc_full: str, d: dict):
    """Plaats één localPost naar Google. Returns (ok: bool, result_dict_or_error_str)."""
    acc = (acc_full or "").split("/")[-1]
    loc = (loc_full or "").split("/")[-1]
    if not acc or not loc:
        return False, "Geen vestiging gekoppeld"
    tok = google_access_token("google_business")
    if not tok:
        return False, "Niet verbonden met Google"
    base = f"https://mybusiness.googleapis.com/v4/accounts/{acc}/locations/{loc}/localPosts"
    try:
        req = urllib.request.Request(
            base, data=json.dumps(_gbp_build_localpost_body(d)).encode(),
            headers={"Authorization": "Bearer " + tok, "Content-Type": "application/json"}, method="POST")
        with urllib.request.urlopen(req, timeout=25) as r:
            res = json.loads(r.read() or b"{}")
        return True, {"name": res.get("name", ""), "state": res.get("state", "")}
    except urllib.error.HTTPError as e:
        return False, f"{e.code}: " + e.read().decode("utf-8", "replace")[:300]
    except Exception as e:
        return False, str(e)


def gbp_get_strategy() -> dict:
    s = kv_get("gbp:strategy") or {}
    return {
        "active": bool(s.get("active", False)),
        "post_count_per_month": int(s.get("post_count_per_month", 4) or 4),
        "themes": s.get("themes") or ["voor-en-na", "tip", "aanbod", "seizoen"],
        "tone": s.get("tone") or "vlot en lokaal",
        "cta_url": s.get("cta_url") or "",
        "auto_approve": bool(s.get("auto_approve", False)),
    }


def gbp_get_queue() -> list:
    return kv_get("gbp:queue", []) or []


def gbp_save_queue(items: list) -> None:
    kv_set("gbp:queue", items)


def _gbp_generate_proposals(n: int, strategy: dict) -> list:
    """Genereer n post-voorstellen met AI. Returns lijst post-dicts (zonder status/datum)."""
    if not _ai_configured():
        return []
    allmedia = _gbp_filter_fotokwaliteit(_ai_context_media(40))
    # Niet filteren op wat de bibliotheek toevallig bevat, maar op wat Google accepteert
    # NA omzetting: een webp-bibliotheek leverde hier anders een lege lijst op en dus
    # posts zonder beeld. De omgezette URL gaat mee de prompt in, zodat de keuze van de
    # AI en de foto in de post gegarandeerd hetzelfde bestand zijn.
    imgs = []
    for _m in allmedia:
        _u = _gbp_photo_url(_m.get("url") or "")
        if _u.lower().endswith((".jpg", ".jpeg", ".png")):
            imgs.append({**_m, "url": _u})
        if len(imgs) >= 20:
            break
    # Vangnet óók alleen jpg/png: GBP weigert webp, en een geweigerde foto is erger dan een andere foto.
    fallback_imgs = [m["url"] for m in imgs if m.get("url")]
    if not imgs:
        # Fail loud: zonder kandidaten verschijnen posts stil zonder beeld. Eén auditregel
        # maakt dat meteen zichtbaar in plaats van maandenlang onopgemerkt.
        try:
            audit_log("gbp.generate.warn", "gbp", "Geen fotokandidaten in de mediabibliotheek — posts krijgen geen beeld")
        except Exception:
            pass
    def _imgdesc(m):
        d = (m.get("alt") or m.get("name") or "").rsplit(".", 1)[0].replace("-", " ").replace("_", " ").strip()
        return d or "foto"
    img_list = "\n".join(f"- {m['url']}  → {_imgdesc(m)}" for m in imgs if m.get("url"))
    img_urls = {m["url"] for m in imgs if m.get("url")}
    # Pagina's als mogelijke knop-bestemming (relatieve paden)
    pages = [p for p in _pages_index() if (p.get("status", "published") == "published")][:25]
    def _ppath(p): return p.get("url") or (("/" + (p.get("slug") or "").strip("/") + "/") if p.get("slug") else "/")
    page_paths = {_ppath(p) for p in pages}
    page_list = "\n".join(f"- {_ppath(p)}  ({p.get('title','')})" for p in pages)
    themes = ", ".join(strategy.get("themes") or [])
    # Vraag er twee extra. Voorstellen kunnen afvallen (lege tekst, een verzonnen
    # review-citaat, een foto die niet in de lijst stond) en dan stonden er drie in de
    # wachtrij terwijl er om vier was gevraagd. Hieronder houden we de eerste n die
    # overblijven; wat over is gooien we weg.
    vraag = min(n + 2, 12)
    try:
        bedrijf = _seo_business_context()
    except Exception:
        bedrijf = "DAM Housing (vloerenbedrijf in Culemborg en regio Rivierenland)"
    # Feitenbron mee de prompt in: de echte sitecontent + de echte reviews. Zonder die
    # context gokt het model — mét context kan het alleen nog beschrijven wat er is.
    site_ctx = _gbp_site_context()
    echte_reviews = _gbp_all_reviews()
    reviews_ctx = _gbp_reviews_context()
    focus_ctx = _gbp_seo_focus()
    system = (
        f"Je bent contentstrateeg voor {bedrijf}. "
        f"Schrijf {vraag} gevarieerde Google Bedrijfsprofiel-posts ({strategy.get('tone', 'vlot en lokaal')}), elk ~40-80 "
        f"woorden, verdeeld over thema's: {themes}.\n"
        "Schrijfstijl (verplicht): natuurlijk, concreet Nederlands zoals een vakman het zelf zou zeggen; varieer "
        "zinslengte; geen holle clichés ('essentieel', 'naadloos', 'cruciaal', 'Ontdek', 'of u nu ... of ...', "
        "'niet alleen ... maar ook'); geen Title Case. Gebruik geen emoji. Gebruik geen em- of en-dashes "
        "(— of –): schrijf met een komma of punt. Geen hashtags.\n"
        "Blijf bij de feiten uit de meegegeven site-informatie en reviews: verzin NOOIT prijzen, acties, "
        "garanties, projecten, cijfers of ervaringen die daar niet staan.\n"
        "Schrijf alle posts in het Nederlands.\n"
        'Je mag één post over een echte klantreview maken (bv. een review van de maand; geef die theme "review"), '
        "maar UITSLUITEND met een letterlijk, woordelijk citaat uit de meegegeven reviews, met de echte naam erbij. "
        "Neem het citaat over in de taal waarin de klant het schreef (een Engels origineel mag dus Engels blijven); "
        "de tekst eromheen blijft Nederlands. "
        "Verzin NOOIT een review of citaat; is er geen passende echte review, maak dan geen review-post.\n"
        "Kies per post de foto die INHOUDELIJK het beste bij het onderwerp past: lees de omschrijving achter de pijl (→) "
        "en matche die op het thema/de dienst van de post (bv. een post over een pvc-vloer → een foto van een gelegde vloer, trappenrenovatie → trapfoto). "
        "Gebruik de URL EXACT zoals in de lijst en gebruik niet twee keer dezelfde foto als het kan.\n"
        "Kies per post de meest relevante knop-bestemming: een pad uit de paginalijst (bv. de dienst die in de post "
        "genoemd wordt). Laat 'link' leeg als de homepage logischer is.\n"
        "Krijg je een blok 'waar de site deze maand aan werkt', laat dan het merendeel van de posts "
        "daarop aansluiten (zelfde dienst, plaats of onderwerp) en kies de genoemde doelpagina als knop-link.\n"
        'Antwoord UITSLUITEND met JSON: {"posts":[{"text":"...","image":"<exacte foto-URL>",'
        '"button":true,"button_type":"LEARN_MORE|BOOK|CALL","link":"<pad uit lijst of leeg>","theme":"..."}, ...]} '
        "met precies " + str(vraag) + " posts.")
    user = ("Genereer de maandelijkse posts."
            + (f"\n\nWaar de site deze maand aan werkt (sluit het merendeel van de posts hierop aan):\n{focus_ctx}" if focus_ctx else "")
            + (f"\n\nOver het bedrijf en de site (feitenbron):\n{site_ctx}" if site_ctx else "")
            + (f"\n\nEchte klantreviews (alleen hieruit letterlijk citeren):\n{reviews_ctx}" if reviews_ctx else "")
            + ("\n\nFoto's (formaat: URL → omschrijving — kies per post de inhoudelijk best passende):\n" + img_list if img_list else "")
            + ("\n\nPagina's voor de knop-link:\n" + page_list if page_list else ""))
    # Haiku (snel) + tokens geschaald op het aantal posts; tolerante JSON-parse.
    r = _anthropic_call([{"role": "user", "content": user}], system=system,
                        max_tokens=min(8000, max(2400, vraag * 170)), model="claude-haiku-4-5-20251001")
    if r.get("error"):
        return []
    txt = "".join(b.get("text", "") for b in r.get("content", []))
    posts = (_loads_lenient(txt) or {}).get("posts") or []
    base = _public_base()
    home_cta = strategy.get("cta_url") or (base + "/")
    out = []
    for i, p in enumerate(posts):
        if len(out) >= n:
            break
        tekst = _gbp_clean_ai_text((p.get("text") or "").strip())
        if not tekst:
            continue
        theme = (p.get("theme") or "").strip()
        if theme.lower().startswith("review") and not _gbp_is_echt_citaat(tekst, echte_reviews):
            # Nepreview: NOOIT doorlaten. Liever een post minder dan een verzonnen
            # klantuitspraak op het profiel (harde eis, geen stijlkeuze).
            try:
                audit_log("gbp.generate.drop", "gbp", "Review-post zonder echt citaat weggegooid")
            except Exception:
                pass
            continue
        image = p.get("image") or ""
        if image and image not in img_urls:
            image = ""
        if not image and fallback_imgs:                       # ALTIJD een foto
            image = fallback_imgs[i % len(fallback_imgs)]
        link = (p.get("link") or "").strip()
        if link and not link.startswith("/"):
            link = "/" + link
        if link and not link.endswith("/") and "." not in link.rsplit("/", 1)[-1]:
            link += "/"
        cta_url = (base + link) if (link and link in page_paths) else home_cta
        out.append({
            "summary": tekst,
            "topic_type": "STANDARD",
            "media_url": image,
            "cta_type": p.get("button_type") or "LEARN_MORE",
            "cta_url": cta_url,
            "theme": theme,
        })
    return [o for o in out if o["summary"]]


def _gbp_enqueue_monthly(strategy: dict, auto: bool = False, force_schedule: bool = False, months: int = 1) -> int:
    """Genereer voorstellen + plaats in de queue, verspreid over `months` maanden (1-12). Returns aantal toegevoegd.
    force_schedule=True -> direct ingepland (1-klik 'Strategie uitvoeren'), anders 'draft' (review-first)."""
    n = max(1, min(12, int(strategy.get("post_count_per_month", 4))))
    try:
        months = max(1, min(12, int(months)))
    except Exception:
        months = 1
    total = min(n * months, 48)  # plafond i.v.m. serverless-tijdslimiet
    proposals = _gbp_generate_proposals(total, strategy)
    if not proposals:
        return 0
    q = gbp_get_queue()
    now = datetime.now()
    span_days = months * 30
    interval = max(1, span_days // len(proposals))
    status = "scheduled" if (force_schedule or (auto and strategy.get("auto_approve"))) else "draft"
    for i, p in enumerate(proposals):
        sched = (now + timedelta(days=(i + 1) * interval)).replace(hour=10, minute=0, second=0, microsecond=0)
        p.update({
            "id": uuid.uuid4().hex[:12],
            "status": status,
            "scheduled_at": sched.isoformat(timespec="seconds"),
            "created_by": "ai",
            "created_at": _now_iso(),
        })
        q.append(p)
    gbp_save_queue(q)
    return len(proposals)


@app.route("/api/gbp/strategy", methods=["GET", "POST"])
def api_gbp_strategy():
    if request.method == "GET":
        # Lezen mag een klant met het gbp_strategie-recht; wijzigen alleen het bureau.
        g = _require_perm("gbp_strategie")
        if g: return g
        return jsonify({"ok": True, "strategy": gbp_get_strategy()})
    a = _require_agency()
    if a: return a
    d = request.get_json(silent=True) or {}
    cur = gbp_get_strategy()
    for k in ("active", "auto_approve"):
        if k in d: cur[k] = bool(d[k])
    if "post_count_per_month" in d:
        try: cur["post_count_per_month"] = max(1, min(12, int(d["post_count_per_month"])))
        except Exception: pass
    if isinstance(d.get("themes"), list):
        cur["themes"] = [str(t).strip() for t in d["themes"] if str(t).strip()][:10]
    if "tone" in d: cur["tone"] = str(d["tone"])[:120]
    if "cta_url" in d: cur["cta_url"] = str(d["cta_url"])[:300]
    kv_set("gbp:strategy", cur)
    audit_log("gbp.strategy.save", "gbp", "Strategie bijgewerkt")
    return jsonify({"ok": True, "strategy": cur})


@app.route("/api/gbp/strategy/generate", methods=["POST"])
def api_gbp_strategy_generate():
    a = _require_agency()
    if a: return a
    if not _ai_configured():
        return jsonify({"ok": False, "error": "Geen Claude API-key ingesteld — vul 'm in bij Instellingen → Integraties → Claude (Anthropic)."}), 503
    _b = request.get_json(silent=True) or {}
