    a = _auth_or_401()
    if a: return a
    if not _ai_configured():
        return jsonify({"ok": False, "error": "Geen Claude API-key ingesteld — vul 'm in bij Instellingen → Integraties → Claude (Anthropic)."}), 503
    d = request.get_json(silent=True) or {}
