# ==================== REVIEWS AUTOMATISCH BEANTWOORDEN ====================
# Instellingen in KV gbp:autoreply (aan/uit, sterren-selectie, wachttijd); welke review
# al beantwoord is staat in gbp:autoreply:log — het idempotentie-anker naast Google's
# eigen 'reviewReply'. Zonder dat log zou een review die Google traag doorgeeft twee
# keer een antwoord krijgen.

def gbp_get_autoreply() -> dict:
    s = kv_get("gbp:autoreply") or {}
    stars = []
    for v in (s.get("stars") or []):
        try:
            iv = int(v)
        except Exception:
            continue
        if 1 <= iv <= 5 and iv not in stars:
            stars.append(iv)
    try:
        delay = max(0, min(168, int(s.get("delay_hours", 24))))
    except Exception:
        delay = 24
    return {"active": bool(s.get("active", False)), "stars": sorted(stars) or [5], "delay_hours": delay}


def _gbp_autoreply_tick() -> dict:
    """Beantwoord nieuwe reviews volgens de instellingen. Draait in de GBP-cron.

    Regels: alleen sterren uit de ingestelde lijst, pas ná de wachttijd, nooit een
    review die al een antwoord heeft (van Google of uit ons log), en max 5 per tick
    (quota + serverless-tijd). Een fout wordt gelogd maar NIET als afgehandeld
    gemarkeerd, zodat een volgende tick het opnieuw probeert — tot 3 mislukkingen,
    daarna laten we de review met rust (handmatig oplosbaar in de admin)."""
    cfg = gbp_get_autoreply()
    uit = {"active": cfg["active"], "checked": 0, "replied": 0, "skipped": 0, "failed": 0}
    if not cfg["active"] or not _ai_configured():
        return uit
    gb = get_settings().get("google_business") or {}
    acc, loc = (gb.get("account") or ""), (gb.get("location") or "")
    if not acc or not loc:
        return uit
    reviews = _gbp_all_reviews(force=True)
    if not reviews:
        return uit
    log = kv_get("gbp:autoreply:log", []) or []
    klaar = {e.get("review_id") for e in log if isinstance(e, dict) and e.get("ok")}
    mislukt_vaak = {}
    for e in log:
        if isinstance(e, dict) and not e.get("ok") and e.get("review_id"):
            mislukt_vaak[e["review_id"]] = mislukt_vaak.get(e["review_id"], 0) + 1
    drempel = datetime.now(timezone.utc) - timedelta(hours=cfg["delay_hours"])
    nieuw_log = []
    for rv in reviews:
        rid = rv.get("id") or ""
        uit["checked"] += 1
        if not rid or rv.get("reply") or rid in klaar or mislukt_vaak.get(rid, 0) >= 3:
            uit["skipped"] += 1
            continue
        if rv.get("stars") not in cfg["stars"]:
            uit["skipped"] += 1
            continue
        t = _gbp_parse_time(rv.get("time"))
        if t is None or t > drempel:
            uit["skipped"] += 1      # nog binnen de wachttijd (of onleesbare tijd: liever wachten)
            continue
        if uit["replied"] >= 5:
            uit["skipped"] += 1
            continue
        tekst, fout = _gbp_ai_review_reply_text(rv.get("author", ""), rv.get("comment", ""), rv.get("stars"))
        if fout or not (tekst or "").strip():
            uit["failed"] += 1
            nieuw_log.append({"review_id": rid, "author": rv.get("author", ""), "stars": rv.get("stars", 0),
                              "at": _now_iso(), "ok": False, "error": (fout or "lege AI-tekst")[:200], "reply_text": ""})
            continue
        ok, fout2 = _gbp_reply(acc, loc, rid, tekst)
        if ok:
            uit["replied"] += 1
        else:
            uit["failed"] += 1
        nieuw_log.append({"review_id": rid, "author": rv.get("author", ""), "stars": rv.get("stars", 0),
                          "at": _now_iso(), "ok": bool(ok), "error": None if ok else str(fout2)[:200],
                          "reply_text": tekst[:300] if ok else ""})
    if nieuw_log:
        kv_set("gbp:autoreply:log", (nieuw_log + log)[:300])
    return uit


def _gbp_autoreply_pending(cfg: dict = None, log: list = None) -> list:
    """Onbeantwoorde reviews binnen de sterren-selectie — de werkvoorraad voor de
    handmatige goedkeur-knop. De wachttijd geldt hier bewust NIET: wie de knop
    gebruikt beslist zelf en hoeft nergens op te wachten. Leest de (12u-gecachete)
    reviewlijst, dus dit kost geen extra Google-quota per pagina-load."""
    cfg = cfg or gbp_get_autoreply()
    if log is None:
        log = kv_get("gbp:autoreply:log", []) or []
    klaar = {e.get("review_id") for e in log if isinstance(e, dict) and e.get("ok")}
    uit = []
    for rv in _gbp_all_reviews():
        rid = rv.get("id") or ""
        if not rid or rv.get("reply") or rid in klaar:
            continue
        if rv.get("stars") not in cfg["stars"]:
            continue
        uit.append({"id": rid, "author": rv.get("author", ""), "stars": rv.get("stars", 0),
                    "comment": rv.get("comment", ""), "time": rv.get("time", "")})
        if len(uit) >= 20:
            break
    return uit


@app.route("/api/gbp/autoreply", methods=["GET", "POST"])
def api_gbp_autoreply():
    if request.method == "GET":
        g = _require_perm("gbp")
        if g:
            return g
        cfg = gbp_get_autoreply()
        log = kv_get("gbp:autoreply:log", []) or []
        uit = {"ok": True, "autoreply": cfg, "log": log[:20]}
        if current_role() == "agency":
            # De wachtrij (+ goedkeur-knop) is bureauwerk; de klant kijkt alleen mee.
            try:
                uit["pending"] = _gbp_autoreply_pending(cfg, log)
            except Exception:
                uit["pending"] = []
        return jsonify(uit)
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    cur = kv_get("gbp:autoreply") or {}
    for k in ("active", "stars", "delay_hours"):
        if k in d:
            cur[k] = d[k]
    kv_set("gbp:autoreply", cur)
    cfg = gbp_get_autoreply()
    kv_set("gbp:autoreply", cfg)   # genormaliseerd terugschrijven
    audit_log("gbp.autoreply.save", "gbp",
              f"actief={cfg['active']} sterren={','.join(map(str, cfg['stars']))} wachttijd={cfg['delay_hours']}u")
    return jsonify({"ok": True, "autoreply": cfg})


@app.route("/api/gbp/autoreply/run", methods=["POST"])
@app.route("/api/gbp/autoreply/run/", methods=["POST"])
def api_gbp_autoreply_run():
    """Plaats de in de popup goedgekeurde (en eventueel bijgewerkte) reacties.

    Zelfde schoonmaak en hetzelfde log als de automatische tick, zodat de wachtrij
    en 'laatst geplaatste reacties' meteen kloppen. Hooguit 8 per verzoek — een
    grote achterstand post de admin in porties, anders loopt één verzoek tegen de
    serverless-tijdslimiet aan."""
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    items = d.get("items") or []
    if not isinstance(items, list) or not items:
        return jsonify({"ok": False, "error": "Geen reacties om te plaatsen"}), 400
    gb = get_settings().get("google_business") or {}
    acc, loc = (gb.get("account") or ""), (gb.get("location") or "")
    if not acc or not loc:
        return jsonify({"ok": False, "error": "Geen vestiging gekoppeld"}), 400
    per_review = {}
    try:
        per_review = {rv.get("id"): rv for rv in _gbp_all_reviews()}
    except Exception:
        pass
    log = kv_get("gbp:autoreply:log", []) or []
    klaar = {e.get("review_id") for e in log if isinstance(e, dict) and e.get("ok")}
    resultaten, nieuw_log = [], []
    geplaatst = mislukt = 0
    for it in items[:8]:
        rid = str((it or {}).get("review_id") or "").strip()
        tekst = _gbp_clean_ai_text(((it or {}).get("comment") or "").strip())
        if not rid or not tekst:
            resultaten.append({"review_id": rid, "ok": False, "error": "Ontbrekende gegevens"})
            mislukt += 1
            continue
        if rid in klaar:
            resultaten.append({"review_id": rid, "ok": False, "error": "Al beantwoord"})
            continue
        rv = per_review.get(rid) or {}
        ok, fout = _gbp_reply(acc, loc, rid, tekst)
        if ok:
            geplaatst += 1
        else:
            mislukt += 1
        resultaten.append({"review_id": rid, "ok": bool(ok), "error": None if ok else str(fout)[:200]})
        nieuw_log.append({"review_id": rid, "author": rv.get("author", ""),
                          "stars": rv.get("stars", 0), "at": _now_iso(), "ok": bool(ok),
                          "error": None if ok else str(fout)[:200],
                          "reply_text": tekst[:300] if ok else ""})
    if nieuw_log:
        kv_set("gbp:autoreply:log", (nieuw_log + log)[:300])
    if geplaatst:
        # Cache verversen zodat de wachtrij (en het reviews-overzicht) meteen klopt.
        try:
            _gbp_all_reviews(force=True)
        except Exception:
            pass
    audit_log("gbp.autoreply.run", "gbp", f"{geplaatst} geplaatst, {mislukt} mislukt")
    return jsonify({"ok": mislukt == 0, "placed": geplaatst, "failed": mislukt,
                    "results": resultaten, "pending": _gbp_autoreply_pending()})


# ==================== GOOGLE CALENDAR ====================
@app.route("/api/calendar/events")
def api_calendar_events():
    a = _require_perm("agenda")
    if a:
        return a
    today = datetime.now()
    frm = request.args.get("from") or today.replace(day=1).strftime("%Y-%m-%d")
    to = request.args.get("to") or (today.replace(day=28) + timedelta(days=10)).strftime("%Y-%m-%d")
    events = []
    # 1) Lead-meetings (lokaal, werkt altijd)
    for l in get_leads():
        for m in (l.get("meetings") or []):
            d = m.get("date", "")
            if d and frm <= d <= to:
                events.append({"title": (m.get("title") or "Afspraak") + " — " + (l.get("name") or ""),
                               "date": d, "time": m.get("time", ""), "source": "lead",
                               "lead_id": l.get("id"), "notes": m.get("notes", "")})
    # 2) Google Calendar (indien gekoppeld)
    gerr = ""
    # Geen fallback op de oude gedeelde token: de agenda toont alleen Google-events
    # als Calendar expliciet gekoppeld is (consistent met de instellingen-status).
    tok = google_access_token("calendar", fallback=False)
    if tok:
        try:
            url = ("https://www.googleapis.com/calendar/v3/calendars/primary/events"
                   f"?singleEvents=true&orderBy=startTime&maxResults=250"
                   f"&timeMin={frm}T00:00:00Z&timeMax={to}T23:59:59Z")
            req = urllib.request.Request(url, headers={"Authorization": "Bearer " + tok})
            with urllib.request.urlopen(req, timeout=20) as r:
                data = json.loads(r.read() or b"{}")
            for it in (data.get("items") or []):
                st = it.get("start", {})
                dt = st.get("dateTime", "") or st.get("date", "")
                events.append({"title": it.get("summary", "(geen titel)"),
                               "date": dt[:10], "time": (dt[11:16] if "T" in dt else ""),
                               "source": "google", "location": it.get("location", ""),
                               "html_link": it.get("htmlLink", "")})
        except urllib.error.HTTPError as e:
            gerr = f"Google Calendar {e.code}: {e.read().decode('utf-8', 'replace')[:200]}"
        except Exception as e:
            gerr = str(e)
    events.sort(key=lambda x: (x.get("date", ""), x.get("time", "")))
    return jsonify({"ok": True, "events": events, "google_connected": bool(tok), "google_error": gerr})


# ==================== GMAIL INBOX ====================
def _gmail_get(path):
    tok = google_access_token("gmail")
    if not tok:
        return None, "Niet (meer) verbonden met Google — koppel Gmail opnieuw."
    try:
        req = urllib.request.Request("https://gmail.googleapis.com/gmail/v1/users/me/" + path,
                                     headers={"Authorization": "Bearer " + tok})
        with urllib.request.urlopen(req, timeout=20) as r:
            return json.loads(r.read() or b"{}"), None
    except urllib.error.HTTPError as e:
        return None, f"Gmail API {e.code}: {e.read().decode('utf-8', 'replace')[:250]}"
    except Exception as e:
        return None, str(e)


@app.route("/api/gmail/signature", methods=["GET"])
def api_gmail_signature():
    """Haalt de custom Gmail-handtekening op (uit users.settings.sendAs) en slaat 'm op
    als e-mailhandtekening. Vereist de scope gmail.settings.basic (Gmail opnieuw koppelen)."""
    a = _auth_or_401()
    if a: return a
    data, err = _gmail_get("settings/sendAs")
    if err:
        return jsonify({"ok": False, "error": err}), 400
    sends = data.get("sendAs") or []
    s = get_settings()
    prefer = [(s.get("smtp", {}).get("from_email") or "").lower(),
              (s.get("company_email") or "").lower()]
    sig = ""
    for addr in prefer:
        for sa in sends:
            if addr and sa.get("sendAsEmail", "").lower() == addr and (sa.get("signature") or "").strip():
                sig = sa["signature"]; break
        if sig: break
    if not sig:
        for sa in sends:
            if sa.get("isDefault") and (sa.get("signature") or "").strip():
                sig = sa["signature"]; break
    if not sig:
        for sa in sends:
            if (sa.get("signature") or "").strip():
                sig = sa["signature"]; break
    if not sig:
        return jsonify({"ok": False, "error": "Geen handtekening gevonden in Gmail voor dit account."}), 404
    existing = kv_get("settings", {}) or {}
    existing["email_signature"] = sig
    kv_set("settings", existing)
    return jsonify({"ok": True, "signature": sig})


def _hdr(headers, name):
    for h in (headers or []):
        if h.get("name", "").lower() == name.lower():
            return h.get("value", "")
    return ""


def _gmail_body(payload):
    """Recursief de tekst/HTML body uit een Gmail payload halen."""
    import base64
    def dec(data):
        try:
            return base64.urlsafe_b64decode(data + "===").decode("utf-8", "replace")
        except Exception:
            return ""
    mime = payload.get("mimeType", "")
    body = payload.get("body", {})
    if body.get("data"):
        return dec(body["data"]), ("html" if "html" in mime else "text")
    html = text = ""
    for part in (payload.get("parts") or []):
        b, kind = _gmail_body(part)
        if kind == "html" and not html:
            html = b
        elif kind == "text" and not text:
            text = b
    return (html, "html") if html else (text, "text")


@app.route("/api/gmail/messages")
def api_gmail_messages():
    a = _auth_or_401()
    if a:
        return a
    box = request.args.get("box", "inbox")
    label = "SENT" if box == "sent" else "INBOX"
    lst, err = _gmail_get(f"messages?maxResults=25&labelIds={label}")
    if err:
        return jsonify({"ok": False, "error": err}), 400
    out = []
    for mref in (lst.get("messages") or [])[:25]:
        msg, merr = _gmail_get(f"messages/{mref['id']}?format=metadata&metadataHeaders=From&metadataHeaders=To&metadataHeaders=Subject&metadataHeaders=Date")
        if merr or not msg:
            continue
        hs = (msg.get("payload") or {}).get("headers", [])
        out.append({"id": msg.get("id"), "threadId": msg.get("threadId"),
                    "from": _hdr(hs, "From"), "to": _hdr(hs, "To"),
                    "subject": _hdr(hs, "Subject"), "date": _hdr(hs, "Date"),
                    "snippet": msg.get("snippet", ""),
                    "unread": "UNREAD" in (msg.get("labelIds") or [])})
    return jsonify({"ok": True, "messages": out})


@app.route("/api/gmail/message/<mid>")
def api_gmail_message(mid):
    a = _auth_or_401()
    if a:
        return a
    msg, err = _gmail_get(f"messages/{mid}?format=full")
    if err:
        return jsonify({"ok": False, "error": err}), 400
    payload = msg.get("payload") or {}
    hs = payload.get("headers", [])
    body, kind = _gmail_body(payload)
    # markeer als gelezen
    try:
        tok = google_access_token("gmail")
        req = urllib.request.Request(f"https://gmail.googleapis.com/gmail/v1/users/me/messages/{mid}/modify",
                                     data=json.dumps({"removeLabelIds": ["UNREAD"]}).encode(),
                                     headers={"Authorization": "Bearer " + tok, "Content-Type": "application/json"}, method="POST")
        urllib.request.urlopen(req, timeout=10).read()
    except Exception:
        pass
    return jsonify({"ok": True, "message": {"id": mid, "threadId": msg.get("threadId"),
                    "from": _hdr(hs, "From"), "to": _hdr(hs, "To"), "subject": _hdr(hs, "Subject"),
                    "date": _hdr(hs, "Date"), "body": body, "kind": kind}})


@app.route("/api/gmail/send", methods=["POST"])
def api_gmail_send():
    a = _auth_or_401()
    if a:
        return a
    import base64
    tok = google_access_token("gmail")
    if not tok:
        return jsonify({"ok": False, "error": "Niet verbonden met Gmail"}), 400
    d = request.get_json(silent=True) or {}
    to = (d.get("to") or "").strip()
    subject = (d.get("subject") or "").strip()
    body = d.get("body") or ""
    if not to or not body:
        return jsonify({"ok": False, "error": "Ontvanger en bericht verplicht"}), 400
    headers = [f"To: {to}", f"Subject: {subject}", "Content-Type: text/html; charset=UTF-8"]
    payload = {}
    if d.get("thread_id"):
        payload["threadId"] = d["thread_id"]
        if d.get("in_reply_to"):
            headers.append(f"In-Reply-To: {d['in_reply_to']}")
            headers.append(f"References: {d['in_reply_to']}")
    raw = ("\r\n".join(headers) + "\r\n\r\n" + body).encode("utf-8")
    payload["raw"] = base64.urlsafe_b64encode(raw).decode()
    try:
        req = urllib.request.Request("https://gmail.googleapis.com/gmail/v1/users/me/messages/send",
                                     data=json.dumps(payload).encode(),
                                     headers={"Authorization": "Bearer " + tok, "Content-Type": "application/json"}, method="POST")
        with urllib.request.urlopen(req, timeout=20):
            pass
        return jsonify({"ok": True})
    except urllib.error.HTTPError as e:
        return jsonify({"ok": False, "error": f"{e.code}: {e.read().decode('utf-8', 'replace')[:250]}"}), 400
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 400


