def formatDate_py(iso: str) -> str:
    try:
        return datetime.fromisoformat(iso).strftime("%d-%m-%Y %H:%M")
    except Exception:
        return (iso or "")[:16].replace("T", " ")


def _seo_notify_pending() -> None:
    """Gedebouncede melding (max 1x/6u) dat er nieuwe concepten klaarstaan ter goedkeuring.
    Review-first is waardeloos als niemand wéét dat er iets te reviewen is — de cron draait dagelijks."""
    items = _seo_pending()
    if not items:
        return
    last = kv_get("seo:pending_notify_at", "") or ""
    try:
        if last and (datetime.now() - datetime.fromisoformat(last)).total_seconds() < 6 * 3600:
            return
    except Exception:
        pass
    base = _public_base() or CANONICAL_BASE
    n = len(items)
    html = (f'<div style="font-family:Poppins,Arial,sans-serif;color:#1d1d1b">'
            f'<p>Er staan <b>{n}</b> SEO-concept(en) klaar ter goedkeuring.</p>'
            f'<p><a href="{base}/admin/#seo" style="color:#f07d22">Bekijk &amp; keur goed in het dashboard &rarr;</a></p></div>')
    try:
        send_email(SEO_AUTO_REPORT_TO, f'{n} SEO-concept(en) ter goedkeuring', html,
                   content_type="html", from_name="DAM Housing SEO-motor")
        kv_set("seo:pending_notify_at", _now_iso())
    except Exception:
        pass


def _seo_opportunities(force: bool = False) -> list:
    """F1: 'Bijna-winnaars' — GSC-queries op positie 5-15 gekoppeld aan hun sterkste pagina,
    gesorteerd op klik-potentie. 24u gecachet; leeg zonder Search Console.

    Sinds 2026-08-24 gekeurd vóór ze op het scherm komen: ruwe GSC-queries bevatten
    naamfragmenten ("wit"), typefouten ("witt") en persoonsnamen — nutteloze kansen.
    Merk- en onbekende losse termen gaan er deterministisch uit; de rest krijgt SE
    Ranking-cijfers (volume/moeilijkheid/intentie) en een gecachet AI-oordeel. De
    keuring draait alleen in dit herbouw-pad (1x/24u, of direct na een versie-bump)."""
    cache = kv_get("seo:opportunities")
    if (not force and isinstance(cache, dict)
            and cache.get("v") == OPP_KEURING_VERSIE
            and (time.time() - float(cache.get("t", 0) or 0)) < 86400):
        return cache.get("items", []) or []
    gsc = _seo_gsc_signals(days=60)
    items = []
    if gsc.get("connected"):
        qmap = {}
        for path, info in (_seo_page_queries(days=60) or {}).items():
            for q in (info.get("top_queries") or []):
                # top_queries zijn strings (of oudere dict-vorm) — beide accepteren
                key = (q.get("query", "") if isinstance(q, dict) else str(q)).lower().strip()
                imp = int((q.get("impressions", 0) if isinstance(q, dict) else 0) or 0)
                if key and (key not in qmap or imp > qmap[key][1]):
                    qmap[key] = (path, imp)
        merk = _opp_merk_tokens()
        focus_tokens = set()
        for kw in (_agent_config().get("focus_keywords") or []):
            focus_tokens |= {w for w in re.split(r"\W+", str(kw).lower()) if w}
        for s in (gsc.get("striking") or [])[:12]:
            if _opp_is_merk_query(s.get("query", ""), merk):
                continue
            path = (qmap.get(str(s.get("query", "")).lower()) or ("", 0))[0]
            pot = max(0, int(int(s.get("impressions", 0)) * 0.11) - int(s.get("clicks", 0)))
            items.append({"query": s.get("query", ""), "position": s.get("position", 0),
                          "impressions": int(s.get("impressions", 0)), "clicks": int(s.get("clicks", 0)),
                          "page": path, "potential": pot})
        # SE Ranking-cijfers als bewijs bij de kans (en als input voor het oordeel).
        try:
            cijfers = _seranking_keyword_cijfers([o["query"] for o in items])
        except Exception:
            cijfers = {}
        items = [o for o in items
                 if not _opp_is_onbekende_losse_term(o["query"], cijfers, focus_tokens)]
        for o in items:
            o.update(cijfers.get(o["query"]) or {})
        oordeel = _opp_ai_oordeel(items, cijfers)
        items = [o for o in items
                 if oordeel.get(str(o.get("query", "")).lower(), {}).get("ok", True)]
        # Zoekintentie: een echte meting (overview) wint; anders de AI-inschatting uit
        # het oordeel, eerlijk gelabeld — intentie is taalwerk, geen meetwerk.
        for o in items:
            if not o.get("intentie"):
                ai_int = oordeel.get(str(o.get("query", "")).lower(), {}).get("intentie", "")
                if ai_int:
                    o["intentie"] = ai_int
                    o["intentie_bron"] = "ai"
        items.sort(key=lambda x: x["potential"], reverse=True)
    if not items:
        # Geen Search Console (of nog geen data): val terug op de posities die SE
        # Ranking al bijhoudt. Die lijst is al gekeurd: het zijn je eigen zoekwoorden.
        items = _seranking_opportunities()
    kv_set("seo:opportunities", {"t": int(time.time()), "v": OPP_KEURING_VERSIE, "items": items})
    return items


def _seo_boost_task(o: dict) -> dict:
    return {"kind": "improve", "path": o.get("page") or "/",
            "issue": f"Bijna-winnaar: '{o.get('query', '')}' staat op positie {o.get('position', '?')} met {o.get('impressions', 0)} vertoningen",
            "action": ("Herschrijf de meta-title en -description gericht op deze zoekterm, scherp de H1 "
                       "aan en voeg een kort FAQ-blok toe met 2-3 vragen in precies deze formulering. "
                       "Behoud de bestaande stijl en lengte van de pagina."),
            "boost_query": o.get("query", ""), "status": "pending",
            "reason": f"Staat al op positie {o.get('position', '?')} voor '{o.get('query', '')}' — kleine optimalisatie kan pagina 1 halen"}


def _seo_decay_candidates() -> list:
    """F4: pagina's met >=30% klikdaling (28d vs voorgaande 28d, >=10 klikken eerst) —
    kandidaten voor een opfris-taak. Leeg zonder Search Console of bij API-fouten."""
    try:
        site = (get_settings().get("search_console") or {}).get("site", "")
        if not site:
            return []
        now = datetime.now()
        cur, e1 = _sc_query(site, (now - timedelta(days=28)).strftime("%Y-%m-%d"),
                            now.strftime("%Y-%m-%d"), ["page"], timeout=8)
        prev, e2 = _sc_query(site, (now - timedelta(days=56)).strftime("%Y-%m-%d"),
                             (now - timedelta(days=29)).strftime("%Y-%m-%d"), ["page"], timeout=8)
        if e1 or e2:
            return []

        def _m(res):
            out = {}
            for r in (res.get("rows") or []):
                try:
                    out[urllib.parse.urlparse(r["keys"][0]).path or "/"] = int(r.get("clicks", 0) or 0)
                except Exception:
                    pass
            return out

        c, p = _m(cur), _m(prev)
        out = []
        for path, prev_clicks in p.items():
            if prev_clicks >= 10 and (prev_clicks - c.get(path, 0)) / prev_clicks >= 0.3:
                out.append({"path": path, "prev": prev_clicks, "cur": c.get(path, 0)})
        out.sort(key=lambda x: x["prev"] - x["cur"], reverse=True)
        return out[:5]
    except Exception:
        return []


