@app.route("/api/seo/opportunities/apply", methods=["POST"])
@app.route("/api/seo/opportunities/apply/", methods=["POST"])
def api_seo_opportunities_apply():
    g = _require_perm("seo")
    if g:
        return g
    if not _ai_configured():
        return jsonify({"ok": False, "error": "Geen AI-koppeling actief"}), 503
    b = request.get_json(silent=True) or {}
    q = (b.get("query") or "").strip()
    items = _seo_opportunities()
    o = next((x for x in items if x.get("query") == q), None)
    if not o:
        return jsonify({"ok": False, "error": "Kans niet gevonden — ververs de lijst."}), 404
    if not o.get("page"):
        o = {**o, "page": (b.get("page") or "").strip() or "/"}
    task = _seo_boost_task(o)
    ok = _seo_do_one_task(task)
    if ok:
        kv_set("seo:opportunities", {"t": int(time.time()),
                                     "items": [x for x in items if x.get("query") != q]})
        _trigger_deploy(f"seo-boost {q[:40]}")
        audit_log("seo.boost", o.get("page", ""), f"Kans gepakt: '{q}'")
    return jsonify({"ok": ok, "error": ("" if ok else (task.get("error") or "Uitvoeren mislukt"))})


def _seo_health(alleen_cache: bool = False) -> dict:
    """De gezondheid van de site, uit de crawl van SE Ranking.

    Hier stond eerst een zelfbedachte score: meta-velden, contentdekking, versheid en
    'technische issues' met verzonnen wegingen (0.3/0.25/0.2/0.25). Die beoordeelde de
    site op zijn eigen huiswerk — alles wat het CMS niet zelf bijhoudt (redirects,
    laadtijd, dubbele titels, kapotte links) telde niet mee, en een hoge score zei dus
    vooral dat we onze eigen velden hadden ingevuld. Weg ermee (Ryan, 2026-08-15).

    Geen afgeronde crawl = geen score. Dat is eerlijker dan een getal dat nergens op
    slaat, en het kan ook: SE Ranking koppelen is een voorwaarde voordat de agent start.
    """
    try:
        audit = _seranking_audit(alleen_cache=alleen_cache)
    except Exception:
        audit = {}
    if not audit.get("score"):
        return {"score": None, "bron": "geen", "factors": [],
                "melding": "Nog geen crawl beschikbaar — koppel SE Ranking om de score te meten."}
    # Geen 'factoren' meer: elk deelcijfer dat we hier zouden tonen zouden we zelf
    # verzinnen. De echte aantallen uit de crawl staan in `audit` en zeggen meer.
    return {"score": audit["score"], "bron": "seranking", "audit": audit, "factors": []}


def _seo_month_yield() -> dict:
    """F6: opbrengst van deze maand uit eigen attributie — organische bezoeken en leads."""
    try:
        today = datetime.now()
        frm = today.replace(day=1).strftime("%Y-%m-%d")
        bd = _channel_breakdown(frm, today.strftime("%Y-%m-%d")) or {}
        rows = bd.get("channels") if isinstance(bd, dict) else None
        org = next((r for r in (rows or []) if "organisch" in str(r.get("label", r.get("channel", ""))).lower()
                    or "organic" in str(r.get("channel", "")).lower()), None)
        pv = 0
        d = today.replace(day=1)
        while d <= today:
            v = kv_get(f"stat:pv:day:{d.strftime('%Y%m%d')}", 0) or 0
            pv += int(v) if isinstance(v, int) else 0
            d += timedelta(days=1)
        return {"visits": pv, "organic_leads": int((org or {}).get("leads", 0) or 0)}
    except Exception:
        return {}


def _linkweave_pending() -> list:
    return kv_get("seo:linkweave", []) or []


def _linkweave_save(items: list) -> None:
    kv_set("seo:linkweave", items[:60])


def _linkweave_sleutel(s: dict) -> tuple:
    """Waaraan je twee suggesties als dezelfde herkent: bron, doel en anker."""
    return ((s.get("source_slug") or "").strip("/"), (s.get("target_slug") or "").strip("/"),
            (s.get("anchor") or "").strip().lower())


def _linkweave_toevoegen(nieuwe: list) -> int:
    """Nieuwe suggesties in de wachtrij zetten, zonder dubbelen. Returns het aantal erbij.

    De ontdubbeling vergeleek eerst `id`, en dat is een verse uuid per scan: hij vond dus
    nooit iets en dezelfde suggestie stapelde zich elke sweep opnieuw op. Samen met een
    voorstel dat bij toepassen bleef staan (zie `_linkweave_zoek_blok`) gaf dat het beeld
    dat afgehandeld werk vanzelf terugkomt."""
    wachtrij = _linkweave_pending()
    bekend = {_linkweave_sleutel(x) for x in wachtrij}
    verse = []
    for s in nieuwe or []:
        k = _linkweave_sleutel(s)
        if k in bekend:
            continue
        bekend.add(k)
        verse.append(s)
    if verse:
        _linkweave_save(wachtrij + verse)
    return len(verse)


# Een anker mag niet in een bestaande link landen: op deze site zet de contentgenerator
# interne links als echte HTML in de alineatekst, en de renderer maakt van [tekst](/pad/)
# alsnog een <a>. Allebei tellen dus als "hier zit al een link".
_LINKWEAVE_LINK_RE = re.compile(r"<a\b[^>]*>.*?</a>|\[[^\]]+\]\([^)\s]*\)", re.S | re.I)

# Alleen doorlopende tekst. In een kop, een USP-kaart, een quote of een CTA-balk is een
# interne link geen link in de lopende tekst maar een verminkt element.
_LINKWEAVE_GEEN_LINK = ("html-raw", "image", "hero", "service-hero", "icon-box", "testimonial",
                        "quote", "cta-banner", "stats", "service-cards", "faq-group", "steps",
                        "button", "list-ul", "list-ol")


def _linkweave_tekstblokken(rec: dict) -> list:
    """De blokken van een pagina waarin een interne link mag landen — ook de blokken die in
    een kolom-sectie genest zitten.

    Zoeken en plaatsen gebruiken allebei deze lijst, zodat de AI precies de tekst ziet die
    `_linkweave_apply` later kan bewerken. Dat liep uiteen: de tekst voor het model werd
    geplukt uit `text` van de blokken op het hoogste niveau, en op een sjabloonpagina zijn
    dat vooral de koppen — de body zelf zit in de kolommen van een 2-koloms sectie. Het
    model kreeg dus een lijstje koppen te lezen en koos daar zijn ankers uit, ondanks de
    instructie "geen koppen". Koppen doen hier daarom niet mee: een link in een <h2> is
    geen interne link maar een verminkte kop.
    """
    out = []

    def loop(blokken, diepte=0):
        if diepte > 4:
            return
        for b in blokken or []:
            if not isinstance(b, dict):
                continue
            for kolom in (b.get("children") or []):
                loop(kolom if isinstance(kolom, list) else [kolom], diepte + 1)
            t = str(b.get("type") or "").lower()
            if t.startswith("heading") or t in _LINKWEAVE_GEEN_LINK:
                continue
            if len(str(b.get("text") or "").strip()) >= 40:
                out.append(b)

    loop(rec.get("content_blocks") or [])
    return out


def _linkweave_al_gelinkt(rec: dict, href: str) -> bool:
    """Verwijst de body van deze pagina al naar dit doel? Dan levert een tweede link niets
    op, en blijven voorstellen betekent dat dezelfde rij na elke sweep terugkomt."""
    naalden = (f'href="{href}"', f"href='{href}'", "](" + href + ")")
    return any(any(n in str(b.get("text") or "") for n in naalden)
               for b in _linkweave_tekstblokken(rec))


def _linkweave_zoek_blok(rec: dict, anch: str, href: str):
    """(blok, foutmelding) — het blok waarin het anker als gewone tekst staat.

    De melding is nu wat er echt aan de hand is. "Ankertekst niet (meer) gevonden" stond
    ook onder een anker dat gewoon zichtbaar op de pagina staat maar al een link is: de
    plaatsing sloeg dat blok over en viel daarna in de verzamelfout onderaan de lus."""
    anch = (anch or "").strip()
    if not anch:
        return None, "Geen ankertekst in de suggestie"
    for b in _linkweave_tekstblokken(rec):
        t = str(b.get("text") or "")
        if anch not in t:
            continue
        if href and (f'href="{href}"' in t or ("](" + href + ")") in t):
            return None, "Deze alinea verwijst al naar die pagina"
        if any(anch in m.group(0) for m in _LINKWEAVE_LINK_RE.finditer(t)):
            return None, "Ankertekst is op die plek al een link"
        return b, ""
    try:
        elders = anch in json.dumps(rec.get("content_blocks") or [], ensure_ascii=False)
    except Exception:
        elders = False
    if elders:
        return None, "Ankertekst staat in een kop of in een blok waar geen link in past"
    return None, "Ankertekst niet (meer) gevonden in de bronpagina"


def _linkweave_generate(target_slug: str, target_title: str) -> list:
    """F2: AI kiest max 3 bestaande pagina's + een LETTERLIJK zinsdeel als anker voor een
    interne link naar de nieuwe pagina. Alleen ankers die echt in de brontekst staan."""
    if not _ai_configured():
        return []
    tw = set(re.findall(r"[a-z\u00e0-\u00ff]{4,}", (target_title or target_slug).lower()))
    cands = []
    for p in _pages_index():
        if p.get("status", "published") != "published":
            continue
        slug = (p.get("slug") or "").strip("/")
        if not slug or slug == target_slug.strip("/"):
            continue
        score = len(tw & set(re.findall(r"[a-z\u00e0-\u00ff]{4,}", (p.get("title") or "").lower())))
        cands.append((score, slug, p.get("title") or slug))
    cands.sort(reverse=True)
    # Design-vaste pagina's doen gewoon mee: `_linkweave_apply` schrijft de link daar in het
    # document dat ook echt geserveerd wordt. De oude poort las `design_locked` van het
    # record, en dat veld bestaat daar niet (het wordt pas bij het ophalen berekend) — hij
    # ging dus nooit dicht. Hem alsnog dichtzetten zou op deze site elke dienstpagina als
    # bron wegstrepen, en dat is juist waar de body staat.
    href_doel = "/" + target_slug.strip("/") + "/"
    src_ctx = []
    for _score, slug, title in cands[:6]:
        rec = _get_page(slug)
        if not rec or _linkweave_al_gelinkt(rec, href_doel):
            continue
        txt = " ".join(str(b.get("text") or "") for b in _linkweave_tekstblokken(rec))[:700]
        if len(txt) > 80:
            src_ctx.append({"slug": slug, "title": title, "text": txt})
        if len(src_ctx) >= 4:
            break
    if not src_ctx:
        return []
    system = ("Je legt interne links voor SEO. Kies uit de BRONPAGINA'S maximaal 3 waar een link naar de "
              "NIEUWE pagina natuurlijk past. Kies als ankertekst een LETTERLIJK, kort zinsdeel (3-8 woorden) "
              "dat exact zo in de brontekst staat en inhoudelijk bij de nieuwe pagina past. Geen koppen. "
              'Antwoord UITSLUITEND met geldig JSON: {"links":[{"source_slug":"...","anchor":"letterlijk zinsdeel"}]}')
    user = json.dumps({"nieuwe_pagina": {"slug": "/" + target_slug.strip("/") + "/", "titel": target_title},
                       "bronpaginas": src_ctx}, ensure_ascii=False)
    r = _anthropic_call([{"role": "user", "content": user}], system=system, max_tokens=500,
                        model="claude-haiku-4-5-20251001")
    if r.get("error"):
        return []
    data = _loads_lenient("".join(c.get("text", "") for c in (r.get("content") or [])))
    out, by_slug = [], {s["slug"]: s for s in src_ctx}
    for l in ((data or {}).get("links") or [])[:3]:
        if not isinstance(l, dict):
            continue
        ss, anch = str(l.get("source_slug") or "").strip("/"), str(l.get("anchor") or "").strip()
        src = by_slug.get(ss)
        if not src or len(anch) < 8 or anch not in src["text"]:
            continue
        # Toetsen tegen het pagina-record zelf, met precies de regels die het toepassen
        # straks hanteert: een suggestie die nooit geplaatst kan worden hoort niet in de
        # wachtrij te belanden om daar bij elke klik dezelfde fout te geven.
        _blok, _waarom = _linkweave_zoek_blok(_get_page(ss) or {}, anch, href_doel)
        if not _blok:
            continue
        out.append({"id": uuid.uuid4().hex[:10], "source_slug": ss, "source_title": src["title"],
                    "anchor": anch, "target_slug": target_slug.strip("/"),
                    "target_title": target_title, "created_at": _now_iso()})
    return out


def _linkweave_apply(sug: dict):
    """Zet [anker](/doel/) in het tekst-blok van de bronpagina dat het anker bevat.

    Returns (gelukt, melding, blijvend) — `blijvend` betekent dat deze suggestie ook bij een
    volgende poging niet gaat lukken, zodat de aanroeper hem uit de wachtrij kan halen in
    plaats van hem er met dezelfde fout te laten staan.

    Op een design-vaste pagina kwam de link nooit live. De poort hieronder las
    `design_locked` van het record, maar dat veld bestaat daar niet — het wordt pas bij het
    ophalen van een pagina berekend en meegestuurd. De poort ging dus nooit dicht, de link
    werd in de blokken en in page:<slug>:html gezet, en juist die render serveert zo'n
    pagina niet: de bezoeker kreeg dienst-html:/inplace/het statische bestand. Resultaat:
    "geplaatst" in het logboek, niets op de pagina. Nu schrijven we de link ook in het
    document dat echt geserveerd wordt — en lukt dat niet, dan zeggen we dat eerlijk."""
    slug = (sug.get("source_slug") or "").strip("/")
    rec = _get_page(slug)
    if not rec:
        return False, "Bronpagina niet (meer) beschikbaar", True
    anch = (sug.get("anchor") or "").strip()
    href = "/" + (sug.get("target_slug") or "").strip("/") + "/"
    b, waarom = _linkweave_zoek_blok(rec, anch, href)
    if not b:
        return False, waarom, True
    t = str(b.get("text") or "")
    if _page_design_locked(slug, rec):
        base, bewaar = _locked_doc(slug, rec)
        if not base:
            return False, "Pagina-HTML niet te lezen — link niet geplaatst", False
        linked = f'<a href="{html_escape(href)}">{html_escape(anch)}</a>'
        bijgewerkt, gelukt = _locked_replace_once(base, anch, linked)
        if not gelukt:
            return False, ("Ankertekst komt meer dan eens (of niet letterlijk) voor op de "
                           "pagina — link niet geplaatst"), True
        bewaar(bijgewerkt)
    b["text"] = t.replace(anch, "[" + anch + "](" + href + ")", 1)
    _save_page(rec)
    try:
        kv_set(f"page:{rec['slug']}:html", render_page_html(rec))
    except Exception:
        pass
    audit_log("seo.linkweave", rec["slug"], f"Interne link naar {href}: '{anch[:60]}'")
    _seo_decision_add("internal_links", "/" + rec["slug"].strip("/") + "/", rec.get("title", ""),
                      reasoning=f"Interne link geweven naar {href} — interne links geven de "
                                "doelpagina autoriteit en helpen Google de site-structuur begrijpen",
                      evidence={"ankertekst": anch[:80], "doelpagina": href},
                      risk=1, status="uitgevoerd")
    return True, "", False


def _linkweave_after_create(kind: str, slug: str, title: str) -> None:
    """Hook na nieuwe content: suggesties maken; buiten 'Voorzichtig' direct toepassen."""
    try:
        sugs = _linkweave_generate(slug, title)
        if not sugs:
            return
        rest = sugs
        if seo_get_auto().get("autonomy") != "conservative":
            applied = [s for s in sugs if _linkweave_apply(s)[0]]
            if applied:
                _trigger_deploy(f"linkweave {slug}")
            rest = [s for s in sugs if s not in applied]
        _linkweave_toevoegen(rest)
    except Exception:
        pass


@app.route("/api/seo/linkweave")
@app.route("/api/seo/linkweave/")
def api_seo_linkweave():
    g = _require_perm("seo")
    if g:
        return g
    return jsonify({"ok": True, "items": _linkweave_pending()})


@app.route("/api/seo/linkweave/apply", methods=["POST"])
@app.route("/api/seo/linkweave/apply/", methods=["POST"])
def api_seo_linkweave_apply():
    g = _require_perm("seo")
    if g:
        return g
    sid = (request.get_json(silent=True) or {}).get("id") or ""
    items = _linkweave_pending()
    sug = next((x for x in items if x.get("id") == sid), None)
    if not sug:
        return jsonify({"ok": False, "error": "Suggestie niet gevonden"}), 404
    ok, err, blijvend = _linkweave_apply(sug)
    if ok:
        _linkweave_save([x for x in items if x.get("id") != sid])
        _trigger_deploy(f"linkweave {sug.get('source_slug', '')}")
    elif blijvend:
        # Een voorstel dat nooit meer kan lukken hoort niet te blijven staan: dat is precies
        # het beeld dat afgehandeld werk terugkomt. Weg uit de wachtrij, mét de reden.
        _linkweave_save([x for x in items if x.get("id") != sid])
        err = (err or "Toepassen mislukt") + " — voorstel is uit de lijst gehaald"
    return jsonify({"ok": ok, "error": err, "removed": bool(blijvend and not ok)})


