@app.route("/api/seo/linkweave/scan", methods=["POST"])
@app.route("/api/seo/linkweave/scan", methods=["POST"], strict_slashes=False)
def api_seo_linkweave_scan():
    g = _require_perm("seo")
    if g:
        return g
    if not _ai_configured():
        return jsonify({"ok": False, "error": "Geen AI-koppeling actief"}), 503
    b = request.get_json(silent=True) or {}
    slug = (b.get("slug") or "").strip("/")
    title = ""
    if not slug:
        pages = sorted([p for p in _pages_index() if p.get("status", "published") == "published"],
                       key=lambda p: p.get("created_at") or p.get("updated_at") or "", reverse=True)
        if not pages:
            return jsonify({"ok": False, "error": "Geen pagina's gevonden"}), 404
        slug = (pages[0].get("slug") or "").strip("/")
        title = pages[0].get("title") or ""
    else:
        rec = _get_page(slug)
        title = (rec or {}).get("title") or slug
    sugs = _linkweave_generate(slug, title)
    added = _linkweave_toevoegen(sugs)
    return jsonify({"ok": True, "added": added, "target": "/" + slug + "/"})


_NL_MAANDEN = ["januari", "februari", "maart", "april", "mei", "juni", "juli",
               "augustus", "september", "oktober", "november", "december"]


def _seo_index_check(force: bool = False) -> dict:
    """F9: wekelijkse URL-Inspection-check voor door de motor gemaakte pagina's/blogs
    (deze maand). Slaat per pad indexed/state op; graceful zonder Search Console."""
    st = kv_get("seo:indexstate") or {}
    if not force and time.time() - float(st.get("_t", 0) or 0) < 7 * 86400:
        return st
    site = (get_settings().get("search_console") or {}).get("site", "")
    base = (_public_base() or "").rstrip("/")
    if not site or not base:
        return st
    paths = []
    for t in (kv_get("seo:plan") or {}).get("queue", []):
        if t.get("status") == "done" and t.get("kind") in ("page", "blog") and t.get("slug"):
            paths.append(("/blog/" + t["slug"].strip("/") + "/") if t["kind"] == "blog"
                         else ("/" + t["slug"].strip("/") + "/"))
    for path in paths[:10]:
        data, err = _google_api("https://searchconsole.googleapis.com/v1/urlInspection/index:inspect",
                                {"inspectionUrl": base + path, "siteUrl": site},
                                "search_console", timeout=8)
        if err:
            break
        res = ((data or {}).get("inspectionResult") or {}).get("indexStatusResult") or {}
        st[path] = {"indexed": res.get("verdict") == "PASS",
                    "state": res.get("coverageState") or "", "checked_at": _now_iso()}
    st["_t"] = int(time.time())
    kv_set("seo:indexstate", st)
    return st


def _seo_report_schedule() -> dict:
    s = kv_get("seo:report:schedule") or {}
    return {"enabled": bool(s.get("enabled")),
            "interval": s.get("interval") if s.get("interval") in ("month", "quarter") else "month",
            "modules": s.get("modules") or ["seo"], "note": s.get("note", ""),
            "to_email": s.get("to_email", ""), "cc": s.get("cc", ""), "bcc": s.get("bcc", ""),
            # 'send' = maken én direct mailen; 'concept' = alleen klaarzetten in de lijst,
            # met optioneel een notificatie naar het bureau (notify_email leeg = geen mail).
            "mode": s.get("mode") if s.get("mode") in ("send", "concept") else "send",
            "notify_email": s.get("notify_email", ""), "sender": s.get("sender", ""),
            "last_key": s.get("last_key", "")}


def _seo_report_autosend_tick() -> bool:
    """F10: op de 1e-3e van de maand (of het kwartaal) automatisch het periode-rapport van de
    afgelopen periode mailen met de opgeslagen wizard-instellingen. Eén keer per periode."""
    cfg = _seo_report_schedule()
    now = datetime.now()
    if not cfg["enabled"] or now.day > 3:
        return False
    if cfg["interval"] == "quarter":
        if now.month not in (1, 4, 7, 10):
            return False
        key = f"{now.year}-Q{(now.month - 1) // 3 + 1}"
    else:
        key = now.strftime("%Y-%m")
    if cfg["last_key"] == key:
        return False
    try:
        first_this = now.replace(day=1)
        to_d = first_this - timedelta(days=1)
        if cfg["interval"] == "quarter":
            frm_d = (to_d.replace(day=1) - timedelta(days=62)).replace(day=1)
            label = f"Kwartaalrapport Q{(to_d.month - 1) // 3 + 1} {to_d.year}"
            period = "quarter"
        else:
            frm_d = to_d.replace(day=1)
            label = f"Maandrapport {_NL_MAANDEN[to_d.month - 1]} {to_d.year}"
            period = "month"
        rep = _seo_build_period_report(frm_d.strftime("%Y-%m-%d"), to_d.strftime("%Y-%m-%d"),
                                       label, period, modules=cfg["modules"], sender=cfg.get("sender", ""))
        if cfg["note"]:
            rep["note"] = cfg["note"]
            kv_set(f"seo:report:{rep['id']}", rep)
        base = _public_base() or ""
        view_url = f'{base}/api/report/view?id={rep["id"]}&t={rep["token"]}'
        if cfg["mode"] == "concept":
            # Alleen klaarzetten: het rapport komt als concept in de lijst en de klant
            # krijgt niets. Het concept telt als 'gedaan' voor deze periode — een
            # mislukte notificatie mag morgen geen tweede concept veroorzaken.
            _seo_report_index_add(rep, "", view_url, status="concept")
            s = kv_get("seo:report:schedule") or {}
            s["last_key"] = key
            kv_set("seo:report:schedule", s)
            audit_log("seo.report.autosend", "concept", label)
            if cfg["notify_email"]:
                naam = (_company().get("name") or "").strip()
                melding = (
                    f'<div style="font-family:Poppins,Arial,sans-serif;max-width:560px;margin:0 auto;color:#1d1d1b">'
                    f'<h2 style="font-size:19px;margin:0 0 6px">Nieuw concept-rapport staat klaar</h2>'
                    f'<p style="line-height:1.6;margin:0 0 14px">Het rapport <b>{_esc(label)}</b>'
                    f'{(" voor " + _esc(naam)) if naam else ""} is klaargezet maar nog niet verstuurd. '
                    f'Controleer het en verstuur het vanuit de Rapportages-pagina.</p>'
                    f'<p style="margin:0 0 6px"><a href="{view_url}" style="color:#f07d22">Bekijk het concept</a></p>'
                    f'<p style="margin:0"><a href="{base}/admin#reports" style="color:#f07d22">Naar Rapportages</a></p></div>')
                send_email(cfg["notify_email"], f"Concept klaar: {label}", melding, content_type="html",
                           from_name=(naam or "Rapportage"))
            return True
        to_email = cfg["to_email"] or (get_settings().get("company_email") or "").strip()
        if not to_email:
            return False
        html = _seo_period_report_html(rep, view_url=view_url, printable=False)
        ok, _msg = send_email(to_email, _rapport_mail_onderwerp(label), html, content_type="html",
                              from_name=_rapport_groet_naam(rep),
                              reply_to=_rapport_afzender_email(rep), from_email=_rapport_afzender_email(rep),
                              cc=(cfg["cc"] or None), bcc=(cfg["bcc"] or None))
        if ok:
            _seo_report_index_add(rep, to_email, view_url)
            s = kv_get("seo:report:schedule") or {}
            s["last_key"] = key
            kv_set("seo:report:schedule", s)
            audit_log("seo.report.autosend", to_email, label)
        return bool(ok)
    except Exception:
        return False


@app.route("/api/seo/report/schedule", methods=["GET", "POST"])
@app.route("/api/seo/report/schedule/", methods=["GET", "POST"])
def api_seo_report_schedule():
    g = _require_perm("reports")
    if g:
        return g
    if request.method == "GET":
        cfg = _seo_report_schedule()
        return jsonify({"ok": True, "schedule": cfg,
                        "next_run_tekst": _seo_report_volgende_run(cfg)})
    d = request.get_json(silent=True) or {}
