@app.route("/api/seo/agent/undo/", methods=["POST"])
def api_seo_agent_undo():
    """F1: draai een agent-beslissing terug. Body: {id}. Werkt voor acties met een meta-undo-recept
    (meta_update/meta_fix/refresh/ctr_experiment/kannibalisatie); nieuwe content draai je terug via
    de bestaande unpublish/reject-knoppen. Slug in de BODY (geen pad-slug — WAF/encoding-les)."""
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    did = (d.get("id") or "").strip()
    entry = next((x for x in _seo_decisions() if x.get("id") == did), None)
    if not entry:
        return jsonify({"ok": False, "error": "Beslissing niet gevonden"}), 404
    if entry.get("status") == "teruggedraaid":
        return jsonify({"ok": False, "error": "Deze beslissing is al teruggedraaid"}), 400
    ok, err = _seo_apply_undo(entry)
    if not ok:
        return jsonify({"ok": False, "error": err}), (404 if "niet (meer) gevonden" in err else 400)
    return jsonify({"ok": True})


@app.route("/api/seo/agent/config", methods=["GET", "POST"])
@app.route("/api/seo/agent/config/", methods=["GET", "POST"])
def api_seo_agent_config():
    """F2: agent-instellingen. GET (seo-recht) leest; POST (bureau) schrijft de whitelist-velden."""
    if request.method == "GET":
        g = _require_perm("seo")
        if g:
            return g
        return jsonify({"ok": True, "config": _agent_config(),
                        "lastrun": kv_get("seo:agent:lastrun") or {},
                        # Alle bestaande paden, zodat het uitsluitveld kan aanvullen in
                        # plaats van de gebruiker een pad te laten intypen dat niet bestaat.
                        "paden": sorted(_agent_known_paths()),
                        # Hoeveel zoekwoorden bij deze site passen — berekend uit de site,
                        # niet uit een vuistregel.
                        "kw_advies": _zoekwoord_advies(),
                        # Pagina's die een handeling dienen en geen zoekvraag: daar valt
                        # niets te winnen, dus daar hoort de agent zijn beurten niet aan
                        # te besteden. Voorgesteld bij de setup, altijd aanpasbaar.
                        "uit_te_sluiten": sorted(p for p in _agent_known_paths()
                                                 if any(k in p.lower() for k in NIET_SCOREND)),
                        "actions_today": _agent_actions_today()})
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    cfg = _agent_config()
    if "enabled" in d:
        cfg["enabled"] = bool(d["enabled"])
    if "tick_hours" in d:
        try:
            cfg["tick_hours"] = max(1, min(24, int(d["tick_hours"])))
        except Exception:
            pass
    if isinstance(d.get("focus_keywords"), list):
        cfg["focus_keywords"] = [str(x).strip()[:60]
                                 for x in d["focus_keywords"] if str(x).strip()][:FOCUS_KEYWORDS_MAX]
    if isinstance(d.get("excluded_paths"), list):
        clean = []
        for x in d["excluded_paths"]:
            p = str(x).strip()
            if not p:
                continue
            if not p.startswith("/"):
                p = "/" + p
            if not p.endswith("/"):
                p += "/"
            clean.append(p[:120])
        cfg["excluded_paths"] = clean[:40]
    # "eigen_instructies" wordt bewust genegeerd: het veld is geschrapt (Ryan 2026-08-26).
    # Elke bewuste opslag door het bureau rondt de setup af. Eenmaal doorlopen blijft
    # hij weg; terugzetten kan alleen expliciet (setup_done=false meesturen), zodat een
    # per ongeluk leeggemaakte lijst je niet ineens weer in de setup-stap gooit.
    # De setup afronden kan alleen met beide bronnen aangesloten. Anders zet je een
    # agent aan die wél publiceert maar niets kan meten, en dat merk je pas weken later.
    if d.get("setup_done", True):
        bronnen = _agent_bronnen()
        if not bronnen["compleet"]:
            mist = []
            if not bronnen["seranking"]:
                mist.append("SE Ranking")
            if not bronnen["gsc"]:
                mist.append("Search Console")
            return jsonify({"ok": False, "bronnen": bronnen,
                            "error": "Koppel eerst " + " en ".join(mist)
                                     + " — zonder die gegevens kan de agent niets meten."}), 400
    cfg["setup_done"] = bool(d.get("setup_done", True))
    kv_set("seo:agent:config", cfg)
    audit_log("seo.agent.config", "seo", "agent-instellingen bijgewerkt")
    return jsonify({"ok": True, "config": cfg})


