@app.route("/api/seo/agent/proposal", methods=["POST"])
@app.route("/api/seo/agent/proposal/", methods=["POST"])
def api_seo_agent_proposal():
    """F2: tier-3-voorstel (noindex/redirect) uitvoeren of afwijzen. Body: {id, approve: true|false}.
    Id in de BODY (geen pad-slug — WAF/encoding-les)."""
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    did = (d.get("id") or "").strip()
    entry = next((x for x in _seo_decisions() if x.get("id") == did), None)
    if not entry or not entry.get("proposal"):
        return jsonify({"ok": False, "error": "Voorstel niet gevonden"}), 404
    if entry.get("status") != "wacht_op_review":
        return jsonify({"ok": False, "error": "Dit voorstel is al afgehandeld"}), 400
    if not d.get("approve"):
        _seo_decision_update(did, status="afgewezen", reviewed_at=_now_iso())
        audit_log("seo.agent.proposal", entry.get("path", ""), "voorstel afgewezen")
        return jsonify({"ok": True, "status": "afgewezen"})
    prop = entry["proposal"]
    if prop.get("type") == "noindex":
        slug = (prop.get("path") or "").strip("/")
        page = _get_page(slug)
        if not page:
            return jsonify({"ok": False, "error": "Pagina niet (meer) gevonden"}), 404
        m = page.setdefault("meta", {})
        old_robots = m.get("robots", "")
        m["robots"] = "noindex,follow"
        _save_page(page)
        update_seo_score(page)
        _seo_decision_update(did, status="uitgevoerd", reviewed_at=_now_iso(),
                             undo={"type": "robots", "slug": slug, "robots": old_robots})
        _trigger_deploy(f"seo agent noindex {slug}")
        audit_log("seo.agent.noindex", slug, "noindex-voorstel uitgevoerd")
        _seo_log("noindex", prop.get("path", ""), page.get("title", ""), "agent-voorstel uitgevoerd: noindex")
        return jsonify({"ok": True, "status": "uitgevoerd"})
    if prop.get("type") == "redirect":
        frm, to = prop.get("from_path", ""), prop.get("to_path", "")
        if not frm or not to or frm == to:
            return jsonify({"ok": False, "error": "Ongeldig redirect-voorstel"}), 400
        rid = _create_redirect(frm, to, 301)
        _seo_decision_update(did, status="uitgevoerd", reviewed_at=_now_iso(),
                             undo={"type": "redirect", "redirect_id": rid})
        _trigger_deploy(f"seo agent redirect {frm}")
        audit_log("seo.agent.redirect", frm, f"301 -> {to} (agent-voorstel)")
        _seo_log("redirect", frm, "", f"agent-voorstel uitgevoerd: 301 naar {to}")
        return jsonify({"ok": True, "status": "uitgevoerd"})
    if prop.get("type") == "extlink_fix":
        # Verwijder precies de bij het voorstel geverifieerde URL's: link weg, tekst blijft.
        slug = (prop.get("path") or "").strip("/") if prop.get("path") != "/" else ""
        page = _get_page(slug)
        if not page:
            return jsonify({"ok": False, "error": "Pagina niet (meer) gevonden"}), 404
        blocks = page.get("content_blocks") or []
        voor = json.loads(json.dumps(blocks))
        urls = [u for u in (prop.get("urls") or []) if isinstance(u, str) and u]

        def _unlink(v):
            if isinstance(v, dict):
                for u in urls:
                    for sleutel in ("href", "src", "url"):
                        if v.get(sleutel) == u:
                            v.pop(sleutel, None)
                return {k: _unlink(x) for k, x in v.items()}
            if isinstance(v, list):
                return [_unlink(x) for x in v]
            if isinstance(v, str):
                nieuw = v
                for u in urls:
                    nieuw = re.sub(r'<a\b[^>]*href=["\']' + re.escape(u) + r'["\'][^>]*>(.*?)</a>',
                                   r'\1', nieuw, flags=re.S)
                return nieuw
            return v

        page["content_blocks"] = _unlink(blocks)
        _save_page(page)
        update_seo_score(page)
        _seo_decision_update(did, status="uitgevoerd", reviewed_at=_now_iso(),
                             undo={"type": "blocks", "slug": slug, "content_blocks": voor})
        _trigger_deploy(f"seo agent extlink-fix {slug or 'home'}")
        audit_log("seo.agent.extlink", slug or "home", f"{len(urls)} kapotte externe link(s) verwijderd")
        _seo_log("extlink_fix", prop.get("path", ""), page.get("title", ""),
                 "agent-voorstel uitgevoerd: kapotte externe links verwijderd")
        return jsonify({"ok": True, "status": "uitgevoerd"})
    if prop.get("type") == "h1_rewrite":
        slug = (prop.get("path") or "").strip("/") if prop.get("path") != "/" else ""
        page = _get_page(slug)
        if not page:
            return jsonify({"ok": False, "error": "Pagina niet (meer) gevonden"}), 404
        blocks = page.get("content_blocks") or []
        h1 = next((b for b in blocks if _blok_is_h1(b)), None)
        naar = str(prop.get("naar") or "").strip()
        if not h1 or not naar:
            return jsonify({"ok": False, "error": "De H1 of de nieuwe kop is er niet meer"}), 400
        voor = json.loads(json.dumps(blocks))
        if isinstance(h1.get("props"), dict):
            h1["props"]["text"] = naar
        if "text" in h1:
            h1["text"] = naar
        page["content_blocks"] = blocks
        _save_page(page)
        update_seo_score(page)
        _seo_decision_update(did, status="uitgevoerd", reviewed_at=_now_iso(),
                             undo={"type": "blocks", "slug": slug, "content_blocks": voor})
        _trigger_deploy(f"seo agent h1-rewrite {slug or 'home'}")
        audit_log("seo.agent.h1", slug or "home", f"H1 ingekort naar: {naar[:60]}")
        _seo_log("h1_rewrite", prop.get("path", ""), page.get("title", ""),
                 "agent-voorstel uitgevoerd: kortere H1")
        return jsonify({"ok": True, "status": "uitgevoerd"})
    return jsonify({"ok": False, "error": "Onbekend voorsteltype"}), 400


@app.route("/api/seo/agent/fleet", methods=["GET", "POST"])
@app.route("/api/seo/agent/fleet/", methods=["GET", "POST"])
def api_seo_agent_fleet():
    """F4: service-API voor het centrale MAIHS-vlootbeheer (staff-dashboard).
    Auth: HMAC over "<ts>.<pad>" met het gedeelde OAUTH_PROXY_SECRET (zelfde geheim als de
    OAuth-proxy — geen nieuw secret te verspreiden), headers X-Fleet-Ts + X-Fleet-Sig,
    ts maximaal 5 minuten oud. Een bureau-sessie mag ook (handig voor testen).
    GET  -> status-samenvatting (gezondheid, autonomie, tellers, laatste denk-beurt).
    POST -> {action: "pause"|"resume"} of {action: "set_autonomy", autonomy: ...}."""
    def _fleet_auth_ok() -> bool:
        secret = (os.environ.get("OAUTH_PROXY_SECRET") or "").strip()
        if not secret:
            return False
        ts = (request.headers.get("X-Fleet-Ts") or "").strip()
        sig = (request.headers.get("X-Fleet-Sig") or "").strip()
        if not ts or not sig:
            return False
        try:
            if abs(time.time() - float(ts)) > 300:
                return False
        except Exception:
            return False
        want = hmac.new(secret.encode(), f"{ts}./api/seo/agent/fleet".encode(), hashlib.sha256).hexdigest()
        return secrets.compare_digest(want, sig)

    if not _fleet_auth_ok() and current_role() != "agency":
        return jsonify({"ok": False, "error": "auth"}), 401
    if request.method == "GET":
        auto = seo_get_auto()
        cfg = _agent_config()
        counts = {}
        for d in _seo_decisions():
            counts[d.get("status", "?")] = counts.get(d.get("status", "?"), 0) + 1
        return jsonify({"ok": True, "site": _public_base() or request.host_url.rstrip("/"),
                        "active": bool(auto.get("active")), "autonomy": auto.get("autonomy", "balanced"),
                        "agent_enabled": bool(cfg.get("enabled")),
                        "health": (kv_get("seo:state") or {}).get("health", {}),
                        "decisions": counts, "actions_today": _agent_actions_today(),
                        "pending_review": counts.get("wacht_op_review", 0),
                        "lastrun": kv_get("seo:agent:lastrun") or {},
                        "budget": _ai_budget(),
                        "recent": [{"action": d.get("action"), "path": d.get("path"),
                                    "status": d.get("status"), "at": d.get("at"),
                                    "result": (d.get("measure") or {}).get("result", "")}
                                   for d in _seo_decisions()[:10]]})
    d = request.get_json(silent=True) or {}
    act = (d.get("action") or "").strip()
    if act in ("pause", "resume"):
        cfg = _agent_config()
        cfg["enabled"] = (act == "resume")
        kv_set("seo:agent:config", cfg)
        audit_log("seo.agent.fleet", "seo", f"agent {'hervat' if act == 'resume' else 'gepauzeerd'} via vlootbeheer")
        return jsonify({"ok": True, "agent_enabled": cfg["enabled"]})
    if act == "set_autonomy" and d.get("autonomy") in ("conservative", "balanced", "autonomous"):
        auto = seo_get_auto()
        auto["autonomy"] = d["autonomy"]
        auto["auto_approve"] = (d["autonomy"] == "autonomous")
        seo_save_auto(auto)
        audit_log("seo.agent.fleet", "seo", f"autonomie -> {d['autonomy']} via vlootbeheer")
        return jsonify({"ok": True, "autonomy": auto["autonomy"]})
    return jsonify({"ok": False, "error": "Onbekende actie"}), 400


@app.route("/api/cron/agent", methods=["GET", "POST"])
@app.route("/api/cron/agent/", methods=["GET", "POST"])
def api_cron_agent():
    """F2: uurlijkse denk-cron (interne debounce bepaalt het echte ritme). Auth als /api/cron/seo."""
    secret = os.environ.get("CRON_SECRET", "")
    authz = request.headers.get("Authorization", "")
    is_cron = bool(secret) and authz == ("Bearer " + secret)
    if not is_cron and current_role() != "agency":
        return jsonify({"ok": False, "error": "auth"}), 401
    # Beheer-meting die het onderhoud-blok in het rapport voedt: deze cron is de enige
    # die uurlijks draait, dus hier hoort de bereikbaarheidsmeting. Faalt stil.
    try:
        _monitor_tick()
    except Exception:
        pass
    res = _agent_tick(force=False)
    if res.get("did") not in ("debounced", "locked", "idle"):
        audit_log("seo.agent.cron", "seo", str(res.get("did", "?")))
    return jsonify(res)


@app.route("/api/seo/auto", methods=["GET", "POST"])
def api_seo_auto():
    """Config + status van de autonome motor. GET (seo-recht) leest; POST (bureau) wijzigt de schakelaar/volumes."""
    if request.method == "GET":
        g = _require_perm("seo")
        if g:
            return g
        cfg = seo_get_auto()
        plan = kv_get("seo:plan") or {}
        progress = {}
        if plan.get("month") == datetime.now().strftime("%Y-%m"):
            q = plan.get("queue", [])
            _klabel = {"page": "Nieuwe pagina", "blog": "Nieuwe blog", "fix": "Meta-fixes",
                       "improve": "On-page verbetering", "refresh": "Pagina opfrissen"}
            progress = {"month": plan["month"], "total": len(q),
                        "done": len([t for t in q if t.get("status") == "done"]),
                        "report_sent": bool(plan.get("report_sent")),
                        "bugs_fixed": int(plan.get("bugs_fixed", 0)),
                        # Vooruitblik: wat de motor deze maand nog doet / al deed (transparantie).
                        "upcoming": _auto_upcoming_with_dates(q, _klabel)}
        reports = [{"id": r["id"], "month": r["month"], "status": r.get("status", ""),
                    "generated_at": r.get("generated_at", ""), "sent_at": r.get("sent_at", ""),
                    "pages": len(r.get("pages", [])), "posts": len(r.get("posts", [])),
                    "bugs_fixed": r.get("bugs_fixed", 0)} for r in _seo_reports()]
        # Goedkeuringsqueue: voeg het pad mee zodat de UI kan linken/voorbeeld tonen.
        pending = [{"kind": x.get("kind"), "slug": x.get("slug"), "title": x.get("title", ""),
                    "created_at": x.get("created_at", ""),
                    "path": (("/blog/" + (x.get("slug") or "").strip("/") + "/") if x.get("kind") == "blog"
                             else ("/" + (x.get("slug") or "").strip("/") + "/"))}
                   for x in _seo_pending()]
        # Search Console-stand mee: zonder die koppeling kan de agent wél handelen maar
        # niets beoordelen (de meetlus draait op klikken en vertoningen). Dat hoort
        # bovenaan het scherm te staan, niet verstopt bij Integraties.
        _sc = get_settings().get("search_console") or {}
        _gsc = {"verbonden": bool((kv_get("google_oauth:search_console") or {}).get("refresh_token")),
                "property": str(_sc.get("site") or "")}
        return jsonify({"ok": True, "auto": cfg, "progress": progress, "reports": reports,
                        "health": _seo_health(), "yield": _seo_month_yield(),
                        "opportunities": (_seo_opportunities() or [])[:5],
                        "pending": pending, "budget": _ai_budget(), "gsc": _gsc})
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    cfg = seo_get_auto()
    if "active" in d:
        cfg["active"] = bool(d["active"])
    if "auto_approve" in d:
        cfg["auto_approve"] = bool(d["auto_approve"])
    if d.get("autonomy") in ("conservative", "balanced", "autonomous"):
        cfg["autonomy"] = d["autonomy"]
        cfg["auto_approve"] = d["autonomy"] == "autonomous"
    # pages/blogs_per_month worden genegeerd: de planner bepaalt het volume zelf
    # (vraag-gestuurd met vaste plafonds — Ryan 2026-08-26).
    seo_save_auto(cfg)
    audit_log("seo.auto.save", "seo", f"active={cfg['active']} autonomy={cfg.get('autonomy')}")
    return jsonify({"ok": True, "auto": cfg})


