@app.route("/api/seo/auto/approve", methods=["POST"])
def api_seo_auto_approve():
    """Keur concept(en) goed -> publiceer live. Eén item ({kind,slug}) of een batch ({items:[...]}),
    met ÉÉN deploy aan het eind (geen deploy-storm bij een hele maandbatch)."""
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    items = d.get("items") if isinstance(d.get("items"), list) else [{"kind": d.get("kind"), "slug": d.get("slug")}]
    published = 0
    for it in items:
        kind = it.get("kind"); slug = (it.get("slug") or "").strip("/")
        ok = _seo_publish_page(slug) if kind == "page" else _seo_publish_post(slug) if kind == "blog" else False
        if ok:
            _seo_pending_remove(kind, slug)
            published += 1
            # F1: de wacht_op_review-beslissing van dit concept -> uitgevoerd (goedgekeurd).
            _p = (("/blog/" + slug + "/") if kind == "blog" else ("/" + slug + "/"))
            _seo_decision_update(pred=lambda x, _p=_p: x.get("path") == _p and x.get("status") == "wacht_op_review",
                                 status="uitgevoerd", reviewed_at=_now_iso(), review="goedgekeurd")
    if not published:
        return jsonify({"ok": False, "error": "Niet gevonden"}), 404
    _trigger_deploy(f"seo approve x{published}")
    audit_log("seo.auto.approve", "", f"{published} concept(en) goedgekeurd + gepubliceerd")
    return jsonify({"ok": True, "published": published, "pending": _seo_pending()})


@app.route("/api/seo/auto/unpublish", methods=["POST"])
def api_seo_auto_unpublish():
    """Undo: zet een zojuist gepubliceerd item terug naar concept (status draft) + opnieuw in de
    goedkeuringsqueue, en deploy. Body: {kind, slug, title?}."""
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    kind = d.get("kind"); slug = (d.get("slug") or "").strip("/")
    title = (d.get("title") or "").strip()
    if kind == "page":
        page = _get_page(slug)
        if not page:
            return jsonify({"ok": False, "error": "Niet gevonden"}), 404
        page["status"] = "draft"; _save_page(page); update_seo_score(page)
        title = title or page.get("title", "")
    elif kind == "blog":
        post = get_post(slug)
        if not post:
            return jsonify({"ok": False, "error": "Niet gevonden"}), 404
        post["status"] = "draft"; save_post(post)
        title = title or post.get("title", "")
    else:
        return jsonify({"ok": False, "error": "Onbekend type"}), 400
    _seo_pending_add(kind, slug, title)
    _trigger_deploy(f"seo unpublish {kind} {slug}")
    audit_log("seo.auto.unpublish", slug, f"{kind} teruggezet naar concept")
    _p = (("/blog/" + slug + "/") if kind == "blog" else ("/" + slug + "/"))
    _seo_decision_update(pred=lambda x, _p=_p: x.get("path") == _p and x.get("action") in ("new_page", "new_blog")
                         and x.get("status") == "uitgevoerd",
                         status="wacht_op_review", reviewed_at=_now_iso(), review="teruggezet naar concept")
    return jsonify({"ok": True, "pending": _seo_pending()})


@app.route("/api/seo/auto/reject", methods=["POST"])
def api_seo_auto_reject():
    """Wijs een concept af -> verwijder het en haal het uit de queue."""
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    kind = d.get("kind"); slug = (d.get("slug") or "").strip("/")
    # Onthoud de afwijzing (leereffect) vóór het verwijderen — titel uit de pending-queue of body.
    title = (d.get("title") or "").strip()
    if not title:
        title = next((x.get("title", "") for x in _seo_pending()
                      if x.get("kind") == kind and (x.get("slug") or "").strip("/") == slug), "")
    _seo_add_rejection(kind, title)
    try:
        if kind == "page":
            _do_page_delete(slug, {})
        elif kind == "blog":
            delete_post(slug)
    except Exception:
        pass
    _seo_pending_remove(kind, slug)
    audit_log("seo.auto.reject", slug, f"{kind} afgewezen + verwijderd")
    _p = (("/blog/" + slug + "/") if kind == "blog" else ("/" + slug + "/"))
    _seo_decision_update(pred=lambda x, _p=_p: x.get("path") == _p and x.get("status") == "wacht_op_review",
                         status="afgewezen", reviewed_at=_now_iso())
    return jsonify({"ok": True, "pending": _seo_pending()})


@app.route("/api/seo/strategy/create-page", methods=["POST"])
def api_seo_strategy_create_page():
    """1-klik: maak een pagina voor een content-gat uit de strategie. Concept (ter goedkeuring) tenzij
    auto-goedkeuren aanstaat. Body: {topic, suggested_path?}."""
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    topic = (d.get("topic") or "").strip()
    if not topic:
        return jsonify({"ok": False, "error": "Geen onderwerp"}), 400
    sp = (d.get("suggested_path") or "").strip().strip("/")
    slug = _safe_slug(sp) if sp else None
    if slug and _seo_slug_exists(slug):
        slug = None  # bestaat al -> generator kiest een unieke slug
    page, err = _ai_generate_page(prompt=topic, template="dienst", slug_override=slug)
    if err or not page:
        out = {"ok": False, "error": (err or {}).get("error", "Genereren mislukt")}
        if err and err.get("details"):
            out["details"] = err["details"]
        return jsonify(out), (err or {}).get("code", 502)
    auto = seo_get_auto().get("auto_approve", False)
    _seo_finalize_page(page, auto)
    audit_log("seo.strategy.create_page", page["slug"], ("gepubliceerd" if auto else "concept ter goedkeuring"))
    return jsonify({"ok": True, "slug": page["slug"], "title": page.get("title", ""),
                    "status": "published" if auto else "draft", "pending": not auto})


@app.route("/api/cron/seo", methods=["GET", "POST"])
@app.route("/api/cron/seo/", methods=["GET", "POST"])
def api_cron_seo():
    """Dagelijkse scheduler voor de autonome SEO-motor. Auth: Vercel Cron (Bearer CRON_SECRET) of bureau."""
    secret = os.environ.get("CRON_SECRET", "")
    authz = request.headers.get("Authorization", "")
    is_cron = bool(secret) and authz == ("Bearer " + secret)
    if not is_cron and current_role() != "agency":
        return jsonify({"ok": False, "error": "auth"}), 401
    # Dagelijkse beheer-taken die het onderhoud-blok in het rapport voeden: een
    # content-back-up en de SSL-status cachen (zodat de rapportbouw daar nooit een
    # netwerk-call voor hoeft te doen). Falen stil, los van elkaar: de motor mag hier
    # nooit op stuklopen.
    try:
        _backup_tick()
    except Exception:
        pass
    try:
        _ssl_tick()
    except Exception:
        pass
    # Autopilot: zorg dat de focus-zoekwoorden in SE Ranking gevolgd worden
    # (idempotent, intern gedebounced op één poging per dag).
    try:
        _seranking_focus_sync()
    except Exception:
        pass
    res = _seo_cron_tick(force=False)
    # Scoremeting bij een nieuwe sitecontrole — ná de tick: die ververst onderweg
    # de audit-cache, dus een verse crawl wordt dezelfde run nog gemeten
    # ('per dag is overdreven, doe het bij een audit', Ryan 2026-08-25).
    try:
        _seo_score_meet_bij_audit()
    except Exception:
        pass
    # Meelift-melding: MAIHS kan onze Google-koppelingen niet zelf zien, dus geven
    # we ze dagelijks door. Faalt stil — rapportage mag de cron nooit breken.
    res["status_reported"] = _meld_koppelingen_aan_maihs()
    audit_log("seo.cron", "seo", str(res.get("did", "?")))
    return jsonify(res)


@app.route("/api/seo/report-approve", methods=["GET"])
def api_seo_report_approve():
    """Token-beveiligde link uit de concept-mail: zet het maandrapport door naar de klant.
    Geen login nodig (Wim klikt vanuit zijn mail) — afgeschermd met een per-rapport token."""
    rid = (request.args.get("id") or "").strip()
    tok = (request.args.get("t") or "").strip()
    reports = _seo_reports()
    rep = next((r for r in reports if r.get("id") == rid), None)

    def _pg(title, msg, ok=True, code=200):
        c = "#16a34a" if ok else "#b91c1c"
        return (f'<!doctype html><html lang="nl"><meta charset="utf-8">'
                f'<meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title>'
                f'<div style="font-family:Poppins,Arial,sans-serif;max-width:520px;margin:64px auto;padding:0 20px;text-align:center;color:#1d1d1b">'
                f'<h1 style="color:{c};font-size:22px">{title}</h1><p style="line-height:1.6;color:#555">{msg}</p></div></html>'), code
    if not rep or not tok or not secrets.compare_digest(tok, rep.get("token", "")):
        return _pg("Link ongeldig", "Deze goedkeur-link is ongeldig of verlopen.", ok=False, code=403)
    if rep.get("status") == "sent":
        return _pg("Al verstuurd", "Dit rapport is al naar de klant verstuurd.", ok=True)
    sent = _seo_send_client_report(rep)
    rep["status"] = "sent" if sent else "send_failed"
    rep["sent_at"] = _now_iso()
    _seo_save_reports(reports)
    audit_log("seo.report.approve", rid, "doorgezet naar klant" if sent else "verzenden mislukt")
    if not sent:
        return _pg("Verzenden mislukt", "Het rapport kon niet worden verstuurd. Controleer de SMTP-instellingen.", ok=False, code=500)
    to = (get_settings().get("company_email") or "info@damhousing.nl")
    return _pg("Verstuurd ✓", f"Het maandrapport is doorgezet naar {to}.", ok=True)


def _seo_report_params():
    """(from, to, label, period, modules) uit query/body. Modules = welke rapport-onderdelen
    (seo/ads/gbp/onderhoud); default seo. Periodekeuze week/maand/kwartaal of aangepast bereik."""
    d = request.get_json(silent=True) or {}
    period = (request.args.get("period") or d.get("period") or "month").strip()
    raw_mods = request.args.get("modules") or d.get("modules") or "seo"
    mods = raw_mods if isinstance(raw_mods, list) else [m.strip() for m in str(raw_mods).split(",")]
    mods = [m for m in mods if m in ("seo", "ads", "gbp", "onderhoud")] or ["seo"]
    frm = (request.args.get("from") or d.get("from") or "").strip()
    to = (request.args.get("to") or d.get("to") or "").strip()
    # Persoonlijke notitie van de accountmanager: komt als kader bovenin het rapport (C1).
    note = str(request.args.get("note") or d.get("note") or "").strip()[:2000]
    # Afzender (Ryan 2026-08-25): vanuit wie het rapport komt; stuurt de ondertekening,
    # de mail-afzendernaam en de toon van het AI-slot.
    sender = str(request.args.get("sender") or d.get("sender") or "").strip()[:60]
    if frm and to:
        return frm, to, f"{frm} t/m {to}", "custom", mods, note, sender
    frm, to, label = _seo_period_range(period)
    return frm, to, label, period, mods, note, sender


@app.route("/api/seo/report/preview", methods=["GET", "POST"])
@app.route("/api/seo/report/preview/", methods=["GET", "POST"])
def api_seo_report_preview():
    """Bouw + bewaar een periode-rapport en geef de data + een (token-)view-URL terug (voor de admin)."""
    a = _require_perm("seo")
    if a:
        return a
    frm, to, label, period, mods, note, sender = _seo_report_params()
    rep = _seo_build_period_report(frm, to, label, period, modules=mods, sender=sender)
    if note:
        rep["note"] = note
        kv_set(f"seo:report:{rep['id']}", rep)   # note mee-persisteren voor view/mail/PDF
    base = _public_base() or CANONICAL_BASE
    rep["view_url"] = f'{base}/api/report/view?id={rep["id"]}&t={rep["token"]}'
    return jsonify({"ok": True, "report": rep})


@app.route("/api/report/view", methods=["GET"])
@app.route("/api/report/view/", methods=["GET"])
# Oude pad blijft als alias: het staat in eerder verstuurde klantmails en mag nooit dood.
@app.route("/api/seo/report/view", methods=["GET"])
@app.route("/api/seo/report/view/", methods=["GET"])
def api_seo_report_view():
    """Publieke, token-beveiligde HTML-weergave van een rapport (mail-link + print->PDF). Geen login.

    Canoniek pad is /api/report/view (Ryan 2026-08-25): rapportages zijn niet alleen SEO."""
    rid = (request.args.get("id") or "").strip()
    tok = (request.args.get("t") or "").strip()
    rep = kv_get(f"seo:report:{rid}") if rid else None
    if not rep or not tok or not secrets.compare_digest(tok, rep.get("token", "")):
        return Response("Rapport niet gevonden of de link is ongeldig.", status=404, mimetype="text/plain")
    base = _public_base() or CANONICAL_BASE
    view_url = f'{base}/api/report/view?id={rid}&t={tok}'
    # ?mail=1: exact de mailversie (rapportage-knop, geen printknop) — voor het
    # mailvoorbeeld in de wizard vóór het echte versturen.
    html = _seo_period_report_html(rep, view_url=view_url, printable=not request.args.get("mail"))
    # ?print=1: meteen het printdialoog openen — 'Opslaan als PDF' geeft daar exact de
    # webversie. Dit ís de PDF-knop van de admin; een losse generator kan de huisstijl
    # (donkere kaart, Poppins) nooit één-op-één namaken.
    if request.args.get("print"):
        html = html.replace("</body>", '<script id="autoprint">window.addEventListener("load",'
                            'function(){setTimeout(function(){rapportPdf()},400)});</script></body>')
    return Response(html, mimetype="text/html")


@app.route("/api/seo/report/send", methods=["POST"])
@app.route("/api/seo/report/send/", methods=["POST"])
def api_seo_report_send():
    """Mail een rapport (nette HTML + online/PDF-link) naar de klant.

    Met een id gaat exact het al gebouwde en gecontroleerde rapport de deur uit:
    geen herbouw, dus geen tweede AI-call van een halve minuut ('hij blijft hangen
    op Versturen', Ryan 2026-08-25) en geen andere teksten dan het mailvoorbeeld
    liet zien. Zonder id (oudere aanroepen) bouwt hij vers, zoals voorheen."""
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    rid = str(d.get("id") or "").strip()
    if rid:
        rep = kv_get(f"seo:report:{rid}")
        if not (rep and rep.get("token")):
            return jsonify({"ok": False, "error": "Rapport niet gevonden; maak het voorbeeld opnieuw."}), 404
        label = rep.get("label") or ""
        mods = rep.get("modules") or ["seo"]
    else:
        frm, to, label, period, mods, note, sender = _seo_report_params()
        rep = _seo_build_period_report(frm, to, label, period, modules=mods, sender=sender)
        if note:
            rep["note"] = note
            kv_set(f"seo:report:{rep['id']}", rep)   # note mee-persisteren voor view/mail/PDF
    base = _public_base() or CANONICAL_BASE
    view_url = f'{base}/api/report/view?id={rep["id"]}&t={rep["token"]}'
    to_email = (d.get("to_email") or "").strip() or (get_settings().get("company_email") or "").strip() or "info@damhousing.nl"
    html = _seo_period_report_html(rep, view_url=view_url, printable=False)
    ok, msg = send_email(to_email, _rapport_mail_onderwerp(label), html, content_type="html",
                         from_name=_rapport_groet_naam(rep),
                         reply_to=_rapport_afzender_email(rep), from_email=_rapport_afzender_email(rep))
    if ok:
        _seo_report_index_add(rep, to_email, view_url)
    audit_log("seo.report.send", to_email, f"Rapportage {label} ({','.join(mods)}) verstuurd")
    return jsonify({"ok": bool(ok), "sent_to": to_email, "view_url": view_url, "error": (None if ok else msg)})


