def _agent_audit_verify() -> dict:
    """Controleer uitgevoerde crawl-fixes tegen de nieuwste crawl. Idempotent."""
    log = _seo_decisions()
    open_fixes = [d for d in log
                  if isinstance(d.get("audit_issue"), dict)
                  and d.get("status") == "uitgevoerd"
                  and not d["audit_issue"].get("result")
                  and d["audit_issue"].get("code")]
    if not open_fixes:
        return {"ok": True, "did": "idle", "beoordeeld": 0}
    try:
        oogst = _seranking_audit_issues()
    except Exception as e:
        return {"ok": False, "did": "error", "error": str(e)[:120], "beoordeeld": 0}
    nieuw_id = str(oogst.get("audit_id") or "")
    if not nieuw_id:
        return {"ok": True, "did": "idle", "beoordeeld": 0}
    # Pad-index van de nieuwste crawl: {code: {paden}}.
    huidig = {}
    for issue in (oogst.get("fixbaar") or []) + (oogst.get("meldingen") or []):
        huidig.setdefault(issue["code"], set()).update(issue.get("paden") or [])
    beoordeeld = opgelost = 0
    for d in open_fixes:
        ai = d["audit_issue"]
        if str(ai.get("audit_id") or "") == nieuw_id:
            continue   # nog niet opnieuw gecrawld — niets te concluderen
        pad = ai.get("path") or d.get("path") or ""
        weg = pad not in huidig.get(ai["code"], set())
        ai["result"] = "opgelost" if weg else "nog_aanwezig"
        ai["verified_audit_id"] = nieuw_id
        ai["verified_at"] = _now_iso()
        beoordeeld += 1
        opgelost += 1 if weg else 0
    if beoordeeld:
        kv_set("seo:decisions", log[:SEO_DECISIONS_CAP])
        audit_log("seo.agent.audit-verify", "seo",
                  f"{beoordeeld} crawl-fix(es) getoetst aan crawl {nieuw_id}; {opgelost} opgelost")
    return {"ok": True, "did": "verify", "beoordeeld": beoordeeld, "opgelost": opgelost,
            "audit_id": nieuw_id}


def _agent_bronnen() -> dict:
    """Staan de twee databronnen klaar waar de agent op draait?

    SE Ranking levert de posities en de crawl-score, Search Console de klikken en
    vertoningen waarmee hij zijn eigen acties beoordeelt. Zonder allebei is elke
    beslissing een gok en elk resultaat 'neutraal' — daarom zijn ze een voorwaarde
    voor de setup en niet iets wat je er later nog eens bij doet.
    """
    try:
        sr = bool(_seranking_site_id())
    except Exception:
        sr = False
    prop = bool(str((get_settings().get("search_console") or {}).get("site") or ""))
    # Een eigen Google-koppeling óf de centrale gateway: allebei genoeg om aan te melden
    # en data op te halen. Zonder dit blijft de setup vragen om "Verbinden met Google"
    # terwijl dat sinds het teamaccount niet meer nodig is.
    google = (bool((kv_get("google_oauth:search_console") or {}).get("refresh_token"))
              or bool(_gateway_origin() and _gateway_key()))
    # Allebei nodig. Op de property alleen afgaan liet de setup "gekoppeld" zeggen terwijl
    # Integraties "niet verbonden" toonde: zonder token valt er niets te lezen, dus dan is
    # de gekozen property een dood gegeven.
    gsc = bool(prop and google)
    return {"seranking": sr, "gsc": gsc, "gsc_verbonden": google,
            "compleet": bool(sr and gsc)}


def _agent_fix_alt(path: str, code: str, audit_id: str, reasoning: str, evidence: dict) -> dict:
    """Vul de ontbrekende alt-teksten van één pagina aan. Bestaande alt-teksten blijven staan."""
    slug = (path or "").strip("/") if path != "/" else ""
    page = _get_page(slug)
    if not page:
        return {"ok": False, "did": "alt_fix", "error": "pagina heeft geen bewerkbare record"}
    blocks = page.get("content_blocks") or []
    if not isinstance(blocks, list):
        return {"ok": False, "did": "alt_fix", "error": "pagina heeft geen blokken"}
    # Harde poort: rendert deze pagina zijn content pas in de browser, dan ziet de crawler
    # onze wijziging nooit en is de melding niet op te lossen met een blok. Niets doen.
    if _pagina_is_client_gerenderd(path):
        return {"ok": False, "did": "alt_fix",
                "error": "pagina is client-gerenderd \u2014 de crawler ziet de content niet, "
                         "een blok toevoegen lost de melding niet op"}

    voor = json.loads(json.dumps(blocks))
    doelen = _lege_alt_dragers(blocks)
    if not doelen:
        return {"ok": False, "did": "alt_fix", "error": "geen afbeeldingen zonder alt-tekst"}
    if not _ai_configured():
        return {"ok": False, "did": "alt_fix", "error": "Geen AI-koppeling actief"}
    titel = page.get("title", "") or slug or "Home"
    context = " ".join((b.get("props") or {}).get("text", "") or b.get("text", "") or ""
                       for b in blocks if b.get("type") in ("paragraph", "heading"))[:600]
    doelen = doelen[:10]
    rr = _anthropic_call(
        [{"role": "user", "content": json.dumps(
            {"pagina": path, "titel": titel, "context": context,
             "afbeeldingen": [src for _d, _p, src in doelen]}, ensure_ascii=False)}],
        system=(f"Je schrijft alt-teksten voor foto's op een pagina van {_seo_business_context()}. "
                "Beschrijf wat er te zien is (feitelijk, Nederlands, max 100 tekens, geen "
                "zoekwoord-stapeling, niet beginnen met 'afbeelding van'). Antwoord UITSLUITEND "
                "als JSON met evenveel items als afbeeldingen: {\"alts\":[\"...\"]}"),
        max_tokens=500, model="claude-haiku-4-5-20251001")
    if rr.get("error"):
        return {"ok": False, "did": "alt_fix", "error": rr.get("error")}
    d = _loads_lenient("".join(b.get("text", "") for b in rr.get("content", []))) or {}
    alts = [str(a).strip()[:120] for a in (d.get("alts") or []) if str(a or "").strip()]
    if not alts:
        return {"ok": False, "did": "alt_fix", "error": "AI gaf geen bruikbare alt-teksten terug"}
    gevuld = 0
    for (drager, props, _src), alt in zip(doelen, alts):
        drager["alt"] = alt
        if isinstance(props, dict):
            props["alt"] = alt
        gevuld += 1
    page["content_blocks"] = blocks
    _save_page(page)
    update_seo_score(page)
    _trigger_deploy(f"seo agent alt-fix {slug or 'home'}")
    audit_log("seo.altfix", slug or "home", f"{gevuld} alt-tekst(en) aangevuld")
    _seo_log("alt_fix", path, titel, f"{gevuld} alt-tekst(en) aangevuld")
    ev = dict(evidence or {})
    ev.update({"audit_code": code, "audit_id": audit_id, "aangevuld": gevuld})
    _seo_decision_add("alt_fix", path, titel, reasoning=reasoning, evidence=ev, risk=1,
                      status="uitgevoerd", source="agent",
                      undo={"type": "blocks", "slug": slug, "content_blocks": voor},
                      extra={"audit_issue": {"code": code, "audit_id": audit_id, "path": path}})
    return {"ok": True, "did": "alt_fix", "aangevuld": gevuld}


def _agent_fix_h1(path: str, code: str, audit_id: str, reasoning: str, evidence: dict) -> dict:
    """Herstel de kopstructuur van één pagina: precies één H1.

    Bewust STRUCTUREEL en geen copywriting — een bestaande H1 laten we met rust. Ontbreekt hij,
    dan schrijven we er één (AI, met de paginatitel als terugval); staan er meerdere, dan blijft
    de eerste staan en zakken de rest naar H2. Dat is exact wat `h1_missing`/`h1_duplicate`
    meldt, en niets daarbuiten.
    """
    slug = (path or "").strip("/") if path != "/" else ""
    page = _get_page(slug)
    if not page:
        return {"ok": False, "did": "h1_fix", "error": "pagina heeft geen bewerkbare record"}
    blocks = page.get("content_blocks") or []
    if not isinstance(blocks, list):
        return {"ok": False, "did": "h1_fix", "error": "pagina heeft geen blokken"}
    # Harde poort: rendert deze pagina zijn content pas in de browser, dan ziet de crawler
    # onze wijziging nooit en is de melding niet op te lossen met een blok. Niets doen.
    if _pagina_is_client_gerenderd(path):
        return {"ok": False, "did": "h1_fix",
                "error": "pagina is client-gerenderd \u2014 de crawler ziet de content niet, "
                         "een blok toevoegen lost de melding niet op"}

    voor = json.loads(json.dumps(blocks))     # undo-recept: de blokken zoals ze waren
    h1s = [b for b in blocks if _blok_is_h1(b)]
    titel = page.get("title", "") or slug or "Home"
    if len(h1s) == 1:
        return {"ok": False, "did": "h1_fix", "error": "er staat al precies één H1 — niets te herstellen"}
    if len(h1s) > 1:
        for b in h1s[1:]:
            _blok_zet_level(b, "h2")
        wat = f"{len(h1s)} H1-koppen teruggebracht naar één"
    else:
        # Eerst kijken of de pagina zélf al een H1 rendert (hero, header, sectie uit de
        # site-code). Zo ja: niets doen — anders krijg je er een tweede, bovenaan in beeld.
        eigen = _pagina_heeft_eigen_h1(path)
        if eigen:
            return {"ok": False, "did": "h1_fix",
                    "error": "de pagina zelf rendert al een H1 (buiten de blokken) — niets toegevoegd"}
        if eigen is None:
            return {"ok": False, "did": "h1_fix",
                    "error": "pagina niet op te halen om te controleren of er al een H1 staat"}
        kop = titel
        if _ai_configured():
            rr = _anthropic_call(
                [{"role": "user", "content": f"Pagina: {path}\nTitel: {titel}\nInhoud: "
                  + " ".join((b.get("props") or {}).get("text", "") or b.get("text", "") or ""
                             for b in blocks)[:800]}],
                system=(f"Je schrijft één H1 voor een pagina van {_seo_business_context()}. "
                        "Kort, concreet, lokaal, max 60 tekens, geen clickbait. "
                        "Antwoord UITSLUITEND als JSON: {\"h1\":\"...\"}"),
                max_tokens=120, model="claude-haiku-4-5-20251001")
            if not rr.get("error"):
                d = _loads_lenient("".join(b.get("text", "") for b in rr.get("content", []))) or {}
                kop = str(d.get("h1") or "").strip()[:70] or titel
        blocks.insert(0, {"type": "heading", "level": "h1", "text": kop, "props": {"level": "h1", "text": kop}})
        wat = "ontbrekende H1 toegevoegd"
    page["content_blocks"] = blocks
    _save_page(page)
    update_seo_score(page)
    _trigger_deploy(f"seo agent h1-fix {slug or 'home'}")
    audit_log("seo.h1fix", slug or "home", wat)
    _seo_log("h1_fix", path, titel, wat)
    ev = dict(evidence or {})
    ev.update({"audit_code": code, "audit_id": audit_id, "herstel": wat})
    _seo_decision_add("h1_fix", path, titel, reasoning=reasoning, evidence=ev, risk=1,
                      status="uitgevoerd", source="agent",
                      undo={"type": "blocks", "slug": slug, "content_blocks": voor},
                      extra={"audit_issue": {"code": code, "audit_id": audit_id, "path": path}})
    return {"ok": True, "did": "h1_fix", "wat": wat}


def _agent_fix_links(path: str, code: str, audit_id: str, reasoning: str, evidence: dict) -> dict:
    """Herschrijf interne links die naar een redirect wijzen naar het eindadres.

    links3xx stond bij Handwerk, maar het CMS kent allebei de kanten: de blokken
    én de redirect-tabel. Opzoeken en vervangen dus — geen AI, geen oordeel
    (Ryan 2026-08-25). Ketens worden tot het eind gevolgd; een redirect-lus is
    niet veilig te herschrijven en blijft staan. Met en zonder slotslash."""
    slug = (path or "").strip("/") if path != "/" else ""
    page = _get_page(slug)
    if not page:
        return {"ok": False, "did": "link_fix", "error": "pagina heeft geen bewerkbare record"}
    blocks = page.get("content_blocks") or []
    if not isinstance(blocks, list):
        return {"ok": False, "did": "link_fix", "error": "pagina heeft geen blokken"}
    if _pagina_is_client_gerenderd(path):
        return {"ok": False, "did": "link_fix",
                "error": "pagina is client-gerenderd — de crawler ziet deze links niet, "
                         "een blok-herschrijving lost de melding niet op"}
    rmap = {}
    for r in (_redirects_index() or []):
        f = _audit_url_naar_pad(r.get("from_path") or "")
        t = _audit_url_naar_pad(r.get("to_path") or "")
        if f and t and f != t:
            rmap[f] = t

    def _eindadres(p):
        gezien = set()
        while p in rmap:
            if p in gezien:
                return ""   # lus — niet veilig te herschrijven
            gezien.add(p)
            p = rmap[p]
        return p

    telling = 0

    def _herschrijf(v):
        nonlocal telling
        if isinstance(v, dict):
            return {k: _herschrijf(x) for k, x in v.items()}
        if isinstance(v, list):
            return [_herschrijf(x) for x in v]
        if isinstance(v, str) and v and rmap:
            nieuw = v
            for f in rmap:
                doel = _eindadres(f)
                if not doel:
                    continue
                kaal = f.rstrip("/") or f
                for oud in {f, kaal}:
                    for patroon in (f'href="{oud}"', f"href='{oud}'"):
                        n = nieuw.count(patroon)
                        if n:
                            nieuw = nieuw.replace(patroon, patroon.replace(oud, doel))
                            telling += n
                    if nieuw == oud:   # kaal url-veld (bv. props.url van een knop)
                        nieuw = doel
                        telling += 1
            return nieuw
        return v

    voor = json.loads(json.dumps(blocks))
    blocks = _herschrijf(blocks)
    if not telling:
        return {"ok": False, "did": "link_fix", "error": "geen interne links naar een redirect gevonden"}
    page["content_blocks"] = blocks
    _save_page(page)
    update_seo_score(page)
    _trigger_deploy(f"seo agent link-fix {slug or 'home'}")
    titel = page.get("title", "") or slug or "Home"
    audit_log("seo.linkfix", slug or "home", f"{telling} link(s) naar het eindadres herschreven")
    _seo_log("link_fix", path, titel, f"{telling} link(s) herschreven")
    ev = dict(evidence or {})
    ev.update({"audit_code": code, "audit_id": audit_id, "herschreven": telling})
    _seo_decision_add("link_fix", path, titel, reasoning=reasoning, evidence=ev, risk=1,
                      status="uitgevoerd", source="agent",
                      undo={"type": "blocks", "slug": slug, "content_blocks": voor},
                      extra={"audit_issue": {"code": code, "audit_id": audit_id, "path": path}})
    return {"ok": True, "did": "link_fix", "herschreven": telling}


def _agent_publicaties_vandaag() -> int:
    """Nieuwe pagina's en blogs van de agent van vandaag — het plafond staat op dit type,
    niet op alle acties: een meta-titel bijschaven is iets anders dan een blog publiceren."""
    today = datetime.now().strftime("%Y-%m-%d")
    return len([d for d in _seo_decisions()
                if d.get("source") == "agent" and str(d.get("at", ""))[:10] == today
                and d.get("action") in ("new_page", "new_blog")])


def _agent_system_prompt(cfg: dict) -> str:
    """De agent-systemprompt. Het vrije instructieveld dat hier ooit in werd gevoegd is
    geschrapt (Ryan 2026-08-26: ruis en frictie) — een ooit opgeslagen tekst mag de
    agent ook niet onzichtbaar blijven sturen, dus de injectie is er helemaal uit."""
    return _AGENT_SYSTEM.format(biz=_seo_business_context())


def _audit_actie_kan_op_pad(actie: str, pad: str) -> str:
    """Lege string = mag; anders de reden waarom niet."""
    soort, _rec = _bijzondere_content(pad)
    if actie in _AUDIT_ALLEEN_OP_PAGINA and soort:
        wat = "Een project" if soort == "project" else "Een blogartikel"
        return (f"Op deze pagina's is alleen meta-werk mogelijk. {wat} rendert zijn kop en de "
                "alt-tekst uit de eigen titel, en een interne link zou naar het verkeerde adres "
                "wijzen. Pas dit met de hand aan.")
    if actie in ("h1_fix", "alt_fix", "link_fix", "extlink_fix", "h1_rewrite") and _pagina_is_client_gerenderd(pad):
        return ("Deze pagina bouwt zijn inhoud pas in de browser op. De crawler ziet die inhoud "
                "niet, dus meldt hij dit ook als het op de pagina gewoon goed staat — en een blok "
                "toevoegen lost het niet op. Controleer het met de hand in de browser.")
    return ""


def _audit_afgehandeld_index(audit_id: str) -> dict:
    """{code: {paden}} van fixes die voor déze audit al zijn uitgevoerd.

    De issue-lijst komt uit de laatste crawl en verandert pas bij de volgende — tot
    die tijd deed het scherm alsof álles nog openstond, ook wat de agent allang had
    gefixt. Alleen status "uitgevoerd" telt (wacht_op_review/afgewezen/teruggedraaid
    is niet af), en een fix die de crawler al als "nog_aanwezig" beoordeelde ook niet.
    """
    uit = {}
    if not audit_id:
        return uit
    for d in _seo_decisions():
        ai = d.get("audit_issue")
        if (not isinstance(ai, dict) or d.get("status") != "uitgevoerd"
                or str(ai.get("audit_id") or "") != str(audit_id)
                or ai.get("result") == "nog_aanwezig" or not ai.get("code")):
            continue
        pad = ai.get("path") or d.get("path") or ""
        if pad:
            uit.setdefault(ai["code"], set()).add(pad)
    return uit


def _audit_agent_taken(cfg: dict) -> list:
    """De fixbare crawl-issues als concrete taken: één per (code, pad).

    Hier vallen de guardrails al: uitgesloten paden, paden die niet als pagina bestaan, en de
    dedupe van 14 dagen. De agent krijgt dus alleen werk voorgeschoteld dat `_agent_guard`
    straks ook echt doorlaat — anders vult hij zijn twee acties per beurt met voorstellen die
    daarna alsnog sneuvelen.
    """
    try:
        oogst = _seranking_audit_issues()
    except Exception as e:
        print(f"[audit-issues] taken opbouwen mislukt: {e}")
        return []
    excl = set(cfg.get("excluded_paths") or [])
    known = _agent_known_paths()
    taken = []
    for issue in oogst.get("fixbaar") or []:
        actie = issue.get("actie") or ""
        for pad in issue.get("paden") or []:
            # Een redirect-pad (404, oud adres) bestaat per definitie NIET als pagina;
            # de known-filter zou de hele http4xx-mapping tot dode letter maken.
            if pad in excl or (pad not in known and actie != "redirect"):
                continue
            if _agent_recent_same(actie, pad):
                continue
            if _audit_actie_kan_op_pad(actie, pad):
                continue
            taken.append({"type": actie, "path": pad, "audit_code": issue["code"],
                          "audit_id": issue.get("audit_id", ""), "audit_naam": issue.get("naam", ""),
                          "status": issue.get("status", ""), "sectie": issue.get("sectie", "")})
    # Fouten vóór waarschuwingen vóór notices: de agent ziet het zwaarste werk bovenaan.
    rang = {"error": 0, "warning": 1, "notice": 2}
    taken.sort(key=lambda t: rang.get(t.get("status", ""), 3))
    return taken[:20]


def _audit_annoteer_afgehandeld(oogst: dict) -> dict:
    """Zet per fixbare rij hoeveel van de gemelde paden al zijn opgepakt."""
    klaar = _audit_afgehandeld_index(str(oogst.get("audit_id") or ""))
    for rij in oogst.get("fixbaar") or []:
        af = klaar.get(rij.get("code"), set())
        rij["afgehandeld"] = len(af & set(rij.get("paden") or []))
    return oogst


def _audit_buiten_bereik(cfg: dict) -> list:
    """Fixbaar werk uit de crawl dat op een pad ligt dat de agent NIET kan bewerken.

    Live gebleken op deze site: van de 15 fixbare paden waren er 14 `/projecten/…` — die zijn
    project-records (`projects:index`), geen pagina-records, en `_seo_improve_page` kan er dus
    niets mee. `_audit_agent_taken` filtert ze weg, en zonder deze lijst zou dat betekenen dat
    14 pagina's met een dubbele meta-omschrijving volledig van de radar verdwijnen — precies het
    liggenblijvende werk dat deze hele laag zichtbaar hoort te maken.

    Uitgesloten paden tellen NIET mee: dat is een bewuste keuze van het bureau, geen gat.
    """
    try:
        oogst = _seranking_audit_issues()
    except Exception:
        return []
    excl = set(cfg.get("excluded_paths") or [])
    known = _agent_known_paths()
    uit = []
    for issue in oogst.get("fixbaar") or []:
        actie = issue.get("actie", "")
        GEEN_RECORD = ("Deze pagina's hebben geen bewerkbaar record in het CMS (bijvoorbeeld een "
                       "blogartikel of een statische pagina uit de export). De agent kan er niets "
                       "aan veranderen \u2014 pas dit met de hand aan.")
        per_reden = {}
        for p in (issue.get("paden") or []):
            if p in excl:
                continue
            # Redirect-paden zonder record zijn géén buiten-bereik: daar maakt de agent
            # juist een voorstel voor. "Geen bewerkbaar record" zou hier misleiden.
            reden = (GEEN_RECORD if (p not in known and actie != "redirect")
                     else _audit_actie_kan_op_pad(actie, p))
            if reden:
                per_reden.setdefault(reden, []).append(p)
        for reden, paden in per_reden.items():
            uit.append({"code": issue["code"], "naam": issue.get("naam", ""), "actie": actie,
                        "status": issue.get("status", ""), "aantal": len(paden),
                        "paden": paden[:12], "waarom": reden})
    return uit


def _audit_catalogus_vingerafdruk() -> str:
    """Korte hash van de indelingsregels. Gaat mee in de cache-geldigheid, want de oogst is
    niet alleen een kopie van de crawl maar ook onze INDELING ervan. Zonder dit bleef een
    gecorrigeerde catalogus tot 12 uur onzichtbaar: de crawl was immers niet veranderd, dus
    de cache gold nog — precies wat er live gebeurde toen `no_inlinks` van melding naar
    agent-werk verhuisde."""
    ruw = repr(sorted(_AUDIT_ISSUE_CATALOGUS.items())) + repr(sorted(_AUDIT_MELDING_REDENEN))
    return hashlib.sha1(ruw.encode()).hexdigest()[:10]


def _audit_checks_uit_rapport(rapport) -> list:
    """Alle checks met value > 0 uit een audit-rapport, nieuwste vorm eerst.

    `sections` is een array van {uid, name, props{}}; elke prop is {code, status, name, value}.
    `value` is het aantal getroffen pagina's — 0 betekent "gecontroleerd en in orde" en is dus
    geen werkvoorraad. Een object in plaats van een array wordt ook gelezen.
    """
    if not isinstance(rapport, dict):
        return []
    secties = rapport.get("sections")
    if isinstance(secties, dict):
        secties = list(secties.values())
    if not isinstance(secties, list):
        return []
    uit = []
    for sec in secties:
        if not isinstance(sec, dict):
            continue
        sectienaam = str(sec.get("name") or sec.get("uid") or "")
        props = sec.get("props")
        if not isinstance(props, dict):
            continue
        for sleutel, prop in props.items():
            if not isinstance(prop, dict):
                continue
            try:
                aantal = int(prop.get("value") or 0)
            except Exception:
                aantal = 0
            if aantal <= 0:
                continue
            code = str(prop.get("code") or sleutel or "").strip().lower()
            if not code:
                continue
            uit.append({"code": code, "status": str(prop.get("status") or ""),
                        "naam": str(prop.get("name") or code), "aantal": aantal,
                        "sectie": sectienaam})
    return uit


def _audit_fix_resultaten(days: int = 90) -> dict:
    """Leren: hoe vaak loste een crawl-fix het gemelde issue écht op? Gaat mee in de context."""
    cutoff = (datetime.now() - timedelta(days=days)).strftime("%Y-%m-%d")
    uit = {"opgelost": 0, "nog_aanwezig": 0, "in_afwachting": 0}
    for d in _seo_decisions():
        ai = d.get("audit_issue")
        if not isinstance(ai, dict) or str(d.get("at", ""))[:10] < cutoff:
            continue
        res = ai.get("result")
        if res in ("opgelost", "nog_aanwezig"):
            uit[res] += 1
        elif d.get("status") == "uitgevoerd":
            uit["in_afwachting"] += 1
    return uit


def _audit_issue_actie(code: str) -> str:
    """De agent-actie voor één issue-code, of "" als het CMS dit niet zelf kan repareren."""
    return _AUDIT_ISSUE_CATALOGUS.get(str(code or "").strip().lower(), "")


def _audit_paden_uit_antwoord(data) -> list:
    """De `urls` uit een issue-pages-antwoord naar site-paden.

    `urls_type` is gedocumenteerd als "simple_urls_array" — een platte lijst strings. Dat veld
    zou niet bestaan als dat de enige vorm was, dus verdragen we hier ook objecten met een
    url-veld en geneste lijstjes (zoals een duplicaat-groep). Onbekende vormen worden stil
    overgeslagen: liever een issue minder dan een agent die op een verzonnen pad losgaat.
    """
    if not isinstance(data, dict):
        return []
    uit, gezien = [], set()

    def _voeg_toe(v):
        if isinstance(v, str):
            p = _audit_url_naar_pad(v)
        elif isinstance(v, dict):
            p = _audit_url_naar_pad(v.get("url") or v.get("page") or v.get("link") or "")
        elif isinstance(v, (list, tuple)):
            for x in v:
                _voeg_toe(x)
            return
        else:
            return
        if p and p not in gezien:
            gezien.add(p)
            uit.append(p)

    _voeg_toe(data.get("urls") or [])
    return uit[:AUDIT_ISSUE_PADEN_MAX]


def _audit_url_naar_pad(url: str) -> str:
    """Een gecrawlde URL naar het site-pad zoals `_agent_known_paths()` het kent: met slotslash,
    de homepage als "/". Zonder deze normalisatie matcht geen enkel pad uit de crawl op onze
    eigen paden en keurt de guard élke audit-actie af als 'bestaat niet op de site'."""
    v = str(url or "").strip()
    if not v:
        return ""
    if "//" in v:
        try:
            v = urllib.parse.urlparse(v).path or "/"
        except Exception:
            return ""
    v = v.split("?")[0].split("#")[0]
    if not v.startswith("/"):
        v = "/" + v
    return v if v.endswith("/") else v + "/"


def _bijzondere_content(path: str):
    """(soort, record) voor content die GEEN pagina-record is: ("project"|"blog", rec).

    Eén plek waar staat welke soorten er nog meer zijn. De guard, de takenlijst en de
    uitvoering leunen hier alle drie op; zouden ze elk hun eigen check doen, dan lopen ze
    gegarandeerd uit elkaar zodra er een vierde soort bij komt.
    """
    pr = _project_by_path(path)
    if pr:
        return "project", pr
    po = _post_by_path(path)
    if po:
        return "blog", po
    return None, None


def _blok_is_h1(b: dict) -> bool:
    """Telt dit blok als H1? Twee vormen naast elkaar: het losse `heading-h1`-type en het
    generieke `heading` met level h1 (zie normalize_block)."""
    if not isinstance(b, dict):
        return False
    t = b.get("type", "")
    if t == "heading-h1":
        return True
    if t != "heading":
        return False
    lvl = (b.get("props") or {}).get("level") or b.get("level") or "h2"
    return str(lvl).lower() == "h1"


def _blok_zet_level(b: dict, level: str) -> None:
    """Zet het kopniveau in béide vormen die de editor kan opslaan (platte key én props)."""
    if b.get("type") == "heading-h1" and level != "h1":
        b["type"] = "heading"
    if isinstance(b.get("props"), dict):
        b["props"]["level"] = level
    if "level" in b or not isinstance(b.get("props"), dict):
        b["level"] = level


def _dode_externe_links(path: str) -> list:
    """De bewijsbaar kapotte externe links op één pagina (status >= 400).

    Verifieert ZELF, op voorstel-moment: de audit zegt alleen dát er iets kapot is,
    niet wat — en een voorstel hoort de exacte URL's te dragen die jij goedkeurt.
    Twijfel (timeout, netwerkfout) telt niet als kapot; max 10 checks per pagina."""
    slug = (path or "").strip("/") if path != "/" else ""
    page = _get_page(slug)
    if not page:
        return []
    eigen_host = re.sub(r"^www\.", "", urllib.parse.urlparse(CANONICAL_BASE).netloc.lower())
    urls, gezien = [], set()

    def _verzamel(v):
        if isinstance(v, dict):
            for k, x in v.items():
                if k in ("href", "src", "url") and isinstance(x, str) and x.startswith("http"):
                    _voeg(x)
                else:
                    _verzamel(x)
        elif isinstance(v, list):
            for x in v:
                _verzamel(x)
        elif isinstance(v, str):
            for m in re.finditer(r'href=["\'](https?://[^"\']+)["\']', v):
                _voeg(m.group(1))

    def _voeg(u):
        host = re.sub(r"^www\.", "", urllib.parse.urlparse(u).netloc.lower())
        if host and host != eigen_host and u not in gezien:
            gezien.add(u)
            urls.append(u)

    _verzamel(page.get("content_blocks") or [])
    return [u for u in urls[:10] if _extlink_status(u) >= 400]


def _domein_tick() -> bool:
    """Dagelijks (gedebounced): registratiestatus van het eigen domein via RDAP. Een
    verloopdatum publiceert niet elke registry (.nl bijvoorbeeld niet) — dan alleen de
    status, eerlijk zonder verzonnen datum."""
    vandaag = datetime.now().strftime("%Y-%m-%d")
    cache = kv_get("monitor:domein") or {}
    if str(cache.get("at", ""))[:10] == vandaag:
        return False
    host = re.sub(r"^https?://", "", (_public_base() or "")).split("/")[0]
    dom = re.sub(r"^www\.", "", host)
    if not dom:
        return False
    r = _rdap_ophalen(dom)
    if not isinstance(r, dict) or not (r.get("status") or r.get("ldhName") or r.get("events")):
        return False
    uit = {"at": _now_iso(), "domein": dom, "status": "actief"}
    try:
        for ev in (r.get("events") or []):
            if ev.get("eventAction") == "expiration" and ev.get("eventDate"):
                verval = datetime.strptime(str(ev["eventDate"])[:10], "%Y-%m-%d")
                uit["verloopt"] = verval.strftime("%Y-%m-%d")
                uit["dagen"] = max(0, (verval - datetime.now()).days)
                break
    except Exception:
        pass
    kv_set("monitor:domein", uit)
    return True


def _extlink_status(url: str) -> int:
    """HTTP-status van een externe link; 0 bij elke netwerkstoring. Apart houdbaar
    (en mockbaar): een timeout is geen bewijs dat een link kapot is."""
    try:
        req = urllib.request.Request(url, method="HEAD",
                                     headers={"User-Agent": "Mozilla/5.0 (DamHousingLinkCheck)"})
        with urllib.request.urlopen(req, timeout=4) as r:
            return int(r.status or 0)
    except urllib.error.HTTPError as e:
        return int(e.code or 0)
    except Exception:
        return 0


def _gbp_clean_ai_text(text: str) -> str:
    """Maakt AI-tekst 'menselijk' volgens de huisstijl: geen emoji, geen em/en-dashes."""
    t = str(text or "")
    t = t.replace(" — ", ", ").replace("—", "-").replace(" – ", ", ").replace("–", "-")
    # Emoji en pictogrammen weg (incl. variation selector en dingbats).
    t = re.sub("[\U0001F000-\U0001FAFF\U0001F1E6-\U0001F1FF☀-➿⬀-⯿️]", "", t)
    return re.sub(r"  +", " ", t).strip()


def _gbp_crosspost(kind: str, titel: str, pad: str) -> bool:
    """Nieuwe site-content = een kant-en-klaar GBP-postvoorstel in de wachtrij
    (draft, review-first): verse content krijgt direct zichtbaarheid terwijl de
    indexering nog loopt. Faalt STIL — een haperende postgenerator mag een
    publicatie nooit blokkeren — en nooit twee voorstellen voor dezelfde pagina."""
    try:
        gb = get_settings().get("google_business") or {}
        if not (gb.get("account") and gb.get("location")) or not _ai_configured():
            return False
        base = _public_base()
        if not base.startswith("http"):
            return False
        cta = base + pad
        q = gbp_get_queue()
        if any(isinstance(it, dict) and it.get("theme") == "nieuw" and it.get("cta_url") == cta for it in q):
            return False
        soort = "blogartikel" if kind == "blog" else "pagina"
        system = (
            "Je schrijft namens DAM Housing (vloerenbedrijf in Culemborg en regio Rivierenland) één korte Google "
            "Bedrijfsprofiel-post (40-70 woorden, Nederlands) die aankondigt dat er iets nieuws op de "
            "site staat, en uitnodigt om het via de knop te lezen. Natuurlijk vakman-Nederlands; "
            "gebruik geen emoji, geen em- of en-dashes, geen hashtags, geen clichés. Verzin geen "
            "feiten, prijzen of acties. Antwoord UITSLUITEND met de posttekst zelf.")
        user = f'Er staat een nieuw {soort} op de site: "{(titel or "").strip()[:120]}" ({pad}). Schrijf de post.'
        r = _anthropic_call([{"role": "user", "content": user}], system=system,
                            max_tokens=350, model="claude-haiku-4-5-20251001")
        if r.get("error"):
            return False
        tekst = _gbp_clean_ai_text("".join(b.get("text", "") for b in r.get("content", [])).strip().strip('"'))
        if not tekst:
            return False
        imgs = [m for m in _gbp_filter_fotokwaliteit(_ai_context_media(40))
                if m.get("url", "").lower().endswith((".jpg", ".jpeg", ".png"))]
        q.append({
            "id": uuid.uuid4().hex[:12], "status": "draft",
            "scheduled_at": (datetime.now() + timedelta(days=1)).replace(
                hour=10, minute=0, second=0, microsecond=0).isoformat(timespec="seconds"),
            "created_by": "ai", "created_at": _now_iso(),
            "summary": tekst, "topic_type": "STANDARD",
            "media_url": (imgs[0]["url"] if imgs else ""),
            "cta_type": "LEARN_MORE", "cta_url": cta, "theme": "nieuw",
        })
        gbp_save_queue(q)
        try:
            audit_log("gbp.crosspost", "gbp", f"Postvoorstel voor nieuw {soort}: {(titel or '')[:60]}")
        except Exception:
            pass
        return True
    except Exception:
        return False


def _gbp_filter_fotokwaliteit(kandidaten: list, max_probes: int = 12) -> list:
    """Weer kleine plaatjes (icons, thumbnails, troep) uit de fotokandidaten.

    De mediabibliotheek kent van externe foto's geen bestandsgrootte, dus we meten de
    échte afmetingen en hanteren Googles ondergrens voor postfoto's (~400x300, ~10kB).
    Eén meting per URL (KV-cache gbp:fotometa:cache) met een meetbudget per run; wat
    (nog) niet gemeten is laten we dóór — een netwerkfout mag de lijst niet leegtrekken,
    dan zouden posts weer stil zonder beeld verschijnen."""
    try:
        cache = kv_get("gbp:fotometa:cache") or {}
    except Exception:
        cache = {}
    if not isinstance(cache, dict):
        cache = {}
    gewijzigd, probes, goed = False, 0, []
    for m in (kandidaten or []):
        url = (m or {}).get("url") or ""
        if not url:
            continue
        meta = cache.get(url)
        if meta is None and probes < max_probes:
            probes += 1
            meta = _gbp_meet_foto(url)
            cache[url] = meta
            gewijzigd = True
        meta = meta if isinstance(meta, dict) else {}
        w, h = meta.get("w") or 0, meta.get("h") or 0
        kb = meta.get("kb") or 0
        if w and h and (w < 400 or h < 300):
            continue
        if kb and kb < 10:
            continue
        goed.append(m)
    if gewijzigd:
        try:
            if len(cache) > 300:
                cache = dict(list(cache.items())[-300:])
            kv_set("gbp:fotometa:cache", cache)
        except Exception:
            pass
    return goed


def _gbp_img_afmetingen(data: bytes):
    """(breedte, hoogte) uit de eerste bytes van een PNG/GIF/JPEG, of None.
    Stdlib-only — de serverless build heeft geen PIL, en de header volstaat."""
    try:
        if data[:8] == b"\x89PNG\r\n\x1a\n" and len(data) >= 24:
            return int.from_bytes(data[16:20], "big"), int.from_bytes(data[20:24], "big")
        if data[:6] in (b"GIF87a", b"GIF89a") and len(data) >= 10:
            return int.from_bytes(data[6:8], "little"), int.from_bytes(data[8:10], "little")
        if data[:2] == b"\xff\xd8":
            i, n = 2, len(data)
            while i + 9 < n:
                if data[i] != 0xFF:
                    i += 1
                    continue
                marker = data[i + 1]
                if marker in (0xD8, 0x01) or 0xD0 <= marker <= 0xD7:
                    i += 2
                    continue
                seglen = int.from_bytes(data[i + 2:i + 4], "big")
                # SOF0..SOF15 minus DHT/JPG/DAC dragen de afmetingen
                if 0xC0 <= marker <= 0xCF and marker not in (0xC4, 0xC8, 0xCC):
                    if i + 9 <= n:
                        return (int.from_bytes(data[i + 7:i + 9], "big"),
                                int.from_bytes(data[i + 5:i + 7], "big"))
                    break
                i += 2 + seglen
    except Exception:
        pass
    return None


def _gbp_in_periode(tijd: str, frm: str, to: str) -> bool:
    """Valt een Google-tijdstempel (RFC3339) binnen het rapportbereik? Zonder bereik: ja."""
    d = str(tijd or "")[:10]
    if not d:
        return False
    if frm and d < frm:
        return False
    if to and d > to:
        return False
    return True


def _gbp_meet_foto(url: str) -> dict:
    """Meet één foto: {"w","h","kb"} (deels gevuld mag) of {} als het niet lukt.
    Leest hooguit de eerste 64kB — genoeg voor de header, goedkoop voor de cron."""
    try:
        u = url or ""
        if u.startswith("/"):
            u = _public_base() + u
        req = urllib.request.Request(u, headers={"Range": "bytes=0-65535",
                                                 "User-Agent": "Mozilla/5.0 (MHS-CMS fotocheck)"})
        with urllib.request.urlopen(req, timeout=6) as r:
            data = r.read(65536)
            cr = r.headers.get("Content-Range", "")
            totaal = 0
            if "/" in cr:
                try:
                    totaal = int(cr.rsplit("/", 1)[-1])
                except Exception:
                    totaal = 0
            if not totaal:
                try:
                    cl = int(r.headers.get("Content-Length") or 0)
                except Exception:
                    cl = 0
                # Zonder Content-Range is Content-Length alleen het totaal als de server
                # de Range negeerde; bij precies 64kB weten we het niet zeker → weglaten.
                if cl and cl != 65536:
                    totaal = cl
                elif len(data) < 65536:
                    totaal = len(data)
        uit = {}
        afm = _gbp_img_afmetingen(data)
        if afm:
            uit["w"], uit["h"] = afm
        if totaal:
            uit["kb"] = round(totaal / 1024, 1)
        return uit
    except Exception:
        return {}


def _gsc_gateway(actie: str, **lading):
    """Search Console via het teamaccount bij MAIHS. Returns (data, fout).

    Zo hoeft deze site geen eigen Google-koppeling te hebben: de gateway doet het met één
    centraal token en geeft ons alleen ons eigen domein — dat haalt hij uit zijn eigen
    administratie, niet uit wat wij meesturen.
    """
    basis, sleutel = _gateway_origin(), _gateway_key()
    if not (basis and sleutel):
        return None, "Geen gateway geconfigureerd"
    try:
        req = urllib.request.Request(
            basis + "/api/gateway/gsc",
            data=json.dumps({"actie": actie, **lading}).encode(), method="POST",
            headers={"Authorization": "Bearer " + sleutel, "Content-Type": "application/json",
                     "User-Agent": "MAIHS-Gateway-Client/1.0"})
        with urllib.request.urlopen(req, timeout=45) as r:
            return json.loads(r.read().decode() or "{}"), ""
    except urllib.error.HTTPError as e:
        rauw = e.read().decode("utf-8", "replace")[:300]
        try:
            return None, str(json.loads(rauw).get("message") or rauw)
        except Exception:
            return None, f"{e.code}: {rauw}"
    except Exception as e:
        return None, str(e)


def _gsc_sitemap_indienen() -> tuple:
    """Meldt de sitemap aan bij Search Console. Geeft (gelukt, melding).

    De oude weg — google.com/ping?sitemap=… — heeft Google in 2023 uitgezet; die
    aanroep hierboven kan dus nooit meer slagen. Met een gekoppelde property is dit
    de manier die wél werkt, en hij hoort automatisch te gebeuren: een sitemap die
    je zelf moet indienen wordt vergeten zodra er pagina's bijkomen.
    """
    site = str((get_settings().get("search_console") or {}).get("site") or "")
    if not site:
        return False, "geen Search Console-property ingesteld"
    tok = google_access_token("search_console")
    if not tok:
        return False, "Search Console niet verbonden"
    sitemap = (_public_base() or "").rstrip("/") + "/sitemap.xml"
    url = ("https://www.googleapis.com/webmasters/v3/sites/" + urllib.parse.quote(site, safe="")
           + "/sitemaps/" + urllib.parse.quote(sitemap, safe=""))
    try:
        req = urllib.request.Request(url, method="PUT", headers={"Authorization": "Bearer " + tok})
        with urllib.request.urlopen(req, timeout=20) as r:
            r.read()
    except urllib.error.HTTPError as e:
        return False, f"{e.code}: {e.read().decode('utf-8', 'replace')[:160]}"
    except Exception as e:
        return False, str(e)
    meta = kv_get("sitemap:meta", {}) or {}
    ingediend = meta.get("last_pinged", {}) or {}
    ingediend["google"] = _now_iso()
    meta["last_pinged"] = ingediend
    kv_set("sitemap:meta", meta)
    return True, sitemap


def _haal_pagina_html(pad: str):
    """De geserveerde HTML van één pad, of None als het niet lukte. Bewust GEEN JS-uitvoering:
    dit moet precies zien wat een crawler ziet."""
    basis = (_public_base() or "").rstrip("/")
    if not basis.startswith("http"):
        return None
    url = basis + (pad if pad.startswith("/") else "/" + pad)
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "MAIHS-H1-Check/1.0"})
        with urllib.request.urlopen(req, timeout=10) as r:
            return r.read(400000).decode("utf-8", "replace")
    except Exception:
        return None


def _huidige_maker() -> str:
    """Weergavenaam van wie er nu is ingelogd, voor 'aangemaakt door' op de kaartregel.
    Team-SSO geeft een echte naam (voornaam is genoeg); het gedeelde admin-account
    is geen persoon en buiten een request (cron) is er niemand — dan leeg."""
    try:
        naam = str(session.get("sso_name") or "").strip()
        if naam:
            return naam.split()[0]
        u = str(session.get("user") or "").strip()
        return u if u and u != "admin" else ""
    except Exception:
        return ""


def _klantformulering(tekst: str) -> str:
    """Herschrijft interne motortaal naar de wij-vorm van het rapport.

    De onderbouwing bij een beslissing is voor onszelf geschreven en zegt dingen als "de agent
    heeft dit automatisch aangepast". In een rapport aan de klant leest dat als machine-output
    en haalt het onderuit dat dit óns werk is. Filteren aan de rand is veiliger dan hopen dat
    elke bron netjes formuleert: de onderbouwing komt uit een taalmodel en is niet te sturen."""
    t = str(tekst or "").strip()
    if not t:
        return ""
    machine = r"(?:seo-)?(?:agent|systeem|motor|a\.?i\.?)"
    I = re.IGNORECASE
    regels = [
        (r"\b(?:de|het)\s+" + machine + r"\s+heeft\b", "we hebben", I),
        (r"\b(?:de|het)\s+" + machine + r"\s+(?:zag|ziet|zei|besloot)\b", "we zagen", I),
        (r"\bdoor\s+(?:de|het)\s+" + machine + r"\b", "door ons", I),
        (r"\b(?:de|het)\s+" + machine + r"\b", "we", I),
        (r"\bautomatis\w*\s*", "", I),
        (r"\bgegenereerd\w*\b", "gemaakt", I),
        (r"\brobot\w*\s*", "", I),
        (r"\bscript\w*\s*", "", I),
        (r"\bagent\w*\b", "we", I),
        (r"\bA\.?I\.?[-\u2011]", "", 0),      # 'AI-voorstel' -> 'voorstel'
        (r"\bA\.?I\.?\b", "", 0),             # hoofdlettergevoelig: anders sneuvelt 'ai' in woorden
        # Crawler-jargon (Ryan 2026-08-25): audit_id, audit_code, description_duplicate en
        # crawl-taak interesseren een klant niet \u2014 vertalen of weglaten.
        # Ook de koppelteken- en spatievariant: '(audit-id 323263, warning)' lekte
        # door terwijl alleen audit_id gedekt was (Ryan 2026-08-25).
        (r"\(?\s*\baudit[-_\s]?id\b[\s:]*\d*\s*\)?", "", I),
        (r"\baudit_code\b[\s:]*", "", I),
        # Engelse severity-woorden uit de crawler horen niet in klanttaal.
        (r"\bwarnings?\b", "aandachtspunt", I),
        (r"\berrors?\b", "fout", I),
        (r"\bnotices?\b", "opmerking", I),
        # 'uit audit 323263' lekte alsnog door (Morris 2026-08-25): eerst de hele
        # frase weg, dan een los overgebleven 'audit 123' vertalen.
        (r"\s*\buit\s+audit\s+\d+\b", "", I),
        (r"\baudit\s+\d+\b", "de sitecontrole", I),
        (r"\bdescription_duplicate\b", "dubbele paginaomschrijving", I),
        (r"\bduplicate\s+descriptions?\b", "dubbele paginaomschrijving", I),
        (r"\bmeta_description\b", "paginaomschrijving", I),
        (r"\bgeverifieerde\s+crawl[-_]?taak\b", "controlepunt", I),
        # 'taak uit onze werklijst', niet kaal 'onze werklijst': dat gaf woordsalade
        # als 'Kant-en-klare onze werklijst'.
        (r"\bcrawl[-_]?taak\b", "taak uit onze werklijst", I),
        (r"\bcrawl[-_]?taken\b", "taken uit onze werklijst", I),
        (r"\bcrawls?\b", "sitecontrole", I),
        (r"\binbound\s+links?\b", "links vanaf andere pagina's", I),
    ]
    for patroon, vervanging, vlaggen in regels:
        t = re.sub(patroon, vervanging, t, flags=vlaggen)
    t = re.sub(r"\(\s*[,;]?\s*\)", "", t)      # lege haakjes die na het strippen overblijven
    t = re.sub(r"\(\s*[,;]\s*", "(", t)
    t = re.sub(r"\s{2,}", " ", t).replace(" ,", ",").replace(" .", ".").strip(" -\u2013\u2014,")
    return (t[:1].upper() + t[1:]) if t else ""


def _kw_sleutel(term: str) -> frozenset:
    """De zoekvraag achter een term: dezelfde woorden in een andere volgorde is dezelfde vraag."""
    woorden = re.findall(r"[a-z0-9]+", (term or "").lower())
    kern = [w for w in woorden if w not in _KW_VULWOORDEN]
    return frozenset(kern or woorden)


def _kw_onderwerpen(termen: list) -> dict:
    """Per term het ONDERWERP waar hij bij hoort: {term: frozenset(twee kernwoorden)}.

    `_kw_sleutel` beantwoordt "is dit dezelfde zoekvraag". Dit beantwoordt de grovere vraag
    "gaat dit over hetzelfde". Dat verschil is precies waar het misging: "<dienst> droogtijd",
    "<dienst> tips" en "<dienst> kosten" zijn drie verschillende zoekvragen, dus `_kw_sleutel`
    liet ze alle drie door — terwijl het voor de klant één onderwerp is. Zo ging op een
    zustersite de hele focuslijst, en daarmee het hele klantrapport, over één dienst
    (Ryan 2026-08-26).

    Het onderwerp is per term het paar woorden dat in DEZE lijst het vaakst voorkomt. Bewust
    geen woordenlijst per branche: op de ene site zit hetzelfde vakwoord in elke term, op een
    vloersite bijvoorbeeld 'vloer'. Door binnen de lijst te tellen zakt het gemeenschappelijke woord vanzelf naar zijn
    plek en blijft er onderscheid over ('vloer egaliseren' vs 'vloer schuren'), terwijl één
    kernwoord ('vloer') die site juist op één hoop zou gooien.
    """
    schoon, telling = {}, {}
    for t in termen or []:
        sleutel = str(t or "")
        woorden = [w for w in re.findall(r"[a-z0-9]+", sleutel.lower())
                   if w not in _KW_VULWOORDEN]
        schoon[sleutel] = woorden
        for w in set(woorden):
            telling[w] = telling.get(w, 0) + 1
    uit = {}
    for sleutel, woorden in schoon.items():
        # Vaakst voorkomend eerst, bij gelijke stand alfabetisch — anders hangt de uitkomst
        # af van de volgorde waarin de termen binnenkwamen.
        kern = sorted(set(woorden), key=lambda w: (-telling.get(w, 0), w))[:2]
        uit[sleutel] = frozenset(kern or [sleutel.strip().lower()])
    return uit


def _spreid_over_onderwerpen(rijen: list, sleutel_van, onderwerpen: dict, cap: int,
                             per_onderwerp: int = 3, ondergrens: int = 5) -> list:
    """Eerst van elk onderwerp de beste rij, dan pas de tweede van een onderwerp, enzovoort.

    De binnenkomende volgorde is de rangorde en blijft binnen elke ronde intact, dus de best
    scorende rij staat nog steeds bovenaan. Alleen de VERDRINGING verdwijnt: één onderwerp kan
    de lijst niet meer volledig vullen zolang er andere onderwerpen op de plank liggen.

    `per_onderwerp` is de bovengrens per onderwerp. Rondlopen alléén is namelijk niet genoeg:
    met vier andere onderwerpen en tien termen over hetzelfde onderwerp vult dat onderwerp
    nog steeds zes van de tien regels, want na ronde 1 is er niks anders meer om mee af te wisselen. Drie regels is
    genoeg om te laten zien dat we op een onderwerp sturen; de rest zegt niets nieuws.

    `ondergrens` is de terugvalklep: liever een iets eenzijdiger tabel dan een tabel van twee
    regels. Blijven er na het quotum minder dan zoveel rijen over, dan vullen we alsnog aan uit
    wat er ligt, in de oorspronkelijke rangorde.
    """
    if len(rijen) <= cap:
        return list(rijen)
    emmers, index = [], {}
    for r in rijen:
        ond = onderwerpen.get(sleutel_van(r))
        if ond not in index:
            index[ond] = len(emmers)
            emmers.append([])
        emmers[index[ond]].append(r)
    uit, gebruikt = [], set()
    for ronde in range(min(per_onderwerp, max(len(e) for e in emmers))):
        for emmer in emmers:
            if len(emmer) > ronde:
                uit.append(emmer[ronde])
                gebruikt.add(id(emmer[ronde]))
                if len(uit) >= cap:
                    return uit
    if len(uit) < min(ondergrens, cap):
        for r in rijen:
            if id(r) not in gebruikt:
                uit.append(r)
                if len(uit) >= min(ondergrens, cap):
                    break
    return uit[:cap]


def _lege_alt_dragers(blocks: list) -> list:
    """Alle afbeeldingen zónder alt-tekst, als (setter, src)-paren. Losse image-blokken én de
    foto's in een galerij — die laatste vergeet je makkelijk en juist daar staan er tien."""
    uit = []
    for b in blocks:
        if not isinstance(b, dict):
            continue
        if b.get("type") == "image":
            props = b.get("props") if isinstance(b.get("props"), dict) else None
            alt = (props or {}).get("alt", b.get("alt", "")) if props else b.get("alt", "")
            if not str(alt or "").strip():
                uit.append((b, props, str((props or b).get("src") or b.get("src") or b.get("url") or "")))
        elif b.get("type") == "image-gallery":
            props = b.get("props") if isinstance(b.get("props"), dict) else None
            imgs = (props or b).get("images") or b.get("images") or []
            for im in imgs:
                if isinstance(im, dict) and not str(im.get("alt") or "").strip():
                    uit.append((im, None, str(im.get("src") or im.get("url") or "")))
    return uit


def _linkweave_sweep() -> dict:
    """Wekelijkse automatische linkkansen-scan (Ryan 2026-08-25: "moet hij dat niet
    vanzelf doen?" — ja dus; de knop is weg). Review-first: suggesties belanden in
    de Voor jou-wachtrij, precies zoals bij de oude knop. De remmen zijn de kosten-
    en ruisbewaking: één sweep per 7 dagen, max 3 pagina's per sweep, per pagina
    hooguit één beurt per 30 dagen, en een volle reviewstapel (>= 10 open
    suggesties) slaat de beurt over — aanvullen terwijl er tien liggen is ruis."""
    if not _ai_configured():
        return {"did": "idle", "reason": "geen AI-koppeling"}
    st = kv_get("seo:linkweave:sweep") or {}
    nu = time.time()
    if nu - float(st.get("_t", 0) or 0) < 7 * 86400:
        return {"did": "idle", "reason": "deze week al gedaan"}
    if len(_linkweave_pending()) >= 10:
        return {"did": "idle", "reason": "reviewstapel is vol — eerst beoordelen"}
    kandidaten = [p for p in (_pages_index() or [])
                  if p.get("status", "published") == "published"
                  and (p.get("slug") or "").strip("/")
                  and nu - float(st.get((p.get("slug") or "").strip("/"), 0) or 0) > 30 * 86400]
    gescand = 0
    for p in kandidaten[:3]:
        slug = (p.get("slug") or "").strip("/")
        try:
            sugs = _linkweave_generate(slug, p.get("title") or slug)
        except Exception:
            continue
        gescand += 1
        st[slug] = nu
        _linkweave_toevoegen(sugs)
    st["_t"] = nu
    kv_set("seo:linkweave:sweep", st)
    return {"did": "sweep", "gescand": gescand}


def _monitor_tick() -> None:
    """Uurlijks (cron/gbp): één bereikbaarheidsmeting in monitor:log. Cap ~3 maanden."""
    ok, ms = _site_check()
    log = kv_get("monitor:log", []) or []
    log.insert(0, {"at": _now_iso(), "ok": bool(ok), "ms": int(ms)})
    kv_set("monitor:log", log[:2200])


# ==================== BACK-UPS VAN DE SITE-INHOUD ====================
# Drie poten (3-2-1): in de sitedatabase zelf, in een APARTE back-updatabase, en
# versleuteld bij een andere provider (Cloudflare R2). Elke poot degradeert los van
# de andere: valt er een weg, dan blijft de rest gewoon een snapshot wegschrijven en
# staat per back-up vastgelegd welke kopieen er echt zijn.

_BACKUP_VASTE_SLEUTELS = ("settings", "leads", "pages:index", "pages:removed",
                          "posts:index", "menu:main",
                          # DAM Housing-eigen. De referentiesite is contact-gedreven; hier draait
                          # de zaak op de offertepijplijn, en offertes, facturen, projecten,
                          # de pipeline-fases, de redirect-tabel en de media-index (met de
                          # alt-teksten) staan nergens anders dan in de database.
                          "quotes:index", "invoices:index", "projects:index",
                          "pipeline:stages", "redirects:index", "media:index")

_BACKUP_PREFIXEN = ("page:", "post:", "quote:", "invoice:")

_BACKUP_BEWAREN = 14

BACKUP_TURSO_DATABASE_URL = os.environ.get("BACKUP_TURSO_DATABASE_URL", "").strip()

BACKUP_TURSO_AUTH_TOKEN = os.environ.get("BACKUP_TURSO_AUTH_TOKEN", "").strip()

_BACKUP_EXTERN_HTTP = re.sub(r"^libsql://", "https://", BACKUP_TURSO_DATABASE_URL).rstrip("/")

_BACKUP_EXTERN_BEWAREN = 30


def _backup_extern_actief() -> bool:
    return bool(BACKUP_TURSO_DATABASE_URL and BACKUP_TURSO_AUTH_TOKEN)


BACKUP_R2_ACCOUNT_ID = os.environ.get("BACKUP_R2_ACCOUNT_ID", "").strip()

BACKUP_R2_ACCESS_KEY_ID = os.environ.get("BACKUP_R2_ACCESS_KEY_ID", "").strip()

BACKUP_R2_SECRET_ACCESS_KEY = os.environ.get("BACKUP_R2_SECRET_ACCESS_KEY", "").strip()

BACKUP_R2_BUCKET = os.environ.get("BACKUP_R2_BUCKET", "mhs-site-backups").strip()

BACKUP_ENCRYPTION_KEY = os.environ.get("BACKUP_ENCRYPTION_KEY", "").strip()

_BACKUP_R2_PREFIX = "damhousing"


def _backup_r2_actief() -> bool:
    # Zonder encryptiesleutel gaat er bewust NIETS naar R2: onversleutelde
    # persoonsgegevens buiten het platform is geen back-up maar een lek.
    return bool(BACKUP_R2_ACCOUNT_ID and BACKUP_R2_ACCESS_KEY_ID
                and BACKUP_R2_SECRET_ACCESS_KEY and len(BACKUP_ENCRYPTION_KEY) == 64)


def _backup_versleutel(raw: bytes, sleutel_hex: str) -> bytes:
    """Versleutel met een HMAC-SHA256-keystream (CTR) + encrypt-then-MAC. Stdlib heeft
    geen AES; deze constructie (PRF-keystream met verse nonce, aparte enc/mac-sleutels,
    integriteitstag over nonce+cijfertekst) is de gangbare stdlib-vervanger.
    Formaat: b'MHSB1' + nonce(16) + tag(32) + cijfertekst."""
    key = bytes.fromhex(sleutel_hex)
    enc_key = hashlib.sha256(b"enc" + key).digest()
    mac_key = hashlib.sha256(b"mac" + key).digest()
    nonce = secrets.token_bytes(16)
    uit = bytearray()
    for i in range(0, len(raw), 32):
        blok = hmac.new(enc_key, nonce + (i // 32).to_bytes(8, "big"), hashlib.sha256).digest()
        stuk = raw[i:i + 32]
        uit += bytes(a ^ b for a, b in zip(stuk, blok))
    tag = hmac.new(mac_key, b"MHSB1" + nonce + bytes(uit), hashlib.sha256).digest()
    return b"MHSB1" + nonce + tag + bytes(uit)


def _backup_ontsleutel(enc: bytes, sleutel_hex: str) -> bytes:
    if enc[:5] != b"MHSB1":
        raise ValueError("Onbekend back-upformaat")
    key = bytes.fromhex(sleutel_hex)
    enc_key = hashlib.sha256(b"enc" + key).digest()
    mac_key = hashlib.sha256(b"mac" + key).digest()
    nonce, tag, cijfer = enc[5:21], enc[21:53], enc[53:]
    verwacht = hmac.new(mac_key, b"MHSB1" + nonce + cijfer, hashlib.sha256).digest()
    if not hmac.compare_digest(tag, verwacht):
        raise ValueError("Integriteitscontrole mislukt: verkeerde sleutel of beschadigd bestand")
    uit = bytearray()
    for i in range(0, len(cijfer), 32):
        blok = hmac.new(enc_key, nonce + (i // 32).to_bytes(8, "big"), hashlib.sha256).digest()
        stuk = cijfer[i:i + 32]
        uit += bytes(a ^ b for a, b in zip(stuk, blok))
    return bytes(uit)


def _s3_sigv4_headers(method: str, host: str, pad: str, payload_hash: str,
                      akid: str = None, secret: str = None) -> dict:
    """Minimale AWS SigV4-ondertekening voor de R2 S3-API (region 'auto'), stdlib-only."""
    akid = akid or BACKUP_R2_ACCESS_KEY_ID
    secret = secret or BACKUP_R2_SECRET_ACCESS_KEY
    nu = datetime.now(timezone.utc)
    amzdate = nu.strftime("%Y%m%dT%H%M%SZ")
    datestamp = nu.strftime("%Y%m%d")
    canonical_headers = f"host:{host}\nx-amz-content-sha256:{payload_hash}\nx-amz-date:{amzdate}\n"
    signed = "host;x-amz-content-sha256;x-amz-date"
    canonical = f"{method}\n{pad}\n\n{canonical_headers}\n{signed}\n{payload_hash}"
    scope = f"{datestamp}/auto/s3/aws4_request"
    te_tekenen = ("AWS4-HMAC-SHA256\n" + amzdate + "\n" + scope + "\n"
                  + hashlib.sha256(canonical.encode()).hexdigest())

    def _hm(sleutel, boodschap):
        return hmac.new(sleutel, boodschap.encode(), hashlib.sha256).digest()
    teken_sleutel = _hm(_hm(_hm(_hm(("AWS4" + secret).encode(), datestamp), "auto"), "s3"), "aws4_request")
    handtekening = hmac.new(teken_sleutel, te_tekenen.encode(), hashlib.sha256).hexdigest()
    return {
        "Authorization": (f"AWS4-HMAC-SHA256 Credential={akid}/{scope}, "
                          f"SignedHeaders={signed}, Signature={handtekening}"),
        "x-amz-date": amzdate,
        "x-amz-content-sha256": payload_hash,
    }


def _backup_r2_put(objectnaam: str, body: bytes) -> None:
    host = f"{BACKUP_R2_ACCOUNT_ID}.r2.cloudflarestorage.com"
    pad = "/" + BACKUP_R2_BUCKET + "/" + urllib.parse.quote(objectnaam)
    payload_hash = hashlib.sha256(body).hexdigest()
    headers = _s3_sigv4_headers("PUT", host, pad, payload_hash)
    headers["Content-Type"] = "application/octet-stream"
    req = urllib.request.Request(f"https://{host}{pad}", data=body, headers=headers, method="PUT")
    with urllib.request.urlopen(req, timeout=30) as r:
        if not (200 <= r.status < 300):
            raise RuntimeError(f"R2 PUT gaf status {r.status}")


def _backup_r2_schrijf(sleutel: str, snap: dict) -> None:
    raw = zlib.compress(json.dumps(snap, ensure_ascii=False, default=str).encode("utf-8"))
    _backup_r2_put(f"{_BACKUP_R2_PREFIX}/{sleutel}.json.zlib.enc",
                   _backup_versleutel(raw, BACKUP_ENCRYPTION_KEY))


def _backup_extern_sql(sql: str, args=None) -> list:
    """Eén statement tegen de aparte back-updatabase (zelfde pipeline-API als de
    hoofddatabase); de kv-tabel wordt on-the-fly aangemaakt. Raiset bij fouten —
    de aanroepers beslissen zelf of dat stil mag falen."""
    stmt = {"sql": sql}
    if args:
        stmt["args"] = [{"type": "null", "value": None} if a is None
                        else {"type": "text", "value": str(a)} for a in args]
    body = {"requests": [
        {"type": "execute", "stmt": {"sql": "CREATE TABLE IF NOT EXISTS kv "
                                            "(key TEXT PRIMARY KEY, value TEXT, updated_at TEXT)"}},
        {"type": "execute", "stmt": stmt},
        {"type": "close"},
    ]}
    req = urllib.request.Request(
        _BACKUP_EXTERN_HTTP + "/v2/pipeline",
        data=json.dumps(body).encode("utf-8"),
        headers={"Authorization": f"Bearer {BACKUP_TURSO_AUTH_TOKEN}", "Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=12) as r:
        resp = json.loads(r.read())
    res = (resp.get("results") or [{}, {}])[1]
    if res.get("type") != "ok":
        raise RuntimeError("backup-db: " + json.dumps(res.get("error", res))[:200])
    rows = ((res.get("response") or {}).get("result") or {}).get("rows", [])
    return [[(None if c.get("type") == "null" else c.get("value")) for c in row] for row in rows]


def _backup_extern_schrijf(sleutel: str, snap: dict) -> None:
    _backup_extern_sql(
        "INSERT INTO kv(key,value,updated_at) VALUES(?,?,datetime('now')) "
        "ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=datetime('now')",
        [sleutel, json.dumps(snap, ensure_ascii=False, default=str)])
    # Rotatie: bij minder rijen dan de limiet geeft de subquery NULL en verwijdert dit niets.
    _backup_extern_sql("DELETE FROM kv WHERE key < (SELECT key FROM kv ORDER BY key DESC "
                       f"LIMIT 1 OFFSET {int(_BACKUP_EXTERN_BEWAREN) - 1})")


def _backup_extern_lijst() -> list:
    uit = []
    for key, at, keys, omvang in _backup_extern_sql(
            "SELECT key, json_extract(value,'$.at'), json_extract(value,'$.keys'), length(value) "
            "FROM kv ORDER BY key DESC"):
        uit.append({"key": key, "at": at or "", "keys": int(keys or 0), "bytes": int(omvang or 0)})
    return uit


def _backup_extern_lees(sleutel: str):
    rows = _backup_extern_sql("SELECT value FROM kv WHERE key = ? LIMIT 1", [sleutel])
    if not rows:
        return None
    try:
        return json.loads(rows[0][0])
    except Exception:
        return None


def _backup_snapshot() -> dict:
    """De bewerkbare site-inhoud uit KV als één dict: teksten/pagina's, blog, leads,
    instellingen, menu's. Media staat extern en de code in git; dit is precies het deel
    dat alleen in de database leeft."""
    data = {}
    for k in _BACKUP_VASTE_SLEUTELS:
        v = kv_get(k)
        if v is not None:
            data[k] = v
    for pref in _BACKUP_PREFIXEN:
        for k in (kv_list(pref) or []):
            v = kv_get(k)
            if v is not None:
                data[k] = v
    return data


def _backup_schrijf(sleutel: str, data: dict) -> dict:
    """Bewaar een snapshot onder backup:<sleutel> + logregel; roteert daarna naar
    maximaal _BACKUP_BEWAREN snapshots (het log zelf telt niet mee). Met de aparte
    back-updatabase geconfigureerd gaat de snapshot ook daarheen; of dat lukte staat
    per back-up vastgelegd (extern: True/False)."""
    omvang = len(json.dumps(data, default=str))
    snap = {"at": _now_iso(), "keys": len(data), "bytes": omvang, "data": data}
    extern = False
    if _backup_extern_actief():
        try:
            _backup_extern_schrijf(sleutel, snap)
            extern = True
        except Exception as e:
            print(f"externe back-up mislukt: {e}")
    r2 = False
    if _backup_r2_actief():
        try:
            _backup_r2_schrijf(sleutel, snap)
            r2 = True
        except Exception as e:
            print(f"R2-back-up mislukt: {e}")
    snap["extern"] = extern
    snap["r2"] = r2
    kv_set(f"backup:{sleutel}", snap)
    log = kv_get("backup:log", []) or []
    log.insert(0, {"at": _now_iso(), "key": sleutel, "keys": len(data), "bytes": omvang,
                   "extern": extern, "r2": r2})
    kv_set("backup:log", log[:60])
    snaps = sorted(k for k in (kv_list("backup:") or []) if k != "backup:log")
    for oud in (snaps[:-_BACKUP_BEWAREN] if len(snaps) > _BACKUP_BEWAREN else []):
        kv_delete(oud)
    return snap


def _backup_tick(force: bool = False) -> bool:
    """Dagelijks (cron/seo): één content-snapshot per dag, idempotent. force=True (de
    handmatige knop) ververst de dagsnapshot met de actuele stand."""
    vandaag = datetime.now().strftime("%Y-%m-%d")
    if not force and kv_get(f"backup:{vandaag}") is not None:
        return False
    _backup_schrijf(vandaag, _backup_snapshot())
    return True


def _backup_key_naam(k: str) -> str:
    """kv_list geeft op Turso echte sleutels ('backup:2026-08-24'), maar de lokale
    file-fallback safe-bestandsnamen ('backup_2026-08-24') — strip beide vormen."""
    return re.sub(r"^backup[:_]", "", str(k or ""))


@app.route("/api/admin/backups", methods=["GET"])
@app.route("/api/admin/backups/", methods=["GET"])
def api_admin_backups_lijst():
    a = _require_agency()
    if a:
        return a
    items = []
    for k in sorted((kv_list("backup:") or []), key=_backup_key_naam, reverse=True):
        naam = _backup_key_naam(k)
        if naam == "log":
            continue
        s = kv_get(k) or {}
        items.append({"key": naam, "at": s.get("at", ""),
                      "keys": int(s.get("keys") or 0), "bytes": int(s.get("bytes") or 0),
                      "bron": "kv+extern" if s.get("extern") else "kv", "r2": bool(s.get("r2"))})
    # Externe kopieën die lokaal (niet meer) bestaan tonen we ook: dat is precies het
    # scenario waarvoor de aparte database er is.
    if _backup_extern_actief():
        try:
            lokaal = {i["key"] for i in items}
            for e in _backup_extern_lijst():
                if e.get("key") and e["key"] not in lokaal:
                    e["bron"] = "extern"
                    items.append(e)
            items.sort(key=lambda i: i.get("key", ""), reverse=True)
        except Exception as e:
            print(f"externe back-uplijst mislukt: {e}")
    return jsonify({"ok": True, "items": items, "extern_actief": _backup_extern_actief(),
                    "r2_actief": _backup_r2_actief()})


@app.route("/api/admin/backups/run", methods=["POST"])
@app.route("/api/admin/backups/run/", methods=["POST"])
def api_admin_backups_run():
    a = _require_agency()
    if a:
        return a
    _backup_tick(force=True)   # de handmatige knop pakt altijd de actuele stand
    audit_log("backups.run", "backups", "Handmatige back-up gemaakt")
    return jsonify({"ok": True})


@app.route("/api/admin/backups/restore", methods=["POST"])
@app.route("/api/admin/backups/restore/", methods=["POST"])
def api_admin_backups_restore():
    a = _require_agency()
    if a:
        return a
    d = request.get_json(silent=True) or {}
    sleutel = str(d.get("key") or "").strip()
    snap = kv_get(f"backup:{sleutel}") if sleutel else None
    if not isinstance(snap, dict) and sleutel and _backup_extern_actief():
        # Niet (meer) in de sitedatabase: pak de externe kopie — hét rampscenario
        # waarvoor de aparte back-updatabase bestaat.
        try:
            snap = _backup_extern_lees(sleutel)
        except Exception:
            snap = None
    if not isinstance(snap, dict) or not isinstance(snap.get("data"), dict):
        return jsonify({"ok": False, "error": "Back-up niet gevonden."}), 404
    # Eerst de huidige stand veiligstellen: terugzetten moet zelf ook terug te draaien zijn.
    herstelpunt = datetime.now().strftime("%Y-%m-%dT%H.%M.%S")
    _backup_schrijf(herstelpunt, _backup_snapshot())
    for k, v in snap["data"].items():
        kv_set(k, v)
    audit_log("backups.restore", sleutel,
              f"Back-up {sleutel} teruggezet ({len(snap['data'])} onderdelen); herstelpunt {herstelpunt}")
    return jsonify({"ok": True, "restored": len(snap["data"]), "herstelpunt": herstelpunt})


@app.route("/api/admin/backups/download", methods=["GET"])
@app.route("/api/admin/backups/download/", methods=["GET"])
def api_admin_backups_download():
    a = _require_agency()
    if a:
        return a
    sleutel = str(request.args.get("key") or "").strip()
    snap = kv_get(f"backup:{sleutel}") if sleutel else None
    if not isinstance(snap, dict) and sleutel and _backup_extern_actief():
        try:
            snap = _backup_extern_lees(sleutel)
        except Exception:
            snap = None
    if not isinstance(snap, dict):
        return jsonify({"ok": False, "error": "Back-up niet gevonden."}), 404
    naam = f"backup-damhousing-{re.sub(r'[^0-9A-Za-z.-]', '_', sleutel)}.json"
    return Response(json.dumps(snap, ensure_ascii=False, indent=1, default=str),
                    mimetype="application/json",
                    headers={"Content-Disposition": f'attachment; filename="{naam}"'})




def _onderhoud_stats(frm: str, to: str) -> dict:
    """Gemeten beheercijfers voor het onderhoud-blok; alleen sleutels waarvoor echt
    gelogd is — geen meting = geen cijfer, en dus ook geen tegel in het rapport."""
    uit = {}
    try:
        checks = [m for m in (kv_get("monitor:log", []) or []) if frm <= str(m.get("at", ""))[:10] <= to]
        if checks:
            ok = [m for m in checks if m.get("ok")]
            uit["checks"] = len(checks)
            uit["verstoringen"] = len(checks) - len(ok)
            uit["uptime_pct"] = round(100.0 * len(ok) / len(checks), 1)
            ms = [int(m.get("ms") or 0) for m in ok if m.get("ms")]
            if ms:
                uit["reactie_ms"] = int(sum(ms) / len(ms))
    except Exception:
        pass
    try:
        buk = [b for b in (kv_get("backup:log", []) or []) if frm <= str(b.get("at", ""))[:10] <= to]
        if buk:
            uit["backups"] = len(buk)
    except Exception:
        pass
    try:
        cert = kv_get("monitor:ssl") or {}
        if cert.get("dagen") is not None:
            uit["ssl_dagen"] = int(cert["dagen"])
    except Exception:
        pass
    try:
        psi = kv_get("monitor:pagespeed") or {}
        if psi.get("score") is not None:
            uit["psi_score"] = int(psi["score"])
        if psi.get("lcp_ms") is not None:
            uit["lcp_ms"] = int(psi["lcp_ms"])
        if psi.get("cls") is not None:
            uit["cls"] = float(psi["cls"])
    except Exception:
        pass
    try:
        dom = kv_get("monitor:domein") or {}
        if dom.get("status"):
            uit["domein_status"] = dom["status"]
            if dom.get("dagen") is not None:
                uit["domein_dagen"] = int(dom["dagen"])
    except Exception:
        pass
    return uit


def _opp_ai_oordeel(kandidaten: list, cijfers: dict) -> dict:
    """AI-keuring per query, met de SE Ranking-cijfers als bewijs: is dit een term
    waar dit bedrijf klanten uit haalt als de pagina erop wordt geoptimaliseerd?

    Wijst af: typefouten (volume 0 is daar het signaal), losse woorden zonder eigen
    zoekintentie, persoonsnamen/merkzoekopdrachten, termen los van de diensten.
    Oordeel per query 30 dagen in de cache — één haiku-call per NIEUWE term, niet
    per paginaweergave. Fail-open: geen AI of geen antwoord = doorlaten."""
    cache = kv_get("seo:opp:oordeel") or {}
    nu = int(time.time())
    todo = [k for k in kandidaten
            if str(k.get("query", "")).lower() not in cache
            or "intentie" not in cache[str(k.get("query", "")).lower()]   # oud schema -> opnieuw
            or nu - int(cache[str(k.get("query", "")).lower()].get("t", 0) or 0) > 30 * 86400]
    if todo and _ai_configured():
        focus = _agent_config().get("focus_keywords") or []
        naam = str((get_settings().get("company") or {}).get("name") or "")
        system = ("Je beoordeelt zoektermen uit Search Console voor een lokaal bedrijf. Per term: kan dit "
                  "bedrijf hier nieuwe klanten uit halen als de pagina op die term wordt geoptimaliseerd? "
                  "'ok' is false bij: spel- of typefouten (geen of nul zoekvolume is daar een sterk signaal); "
                  "losse woorden zonder eigen zoekintentie (een kleur, een naamfragment); zoekopdrachten op de "
                  "bedrijfsnaam of een persoonsnaam (die bezoekers vinden de site toch al); termen die niets "
                  "met de diensten te maken hebben; en generieke termen waar dit lokale bedrijf realistisch "
                  "nooit op wint (hoge moeilijkheid zonder dienst- of plaatsrelatie — 'wit' is voor een "
                  "vloerenbedrijf gewoon de vloersoort). Weeg volume, moeilijkheid en intentie expliciet mee. "
                  "Geef per term ook de zoekintentie als één Nederlands woord "
                  "(informatief, navigatie, transactioneel, commercieel, lokaal, merk of typefout). "
                  "Bij twijfel over ok: true. Antwoord UITSLUITEND met geldig JSON: "
                  '{"oordeel":[{"query":"...","ok":true,"reden":"kort","intentie":"..."}]}')
        user = json.dumps({"bedrijf": naam, "diensten": focus,
                           "termen": [{"query": k.get("query", ""), "positie": k.get("position", 0),
                                       "vertoningen": k.get("impressions", 0),
                                       "volume": (cijfers.get(k.get("query", "")) or {}).get("volume"),
                                       "moeilijkheid": (cijfers.get(k.get("query", "")) or {}).get("moeilijkheid"),
                                       "intentie": (cijfers.get(k.get("query", "")) or {}).get("intentie")}
                                      for k in todo]}, ensure_ascii=False)
        r = _anthropic_call([{"role": "user", "content": user}], system=system, max_tokens=800,
                            model="claude-haiku-4-5-20251001")
        if not r.get("error"):
            data = _loads_lenient("".join(c.get("text", "") for c in (r.get("content") or []))) or {}
            for o in (data.get("oordeel") or []):
                q = str(o.get("query", "")).lower().strip()
                if q:
                    cache[q] = {"ok": bool(o.get("ok", True)), "reden": str(o.get("reden", ""))[:120],
                                "intentie": str(o.get("intentie", "")).strip().lower()[:24], "t": nu}
            # Cap: oudste eruit boven de 200, anders groeit dit eeuwig door.
            if len(cache) > 200:
                cache = dict(sorted(cache.items(), key=lambda kv_: kv_[1].get("t", 0))[-200:])
            kv_set("seo:opp:oordeel", cache)
    return cache


def _opp_is_merk_query(query: str, merk_tokens: set) -> bool:
    """Alle tokens uit de bedrijfsnaam = navigatie ("damhousing", "damhousing culemborg"), geen kans:
    wie daarop zoekt vindt de site toch al, en de term zelf levert geen klanten."""
    tokens = [w for w in re.split(r"\W+", str(query).lower()) if w]
    return bool(tokens) and all(t in merk_tokens for t in tokens)


def _opp_is_onbekende_losse_term(query: str, cijfers: dict, focus_tokens: set) -> bool:
    """Eén los woord, geen focus-overlap, en SE Ranking kent de term niet eens:
    dat is een typefout of ruis ("witt"), geen zoekterm om op te optimaliseren.
    Alleen toepasbaar als de cijferbron überhaupt antwoordde (cijfers niet leeg) —
    anders zou een gateway-storing élke losse term wegtrekken."""
    if not cijfers:
        return False
    tokens = [w for w in re.split(r"\W+", str(query).lower()) if w]
    if len(tokens) != 1 or tokens[0] in focus_tokens:
        return False
    return query not in cijfers


def _opp_merk_tokens() -> set:
    """De bedrijfsnaam-tokens die géén dienst zijn: "DAM Housing Vloeren Culemborg" -> {culemborg}.

    Een token dat óók in een focus-zoekwoord zit (bv. "vloeren") telt als dienst:
    daar wil je juist wél op gevonden worden. Wat overblijft is puur merk/naam."""
    naam = str((get_settings().get("company") or {}).get("name") or "")
    focus = set()
    for kw in (_agent_config().get("focus_keywords") or []):
        focus |= {w for w in re.split(r"\W+", str(kw).lower()) if w}
    return {w for w in re.split(r"\W+", naam.lower()) if w} - focus


def _pagespeed_tick() -> bool:
    """Dagelijks (gedebounced in de uurlijkse cron): PageSpeed-score en Core Web Vitals
    van de site, gecachet in KV — het rapport leest alleen de cache."""
    vandaag = datetime.now().strftime("%Y-%m-%d")
    cache = kv_get("monitor:pagespeed") or {}
    if str(cache.get("at", ""))[:10] == vandaag:
        return False
    base = _public_base()
    if not base:
        return False
    r = _psi_ophalen(base.rstrip("/") + "/")
    if not r:
        return False
    uit = {"at": _now_iso()}
    try:
        uit["score"] = int(round(100 * float(r["lighthouseResult"]["categories"]["performance"]["score"])))
    except Exception:
        pass
    audits = ((r.get("lighthouseResult") or {}).get("audits") or {})
    try:
        lcp = (audits.get("largest-contentful-paint") or {}).get("numericValue")
        if lcp is not None:
            uit["lcp_ms"] = int(lcp)
    except Exception:
        pass
    try:
        cls_ = (audits.get("cumulative-layout-shift") or {}).get("numericValue")
        if cls_ is not None:
            uit["cls"] = round(float(cls_), 3)
    except Exception:
        pass
    if "score" not in uit and "lcp_ms" not in uit:
        return False
    kv_set("monitor:pagespeed", uit)
    return True


def _pagina_heeft_eigen_h1(pad: str):
    """Staat er een H1 in de ECHTE pagina? True/False, of None als we het niet konden zien.

    De blokken in het CMS zijn maar een deel van wat een bezoeker krijgt: hero's, headers en
    hele secties komen uit de site-code zelf. Een audit die 'geen H1' meldt zegt dus iets over
    wat de crawler zag, niet per se over de pagina. Zonder deze controle zette de fix een losse
    kop bovenaan een pagina die allang een H1 had — zichtbaar, boven de hero, op de live site.
    """
    html = _haal_pagina_html(pad)
    if html is None:
        return None
    return bool(re.search(r"<h1[\s>]", html, re.I))


def _pagina_is_client_gerenderd(pad: str):
    """Rendert deze pagina zijn content pas in de browser? True/False, of None bij twijfel.

    Waarom dit bestaat: de homepage van deze site is een Vite-shell van 3,5 kB met
    `<div id="root">` en nul koppen. SE Ranking crawlt die HTML en meldt dus eeuwig
    `h1_missing` — terwijl de hero-H1 er na het renderen gewoon staat. `_pagina_heeft_eigen_h1`
    kijkt naar diezelfde kale HTML en zag daarom ook geen H1: die gaf "ga je gang" en de agent
    zette een losse kop bovenaan de LIVE homepage, boven de hero.

    Geen enkel CMS-blok kan zo'n melding oplossen (de crawler ziet het blok immers ook niet),
    dus content-acties horen hier niet thuis. Meta-tags zijn een ander verhaal: die staan wél
    gewoon in de shell en worden wél gelezen — `meta_update` blijft dus toegestaan.

    Herkenning: geen enkele kop (h1-h6) in de geserveerde HTML. Dat is het criterium dat er
    echt toe doet — een pagina zonder ook maar één kop is geen pagina die de crawler kan
    beoordelen op koppen of alt-teksten.
    """
    sleutel = "audit:clientside:" + hashlib.sha1((pad or "/").encode()).hexdigest()[:12]
    bewaard = kv_get(sleutel)
    if isinstance(bewaard, dict) and (time.time() - float(bewaard.get("t", 0) or 0)) < 24 * 3600:
        return bewaard.get("v")
    html = _haal_pagina_html(pad)
    if html is None:
        return None
    verdict = not re.search(r"<h[1-6][\s>]", html, re.I)
    kv_set(sleutel, {"t": int(time.time()), "v": verdict})
    return verdict


def _post_by_path(path: str):
    """Het blogartikel achter een `/blog/<slug>/`-pad, of None.

    Alleen GEPUBLICEERDE artikelen, en nadrukkelijk niet `/blog/` zelf — dat is de index."""
    m = re.match(r"^/blog/([^/]+)/?$", str(path or "").strip())
    if not m:
        return None
    post = get_post(m.group(1))
    if not post or post.get("status") != "published":
        return None
    return post


def _project_by_path(path: str):
    """Het projectrecord achter een `/projecten/<slug>/`-pad, of None.

    Alleen GEPUBLICEERDE projecten: een concept staat niet op de site, dus de crawler kan er
    niets over melden en de agent hoort er af te blijven."""
    m = re.match(r"^/projecten/([^/]+)/?$", str(path or "").strip())
    if not m:
        return None
    slug = _safe_slug(m.group(1))
    for p in get_projects():
        if p.get("status", "published") != "published":
            continue
        if _project_slug(p) == slug:
            return p
    return None


def _psi_ophalen(url: str):
    """Ruwe PageSpeed Insights-respons (mobiel, performance); None bij elke storing.
    Keyless: één meting per dag blijft ruim binnen de gratis limiet."""
    try:
        api = ("https://www.googleapis.com/pagespeedonline/v5/runPagespeed?url="
               + urllib.parse.quote(url, safe="") + "&strategy=mobile&category=performance")
        req = urllib.request.Request(api, headers={"User-Agent": "damhousing-monitor/1.0"})
        with urllib.request.urlopen(req, timeout=45) as r:
            return json.loads(r.read() or b"{}")
    except Exception:
        return None


def _r_datum_kort(iso: str) -> str:
    """'2026-08-20' -> '20 augustus'. Leeg bij onzin, zodat de kop nooit half gevuld is."""
    try:
        d = datetime.strptime(str(iso)[:10], "%Y-%m-%d")
        return f"{d.day} {_NL_MAANDEN[d.month - 1]}"
    except Exception:
        return ""


def _rapport_afzender_email(report) -> str:
    """Waar vragen over dit rapport landen én (waar de mailer dat kan) het afzendadres:
    de mailbox van de gekozen afzender; het hele team of onbekend = marjolein@."""
    naam = str((report or {}).get("sender") or "").strip()
    if naam and "team" not in naam.lower():
        voornaam = re.sub(r"[^a-z]", "", naam.split()[0].lower())
        if voornaam:
            return f"{voornaam}@mhsmedia.nl"
    return "marjolein@mhsmedia.nl"


def _rapport_afzender_foto(report) -> str:
    """Profielfoto van de afzender: centraal gehost bij MAIHS (public/team/<voornaam>.jpg),
    alleen gerenderd als het bestand echt bestaat (HEAD-check, 6 uur gecachet)."""
    naam = str((report or {}).get("sender") or "").strip()
    if not naam or "team" in naam.lower():
        return ""
    voornaam = re.sub(r"[^a-z]", "", naam.split()[0].lower())
    if not voornaam:
        return ""
    url = f"https://software.mhsmedia.nl/team/{voornaam}.jpg"
    try:
        cache = kv_get(f"teamfoto:{voornaam}") or {}
        if cache.get("at", "") >= (datetime.now() - timedelta(hours=6)).isoformat(timespec="seconds"):
            return url if cache.get("ok") else ""
        ok = _url_bestaat(url)
        kv_set(f"teamfoto:{voornaam}", {"at": _now_iso(), "ok": bool(ok)})
        return url if ok else ""
    except Exception:
        return ""


def _rapport_ai_teksten(report: dict, instructie: str = "") -> dict:
    """Laat de AI de verhaalteksten schrijven op basis van de feiten. {} bij elke storing:
    de vaste teksten vangen het op en het rapport genereert altijd. Met een instructie
    (de aanpas-functie in de wizard) krijgt het model ook de huidige teksten mee en
    herschrijft het gericht in plaats van blanco opnieuw te beginnen."""
    try:
        if not _ai_configured():
            return {}
        mods = report.get("modules") or ["seo"]
        system = (
            "Je schrijft namens marketingbureau MHS Media de periodieke klantrapportage voor een klant. "
            "Schrijf in het Nederlands, in de wij-vorm ('we'), warm, concreet en zonder jargon: de lezer "
            "is de ondernemer zelf. Spreek de lezer aan met je en jullie, nooit met u. "
            "Denk echt na over deze klant: welke dienst we leveren (de onderdelen "
            "hieronder), hoelang we al bezig zijn en wat de progressie is. "
            # Harde regel bovenop het server-side claimslot (Ryan 2026-08-26): de AI
            # verzon eerder posities die nergens gemeten waren.
            "HARDE REGEL, BOVEN ALLES: NIET VERZINNEN. Elk cijfer, elke positie, elk zoekwoord, elke naam "
            "en elke gebeurtenis die je noemt moet letterlijk in het feitenoverzicht staan. Niets schatten, "
            "niets afronden naar een mooier getal, geen voorbeelden bedenken die er niet staan. Weet je "
            "iets niet of staat het er niet, laat het dan weg: een rapport zonder dat detail is prima, een "
            "rapport met een verzonnen detail is onbruikbaar en schaadt het vertrouwen van de klant. "
            "Overige regels: gebruik UITSLUITEND de "
            "feiten en cijfers uit het overzicht; noem alleen de onderdelen die dit rapport "
            "bevat; geen em- of en-dashes; geen emoji; verraad nooit dat er techniek of een taalmodel "
            "meeschrijft (woorden als agent, automatisch, systeem, gegenereerd zijn verboden; het is óns "
            "werk); een daling breng je rustig als aandachtspunt voor de komende periode, nooit als "
            "mislukking; woorden als mislukt, helaas, teleurstellend of slecht gebruik je niet. "
            "Antwoord met ALLEEN een JSON-object, zonder tekst eromheen, met deze sleutels: "
            '"titel" (pakkende kop van maximaal 60 tekens, in zinsstijl, met punt), '
            '"intro" (lijst van 1 of 2 korte alinea\'s die aansluiten bij kick-off of terugblik en de looptijd), '
            '"inzicht" (wat de cijfers voor de klant betekenen; alleen als er echt cijfers zijn, anders weglaten), '
            + ('"score" (duiding van het scoreverloop), "posities" (duiding van de zoekwoordposities), '
               if "seo" in mods else "")
            + ('"gbp" (het bedrijfsprofiel-verhaal van deze periode in een alinea), ' if "gbp" in mods else "")
            + ('"onderhoud" (korte alinea over het beheer: bereikbaarheid, back-ups, beveiliging; '
               'alleen over de gemeten beheer-cijfers), ' if "onderhoud" in mods else "")
            + '"vooruit" (lijst van 2 tot 4 concrete focuspunten voor de komende periode, elk een zin), '
            '"slot" (afsluitende alinea met een uitnodiging om te reageren, zonder afsluitende groet '
            'of ondertekening: die staat al vast onder het rapport). '
            "Sleutels waarvoor het overzicht geen gegevens heeft, laat je weg."
        )
        vraag = "Het overzicht met feiten:\n" + _rapport_feiten(report)
        if (instructie or "").strip():
            huidige = json.dumps(report.get("teksten") or {}, ensure_ascii=False)[:4000]
            vraag += ("\n\nDe huidige teksten van het rapport (JSON):\n" + huidige
                      + "\n\nAanwijzing van de accountmanager voor deze nieuwe versie: "
                      + str(instructie).strip()[:500]
                      # 'Het hoeft niet alles opnieuw te schrijven, gewoon aanpassen'
                      # (Ryan 2026-08-25): een aanwijzing is een gerichte wijziging.
                      + "\nDit is een gerichte aanpassing, geen nieuwe versie: wijzig "
                        "UITSLUITEND wat de aanwijzing raakt en neem elk ander veld "
                        "letterlijk en ongewijzigd over uit de huidige teksten. Gaat de "
                        "aanwijzing over iets wat niet in deze teksten voorkomt, geef dan "
                        "alle velden letterlijk ongewijzigd terug. Alle regels hierboven "
                        "blijven onverkort gelden.")
        resp = _anthropic_call([{"role": "user", "content": vraag}],
                               system=system, max_tokens=1400, timeout=40)
        if not isinstance(resp, dict) or resp.get("error"):
            return {}
        raw = "".join(b.get("text", "") for b in (resp.get("content") or []) if isinstance(b, dict))
        data = _loads_lenient(raw)
        if not isinstance(data, dict):
            return {}
        uit = {}
        for k in ("titel", "inzicht", "score", "posities", "gbp", "onderhoud", "slot"):
            v = _rapport_ai_veld(data.get(k), 90 if k == "titel" else 700)
            if v and not _rapport_posities_claims_kloppen(v, report.get("positions")):
                # Verzonnen positie-claims: het hele veld vervalt, de vaste tekst vangt op.
                continue
            if v and k == "slot":
                # De vaste ondertekening staat al onder het rapport; een eigen groet
                # van het model zou dubbel zijn.
                v = re.split(r"(?i)(?:met\s+)?(?:vriendelijke|hartelijke|warme)\s+groet\w*", v)[0]
                v = re.split(r"(?i)\bgroetjes\b", v)[0].rstrip(" \n,")
            if v:
                uit[k] = v
        for k in ("intro", "vooruit"):
            items = [_rapport_ai_veld(x, 500) for x in (data.get(k) or [])] if isinstance(data.get(k), list) else []
            items = [x for x in items if x
                     and _rapport_posities_claims_kloppen(x, report.get("positions"))][: (2 if k == "intro" else 4)]
            if items:
                uit[k] = items
        return uit
    except Exception as e:
        print(f"rapport-ai overgeslagen: {e}")
        return {}


def _rapport_ai_veld(waarde, maxlen: int = 700) -> str:
    """Schoon één AI-veld volgens de huisregels; leeg als het door de robottaal-gate valt."""
    t = _gbp_clean_ai_text(str(waarde or ""))[:maxlen].strip()
    if not t:
        return ""
    for pat in _RAPPORT_ROBOTTAAL:
        if pat.search(t):
            return ""
    return t


def _rapport_beeld_bron(url: str, printable: bool) -> str:
    u = str(url or "")
    if not printable or not u.startswith(_RAPPORT_BEELD_HOST):
        return u
    return "/api/report/img?src=" + urllib.parse.quote(u, safe="")


def _rapport_feiten(report: dict) -> str:
    """De feitenbron voor de AI: uitsluitend echte gegevens uit dit rapport en de site.
    Alles wat hier niet in staat, mag de tekst ook niet beweren."""
    mods = report.get("modules") or ["seo"]
    r = []
    try:
        r.append("Bedrijf: " + _seo_business_context()[:1200])
    except Exception:
        pass
    r.append("Rapport: " + (report.get("label") or "") + f" (periode {report.get('from', '')} t/m {report.get('to', '')})")
    r.append("Onderdelen van dit rapport: " + ", ".join(_RAPPORT_MODULE_LABELS.get(m, m) for m in mods))
    r.append("Dit is de eerste rapportage voor deze klant (kick-off)." if report.get("first_report")
             else "Dit is een vervolgrapportage.")
    r.append("Het rapport wordt ondertekend door: " + _rapport_groet_naam(report) + ".")
    try:
        hist = kv_get("seo:report:history", []) or []
        oudste = min((h.get("generated_at", "") for h in hist if h.get("generated_at")), default="")
        acts = kv_get("seo:activity", []) or []
        oudste_act = min((a.get("at", "") for a in acts if a.get("at")), default="")
        start = min((x for x in (oudste, oudste_act) if x), default="")
        if start:
            r.append(f"We werken voor deze klant sinds {start[:7]}.")
        if hist:
            r.append(f"Eerdere rapportages: {len(hist)}, laatste was '{hist[0].get('label', '')}'.")
    except Exception:
        pass
    s = report.get("search") or {}
    if s.get("clicks") or s.get("impressions"):
        regel = f"Google-zoekverkeer deze periode: {s.get('clicks', 0)} klikken op {s.get('impressions', 0)} vertoningen."
        if s.get("clicks_delta") is not None:
            regel += f" Verschil met de periode ervoor: {s.get('clicks_delta'):+d} klikken."
        r.append(regel)
    posities = report.get("positions") or []
    if posities:
        top = ", ".join(
            (f"'{p.get('keyword', '')}' op positie {p.get('position')}"
             + (f" (vorige maand {p['vorige']})" if p.get("vorige") else f" ({int(p.get('change') or 0):+d})"))
            if int(p.get("position") or 0) > 0
            else f"'{p.get('keyword', '')}' staat nog niet in de top 100"
            for p in posities[:6])
        r.append("Zoekwoordposities: " + top)
        genoteerd = [int(p.get("position") or 0) for p in posities if int(p.get("position") or 0) > 0]
        regel = (f"Samenvatting posities: {sum(1 for p in posities if int(p.get('position') or 99) <= 3)} "
                 f"in de top 3, {sum(1 for p in posities if int(p.get('position') or 99) <= 10)} in de top 10")
        if genoteerd:
            regel += f", gemiddelde positie {round(sum(genoteerd) / len(genoteerd), 1)}"
        if len(genoteerd) < len(posities):
            regel += (f"; {len(posities) - len(genoteerd)} van de {len(posities)} getoonde "
                      "zoekwoorden staan nog niet in de top 100")
        totaal_pos = int(report.get("positions_totaal") or 0)
        if totaal_pos > len(posities):
            regel += (f". In totaal volgen we {totaal_pos} zoekwoorden; getoond zijn de "
                      "focus-zoekwoorden en de termen met een notering")
        r.append(regel + ".")
    c = report.get("counts") or {}
    if "seo" in mods and any(c.values()):
        r.append(f"Deze periode gedaan: {c.get('pages', 0)} nieuwe pagina's, {c.get('blogs', 0)} blogs, "
                 f"{c.get('fixes', 0)} meta-fixes, {c.get('improvements', 0)} verbeteringen.")
    for i in ((report.get("agent") or {}).get("items") or [])[:5]:
        onderbouwing = _klantformulering(i.get("reasoning", ""))
        if onderbouwing:
            r.append("Uitgevoerd: " + _klantformulering(i.get("label", "")) + ": " + onderbouwing)
    reeks = report.get("score_history") or []
    if len(reeks) >= 2:
        try:
            r.append(f"Sitescore-verloop: van {reeks[0].get('score')} naar {reeks[-1].get('score')} "
                     f"sinds {_rapport_startmaand(reeks)}.")
        except Exception:
            pass
    if int(report.get("avg_score") or 0):
        regel_score = (f"SEO-score nu: {report.get('avg_score')}/100 "
                       + ("(de gezondheidsscore van de site uit onze doorlopende sitecontrole)"
                          if (report.get("score_bron") or "") == "sitecontrole"
                          else "(het gemiddelde van alle pagina's)"))
        if report.get("score_start") is not None:
            regel_score += (f"; aan het begin van de periode was dit {report['score_start']}/100 "
                            "(zelfde meetlat)")
        r.append(regel_score + ".")
    gbp = report.get("gbp") or {}
    if gbp.get("connected"):
        r.append(f"Bedrijfsprofiel deze periode: {gbp.get('posts', 0)} berichten geplaatst, "
                 f"{gbp.get('photos', 0)} foto's, {gbp.get('new_reviews', 0)} nieuwe reviews, "
                 f"{gbp.get('replies', 0)} reviews beantwoord, gemiddeld {gbp.get('average', 0)} sterren "
                 f"({gbp.get('total', 0)} reviews totaal), {gbp.get('views', 0)} keer getoond in Google.")
        titels = ", ".join(str(p.get("summary") or "")[:80] for p in (gbp.get("post_items") or [])[:3])
        if titels:
            r.append("Geplaatste berichten: " + titels)
    elif "gbp" in mods:
        r.append("Het Google Bedrijfsprofiel is nog niet gekoppeld.")
    ads = report.get("ads") or {}
    if ads.get("connected"):
        r.append(f"Google Ads deze periode: {ads.get('clicks', 0)} klikken, {ads.get('impressions', 0)} "
                 f"vertoningen, {ads.get('conversions', 0)} conversies, kosten {ads.get('cost', 0)}.")
    elif "ads" in mods:
        r.append("Google Ads is nog niet gekoppeld.")
    for lbl, n, voorbeelden in _rapport_onderhoud_groepen(report):
        r.append(f"Onderhoud: {lbl} ({n}x): {voorbeelden}")
    oh = report.get("onderhoud_stats") or {}
    if oh.get("checks"):
        r.append(f"Beheer: uptime {oh.get('uptime_pct')}% bij {oh['checks']} bereikbaarheidsmetingen, "
                 f"{oh.get('verstoringen', 0)} verstoringen"
                 + (f", gemiddelde reactietijd {oh['reactie_ms']} ms." if oh.get("reactie_ms") else "."))
    if oh.get("backups"):
        r.append(f"Beheer: {oh['backups']} dagelijkse back-ups van de site-inhoud gemaakt.")
    if oh.get("ssl_dagen") is not None:
        r.append(f"Beheer: SSL-certificaat geldig (nog {oh['ssl_dagen']} dagen).")
    if oh.get("psi_score") is not None:
        r.append(f"Beheer: Google PageSpeed-score {oh['psi_score']}/100 (mobiel)"
                 + (f", grootste beeldelement na {oh['lcp_ms']} ms." if oh.get("lcp_ms") else "."))
    if oh.get("domein_status"):
        r.append("Beheer: domeinregistratie actief"
                 + (f", loopt nog {oh['domein_dagen']} dagen." if oh.get("domein_dagen") is not None else "."))
    if report.get("summary"):
        r.append("Strategiebeeld: " + _klantformulering(str(report.get("summary"))[:400]))
    for p in (report.get("priorities") or [])[:3]:
        r.append("Focuspunt uit de strategie: " + _klantformulering(str(p)))
    for g in (report.get("open_gaps") or [])[:3]:
        if g.get("topic"):
            r.append(f"Nog te maken content: {g['topic']}: {_klantformulering(g.get('action', ''))}")
    if report.get("note"):
        r.append("Persoonlijke notitie van de accountmanager: " + str(report.get("note"))[:600])
    return "\n".join("- " + x for x in r if x)


def _rapport_gbp_tekst(gbp: dict, report=None) -> str:
    """Het bedrijfsprofiel-verhaal in één alinea; valt terug op een uitleg als er niets
    gebeurde of het profiel (nog) niet gekoppeld is."""
    ai = _rapport_tekst_uit(report, "gbp")
    if ai:
        return ai
    zinnen = []
    if gbp.get("posts"):
        titels = ", ".join(str(p.get("summary") or "") for p in (gbp.get("post_items") or [])[:3])
        zinnen.append(f"We maakten {gbp['posts']} post{'s' if gbp['posts'] > 1 else ''} op het "
                      f"profiel{': ' + titels if titels else ''}.")
    if gbp.get("photos"):
        meervoud = "foto's" if gbp["photos"] > 1 else "foto"
        zinnen.append(f"Er kwamen {gbp['photos']} {meervoud} bij; een profiel met verse beelden "
                      "wordt vaker aangeklikt.")
    if gbp.get("new_reviews"):
        zinnen.append(f"En er kwamen {gbp['new_reviews']} nieuwe review"
                      f"{'s' if gbp['new_reviews'] > 1 else ''} binnen.")
    if gbp.get("replies"):
        zinnen.append(f"We reageerden op {gbp['replies']} review{'s' if gbp['replies'] > 1 else ''}; "
                      "een profiel dat antwoordt wekt vertrouwen bij nieuwe klanten.")
    if gbp.get("stats"):
        zinnen.append(f"Het profiel werd {gbp.get('views', 0)} keer getoond in Google, waarvan "
                      f"{gbp.get('views_maps', 0)} keer in Maps.")
    if zinnen:
        return " ".join(zinnen)
    if gbp.get("connected"):
        return ("Het profiel staat er goed op. We houden de reviews en vermeldingen in "
                "de gaten en plaatsen berichten zodra er iets te melden valt.")
    return ("Zodra we het Google Bedrijfsprofiel aansluiten, zie je hier hoe vaak "
            "jullie in Maps en het lokale zoekresultaat verschijnen, en wat we daar "
            "hebben geplaatst.")


def _rapport_gedaan_items(report: dict, eerste: bool) -> list:
    """[(titel, uitleg)] — wat we deze periode deden, in klanttaal. Eerst de beslissingen
    van de motor, anders de tellers uit het activiteitenlog, anders het eerlijke
    'geen ingreep nodig'-verhaal."""
    gedaan = []
    # Vijf werklijst-fixes van dezelfde soort gaven vijf bijna identieke regels en
    # drukten de unieke acties uit de top vijf (Morris 2026-08-25: 'allemaal vrij
    # dubbel op'). Groepeer per soort werk: een groep wordt één regel met aantal en
    # pagina's, een unieke actie houdt zijn eigen onderbouwing.
    groepen = {}
    for i in (report.get("agent") or {}).get("items", []):
        groepen.setdefault(i.get("action") or i.get("label") or "", []).append(i)
    for groep in list(groepen.values())[:5]:
        kop = groep[0]
        label = _RAPPORT_ACTIE_LABELS.get(kop.get("action", "")) or _klantformulering(kop.get("label", ""))
        if not label:
            continue
        if len(groep) == 1:
            uitleg = _klantformulering(kop.get("reasoning", ""))
            pad = (kop.get("path") or "").strip()
            if pad:
                uitleg = (uitleg + " " if uitleg else "") + f"({_rapport_pad(pad)})"
            gedaan.append((label, uitleg))
        else:
            paden = []
            for i in groep:
                p = (i.get("path") or "").strip()
                if p and _rapport_pad(p) not in paden:
                    paden.append(_rapport_pad(p))
            uitleg = ("Onder andere op " + ", ".join(paden[:3]) + "." if paden
                      else f"Op {len(groep)} plekken doorgevoerd.")
            gedaan.append((f"{label} op {len(groep)} pagina's", uitleg))
    if not gedaan:
        c = report.get("counts") or {}

        def _mv(n, enkel, meer):
            return f"{n} {meer if n > 1 else enkel}"
        if c.get("pages"):
            gedaan.append((_mv(c["pages"], "nieuwe pagina", "nieuwe pagina's") + " gepubliceerd",
                           "Elke pagina richt zich op een eigen zoekvraag, zodat jullie op meer termen "
                           "gevonden worden."))
        if c.get("blogs"):
            gedaan.append((_mv(c["blogs"], "nieuw blogartikel", "nieuwe blogartikelen") + " geschreven",
                           "Verse artikelen laten Google zien dat de site leeft en trekken bezoekers "
                           "binnen die nog aan het oriënteren zijn."))
        if c.get("fixes"):
            gedaan.append((_mv(c["fixes"], "pagina", "pagina's") + " beter in beeld gebracht",
                           "We hebben de titels en omschrijvingen aangevuld die Google in de "
                           "zoekresultaten laat zien."))
        if c.get("improvements"):
            gedaan.append((_mv(c["improvements"], "bestaande pagina", "bestaande pagina's") + " aangescherpt",
                           "Sterkere koppen, duidelijkere teksten en betere onderlinge links."))
    if not gedaan:
        gedaan.append(("De site helemaal doorgelicht",
                       "We hebben in kaart gebracht welke pagina's er zijn, waarop ze gevonden worden "
                       "en waar de winst te halen valt.") if eerste else
                      ("De site in de gaten gehouden",
                       "We hebben posities, techniek en teksten gevolgd. Er was deze periode geen "
                       "ingreep nodig, en dat is goed nieuws."))
    return gedaan


def _rapport_groet_naam(report) -> str:
    """Wie ondertekent het rapport (Ryan 2026-08-25): de gekozen afzender ('Marjolein
    van MHS Media') of, zonder keuze, het hele team."""
    naam = str((report or {}).get("sender") or "").strip()
    if not naam or "team" in naam.lower() or naam.lower() in ("mhs media", "iedereen"):
        return "Team MHS Media"
    return f"{naam} van MHS Media"


def _rapport_img_ophalen(url: str):
    """Haalt een rapportbeeld op (max 3MB); None bij elke storing."""
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "damhousing-rapport/1.0"})
        with urllib.request.urlopen(req, timeout=8) as r:
            if not (200 <= int(getattr(r, "status", 200) or 200) < 300):
                return None
            data = r.read(3 * 1024 * 1024 + 1)
            return data if data and len(data) <= 3 * 1024 * 1024 else None
    except Exception:
        return None


def _rapport_intro(naam: str, eerste: bool, report=None):
    """(titel, intro-alinea's). AI-geschreven waar beschikbaar (zie _rapport_ai_teksten),
    anders de vaste tekst. Een eerste rapportage is een kick-off, een vervolg een terugblik.
    Zonder SEO-onderdeel gaat het over de online zichtbaarheid, niet over vindbaarheid."""
    focus = "vindbaarheid" if "seo" in ((report or {}).get("modules") or ["seo"]) else "online zichtbaarheid"
    if eerste:
        vast = (f"Zo starten we met jullie {focus}.", [
            f"Leuk dat we samen aan de slag gaan met de {focus} van {naam}. "
            "Dit is de eerste rapportage, en die is vooral bedoeld als vertrekpunt: hij laat zien "
            "waar jullie nu staan en wat we als eerste oppakken.",
            "Vanaf nu krijg je dit overzicht elke periode. Zo zie je precies wat we doen, wat dat "
            "oplevert en waar we de volgende stap zetten.",
        ])
    else:
        vast = ("Wat we deze periode voor jullie hebben gedaan.", [
            f"We hebben de afgelopen periode weer doorgepakt op de {focus} van {naam}. "
            "Hieronder zie je wat we hebben aangepakt, wat het oplevert en waar we ons de komende "
            "periode op richten.",
        ])
    return (_rapport_tekst_uit(report, "titel") or vast[0],
            _rapport_lijst_uit(report, "intro") or vast[1])


def _rapport_inzicht(report: dict, eerste: bool) -> str:
    ai = _rapport_tekst_uit(report, "inzicht")
    if ai:
        return ai
    # Zonder SEO-onderdeel geen vindbaarheids-verhaal als vaste tekst (Morris, 2026-08-24).
    if "seo" not in (report.get("modules") or ["seo"]):
        return ""
    s = report.get("search") or {}
    inzicht = _klantformulering(report.get("summary", ""))
    if inzicht:
        return inzicht
    if s.get("clicks"):
        return (f"Via Google kwamen er {s.get('clicks')} bezoekers binnen op "
                f"{s.get('impressions', 0)} vertoningen. Dat betekent dat jullie al goed zichtbaar "
                "zijn; de winst zit nu in de pagina's die net buiten de top staan.")
    if eerste:
        return ("De basis staat en alles is meetbaar gemaakt. Vanaf hier bouwen we per periode "
                "verder aan pagina's die op de juiste zoekvragen antwoord geven.")
    return ""


def _rapport_lijst_uit(report, key: str) -> list:
    try:
        v = ((report or {}).get("teksten") or {}).get(key)
    except Exception:
        return []
    if isinstance(v, list):
        return [str(x).strip() for x in v if str(x).strip()]
    return []


def _rapport_mail_onderwerp(label: str) -> str:
    """Onderwerp van de rapportmail. 'Rapportage — Maandrapport augustus' was dubbelop
    én bevatte een em-dash; een label dat al 'rapport' zegt is zelf het onderwerp."""
    label = _rapport_zonder_dashes((label or "").strip())
    return label if "rapport" in label.lower() else ("Rapportage " + label).strip()


def _rapport_onderhoud_groepen(report: dict) -> list:
    """[(label, aantal, voorbeelden)] — gegroepeerd per soort werk: veertien losse regels
    'Meta-fix · Pagina 7' leest als een logbestand en zegt de klant niets."""
    groepen = {}
    for m in (report.get("maintenance") or []):
        lbl = (m.get("label") or "Onderhoud").strip()
        g = groepen.setdefault(lbl, {"n": 0, "titels": []})
        g["n"] += 1
        t = (m.get("title") or "").strip()
        if t and len(g["titels"]) < 4:
            g["titels"].append(t)
    uit = []
    for lbl, g in groepen.items():
        voorbeelden = ", ".join(g["titels"])
        if g["n"] > len(g["titels"]):
            voorbeelden += f" en {g['n'] - len(g['titels'])} andere"
        uit.append((lbl, g["n"], voorbeelden))
    return uit


def _rapport_onderhoud_stats_zin(stats: dict, report=None) -> str:
    """Het beheer-verhaal (uptime/back-ups/SSL) in klanttaal; AI-geschreven waar
    beschikbaar, en alleen over wat er echt gemeten is."""
    ai = _rapport_tekst_uit(report, "onderhoud")
    if ai:
        return ai
    delen = []
    if stats.get("checks"):
        pct = str(stats.get("uptime_pct", 0)).replace(".", ",")
        basis = f"De site was {pct}% van de tijd bereikbaar bij {stats['checks']} controles"
        v = int(stats.get("verstoringen") or 0)
        basis += (f"; we zagen {v} korte verstoring{'en' if v != 1 else ''}." if v
                  else ", zonder verstoringen.")
        delen.append(basis)
        if stats.get("reactie_ms"):
            delen.append(f"Gemiddeld stond de pagina er binnen {stats['reactie_ms']} milliseconden.")
    if stats.get("backups"):
        n = int(stats["backups"])
        delen.append(f"We maakten {n} back-up{'s' if n != 1 else ''} van de site-inhoud; "
                     "die kunnen we bij problemen direct terugzetten.")
    if stats.get("psi_score") is not None:
        zin = f"Google geeft de site een snelheidsscore van {stats['psi_score']} van de 100"
        if stats.get("lcp_ms"):
            sec = str(round(stats["lcp_ms"] / 1000, 1)).replace(".", ",")
            zin += f"; het grootste beeldelement staat er binnen {sec} seconden"
        delen.append(zin + ".")
    if stats.get("ssl_dagen") is not None:
        delen.append("De beveiligde verbinding (SSL) is actief en het certificaat is geldig.")
    if stats.get("domein_status"):
        if stats.get("domein_dagen") is not None:
            delen.append(f"De domeinregistratie is actief en loopt nog {stats['domein_dagen']} dagen.")
        else:
            delen.append("De domeinregistratie is actief.")
    return " ".join(delen)


def _rapport_pad(pad: str) -> str:
    """'/' zegt een klant niets \u2014 benoem de homepagina expliciet."""
    pad = (pad or "").strip()
    return "/ (homepagina)" if pad == "/" else pad


def _rapport_posities_claims_kloppen(tekst: str, posities: list) -> bool:
    """Elke 'zoekwoord op/rond positie N'-claim in een AI-tekst moet een echte meting
    zijn (1 positie speling voor 'rond'). De AI kreeg alleen feiten mee, maar verzon
    er posities bij (''kitter' rond positie 5' - te mooi om waar te zijn, Ryan
    2026-08-26); zulke tekst hoort nooit bij de klant te landen."""
    echte = {str(p.get("keyword") or "").strip().lower(): int(p.get("position") or 0)
             for p in (posities or [])}
    for kw, pos in _POSITIE_CLAIM_RE.findall(tekst or ""):
        werkelijk = echte.get(kw.strip().lower())
        if not werkelijk or abs(werkelijk - int(pos)) > 1:
            return False
    return True


def _rapport_posities_duiding(posities: list, report=None) -> str:
    ai = _rapport_tekst_uit(report, "posities")
    if ai:
        return ai
    top3 = [p for p in posities if int(p.get("position") or 99) <= 3]
    bijna = [p for p in posities if 4 <= int(p.get("position") or 99) <= 20]
    if top3:
        duiding = (f"Op {len(top3)} zoekterm{'en' if len(top3) > 1 else ''} staan jullie in de top 3; "
                   "daar komt het meeste verkeer vandaan.")
        if bijna:
            duiding += (f" Nog {len(bijna)} term{'en staan' if len(bijna) > 1 else ' staat'} net "
                        "daarbuiten; die brengen we als volgende naar voren.")
        return duiding
    if bijna:
        return (f"{len(bijna)} zoekterm{'en staan' if len(bijna) > 1 else ' staat'} binnen bereik van "
                "de eerste pagina. Daar zit de snelste winst, dus daar zetten we op in.")
    return "De posities zijn vastgelegd; hiermee hebben we een ijkpunt om de groei aan af te meten."


def _rapport_posities_selectie(posities: list, focus: list, cap: int = 10) -> list:
    """Wat rapporteren we aan de klant? Eerst waar we op sturen én al ergens staan,
    dan de overige genoteerde, dan focus zonder notering ('>100' is een eerlijk
    vertrekpunt). Een niet-focus-zoekwoord zonder notering ('vloerenbedrijf' is
    supercompetitief, 'dat kun je op het begin niet winnen', Ryan 2026-08-25) zegt
    de klant niets en valt weg. Focus-zoekwoorden die SE Ranking nog niet volgt
    doen tóch mee als '>100'-rij ('moeten er echt wel 5-10 staan'): de autopilot
    meldt ze dagelijks aan en dit zijn precies de termen waar we op sturen.
    Zonder focuslijst valt er niets te kiezen: alles."""
    focus = [str(k).strip() for k in (focus or []) if str(k).strip()]
    fl = {k.lower() for k in focus}
    if not fl:
        return list(posities)[:cap]
    aanwezig = {str(p.get("keyword") or "").strip().lower() for p in posities}
    alle = list(posities) + [{"keyword": k, "position": 0, "change": 0}
                             for k in focus if k.lower() not in aanwezig]

    def rang(p):
        pos = int(p.get("position") or 0)
        is_focus = str(p.get("keyword") or "").strip().lower() in fl
        groep = 0 if (is_focus and pos > 0) else (1 if pos > 0 else 2)
        return (groep, pos or 9999, str(p.get("keyword") or ""))
    uit = [p for p in alle
           if int(p.get("position") or 0) > 0
           or str(p.get("keyword") or "").strip().lower() in fl]
    gesorteerd = sorted(uit, key=rang)
    # Binnen die rangorde spreiden we over ONDERWERPEN (Ryan 2026-08-26: "ipv dat alles bijv
    # over één dienst gaat"). Tien regels die alle tien varianten van één onderwerp zijn
    # vertellen de klant niets over de rest van zijn site. Nu komt eerst van elk onderwerp de
    # best genoteerde regel. Bij tien of minder kandidaten is de uitkomst identiek aan vroeger.
    # Let op: is de FOCUSLIJST zelf eenzijdig, dan kan het rapport geen breedte tonen die er
    # niet is — dat wordt bij de keuze rechtgezet (`_zoekwoord_aanbevelen`), niet hier.
    onderwerpen = _kw_onderwerpen([str(p.get("keyword") or "") for p in gesorteerd])
    return _spreid_over_onderwerpen(
        gesorteerd, lambda p: str(p.get("keyword") or ""), onderwerpen, cap)


def _rapport_score_actueel() -> tuple:
    """(score, bron) zoals het rapport hem toont: de gezondheidsscore uit de
    sitecontrole-cache, anders het paginagemiddelde."""
    try:
        g = (_seo_health(alleen_cache=True) or {}).get("score")
    except Exception:
        g = None
    return (int(g), "sitecontrole") if g else (_seo_score_gemiddeld(), "paginas")


def _rapport_score_duiding(groei: int, startmaand: str, report=None) -> str:
    ai = _rapport_tekst_uit(report, "score")
    if ai:
        return ai
    if groei > 0:
        return (f"De score is sinds {startmaand} met {groei} punten gestegen. "
                "Dat is precies de lijn die we willen vasthouden.")
    if groei == 0:
        return ("De score houdt zich stabiel. De basis staat; de winst zit nu in de "
                "pagina's die net buiten de top staan, en daar zetten we op in.")
    return ("De score ligt iets lager dan bij de start. Dat komt doordat er nieuwe "
            "pagina's zijn bijgekomen die nog moeten inlopen; die pakken we als "
            "eerste op.")


def _rapport_slottekst(eerste: bool, report=None) -> str:
    ai = _rapport_tekst_uit(report, "slot")
    if ai:
        return ai
    if eerste:
        return ("We gaan hier de komende periode volop mee aan de slag. Heb je vragen over dit rapport "
                "of wil je ergens extra nadruk op leggen? Laat het weten, we denken graag mee.")
    return ("Vragen over dit rapport, of ideeën waar we de komende periode op moeten inzetten? "
            "Laat het weten, we denken graag mee.")


def _rapport_soortlabel(report) -> str:
    """Kopregel-label boven het rapport. Altijd gewoon 'Rapportage' (Morris 2026-08-25):
    met GBP en Onderhoud erbij dekte 'SEO-rapportage' de lading niet meer."""
    return "Rapportage"


def _rapport_startmaand(reeks: list) -> str:
    """Voluit ('augustus'): op de grafiek-as staan afkortingen omdat er zes naast elkaar
    moeten, maar in een lopende zin leest 'sinds maart' beter dan 'sinds mrt'."""
    try:
        return _NL_MAANDEN[int(reeks[0]["maand"][5:7]) - 1]
    except Exception:
        return reeks[0]["label"] if reeks else ""


def _rapport_tekst_uit(report, key: str) -> str:
    """AI-sectietekst van het rapport zelf; leeg = terugvallen op de vaste tekst."""
    try:
        v = ((report or {}).get("teksten") or {}).get(key)
    except Exception:
        return ""
    return v.strip() if isinstance(v, str) else ""


# Een door de AI meegeschreven "Stap 2:" vooraan de tekst. Het model nam dat over uit het
# voorbeeldschema van de strategie-prompt, dat de stappen genummerd voordeed.
_RAPPORT_STAP_VOORAF = re.compile(r"^\s*stap\s*\d+\s*[:.)\-–]\s*", re.I)


def _rapport_stap(nr: int, tekst: str) -> tuple:
    """('Stap 1', tekst) — het stapnummer als vetgedrukte aanhef, net als de onderwerpen
    van de punten eronder.

    Morris 2026-08-27: "Stap 1,2,3 is niet dikgedrukt". Ze stonden als kale regel omdat het
    label uit de AI-tekst zelf kwam en niet uit de kop, en alleen een kop wordt vet gezet.
    Het nummer komt nu uit de code — dan staat het er op elke site en in elk rapport — en
    een meegeschreven "Stap n:" halen we weg zodat het er niet twee keer staat."""
    return f"Stap {nr}", _RAPPORT_STAP_VOORAF.sub("", tekst or "").strip()


def _rapport_vooruit_items(report: dict) -> list:
    """[(kop, tekst)] — focuspunten voor de komende periode; kop (het gap-onderwerp) mag
    leeg zijn. AI-geschreven waar beschikbaar; de vaste terugval is module-bewust, zodat
    een bedrijfsprofiel-rapport geen SEO-focuspunten voorgeschoteld krijgt."""
    ai = _rapport_lijst_uit(report, "vooruit")
    if ai:
        return [("", t) for t in ai][:5]
    mods = report.get("modules") or ["seo"]
    vooruit = [_rapport_stap(i, _klantformulering(p))
               for i, p in enumerate((report.get("priorities") or [])[:3], 1)]
    # Een kale "Stap 2:" zonder tekst erachter is geen focuspunt maar een lege regel.
    vooruit = [(k, t) for k, t in vooruit if t]
    vooruit += [((g.get("topic") or ""), _klantformulering(g.get("action", "")))
                for g in (report.get("open_gaps") or [])[:3] if g.get("topic")]
    vooruit = [(k, t) for k, t in vooruit if k or t]
    if not vooruit and "seo" in mods:
        bijna = [p for p in (report.get("positions") or []) if 4 <= int(p.get("position") or 99) <= 20]
        if bijna:
            vooruit.append(("", f"De {len(bijna)} zoektermen die net buiten de top 3 staan naar voren "
                                "brengen."))
        vooruit.append(("", "De best bezochte pagina's verder aanscherpen, zodat meer bezoekers ook echt "
                            "contact opnemen."))
        vooruit.append(("", "Nieuwe content toevoegen op de zoekvragen waar jullie nu nog niet op gevonden "
                            "worden."))
    elif not vooruit and "gbp" in mods:
        vooruit.append(("", "Het profiel gevuld houden met verse berichten en foto's van recent werk."))
        vooruit.append(("", "Elke nieuwe review snel en persoonlijk blijven beantwoorden."))
    elif not vooruit:
        vooruit.append(("", "De resultaten verder aanscherpen; daarover lees je in de volgende rapportage."))
    return vooruit[:5]


def _rapport_zonder_dashes(tekst: str) -> str:
    """Huisregel: geen em- of en-dashes in klantcontent. De vaste rapportteksten zijn al
    schoon; dit is het vangnet voor alles wat het rapport instroomt (AI-tekst, logregels,
    de persoonlijke notitie). ' — ' midden in een zin wordt een komma, een aangeplakt
    streepje een koppelteken. Entiteiten eerst, anders blijft &mdash; gewoon staan."""
    t = str(tekst or "")
    for los in (" &mdash; ", " &#8212; ", " &ndash; ", " &#8211; ", " — ", " – "):
        t = t.replace(los, ", ")
    for vast in ("&mdash;", "&#8212;", "&ndash;", "&#8211;", "—", "–"):
        t = t.replace(vast, "-")
    return t


def _rdap_ophalen(domein: str):
    """Ruwe RDAP-respons voor het domein; None bij elke storing."""
    try:
        req = urllib.request.Request("https://rdap.org/domain/" + urllib.parse.quote(domein),
                                     headers={"User-Agent": "damhousing-monitor/1.0",
                                              "Accept": "application/rdap+json"})
        with urllib.request.urlopen(req, timeout=15) as r:
            return json.loads(r.read() or b"{}")
    except Exception:
        return None


def _report_top_pages(frm: str, to: str, limiet: int = 5) -> list:
    """Best bezochte pagina's in de periode, uit onze eigen bezoekersteller.

    Bewust de eigen teller en niet Google: die werkt vanaf dag één en op elke site,
    ook zonder Search Console- of Analytics-koppeling."""
    try:
        d_van = datetime.strptime(frm, "%Y-%m-%d")
        d_tot = datetime.strptime(to, "%Y-%m-%d")
    except Exception:
        return []
    if d_tot < d_van or (d_tot - d_van).days > 92:   # langer bereik = duizenden kv_list-calls
        return []
    paden = {}
    d = d_van
    while d <= d_tot:
        bucket = d.strftime("%Y%m%d")
        prefix = f"stat:pv:day:{bucket}:"
        try:
            for pk in (kv_list(prefix) or []):
                if pk.startswith(prefix):
                    pad = pk[len(prefix):]
                else:
                    sp = _safe_kv_filename(prefix)
                    pad = pk[len(sp):].replace("_", "/") if pk.startswith(sp) else ""
                if not pad:
                    continue
                n = kv_get(f"stat:pv:day:{bucket}:{pad}", 0) or 0
                if isinstance(n, int) and n > 0:
                    paden[pad] = paden.get(pad, 0) + n
        except Exception:
            pass
        d += timedelta(days=1)
    top = sorted(({"path": p, "views": v} for p, v in paden.items()), key=lambda x: -x["views"])
    return top[:limiet]


def _seo_improve_post(path: str, issue: str = "", action: str = "",
                      decision_reason: str = "", decision_evidence: dict = None,
                      decision_source: str = "autopilot") -> dict:
    """Schrijf een meta-titel/-omschrijving op één BLOGARTIKEL.

    Anders dan bij een project hoeft het model hier niet te veranderen: een post heeft al een
    `meta`-dict. Die is alleen leeg, en dan valt de render terug op "{titel} | <bedrijf>" —
    bij een lange artikelkop precies de `title_long` die de crawl meldt.
    """
    if not _ai_configured():
        return {"ok": False, "error": "Geen AI-koppeling actief", "code": 400}
    post = _post_by_path(path)
    if not post:
        return {"ok": False, "error": "Blogartikel niet gevonden", "code": 404}
    meta = dict(post.get("meta") or {})     # canonical e.d. blijft staan
    oude_titel = str(meta.get("title") or "").strip()
    oude_desc = str(meta.get("description") or "").strip()
    tekst = " ".join((b.get("props") or {}).get("text", "") or b.get("text", "") or ""
                     for b in (post.get("content_blocks") or []) if isinstance(b, dict))[:1000]
    sysp = (f"Je bent SEO-copywriter voor {_seo_business_context()}. Je schrijft de meta-titel en "
            "-omschrijving voor één BLOGARTIKEL. De titel moet de zoekvraag dekken en binnen de "
            "lengte blijven; de omschrijving maakt nieuwsgierig zonder clickbait. "
            "Antwoord UITSLUITEND als JSON: {\"title\":\"max 60 tekens\","
            "\"description\":\"120-158 tekens\"}.")
    usr = (f"Artikel: {post.get('title', '')}\nSamenvatting: {post.get('excerpt', '') or '(geen)'}\n"
           f"Inhoud (fragment): {tekst or '(geen)'}\n"
           f"Gesignaleerd probleem: {issue or '(geen)'}\nAanbevolen actie: {action or '(schrijf betere meta)'}")
    rr = _anthropic_call([{"role": "user", "content": usr}], system=sysp,
                         max_tokens=400, model="claude-haiku-4-5-20251001")
    if rr.get("error"):
        return {"ok": False, "error": rr.get("error"), "code": 502}
    d = _loads_lenient("".join(b.get("text", "") for b in rr.get("content", []))) or {}
    applied = {}
    if d.get("title"):
        meta["title"] = str(d["title"]).strip()[:65]
        applied["title"] = meta["title"]
    if d.get("description"):
        meta["description"] = str(d["description"]).strip()[:170]
        applied["description"] = meta["description"]
    if not applied:
        return {"ok": False, "error": "AI gaf geen bruikbare meta terug.", "code": 502}
    post["meta"] = meta
    save_post(post)
    _trigger_deploy(f"seo blog-meta {post.get('slug', '')}")
    audit_log("seo.improve.post", post.get("slug", ""), "meta van blogartikel herschreven")
    _seo_log("improve", path, post.get("title", ""), "blogmeta herschreven")
    ev = {"oude_titel": oude_titel, "oude_omschrijving": oude_desc}
    if "title" in applied:
        ev["nieuwe_titel"] = applied["title"]
    if "description" in applied:
        ev["nieuwe_omschrijving"] = applied["description"]
    ev.update(decision_evidence or {})
    did = _seo_decision_add("meta_update", path, post.get("title", ""),
                            reasoning=decision_reason or f"{issue} — {action}".strip(" —") or "Blogmeta verbeterd",
                            evidence=ev, risk=1, status="uitgevoerd", source=decision_source,
                            undo={"type": "post_meta", "slug": post.get("slug", ""),
                                  "meta": {"title": oude_titel, "description": oude_desc}})
    return {"ok": True, "applied": applied, "id": did}


def _seo_improve_project(path: str, issue: str = "", action: str = "",
                         decision_reason: str = "", decision_evidence: dict = None,
                         decision_source: str = "autopilot") -> dict:
    """Schrijf een unieke meta-titel/-omschrijving op één PROJECT.

    Tegenhanger van `_seo_improve_page` voor de andere contentsoort. Nodig omdat een project
    geen pagina-record is: `_seo_improve_page` gaf er een nette 404 op, waardoor de crawl-
    meldingen op projectpagina's onherstelbaar waren. En juist daar zat het volume — de render
    leidde de meta af, dus elk project zonder eigen tekst kreeg dezelfde generieke omschrijving
    en dat is precies wat de audit als `description_duplicate` opmerkte.
    """
    if not _ai_configured():
        return {"ok": False, "error": "Geen AI-koppeling actief", "code": 400}
    # Zoek in DEZELFDE lijst die we straks opslaan: `_project_by_path` leest opnieuw uit KV,
    # dus een wijziging op dat object zou nooit bewaard worden.
    ref = _project_by_path(path)
    if not ref:
        return {"ok": False, "error": "Project niet gevonden", "code": 404}
    items = get_projects()
    doel = next((p for p in items if p.get("id") == ref.get("id")), None)
    if not doel:
        return {"ok": False, "error": "Project niet gevonden", "code": 404}
    oude_titel = str(doel.get("meta_title") or "").strip()
    oude_desc = str(doel.get("meta_description") or "").strip()
    sysp = (f"Je bent SEO-copywriter voor {_seo_business_context()}. Je schrijft de meta-titel en "
            "-omschrijving voor één uitgevoerd PROJECT (een referentie/case, geen dienstpagina). "
            "Maak het concreet en lokaal: wat is er gedaan en waar. Geen clickbait, geen "
            "zoekwoord-stapeling, en maak het ONDERSCHEIDEND van andere projecten. "
            "Antwoord UITSLUITEND als JSON: {\"title\":\"max 60 tekens\","
            "\"description\":\"120-158 tekens\"}.")
    usr = (f"Project: {doel.get('title', '')}\nPlaats: {doel.get('location', '') or '(onbekend)'}\n"
           f"Datum: {doel.get('date', '')}\nBeschrijving: {(doel.get('description') or '')[:800] or '(geen)'}\n"
           f"Gesignaleerd probleem: {issue or '(geen)'}\nAanbevolen actie: {action or '(schrijf unieke meta)'}")
    rr = _anthropic_call([{"role": "user", "content": usr}], system=sysp,
                         max_tokens=400, model="claude-haiku-4-5-20251001")
    if rr.get("error"):
        return {"ok": False, "error": rr.get("error"), "code": 502}
    d = _loads_lenient("".join(b.get("text", "") for b in rr.get("content", []))) or {}
    applied = {}
    if d.get("title"):
        doel["meta_title"] = str(d["title"]).strip()[:65]
        applied["title"] = doel["meta_title"]
    if d.get("description"):
        doel["meta_description"] = str(d["description"]).strip()[:170]
        applied["description"] = doel["meta_description"]
    if not applied:
        return {"ok": False, "error": "AI gaf geen bruikbare meta terug.", "code": 502}
    save_projects(items)
    _trigger_deploy(f"seo project-meta {_project_slug(doel)}")
    audit_log("seo.improve.project", _project_slug(doel), "meta van project herschreven")
    _seo_log("improve", path, doel.get("title", ""), "projectmeta herschreven")
    ev = {"oude_titel": oude_titel, "oude_omschrijving": oude_desc}
    if "title" in applied:
        ev["nieuwe_titel"] = applied["title"]
    if "description" in applied:
        ev["nieuwe_omschrijving"] = applied["description"]
    ev.update(decision_evidence or {})
    did = _seo_decision_add("meta_update", path, doel.get("title", ""),
                            reasoning=decision_reason or f"{issue} — {action}".strip(" —") or "Projectmeta verbeterd",
                            evidence=ev, risk=1, status="uitgevoerd", source=decision_source,
                            undo={"type": "project_meta", "pid": doel.get("id"),
                                  "meta": {"title": oude_titel, "description": oude_desc}})
    return {"ok": True, "applied": applied, "id": did}


def _seo_plan_vingerafdruk(cfg: dict) -> str:
    """Waar het maandplan van afhangt: planner-versie, focus-zoekwoorden en volumes.
    Wijkt de afdruk van het staande plan af, dan is de wereld veranderd en replant
    de dagelijkse tick zelf (afgerond werk blijft staan)."""
    try:
        focus = sorted(str(k).lower() for k in (_agent_config().get("focus_keywords") or []))
    except Exception:
        focus = []
    ruw = repr([PLAN_TAKEN_VERSIE, focus])
    return hashlib.sha1(ruw.encode()).hexdigest()[:10]


def _seo_replan(cfg: dict) -> dict:
    """Herbouw het maandplan met behoud van afgerond werk en de tellers. Gedeeld door
    de tick (automatisch, op vingerafdruk) en het replan-endpoint."""
    old = kv_get("seo:plan") or {}
    done = [t for t in (old.get("queue") or []) if t.get("status") in ("done", "failed")]
    plan = _seo_plan_for_month(cfg)
    plan["queue"] = done + (plan.get("queue") or [])
    plan["bugs_fixed"] = int(old.get("bugs_fixed", 0) or 0)
    plan["report_sent"] = bool(old.get("report_sent"))
    plan["report_id"] = old.get("report_id", "")
    kv_set("seo:plan", plan)
    audit_log("seo.auto.replan", plan.get("month", ""),
              f"{len(plan['queue']) - len(done)} nieuwe taken; {plan.get('volume_reason', '')[:120]}")
    return {"plan": plan, "planned": len(plan["queue"]) - len(done), "kept": len(done)}


def _seo_report_is_first(report: dict) -> bool:
    """Is dit de eerste rapportage voor deze klant? De variant wordt bij het bouwen
    vastgelegd op het rapport zelf: een verstuurd rapport belandt in de historie, en zonder
    die stempel zou dezelfde link een maand later plots een vervolgrapport tonen."""
    if "first_report" in report:
        return bool(report.get("first_report"))
    try:
        eerder = [h for h in (kv_get("seo:report:history", []) or [])
                  if isinstance(h, dict) and h.get("id") != report.get("id")]
        return not eerder
    except Exception:
        return False


def _seo_report_volgende_run(cfg: dict) -> str:
    """Wanneer maakt de automatische rapportage het volgende rapport? Voor de popup
    (Morris 2026-08-26: 'wanneer verstuurd ie, welke datum en hoelaat?'). De
    dagelijkse cron draait in de ochtend en pakt de 1e-3e van de periode."""
    try:
        now = datetime.now()
        kwartaal_maanden = (1, 4, 7, 10)
        if cfg.get("interval") == "quarter":
            key = f"{now.year}-Q{(now.month - 1) // 3 + 1}"
            if now.month in kwartaal_maanden and now.day <= 3 and cfg.get("last_key") != key:
                return "vandaag of morgenochtend (rond 10:00)"
            volgende = next((m for m in kwartaal_maanden if m > now.month), None)
            d = datetime(now.year, volgende, 1) if volgende else datetime(now.year + 1, 1, 1)
        else:
            if now.day <= 3 and cfg.get("last_key") != now.strftime("%Y-%m"):
                return "vandaag of morgenochtend (rond 10:00)"
            d = (now.replace(day=1) + timedelta(days=32)).replace(day=1)
        return f"1 {_NL_MAANDEN[d.month - 1]} {d.year}, in de ochtend (rond 10:00)"
    except Exception:
        return ""


def _seo_score_gemiddeld() -> int:
    """Gemiddelde SEO-score over de LEVENDE pagina's — dezelfde bron als het
    meta-tags-scherm. seo_scores accumuleert élke ooit gescoorde slug, ook van
    verwijderde pagina's; blind daarover middelen drukte het rapportcijfer
    (80 in het rapport tegen 92 op het scherm, Ryan 2026-08-25)."""
    scores = kv_get("seo_scores", {}) or {}
    if not scores:
        return 0
    try:
        levend = {p.get("slug") for p in (_pages_index() or [])}
    except Exception:
        levend = set()
    cijfers = [int((scores.get(s) or {}).get("score") or 0) for s in levend if s in scores]
    if not cijfers:
        # Geen levende pagina met een score (verse site of lege index): alles telt.
        cijfers = [int(v.get("score") or 0) for v in scores.values() if isinstance(v, dict)]
    return int(sum(cijfers) / len(cijfers)) if cijfers else 0


def _seo_score_log_seed() -> None:
    """Eenmalige handmatige startwaarde (verzoek Ryan 2026-08-25): vóór de dagelijkse
    scorelog bestond, was de gezondheidsscore aan het begin van deze periode 80.
    Zonder die meting kan het lopende rapport geen verschil tonen; vanaf nu neemt
    de dagelijkse log het over. Idempotent via een KV-vlag."""
    try:
        if kv_get("seo:score:log:seed80"):
            return
        log = kv_get("seo:score:log", []) or []
        if not any(isinstance(e, dict) and e.get("d") == "2026-07-26"
                   and e.get("bron") == "sitecontrole" for e in log):
            log.append({"d": "2026-07-26", "score": 80, "bron": "sitecontrole"})
            log.sort(key=lambda e: str(e.get("d")))
            kv_set("seo:score:log", log[-730:])
        kv_set("seo:score:log:seed80", True)
    except Exception:
        pass


def _seo_score_log_upsert(score: int, bron: str, datum: str = "") -> None:
    """Dagelijkse scorelog (score + bron) — de bron voor 'verschil sinds begin van
    de periode' in het rapport (Ryan 2026-08-25). Eén meting per dag, cap twee jaar."""
    try:
        if not int(score or 0):
            return
        log = kv_get("seo:score:log", []) or []
        datum = (datum or datetime.now().strftime("%Y-%m-%d"))[:10]
        log = [e for e in log if isinstance(e, dict)
               and not (e.get("d") == datum and e.get("bron") == str(bron or ""))]
        log.append({"d": datum, "score": int(score), "bron": str(bron or "")})
        log.sort(key=lambda e: str(e.get("d")))
        kv_set("seo:score:log", log[-730:])
    except Exception:
        pass


def _seo_score_maandreeks(gemiddelde: int, tot_datum: str) -> list:
    """[{maand, label, score}] — het scoreverloop per maand, maximaal zes.

    Het dashboard bewaart alleen de laatste twaalf wéken; na een kwartaal valt er dan niets
    meer te vergelijken. Daarom houden we hier een eigen maandreeks bij, geënt op de
    weekhistorie die er al ligt zodat een bestaande site niet met een lege grafiek begint."""
    try:
        hist = kv_get("seo:score:months") or {}
        if not isinstance(hist, dict):
            hist = {}
        for wk, sc in sorted((kv_get("seo:score:weeks") or {}).items()):
            try:
                jaar, week = str(wk).split("-W")
                maand = datetime.strptime(f"{int(jaar)} {int(week)} 1", "%G %V %u").strftime("%Y-%m")
            except Exception:
                continue
            hist.setdefault(maand, int(sc or 0))
        maand_nu = (tot_datum or datetime.now().strftime("%Y-%m-%d"))[:7]
        if gemiddelde:
            hist[maand_nu] = int(gemiddelde)
        hist = {k: int(v or 0) for k, v in sorted(hist.items())[-24:] if int(v or 0) > 0}
        kv_set("seo:score:months", hist)
        return [{"maand": m, "label": _NL_MAANDEN_KORT[int(m[5:7]) - 1], "score": s}
                for m, s in sorted(hist.items())[-6:]]
    except Exception:
        return []


def _seo_score_meet_bij_audit() -> None:
    """Schrijf een scoremeting bij zodra er een NIEUWE afgeronde sitecontrole is —
    niet blind elke dag ('per dag is overdreven, doe het bij een audit', Ryan
    2026-08-25). De meting krijgt de datum van de crawl zelf; zonder sitecontrole
    in de cache valt er niets te meten en gebeurt er niets. Cache-only: dit mag
    nooit zelf een verse oogst starten."""
    try:
        audit = _seranking_audit(alleen_cache=True) or {}
        score = int(audit.get("score") or 0)
        if not score:
            return
        marker = f"{audit.get('audit_id') or ''}@{audit.get('datum') or ''}"
        if kv_get("seo:score:log:audit") == marker:
            return
        _seo_score_log_upsert(score, "sitecontrole", str(audit.get("datum") or "")[:10])
        kv_set("seo:score:log:audit", marker)
    except Exception:
        pass


def _seo_score_start(frm: str, to: str, bron: str):
    """De score aan het begin van de periode, uit de scorelog en MET DEZELFDE BRON:
    de gezondheidsscore en het paginagemiddelde mogen nooit tegen elkaar afgezet
    worden. None = geen bruikbare startmeting (dan geen verschil tonen)."""
    try:
        log = [e for e in (kv_get("seo:score:log", []) or [])
               if isinstance(e, dict) and e.get("bron") == bron and int(e.get("score") or 0)]
        vandaag = datetime.now().strftime("%Y-%m-%d")
        # De laatste meting op of vóór de periodestart IS het begin; die mag niet
        # verdrongen worden door een verse meting middenin de periode ('0 sinds
        # begin periode' terwijl de start 80 was, Ryan 2026-08-26).
        voor = [e for e in log if str(e.get("d")) <= frm and str(e.get("d")) != vandaag]
        if voor:
            return int(max(voor, key=lambda x: str(x.get("d")))["score"])
        binnen = [e for e in log if frm < str(e.get("d")) <= to and str(e.get("d")) != vandaag]
        return int(min(binnen, key=lambda x: str(x.get("d")))["score"]) if binnen else None
    except Exception:
        return None


def _seranking_audit(alleen_cache: bool = False) -> dict:
    """De crawl-uitkomst van SE Ranking voor deze site: score, fouten, gecrawlde pagina's.

    SE Ranking crawlt de site echt; onze eigen score keek alleen naar wat het CMS zelf
    weet (meta-velden, versheid). Die twee naast elkaar zetten geeft een score die niet
    meebeweegt met onze eigen aannames. Leeg dict = geen audit beschikbaar; de eigen
    berekening blijft dan gewoon staan.
    """
    sid = _seranking_site_id()
    if not sid:
        return {}
    # alleen_cache: het rapportpad mag hier nooit op een verse call wachten.
    data = (_seranking_cache_lees("/v1/site-audit/audits", max_uren=12) if alleen_cache
            else _seranking_get("/v1/site-audit/audits", cache_uren=12))
    for a in ((data or {}).get("items") or []):
        if str(a.get("site_id") or "") != str(sid):
            continue
        st = a.get("stats") or {}
        if str(a.get("status") or "") != "finished":
            continue
        return {"score": int(st.get("score") or 0),
                "errors": int(st.get("errors") or 0),
                "warnings": int(st.get("warnings") or 0),
                "notices": int(st.get("notices") or 0),
                "crawled": int(st.get("crawled") or 0),
                "audit_id": str(a.get("id") or ""),
                "datum": str(a.get("last_update") or "")}
    return {}


def _seranking_audit_issues(force: bool = False) -> dict:
    """De losse issues van de laatste crawl, gesplitst in fixbaar en melding.

    Gecachet op audit_id: een nieuwe crawl is nieuw werk, dezelfde crawl is dezelfde uitkomst.
    Elke storing eindigt in een lege oogst — de agent moet doorlopen op wat hij wél heeft.
    """
    audit = _seranking_audit() or {}
    audit_id = str(audit.get("audit_id") or "")
    leeg = {"audit_id": audit_id, "datum": str(audit.get("datum") or ""),
            "fixbaar": [], "meldingen": [], "opgehaald_at": _now_iso()}
    if not audit_id:
        return leeg
    vinger = _audit_catalogus_vingerafdruk()
    bewaard = kv_get("seranking:issues") or {}
    if (not force and isinstance(bewaard, dict)
            and str(bewaard.get("audit_id") or "") == audit_id
            and str(bewaard.get("catalogus") or "") == vinger
            and (time.time() - float(bewaard.get("t", 0) or 0)) < AUDIT_ISSUE_CACHE_UREN * 3600):
        return bewaard.get("data") or leeg

    rapport = _seranking_get("/v1/site-audit/audits/report", {"audit_id": audit_id},
                             cache_uren=AUDIT_ISSUE_CACHE_UREN)
    checks = _audit_checks_uit_rapport(rapport)
    if not checks:
        return leeg
    # Fixbare codes eerst: als het budget aan calls opraakt, raken we liever een melding kwijt
    # dan werk dat de agent had kunnen doen.
    checks.sort(key=lambda c: (0 if _audit_issue_actie(c["code"]) else 1, -c["aantal"]))
    fixbaar, meldingen = [], []
    start = time.monotonic()
    onvolledig = False
    for c in checks[:AUDIT_ISSUE_CODES_MAX]:
        if time.monotonic() - start > AUDIT_ISSUE_TIJDBUDGET_S:
            onvolledig = True
            break
        pagina_data = _seranking_get("/v1/site-audit/audits/issue-pages",
                                     {"audit_id": audit_id, "code": c["code"],
                                      "limit": AUDIT_ISSUE_PADEN_MAX, "offset": 0},
                                     cache_uren=AUDIT_ISSUE_CACHE_UREN)
        if pagina_data is None:
            continue   # één mislukte call sleept de rest van de oogst niet mee
        paden = _audit_paden_uit_antwoord(pagina_data)
        rij = dict(c, paden=paden, audit_id=audit_id)
        actie = _audit_issue_actie(c["code"])
        if actie:
            rij["actie"] = actie
            fixbaar.append(rij)
        else:
            rij["waarom"] = _AUDIT_MELDING_REDENEN.get(c["code"], _AUDIT_MELDING_ALGEMEEN)
            meldingen.append(rij)
    data = {"audit_id": audit_id, "datum": str(audit.get("datum") or ""),
            "fixbaar": fixbaar, "meldingen": meldingen, "opgehaald_at": _now_iso()}
    if onvolledig:
        # Een half opgehaalde crawl niet 12 uur lang als de hele waarheid bewaren. De losse
        # calls die wél lukten zitten al in de cache van `_seranking_get`, dus de volgende
        # ronde maakt het karwei goedkoop af.
        data["onvolledig"] = True
        return data
    kv_set("seranking:issues", {"t": int(time.time()), "audit_id": audit_id,
                                "catalogus": vinger, "data": data})
    return data


def _seranking_bekend() -> dict:
    """Wat eerdere SEO-runs over het SE Ranking-project van deze site vastlegden.

    Bewust zonder netwerkcall: de instellingenpagina toont hier alleen de stand
    en mag niet blijven hangen op een externe dienst die traag of even weg is."""
    if kv_get("seranking:losgekoppeld"):
        return {"gekeken": True, "site_id": ""}
    b = kv_get("seranking:site_id")
    if isinstance(b, str):
        return {"gekeken": bool(b), "site_id": b}
    if isinstance(b, dict):
        return {"gekeken": True, "site_id": str(b.get("id") or "")}
    return {"gekeken": False, "site_id": ""}


def _seranking_cache_lees(pad: str, params: dict = None, max_uren: int = 24):
    """Alleen het gecachete antwoord, zonder netwerk. Voor paden met een strak
    tijdbudget (rapportbouw draait naast de AI-call binnen maxDuration 60s):
    een koude cache betekent dan 'geen data', nooit een wachtende call."""
    bewaard = kv_get("seranking:" + _seranking_cache_sleutel(pad, params))
    if isinstance(bewaard, dict) and (time.time() - float(bewaard.get("t", 0) or 0)) < max_uren * 3600:
        return bewaard.get("data")
    return None


def _seranking_cache_sleutel(pad: str, params: dict = None) -> str:
    qs = urllib.parse.urlencode({"path": pad, **(params or {})})
    return hashlib.sha1(qs.encode()).hexdigest()[:16]


def _seranking_cache_vergeet(pad: str, params: dict = None) -> None:
    """Gooi het gecachete antwoord van één pad weg. Nodig zodra wíj de bron veranderen:
    de sitelijst staat 24 uur vast, dus na het aanmelden zou de site zichzelf een dag
    lang niet terugvinden."""
    kv_delete("seranking:" + _seranking_cache_sleutel(pad, params))


def _seranking_focus_sync() -> None:
    """Autopilot-taak (Ryan 2026-08-25: 'de autopilot zou dit vanzelf moeten doen'):
    zorg dat in elk geval alle focus-zoekwoorden in SE Ranking worden gevolgd — het
    rapport en de kansen-motor kijken daarnaar. Alleen als het project al bestaat
    (aanmelden blijft een bewuste actie), hooguit één poging per dag, en nooit na
    een handmatige ontkoppeling. Faalt stil: de cron mag hier niet op stuklopen."""
    if not _gateway_aan() or kv_get("seranking:losgekoppeld"):
        return
    focus = [str(k).strip() for k in (_agent_config().get("focus_keywords") or []) if str(k).strip()]
    if not focus:
        return
    sid = _seranking_site_id()
    if not sid:
        return
    gevolgd = {str(k.get("name") or "").strip().lower()
               for k in (_seranking_get("/v1/project-management/keywords", {"site_id": sid}) or [])
               if isinstance(k, dict)}
    missend = [k for k in focus if k.lower() not in gevolgd]
    if not missend:
        return
    try:
        laatst = float(kv_get("seranking:focus_sync") or 0)
    except Exception:
        laatst = 0.0
    if time.time() - laatst < 24 * 3600:
        return
    kv_set("seranking:focus_sync", time.time())
    # Korte timeout: de dagelijkse cron doet al veel binnen zijn 60s-budget, en een
    # mislukt-lijkende poging is onschuldig — MAIHS maakt server-side af wat kan en
    # morgen synct de rest idempotent bij.
    ok, _data = _seranking_registreer(focus, timeout=15)
    if ok:
        _seranking_cache_vergeet("/v1/project-management/keywords", {"site_id": sid})
        audit_log("seo.seranking.focus_sync", ",".join(missend)[:120],
                  f"{len(missend)} focus-zoekwoord(en) aangemeld bij SE Ranking")


# Waarom een storing bij SE Ranking niet meer verdwijnt. `_seranking_get` geeft bij elke
# fout None terug — dat is met opzet (de SEO-motor loopt door op wat hij wél heeft), maar het
# gooide ook de reden weg. Een endpoint dat daarna 502 teruggaf kon alleen gissen, en gokte
# op "controleer of het project gekoppeld is" terwijl er in werkelijkheid "402 Payment
# Required" uit de gateway kwam: het tegoed van het SE Ranking-account was op (live gezien
# 2026-08-26 op een andere site, en 2026-08-27 vloot-breed). Die melding stuurt je een uur
# de verkeerde kant op — naar een koppeling die niets mankeert.
_SERANKING_FOUT: dict = {}

_SERANKING_UITLEG = {
    402: "SE Ranking accepteert geen aanvragen meer: het abonnement of het tegoed van het "
         "teamaccount is op (402). Zoekwoorddata komt pas terug als dat is bijgevuld.",
    401: "De SEO-gateway wees de aanvraag af (401): de gatewaysleutel klopt niet meer.",
    403: "De SEO-gateway wees de aanvraag af (403): dit endpoint zit niet in het abonnement.",
    429: "SE Ranking kreeg te veel aanvragen op rij (429). Even wachten en opnieuw proberen.",
}


def _seranking_fout_onthoud(code: int, detail: str) -> None:
    """Leg vast waaróm de laatste aanvraag faalde (0 = niet eens verstuurd/bereikt)."""
    _SERANKING_FOUT.clear()
    _SERANKING_FOUT.update({"code": int(code or 0), "detail": str(detail or "")[:300]})


def _seranking_fout_vergeet() -> None:
    """Schone lei. Nodig aan het begin van een handeling: de lambda blijft warm tussen
    requests, dus zonder dit zou de storing van een vorige bezoeker blijven plakken."""
    _SERANKING_FOUT.clear()


def _seranking_fout_reden() -> str:
    """De laatste storing in mensentaal, of "" als er niets misging."""
    if not _SERANKING_FOUT:
        return ""
    code = int(_SERANKING_FOUT.get("code") or 0)
    detail = str(_SERANKING_FOUT.get("detail") or "").strip()
    if code in _SERANKING_UITLEG:
        return _SERANKING_UITLEG[code]
    if code:
        return f"De SEO-gateway gaf {code} terug op de zoekwoorddata."
    return ("De SEO-gateway was niet bereikbaar"
            + (f": {detail}" if detail else "."))


def _gateway_foutmelding(code: int, rauw: str) -> str:
    """De reden uit een gateway-ANTWOORD (dus met body), in taal voor wie het moet oplossen.

    MAIHS stuurt bij een fout JSON mee met `message` (mensentaal) en `error` (code).
    Zonder uitpakken belandde de rauwe JSON in de melding op het scherm, of alleen het
    nummer — en "502" zegt niemand iets."""
    try:
        d = json.loads(rauw or "{}")
    except Exception:
        d = {}
    melding = str(d.get("message") or "").strip()
    if melding:
        return melding
    kort = str(d.get("error") or "").strip()
    if kort == "no_domain":
        return ("Deze site staat bij MHS Media nog zonder domein, dus SE Ranking weet niet "
                "welk adres het moet volgen.")
    if code in _SERANKING_UITLEG:
        return _SERANKING_UITLEG[code]
    return "De gateway gaf " + str(code) + " terug" + ((" (" + kort + ")") if kort else "") + "."


def _seranking_get(pad: str, params: dict = None, cache_uren: int = 6):
    """Leest via de gateway. Geeft None terug bij elke storing: de SEO-motor moet
    doorlopen op wat hij wél heeft, niet stukvallen omdat een bron even weg is."""
    basis = _gateway_origin()
    if not (basis and _gateway_key()):
        _seranking_fout_onthoud(0, "geen SEO-gateway geconfigureerd op deze site")
        return None
    sleutel = "seranking:" + _seranking_cache_sleutel(pad, params)
    bewaard = kv_get(sleutel)
    if isinstance(bewaard, dict) and (time.time() - float(bewaard.get("t", 0) or 0)) < cache_uren * 3600:
        return bewaard.get("data")
    qs = urllib.parse.urlencode({"path": pad, **(params or {})})
    try:
        req = urllib.request.Request(
            f"{basis}/api/seo-gateway/seranking?{qs}",
            headers={"Authorization": "Bearer " + _gateway_key(),
                     # Cloudflare weigert de standaard urllib-User-Agent (fout 1010).
                     "User-Agent": "MAIHS-SEO-Gateway-Client/1.0"})
        with urllib.request.urlopen(req, timeout=25) as r:
            data = json.loads(r.read().decode("utf-8") or "null")
    except urllib.error.HTTPError as e:
        _seranking_fout_onthoud(e.code, f"{e.code} {e.reason}")
        print(f"[seranking] {pad} mislukt: HTTP {e.code} {e.reason}")
        return None
    except Exception as e:
        _seranking_fout_onthoud(0, str(e))
        print(f"[seranking] {pad} mislukt: {e}")
        return None
    # Een geslaagde aanroep wist de vorige storing -- behalve een 429. Die gaat niet over
    # één aanroep maar over de hele reeks: de gateway knijpt af rond de elf aanroepen op
    # rij, en de zoekwoordronde doet er twee per zaad. Wist een latere meevaller die 429,
    # dan kwam er een halve lijst terug met de melding dat SE Ranking de zoektermen niet
    # kent -- en ga je de zaden zitten aanpassen terwijl er niets mis mee is.
    if int(_SERANKING_FOUT.get("code") or 0) != 429:
        _seranking_fout_vergeet()
    kv_set(sleutel, {"t": int(time.time()), "data": data})
    return data


def _seranking_intent_labels(codes) -> str:
    """SE Ranking codeert zoekintentie als letters (L/I/N/T/C); naar buiten toe
    horen dat Nederlandse woorden te zijn. Onbekende waarden passeren ongewijzigd
    (de API kan ooit voluit gaan schrijven)."""
    kaart = {"L": "lokaal", "I": "informatief", "N": "navigatie",
             "T": "transactioneel", "C": "commercieel",
             "informational": "informatief", "navigational": "navigatie",
             "transactional": "transactioneel", "commercial": "commercieel", "local": "lokaal"}
    uit = []
    for c in (codes or []):
        c = str(c).strip()
        if c:
            uit.append(kaart.get(c, kaart.get(c.upper(), c)))
    return ", ".join(uit)


def _seranking_keyword_cijfers(termen: list) -> dict:
    """Volume, moeilijkheid en intentie voor EXACTE zoekwoorden, uit SE Ranking.

    Twee keer achterhaald en nu op bewijs (2026-08-25, live nagemeten): overview/
    analyze/suggestions geven 401 (niet in het abonnement), maar similar en related
    werken wél — en élk endpoint sluit zijn eigen seed uit van de resultaten. De
    exacte term is dus via een BRUG te vinden: pak de eerste verwante term uit
    similar(term) en zoek de term zelf terug in related(brug). Ryan had gelijk dat
    de data in het abonnement zit ("bij het setupscherm werkt het ook gewoon").
    Hyperlokale termen die SE Ranking echt niet kent blijven eerlijk leeg; beide
    calls liggen per term 24 uur in de eigen KV-cache.
    """
    uit = {}
    schoon = [str(t).strip() for t in (termen or []) if str(t).strip()][:12]

    def _vind(data, laag):
        for k in ((data or {}).get("keywords") or []):
            if isinstance(k, dict) and str(k.get("keyword") or "").strip().lower() == laag:
                return k
        return None

    for term in schoon:
        laag = term.lower()
        s = _seranking_get("/v1/keywords/similar", {"keyword": term, "source": "nl"}, cache_uren=24)
        k = _vind(s, laag)
        if not k:
            r = _seranking_get("/v1/keywords/related", {"keyword": term, "source": "nl"}, cache_uren=24)
            k = _vind(r, laag)
            # Als brug alleen termen die het zoekwoord ZELF bevatten, en dan langs beide
            # endpoints. De vorige versie pakte botweg de eerste rij en vroeg alleen
            # `related`: bij "<dienst>werk" is dat "<dienst>werker", en daar geeft
            # `related` niets op terug -- terwijl `similar` op diezelfde brug het zoekwoord
            # wél teruggeeft. Zo stond een term met 2400 zoekopdrachten per maand als
            # "geen data" op het scherm, met de mededeling dat er bijna niet op gezocht
            # wordt (Ryan 27-08-2026).
            bruggen = []
            for bron in (s, r):
                for rij in ((bron or {}).get("keywords") or []):
                    kandidaat = str(rij.get("keyword") or "").strip()
                    if laag in kandidaat.lower() and kandidaat.lower() != laag \
                            and kandidaat not in bruggen:
                        bruggen.append(kandidaat)
            for brug in bruggen[:3]:
                if k:
                    break
                for _endpoint in ("/v1/keywords/similar", "/v1/keywords/related"):
                    k = _vind(_seranking_get(_endpoint, {"keyword": brug, "source": "nl"},
                                             cache_uren=24), laag)
                    if k:
                        break
        if k:
            uit[term] = {"volume": int(k.get("volume") or 0),
                         "moeilijkheid": int(k.get("difficulty") or 0),
                         "intentie": _seranking_intent_labels(k.get("intents"))}
    return uit


# Woorden die als los zaad niets betekenen. Een zaad dat hierop begint of eindigt is een
# halve zin ("<dienst> per") en levert gegarandeerd niets op.
_ZAAD_KOPPELWOORDEN = {
    "de", "het", "een", "en", "of", "voor", "met", "van", "in", "op", "per", "te",
    "aan", "bij", "naar", "om", "als", "door", "uit", "over", "je", "uw", "u", "we",
}
# Staarten van bijvoeglijke naamwoorden. Die zijn slechte zaden: SE Ranking geeft er de
# hele Nederlandse markt op terug in plaats van deze branche. Ze worden niet uitgesloten,
# maar achteraan gezet -- soms is een bijvoeglijk naamwoord het enige dat overblijft.
_ZAAD_BIJVOEGLIJK = ("lijk", "ig", "ief", "isch", "baar", "loos", "vol", "e")
# Hoeveel PROEF-aanroepen een hele ronde hoogstens mag doen. De gateway knijpt af rond de
# elf aanroepen op rij (nagemeten 2026-08-27) en de gewone ronde gebruikt er al twee per
# zaad; zonder plafond zou de terugval de rest van de zaden 429 in duwen.
_ZAAD_PROEF_MAX = 6
# Zoveel rijen moet een kortere variant opleveren om als vervanger te tellen. Eén losse
# treffer is ruis en geeft een voorstellenlijst van één regel.
_ZAAD_PROEF_DREMPEL = 5


def _zaad_is_bijvoeglijk(woord: str) -> bool:
    """Ruwe test op bijvoeglijk naamwoord of voltooid deelwoord.

    Bewust grof: hij bepaalt alleen de VOLGORDE waarin we varianten proberen, dus een
    zelfstandig naamwoord dat toevallig op -e eindigt kost hooguit een plek in de rij.
    """
    if woord.startswith("ge") and (woord.endswith(("t", "d")) or woord.endswith("en")):
        return True
    return woord.endswith(_ZAAD_BIJVOEGLIJK)


def _zaad_varianten(zaad: str) -> list:
    """Kortere zaden om te proberen als SE Ranking het hele zaad niet kent.

    Het siteprofiel levert zaden die lezen als een verkoopzin ("<dienst> <eigenschap>
    <eigenschap>"). SE Ranking kent zulke frases niet en geeft er nul rijen op terug --
    en dan strandt de setup-wizard op een lege lijst terwijl er met de koppeling en het
    tegoed niets mis is (live gezien, Ryan 27-08-2026). Terug naar het kernwoord dus:
    daar zit de data wel.

    Volgorde: zelfstandige naamwoorden eerst, dan het langste woord -- in het Nederlands
    zit de betekenis in de samenstelling ("<dienst>werk") en niet in het bijvoeglijk
    naamwoord ervoor. Bij gelijke lengte wint het woord dat achteraan staat, want een
    Nederlandse woordgroep is kopfinaal.
    """
    woorden = [w for w in re.split(r"\W+", str(zaad or "").lower()) if w]
    kandidaten = [(w, i) for i, w in enumerate(woorden)
                  if w not in _ZAAD_KOPPELWOORDEN and len(w) > 2]
    kandidaten.sort(key=lambda p: (_zaad_is_bijvoeglijk(p[0]), -len(p[0]), -p[1]))
    uit, gezien = [], {str(zaad or "").strip().lower()}
    for woord, _ in kandidaten:
        if woord not in gezien:
            gezien.add(woord)
            uit.append(woord)
    return uit


def _seranking_keyword_ideeen(zaden: list, maximaal: int = 12, vers: bool = False) -> list:
    """Zoekwoordvoorstellen mét cijfers, via SE Ranking's keyword-data.

    Levert per suggestie volume, moeilijkheid en zoekintentie — precies wat een AI
    níét kan verzinnen. Twee endpoints per zaad: `similar` voor varianten van de term
    zelf, `related` voor wat mensen erómheen zoeken. Met alleen `similar` bestond de
    halve lijst uit dezelfde term met een andere plaatsnaam erachter.

    Elke aanroep kost credits, dus blijft het bij hoogstens acht zaden en liggen de
    resultaten 24 uur in de cache. Het aantal zaden volgt het doel: bij twintig
    focus-zoekwoorden heb je tien onderwerpen nodig, niet drie.
    """
    # Schone lei: wat hierna in `_SERANKING_FOUT` staat gaat over DEZE aanvraag. De lambda
    # blijft warm tussen requests, dus zonder dit kan de storing van een vorige bezoeker
    # blijven plakken en zou het scherm een probleem melden dat allang over is.
    _seranking_fout_vergeet()
    per_zaad, gezien = [], set()
    proeven = [_ZAAD_PROEF_MAX]

    def _rauwe_rijen(term):
        """Beide invalshoeken voor één term, achter elkaar."""
        rijen = []
        # Twee invalshoeken per dienst. `similar` geeft varianten van de term zelf en dus
        # tien keer dezelfde term met een andere plaatsnaam erachter; `related` geeft wat
        # mensen erómheen zoeken. De variatie waar de klant om vroeg zit in die tweede
        # lijst, en beide endpoints zitten in het abonnement (nagemeten 2026-08-25).
        for _endpoint in ("/v1/keywords/similar", "/v1/keywords/related"):
            params = {"keyword": term, "source": "nl"}
            # "Opnieuw ophalen" moet ook echt opnieuw ophalen: anders kreeg je 24 uur lang
            # dezelfde lijst terug en leek de knop stuk.
            if vers:
                _seranking_cache_vergeet(_endpoint, params)
            rijen += ((_seranking_get(_endpoint, params, cache_uren=24) or {}).get("keywords") or [])
        return rijen

    def _rijen_met_terugval(term):
        """De rijen voor dit zaad, of die van het kortste zaad dat SE Ranking wél kent."""
        rijen = _rauwe_rijen(term)
        if rijen:
            return rijen
        for variant in _zaad_varianten(term):
            if proeven[0] <= 0:
                break
            proeven[0] -= 1
            proef = _seranking_get("/v1/keywords/similar", {"keyword": variant, "source": "nl"},
                                   cache_uren=24)
            if len(((proef or {}).get("keywords") or [])) >= _ZAAD_PROEF_DREMPEL:
                return _rauwe_rijen(variant)
        return []

    for zaad in [z for z in zaden if z][:8]:
        rij = []
        for k in _rijen_met_terugval(zaad):
            term = str(k.get("keyword") or "").strip()
            if not term or term.lower() in gezien:
                continue
            gezien.add(term.lower())
            rij.append({"keyword": term[:60],
                        # Uit wélke dienst dit voorstel komt. Zonder dat is er geen
                        # eerlijke verdeling te maken: één dienst vulde de hele lijst.
                        "zaad": zaad,
                        "volume": int(k.get("volume") or 0),
                        "moeilijkheid": int(k.get("difficulty") or 0),
                        "intentie": _seranking_intent_labels(k.get("intents")),
                        "bron": "seranking"})
        # Op volume sorteren: een term waar niemand op zoekt is geen focus-zoekwoord,
        # hoe mooi hij ook klinkt. Maar wél BINNEN het zaad.
        rij.sort(key=lambda x: -x["volume"])
        per_zaad.append(rij)
    # ...en dan om en om uit elk zaad. Eén lijst op volume sorteren gaf het zaad met de
    # zwaarste termen de hele top, waardoor één onderwerp de focuslijst — en dus het
    # klantrapport — volledig vulde (live gezien op een zustersite, Ryan 2026-08-26: elke
    # regel ging over dezelfde dienst). De zwaarste term per zaad staat nog steeds vooraan; de
    # verdringing tussen de zaden is weg.
    uit = []
    for ronde in range(max((len(r) for r in per_zaad), default=0)):
        for rij in per_zaad:
            if len(rij) > ronde:
                uit.append(rij[ronde])
    return uit[:maximaal]


def _seranking_koppeling_herstellen() -> None:
    """Maakt een handmatige ontkoppeling ongedaan en laat de site zichzelf opnieuw zoeken."""
    kv_delete("seranking:losgekoppeld")
    kv_delete("seranking:site_id")
    _seranking_cache_vergeet("/v1/project-management/sites")


def _seranking_opportunities() -> list:
    """Bijna-winnaars uit SE Ranking, in dezelfde vorm als de GSC-variant.

    Bewust GEEN vertoningen/klikken: die weet SE Ranking niet, en verzonnen
    cijfers zouden in de onderbouwing van de agent terechtkomen. `potential` is
    hier puur een rangschikking op positie."""
    items = []
    for r in _seranking_posities():
        if 4 <= r["position"] <= 20:
            items.append({"query": r["keyword"], "position": r["position"],
                          "impressions": 0, "clicks": 0,
                          "page": _seranking_pagina_voor(r["keyword"]),
                          "potential": max(0, 21 - r["position"]),
                          "source": "seranking"})
    return items[:12]


def _seranking_pagina_voor(keyword: str) -> str:
    """Beste gok voor de pagina die bij een keyword hoort, op woordoverlap met de
    titel en de slug. Zonder dit zou elke taak op de homepagina landen."""
    woorden = {w for w in re.split(r"\W+", keyword.lower()) if len(w) > 3}
    beste, score_beste = "", 0
    for p in (_pages_index() or []):
        tekst = f"{p.get('title', '')} {p.get('slug', '')}".lower()
        score = sum(1 for w in woorden if w in tekst)
        if score > score_beste:
            beste, score_beste = p.get("url") or ("/" + (p.get("slug") or "")), score
    return beste


def _seranking_posities() -> list:
    """[{keyword, position, change, vorige?}] — zie _seranking_posities_ophalen.

    Leeg terwijl de koppeling aanstaat? Eén verse herkansing per uur: een verlopen
    abonnement of storing kan 'niet gevonden' en lege lijsten in de caches hebben
    gezet (site-id 24 uur, calls 6 uur), en zodra SE Ranking weer leeft moet een
    rapportbouw dat meteen zien — niet pas als de cache verloopt."""
    uit = _seranking_posities_ophalen()
    if uit or not _gateway_aan() or kv_get("seranking:losgekoppeld"):
        return uit
    try:
        laatst = float(kv_get("seranking:herkansing") or 0)
    except Exception:
        laatst = 0.0
    if time.time() - laatst < 3600:
        return uit
    kv_set("seranking:herkansing", time.time())
    kv_delete("seranking:site_id")
    _seranking_cache_vergeet("/v1/project-management/sites")
    return _seranking_posities_ophalen(vers=True)


def _seranking_posities_ophalen(vers: bool = False) -> list:
    """[{keyword, position, change, vorige?}] — de laatst gemeten stand per keyword,
    plus de positie van ongeveer een maand geleden (rapport-wens Ryan 2026-08-25:
    'het verschil met de maand ervoor'). We vragen vijf weken historie op; 'change'
    is dan het verschil met die maandmeting (positief = gestegen). Zonder oude
    meting valt 'change' terug op SE Rankings eigen dagwijziging.

    vers=True vergeet de gecachete keyword- en positie-antwoorden eerst (de
    herkansing hierboven wil de echte actuele stand, niet de storing van vanmorgen)."""
    sid = _seranking_site_id()
    if not sid:
        return []
    if vers:
        _seranking_cache_vergeet("/v1/project-management/keywords", {"site_id": sid})
    namen = {}
    for k in (_seranking_get("/v1/project-management/keywords", {"site_id": sid}) or []):
        if isinstance(k, dict) and k.get("id"):
            namen[str(k["id"])] = str(k.get("name") or "").strip()
    nu = datetime.now()
    doel = nu - timedelta(days=30)
    bereik = {"site_id": sid, "date_from": (nu - timedelta(days=35)).strftime("%Y-%m-%d"),
              "date_to": nu.strftime("%Y-%m-%d")}
    if vers:
        _seranking_cache_vergeet("/v1/project-management/sites/positions", bereik)
    uit = {}
    for engine in (_seranking_get("/v1/project-management/sites/positions", bereik) or []):
        for k in (engine.get("keywords") or []) if isinstance(engine, dict) else []:
            metingen = [m for m in (k.get("positions") or []) if isinstance(m, dict) and m.get("pos")]
            if not metingen:
                continue
            metingen.sort(key=lambda m: str(m.get("date") or ""))
            laatste = metingen[-1]
            naam = namen.get(str(k.get("id")), "")
            pos = int(laatste.get("pos") or 0)
            if not naam or pos <= 0:
                continue
            vorige = None
            try:
                # De meting het dichtst bij 30 dagen terug; minimaal ~3 weken oud,
                # anders is het geen maandvergelijking maar ruis van vorige week.
                oud = [m for m in metingen[:-1]
                       if str(m.get("date") or "")[:10] <= (nu - timedelta(days=21)).strftime("%Y-%m-%d")]
                if oud:
                    dichtstbij = min(oud, key=lambda m: abs(
                        (datetime.strptime(str(m.get("date"))[:10], "%Y-%m-%d") - doel).days))
                    vorige = int(dichtstbij.get("pos") or 0) or None
            except Exception:
                vorige = None
            entry = {"keyword": naam, "position": pos,
                     "change": (vorige - pos) if vorige else int(laatste.get("change") or 0)}
            if vorige:
                entry["vorige"] = vorige
            if naam not in uit or pos < uit[naam]["position"]:
                uit[naam] = entry
    # Gevolgde zoekwoorden zonder notering (nog niet in de top 100) verdwenen stil
    # uit het rapport ('hoezo maar 1 zoekwoord', Ryan 2026-08-25). Toon ze wél, als
    # positie 0 achteraan; de kansen-motor (4-20) kijkt alleen naar genoteerde.
    for naam in namen.values():
        naam = str(naam or "").strip()
        if naam and naam not in uit:
            uit[naam] = {"keyword": naam, "position": 0, "change": 0}
    return sorted(uit.values(),
                  key=lambda x: (0 if x["position"] > 0 else 1, x["position"] or 9999, x["keyword"]))


def _seranking_posities_reden() -> str:
    """Waarom _seranking_posities() niets teruggaf, in taal voor de accountmanager.

    Alleen aanroepen als de lijst leeg is: de keywords-call hieronder komt dan net
    uit dezelfde build en zit nog in de 6-uurscache, dus dit kost geen extra tegoed."""
    if not _gateway_aan():
        return "De centrale MHS-gateway is hier niet ingesteld, dus SE Ranking-data is niet beschikbaar."
    sid = _seranking_site_id()
    if not sid:
        return "Deze site staat nog niet als project in SE Ranking."
    kws = _seranking_get("/v1/project-management/keywords", {"site_id": sid})
    if kws is None:
        # Zeg wát er misging: bij een leeg tegoed (402) is "probeer het later opnieuw"
        # een leugen — dat lost zichzelf niet op.
        return (_seranking_fout_reden()
                or "SE Ranking was even niet bereikbaar; probeer het later opnieuw.")
    if not [k for k in kws if isinstance(k, dict) and k.get("id")]:
        return "Het SE Ranking-project volgt nog geen zoekwoorden; voeg ze toe in SE Ranking."
    return "SE Ranking heeft nog geen positiemetingen voor de gevolgde zoekwoorden."


def _seranking_post(pad: str, params: dict = None):
    """Eén schrijfactie via de gateway (nu alleen: audit opnieuw starten). Geeft
    (status, data) terug; (0, None) bij een netwerkstoring. Geen cache — een
    schrijfactie is een handeling, geen vraag."""
    basis = _gateway_origin()
    if not (basis and _gateway_key()):
        return 0, None
    qs = urllib.parse.urlencode({"path": pad, **(params or {})})
    req = urllib.request.Request(
        f"{basis}/api/seo-gateway/seranking?{qs}", data=b"", method="POST",
        headers={"Authorization": "Bearer " + _gateway_key(),
                 "User-Agent": "MAIHS-SEO-Gateway-Client/1.0"})
    try:
        with urllib.request.urlopen(req, timeout=25) as r:
            return r.status, json.loads(r.read().decode("utf-8") or "null")
    except urllib.error.HTTPError as e:
        try:
            return e.code, json.loads(e.read().decode("utf-8") or "null")
        except Exception:
            return e.code, None
    except Exception as e:
        print(f"[seranking] POST {pad} mislukt: {e}")
        return 0, None


def _seranking_registreer(keywords: list, timeout: int = 45) -> tuple:
    """Meld deze site (met zoekwoorden) aan bij SE Ranking via de eigen
    MAIHS-registratieroute (/api/gateway/seranking-register — dit is bewust NIET de
    GET-only seo-gateway-proxy). MAIHS synct idempotent: bestaande zoekwoorden
    blijven staan, alleen ontbrekende komen erbij, en bij de abonnementslimiet
    stopt hij netjes. Geeft (ok, data|fout)."""
    basis = _gateway_origin()
    if not (basis and _gateway_key()):
        return False, "Geen gateway geconfigureerd"
    try:
        req = urllib.request.Request(
            basis + "/api/gateway/seranking-register",
            data=json.dumps({"keywords": [str(k).strip() for k in (keywords or []) if str(k).strip()][:50]}).encode(),
            method="POST",
            headers={"Authorization": "Bearer " + _gateway_key(),
                     "Content-Type": "application/json",
                     "User-Agent": "MAIHS-Gateway-Client/1.0"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return True, json.loads(r.read().decode() or "{}")
    except urllib.error.HTTPError as e:
        return False, _gateway_foutmelding(e.code, e.read().decode("utf-8", "replace")[:500])
    except Exception as e:
        return False, str(e)


def _seranking_site_id() -> str:
    """Het SE Ranking-project van deze site, gezocht op domein.

    Ook 'niet gevonden' wordt bewaard. Een site die nog niet in SE Ranking staat
    is de normale toestand vlak na oplevering, en zonder die notitie zou elke
    aanroep opnieuw de hele sitelijst ophalen — en kan de instellingenpagina niet
    laten zien dat het project nog moet worden aangemaakt."""
    # Handmatig losgekoppeld? Dan niet opnieuw gaan zoeken: het project bestáát nog bij
    # SE Ranking (met alle meetgeschiedenis), deze site gebruikt het alleen niet meer.
    if kv_get("seranking:losgekoppeld"):
        return ""
    bewaard = kv_get("seranking:site_id")
    if isinstance(bewaard, str) and bewaard:  # oud formaat: alleen het id
        return bewaard
    if isinstance(bewaard, dict) and (time.time() - float(bewaard.get("t", 0) or 0)) < 24 * 3600:
        return str(bewaard.get("id") or "")
    sites = _seranking_get("/v1/project-management/sites", cache_uren=24)
    if sites is None:  # gateway onbereikbaar — niets vastleggen, straks opnieuw
        return ""
    host = re.sub(r"^www\.", "", urllib.parse.urlparse(CANONICAL_BASE).netloc.lower())

    def _host(v: str) -> str:
        v = str(v or "").lower().strip()
        if "//" in v:
            v = urllib.parse.urlparse(v).netloc
        return re.sub(r"^www\.", "", v.strip("/"))

    gevonden = ""
    for s in sites:
        if not isinstance(s, dict):
            continue
        # Een project heet lang niet altijd naar het domein ("DAM Housing"); dan
        # staat het domein in `url`. Alleen op de naam zoeken laat de site zichzelf
        # missen, en dan blijft aanmelden eeuwig "project stond er al" antwoorden.
        if host in {_host(s.get("name")), _host(s.get("title")), _host(s.get("url"))}:
            gevonden = str(s.get("id"))
            break
    kv_set("seranking:site_id", {"id": gevonden, "t": int(time.time())})
    return gevonden


def _site_check():
    """Komt de eigen site op, gemeten via de edge zoals een bezoeker? -> (ok, ms).
    Een HTTP-antwoord telt als bereikbaar, óók een firewall-challenge (403): het
    platform antwoordde. Alleen geen verbinding of een timeout is 'down'."""
    base = _public_base() or CANONICAL_BASE
    t0 = time.time()
    try:
        req = urllib.request.Request(base + "/", headers={"User-Agent": "damhousing-monitor/1.0",
                                                          "Accept": "text/html"})
        with urllib.request.urlopen(req, timeout=10) as r:
            return (200 <= int(getattr(r, "status", 200) or 200) < 500), int((time.time() - t0) * 1000)
    except urllib.error.HTTPError:
        return True, int((time.time() - t0) * 1000)
    except Exception:
        return False, int((time.time() - t0) * 1000)


def _ssl_dagen_over(host: str):
    """Dagen tot het SSL-certificaat van de site verloopt; None bij elke storing."""
    try:
        ctx = ssl.create_default_context()
        with socket.create_connection((host, 443), timeout=6) as sock:
            with ctx.wrap_socket(sock, server_hostname=host) as s:
                exp = (s.getpeercert() or {}).get("notAfter") or ""
        d = datetime.strptime(exp, "%b %d %H:%M:%S %Y %Z")
        return max(0, (d - datetime.now()).days)
    except Exception:
        return None


def _ssl_tick() -> None:
    """Dagelijks (cron/seo): SSL-status cachen zodat het rapport 'm zonder netwerk-call
    kan tonen. Een storing wist de laatste goede meting niet."""
    host = re.sub(r"^https?://", "", (_public_base() or "")).split("/")[0]
    d = _ssl_dagen_over(host) if host else None
    if d is not None:
        kv_set("monitor:ssl", {"at": _now_iso(), "dagen": int(d)})


def _url_bestaat(url: str) -> bool:
    """Bestaat deze URL echt (2xx/3xx)? Voor optionele beelden: een kapot plaatje in
    een klantmail is erger dan geen plaatje."""
    try:
        req = urllib.request.Request(url, method="HEAD",
                                     headers={"User-Agent": "damhousing-rapport/1.0"})
        with urllib.request.urlopen(req, timeout=6) as r:
            return 200 <= int(getattr(r, "status", 200) or 200) < 400
    except Exception:
        return False


def _zoekwoord_aanbevelen(ideeen: list, al_gekozen: list) -> None:
    """Markeert de zoekwoorden die deze site het beste kan pakken (in-place).

    Vijf dingen bepalen de keuze, in deze volgorde:
      1. geen twee termen met dezelfde zoekvraag — daar zou je eigen pagina's mee laten
         concurreren, en dat kost allebei positie;
      2. hoogstens twee termen per ONDERWERP — zie hieronder;
      3. geen informatieve zoekopdrachten — zie hieronder;
      4. winbaarheid: een lage moeilijkheid levert bij een lokale site sneller posities op
         dan een zware term met veel volume;
      5. zoekintentie: iemand die wil laten kitten is meer waard dan iemand die iets opzoekt.
    Het AANTAL komt uit `_zoekwoord_advies()`: zoveel als deze site aan pagina's kan dragen.
    """
    advies = _zoekwoord_advies()
    # Tot de BOVENgrens, niet tot de ondergrens: op het minimum is er nog ruimte, en dan
    # hoort het scherm te laten zien wat het zou kiezen in plaats van niets te markeren.
    ruimte = max(0, int(advies.get("max") or advies.get("min") or 0) - len(al_gekozen or []))
    bezet = {_kw_sleutel(k): k for k in (al_gekozen or [])}
    # Onderwerp-quotum. `_kw_sleutel` ving alleen de letterlijke dubbelingen; tien varianten
    # van één onderwerp zijn tien verschillende zoekvragen en kwamen er dus allemaal doorheen.
    # Zo ging op een zustersite de complete focuslijst over één dienst (Ryan 2026-08-26). Dan
    # liever minder termen, maar wel over de breedte van wat de site verkoopt. Al gekozen
    # termen tellen mee, anders vul je het quotum bij elke ronde opnieuw.
    ONDERWERP_MAX = ZOEKWOORD_ONDERWERP_MAX
    # Waar deze site iets te zoeken heeft: elk woord dat in een eigen slug, in de regio
    # of in het werkgebied voorkomt. Een lokale zoekopdracht met een plaatsnaam die daar
    # niet bij zit gaat over een plaats waar deze site niets heeft.
    _vocab = _eigen_vocabulaire()
    # De zaadwoorden zelf horen er ook bij: die komen uit deze site. Zonder dat is
    # "bureau" in "<dienst>bureau <stad>" een vreemd woord en wijst de regel hieronder
    # de hele familie af — ook de steden waar wél een pagina voor bestaat.
    for _z in (ideeen or []):
        _vocab.update(re.findall(r"[a-z]{3,}", str(_z.get("zaad") or "").lower()))
    # Één dienst mag de lijst niet vullen. `_kw_onderwerpen` kijkt naar woordparen, en ziet
    # "<dienst> plaats a" en "<dienst> plaats b" als twee onderwerpen — dan bindt het quotum
    # hierboven niet. Het ZAAD waar een voorstel vandaan komt is wél eenduidig: dat is de
    # dienst. De helft van de aanbevelingen ging over één dienst voordat dit erbij kwam
    # (Ryan 27-08-2026).
    zaden_in_lijst = {str(i.get("zaad") or "") for i in (ideeen or []) if i.get("zaad")}
    per_zaad_max = max(2, ruimte // max(1, len(zaden_in_lijst))) if zaden_in_lijst else ruimte
    per_zaad = {}
    onderwerpen = _kw_onderwerpen([str(i.get("keyword", "")) for i in (ideeen or [])]
                                  + [str(k) for k in (al_gekozen or [])])
    per_onderwerp = {}
    for k in (al_gekozen or []):
        ond = onderwerpen.get(str(k))
        per_onderwerp[ond] = per_onderwerp.get(ond, 0) + 1

    # Het onderwerp per voorstel gaat mee naar het scherm. Dat moet de aanbeveling opnieuw
    # kunnen uitrekenen — ruimte en quota verschuiven zodra je aan- of uitvinkt — en zou de
    # clustering hierboven anders in JavaScript moeten nabouwen. Precies daar liepen de twee
    # kanten uiteen: het scherm kende het quotum niet en zette termen groen die hier waren
    # afgewezen (Ryan 27-08-2026).
    for idee in (ideeen or []):
        _ond = onderwerpen.get(str(idee.get("keyword", "")))
        idee["onderwerp"] = " ".join(sorted(_ond)) if _ond else ""

    def kans(kd) -> float:
        if not kd:
            return 0.8                      # onbekend: niet belonen, niet afstraffen
        return 1.0 if kd <= 20 else (0.55 if kd <= 45 else 0.15)

    def intentie_code(idee) -> str:
        """T/L/C/I/N, ongeacht of SE Ranking lettercodes of NL-woorden teruggeeft.

        Sinds 2026-08-25 komt de intentie als Nederlands woord binnen
        (`_seranking_intent_labels`). De weging hieronder keek alleen naar lettercodes, dus
        viel élke term terug op factor 1.0 en speelde de zoekintentie in de praktijk geen
        enkele rol meer — precies de reden dat informatieve doe-het-zelf-termen
        ("<dienst> droogtijd", "<dienst> zelf doen") aanbevolen konden worden.
        """
        eerste = (idee.get("intentie") or "").split(",")[0].strip().lower()
        return {"transactioneel": "T", "lokaal": "L", "commercieel": "C",
                "informatief": "I", "navigatie": "N"}.get(eerste, eerste[:1].upper())

    def gewicht(idee) -> float:
        factor = {"T": 1.3, "L": 1.25, "C": 1.15, "I": 0.85, "N": 0.5}.get(
            intentie_code(idee), 1.0)
        return float(idee.get("volume") or 0) * kans(idee.get("moeilijkheid")) * factor

    for idee in sorted(ideeen, key=gewicht, reverse=True):
        sleutel = _kw_sleutel(idee.get("keyword", ""))
        botst = bezet.get(sleutel)
        if botst:
            # Al gekozen termen staan óók in `bezet`; die botsen met zichzelf en dat is
            # geen dubbeling maar gewoon "deze heb je al".
            if botst != idee.get("keyword"):
                idee["dubbel_met"] = botst
            continue
        if ruimte <= 0:
            continue
        # Informatieve zoekopdrachten ("<dienst> droogtijd", "<dienst> zelf doen") niet
        # aanraden: dat is iemand die het zélf gaat doen, geen klant. Ze wogen alleen wat
        # lichter mee (x0.85) — en door de kapotte intentie-lezing hierboven zelfs dat niet.
        # Aanvinken mag nog steeds, aanraden niet.
        # Een lokale zoekopdracht naar een plaats die deze site niet bedient: daar win je
        # zelden (Google weegt adres en Bedrijfsprofiel mee), en win je wel, dan zocht die
        # bezoeker iemand in de buurt. Vijftien stadsvarianten van één dienst zijn boven-
        # dien vijftien pagina's die hetzelfde zeggen — doorway pages. Aanvinken mag,
        # aanraden niet (Ryan 27-08-2026).
        if intentie_code(idee) == "L":
            _vreemd = sorted(set(re.findall(r"[a-z]{3,}", str(idee.get("keyword", "")).lower()))
                             - _vocab)
            if _vreemd:
                idee["niet_aanbevolen"] = ("lokale zoekopdracht voor \u201c" + _vreemd[0]
                                          + "\u201d: daar heeft deze site geen pagina of vestiging")
                # Blijvend: dit oordeel hangt aan het werkgebied van deze site, niet aan wat
                # jij aanvinkt. Het scherm mag het er dus niet weer uit rekenen.
                idee["vast_afgewezen"] = True
                continue
        if intentie_code(idee) == "I":
            idee["niet_aanbevolen"] = "informatief: de zoeker wil uitleg, geen vakman"
            # Blijvend, net als hierboven: de zoekintentie van een term verandert niet
            # doordat jij iets anders aanvinkt.
            idee["vast_afgewezen"] = True
            continue
        zaad_van = str(idee.get("zaad") or "")
        if zaad_van and per_zaad.get(zaad_van, 0) >= per_zaad_max:
            idee["niet_aanbevolen"] = "er staan al genoeg termen over deze dienst"
            continue
        ond = onderwerpen.get(str(idee.get("keyword", "")))
        if per_onderwerp.get(ond, 0) >= ONDERWERP_MAX:
            idee["niet_aanbevolen"] = "er staan al twee termen over dit onderwerp"
            continue
        kd = idee.get("moeilijkheid")
        # Ruimte betekent niet "vul maar op": een term met zware concurrentie of zonder
        # zoekvolume raden we niet aan, ook niet als er nog plek is. Dan liever minder.
        if (kd and kd > 45) or not idee.get("volume"):
            continue
        # De onderbouwing is het oordeel, niet de cijfers: die staan er in hun eigen regel
        # onder. Twee keer hetzelfde getal lezen helpt niemand kiezen.
        reden = []
        if kd:
            reden.append("weinig concurrentie" if kd <= 20 else
                         ("te doen met wat geduld" if kd <= 45 else "zwaar, maar het meest waard"))
        if idee.get("intentie_uitleg"):
            reden.append("de zoeker %s" % idee["intentie_uitleg"])
        idee["aanbevolen"] = True
        idee["aanbeveling"] = " en ".join(reden) or "past bij het aanbod van deze site"
        bezet[sleutel] = idee["keyword"]
        per_onderwerp[ond] = per_onderwerp.get(ond, 0) + 1
        if zaad_van:
            per_zaad[zaad_van] = per_zaad.get(zaad_van, 0) + 1
        ruimte -= 1

    # Wie varianten van zijn eigen zoekvraag opzij zette, mag dat zeggen: dat is precies
    # de keuze die het scherm anders aan de gebruiker overlaat.
    varianten = {}
    for idee in ideeen:
        if idee.get("dubbel_met"):
            varianten[idee["dubbel_met"]] = varianten.get(idee["dubbel_met"], 0) + 1
    for idee in ideeen:
        n = varianten.get(idee.get("keyword", ""), 0)
        if idee.get("aanbevolen") and n:
            idee["aanbeveling"] += (f" — en van de {n + 1} varianten op deze zoekvraag "
                                    f"de beste")


def _zoekwoord_advies() -> dict:
    """Hoeveel focus-zoekwoorden bij DEZE site passen, afgeleid uit de site zelf.

    Een vast getal ("acht tot twintig") is een slag in de lucht: het juiste aantal hangt aan
    hoeveel pagina's je hebt die op een eigen zoekvraag kunnen scoren. Google zet er per
    zoekopdracht één van je site vooraan, dus één term per pagina is de ondergrens. De
    bovengrens telt daar de blogs bij op (die bedienen hun eigen informatieve vragen) plus
    ruimte voor wat de agent er de komende maanden bij maakt.
    """
    # Twee bronnen, want op een handgebouwde SPA staat maar een deel in de CMS-index:
    # de dienstpagina's komen uit _SPA_ROUTES (dezelfde lijst als de sitemap gebruikt).
    # Projecten en collectie tellen bewust niet mee: dat is een portfolio en een
    # catalogus, geen set eigen zoekvragen.
    scorend = set(_scorende_spa_paden())
    try:
        for p in (_pages_index() or []):
            if (p.get("status") or "published") != "published":
                continue
            slug = (p.get("slug") or "").strip("/")
            if any(k in slug.lower() for k in NIET_SCOREND):
                continue
            scorend.add(("/" + slug + "/") if slug else "/")
    except Exception:
        pass
    paginas = sorted(scorend)
    try:
        blogs = len([b for b in (get_posts_index() or [])
                     if (b.get("status") or "published") == "published"])
    except Exception:
        blogs = 0
    n = max(1, len(paginas))
    # Nooit meer adviseren dan de agent bewaakt: daarboven kapt het opslaan de lijst af, dus
    # belooft het scherm iets wat er bij de eerstvolgende opslag weer af gaat.
    laag = min(n, FOCUS_KEYWORDS_MAX)
    hoog = min(n + blogs + 3, FOCUS_KEYWORDS_MAX)   # +3 = ruimte voor pagina's die er nog bij komen
    # Heeft de site meer scorende pagina's dan de agent termen bewaakt, dan is "één term per
    # pagina" geen maat meer en gaat het advies over KIEZEN.
    vol = n >= FOCUS_KEYWORDS_MAX

    # Waar je binnen dat bereik moet gaan zitten, hangt af van hoe je bestaande pagina's
    # het doen. Staan ze al vooraan, dan levert een nieuwe pagina meer op dan nóg een term
    # op een pagina die al wint. Staan ze op positie 15, dan is er meer te halen uit het
    # sterker maken van wat je hebt — meer pagina's verdunt dan alleen de aandacht.
    posities = []
    try:
        for rij in (_seo_gsc_signals(90) or {}).get("striking") or []:
            p_ = float(rij.get("position") or 0)
            if p_:
                posities.append(p_)
    except Exception:
        posities = []
    gem = round(sum(posities) / len(posities), 1) if posities else 0
    uitleg = (f"Je site heeft {n} pagina{chr(39) + 's' if n != 1 else ''} die op een eigen zoekvraag "
              f"{'kunnen' if n != 1 else 'kan'} scoren" + (f" en {blogs} blog{'s' if blogs != 1 else ''}" if blogs else "")
              + (f". De agent bewaakt hoogstens {FOCUS_KEYWORDS_MAX} zoekwoorden tegelijk, "
                 f"dus is dat hier de bovengrens."
                 if vol else
                 f". Eén term per pagina, plus ruimte voor wat erbij komt: {laag} tot {hoog}."))

    if vol:
        koers, doel, advies = ("kiezen", hoog,
                               (f"Je pagina's staan gemiddeld op positie {gem}. " if gem else "")
                               + f"Kies de {hoog} zoekvragen waar het meeste aan hangt — meer "
                                 f"bewaakt de agent niet tegelijk. De rest van je pagina's blijft "
                                 f"gewoon staan, hij stuurt er alleen niet actief op.")
    elif not posities:
        koers, doel, advies = ("onbekend", laag,
                               "Nog geen posities bekend: begin bij één term per bestaande pagina. "
                               "Zodra Search Console data heeft, zien we of uitbreiden of verbeteren meer oplevert.")
    elif gem <= 10:
        koers, doel, advies = ("uitbreiden", hoog,
                               f"Je pagina's staan gemiddeld op positie {gem}. Wat je hebt wint al, dus zit de groei "
                               f"in nieuwe zoekvragen: ga richting {hoog} en laat de agent er pagina's bij maken.")
    elif gem <= 20:
        koers, doel, advies = ("mengen", (laag + hoog) // 2,
                               f"Je pagina's staan gemiddeld op positie {gem} — net buiten de eerste pagina van Google. "
                               f"Kies één term per bestaande pagina en een paar nieuwe: rond de {(laag + hoog) // 2}.")
    else:
        koers, doel, advies = ("verdiepen", laag,
                               f"Je pagina's staan gemiddeld op positie {gem}. Meer pagina's verdunt dan alleen de "
                               f"aandacht; houd het op {laag} — één term per bestaande pagina — en maak die sterker.")
    return {"min": laag, "max": hoog, "paginas": n, "blogs": blogs, "uitleg": uitleg,
            "koers": koers, "doel": doel, "advies": advies, "gem_positie": gem}


def _zoekwoord_sorteren(ideeen: list) -> list:
    """Aanbevolen bovenaan, daarna op zoekvolume. Sorteren op volume alleen zette onze
    eigen keuzes willekeurig door de lijst — dan is het oordeel onzichtbaar."""
    return sorted(ideeen, key=lambda i: (0 if i.get("aanbevolen") else 1, -int(i.get("volume") or 0)))


# ---------- Wat verkoopt deze site eigenlijk? (Ryan 27-08-2026) ----------
# Het zoekwoordonderzoek begon bij de slug van een dienstpagina. Kort en schoon, maar
# contextloos: dezelfde dienstnaam betekent bij een zakelijk bureau iets anders dan bij een
# winkel, en SE Ranking beantwoordt precies de vraag die je stelt. Vraag je "<dienst>", dan
# krijg je de consumentenkant van die markt terug — inclusief webshops van winkelketens en
# boeken over het onderwerp. De vraag moet de context dragen, en die staat op de site zelf.
SITEPROFIEL_SLEUTEL = "seo:siteprofiel"
SITEPROFIEL_DAGEN = 30


def _siteprofiel_bron(maximaal: int = 10) -> dict:
    """De tekst die de site zélf over zichzelf schrijft: bedrijfsprofiel + dienstpagina's."""
    b = _business_profile()
    paginas = []
    try:
        diensten, overig = [], []
        for p in _pages_index():
            slug = (p.get("slug") or "").strip("/")
            if (not slug or _niet_scorend_pad(slug)
                    or (p.get("status") or "published") != "published"):
                continue
            (diensten if slug.startswith(("diensten/", "dienst/")) else overig).append(p)
        for p in (diensten or overig)[:maximaal]:
            slug = (p.get("slug") or "").strip("/")
            vol = _get_page(slug) or {}
            blokken = vol.get("content_blocks") or []
            tekst = _extract_plaintext(
                *[v for b_ in blokken if isinstance(b_, dict)
                  for v in b_.values() if isinstance(v, str)], limit=400)
            paginas.append({"pad": "/" + slug + "/",
                            "titel": str(p.get("title") or "")[:120],
                            "omschrijving": str((vol.get("meta") or {}).get("description") or "")[:200],
                            "tekst": tekst})
    except Exception:
        pass
    return {"bedrijf": {"naam": b.get("name"), "sector": b.get("sector"),
                        "regio": b.get("region"), "werkgebied": b.get("service_area")},
            "paginas": paginas}


def _site_profiel(vers: bool = False) -> dict:
    """Wat verkoopt deze site, aan wie en met welk doel — afgeleid uit de site zelf.

    De AI verzint hier niets: hij krijgt uitsluitend tekst die al op deze site staat, en zet
    die om in de woorden waarmee een klant zoekt. Elke dienst moet aan een bestaand pad
    hangen; wat daar niet aan te koppelen is valt af. Zo blijft de oude regel overeind — een
    taalmodel dat de branche verzint, verzint ook de zoekwoorden erbij — terwijl het wél de
    context toevoegt die een slug mist: dat een dienst zakelijk is en niet particulier, of
    dat de site iets bouwt in plaats van verkoopt.

    Ligt 30 dagen in KV. Zonder AI-sleutel, of bij een storing, komt er een leeg profiel
    terug en valt het onderzoek terug op de slugs — het loopt dus nooit vast op deze stap.
    """
    if not vers:
        bewaard = kv_get(SITEPROFIEL_SLEUTEL)
        if (isinstance(bewaard, dict) and isinstance(bewaard.get("profiel"), dict)
                and (time.time() - float(bewaard.get("t", 0) or 0)) < SITEPROFIEL_DAGEN * 86400):
            return bewaard["profiel"]
    if not _ai_configured():
        return {}
    bron = _siteprofiel_bron()
    if not bron["paginas"] and not (bron["bedrijf"].get("sector") or ""):
        return {}
    system = (
        "Je leest de tekst van ÉÉN website en beschrijft wat dat bedrijf verkoopt. Je baseert je "
        "UITSLUITEND op de aangeleverde tekst: verzin geen diensten, merken of plaatsen die er niet "
        "in staan. Antwoord uitsluitend met JSON:\n"
        '{"wat": "...", "doelgroep": "...", "doel": "leads|verkoop|bekendheid", '
        '"diensten": [{"pad": "/...", "zoekterm": "...", "waarom": "..."}], "vermijd": ["..."]}\n'
        '- "wat": één zin: wat doet dit bedrijf, voor wie.\n'
        '- "zoekterm": hoe een klant DEZE dienst intypt bij Google. Twee tot vier woorden, geen '
        "merknaam, en mét het onderscheid dat de dienst zakelijk of particulier maakt — een "
        "kale dienstnaam levert de verkeerde markt op.\n"
        '- "pad": exact overnemen uit de aangeleverde lijst.\n'
        '- "vermijd": losse woorden die in zoekwoorden opduiken maar bij een ANDERE markt horen '
        "dan deze site bedient. Alleen woorden die deze site echt niet bedient, en nooit een woord "
        "dat in een zoekterm hierboven staat.")
    r = _anthropic_call([{"role": "user", "content": json.dumps(bron, ensure_ascii=False)[:6000]}],
                        system=system, max_tokens=1200)
    if r.get("error"):
        print(f"[siteprofiel] AI mislukt: {r.get('error')}")
        return {}
    txt = "".join(b_.get("text", "") for b_ in r.get("content", []))
    m = re.search(r"\{.*\}", txt, re.S)
    try:
        rauw = json.loads(m.group(0)) if m else {}
    except json.JSONDecodeError:
        return {}
    if not isinstance(rauw, dict):
        return {}

    # Valideren tegen de site zelf. Een pad dat hier niet bestaat is verzonnen, en een
    # "zoekterm" van acht woorden is een zin — precies waar dit onderzoek eerder op strandde.
    paden = {p["pad"] for p in bron["paginas"]}
    diensten = []
    for d in (rauw.get("diensten") or []):
        if not isinstance(d, dict):
            continue
        pad = str(d.get("pad") or "").strip()
        term = re.sub(r"\s+", " ", str(d.get("zoekterm") or "")).strip().lower()
        if pad not in paden or not (2 <= len(term.split()) <= 5):
            continue
        diensten.append({"pad": pad, "zoekterm": term[:60],
                         "waarom": str(d.get("waarom") or "")[:200]})
    profiel = {
        "wat": str(rauw.get("wat") or "")[:300],
        "doelgroep": str(rauw.get("doelgroep") or "")[:200],
        "doel": str(rauw.get("doel") or "")[:40],
        "diensten": diensten,
        # Alleen losse woorden: een hele zin in deze lijst zou nooit matchen, en een woord dat
        # ook in een zoekterm staat zou de site zijn eigen diensten laten wegfilteren.
        "vermijd": sorted({w for w in (str(x).strip().lower() for x in (rauw.get("vermijd") or []))
                           if w and len(w) >= 3 and " " not in w
                           and not any(w in d["zoekterm"] for d in diensten)})[:25],
    }
    kv_set(SITEPROFIEL_SLEUTEL, {"t": int(time.time()), "profiel": profiel})
    return profiel


def _eigen_vocabulaire() -> set:
    """Elk woord waar deze site iets mee te maken heeft: slugs, regio, werkgebied, diensten.

    Waarvoor: een lokale zoekopdracht met een plaatsnaam die hier niet in staat gaat over een
    plaats waar deze site niets heeft — geen pagina, geen vestiging. "<dienst> <stad>" is dan
    geen focus-zoekwoord maar een doorway-pagina in de dop, en vijftien van die varianten
    vulden de hele lijst (Ryan 27-08-2026). Staat de stad er wél in, dan bestaat er een
    locatiepagina of ligt hij in het werkgebied, en is de term juist waardevol.
    """
    woorden = set()

    def _neem(tekst):
        woorden.update(re.findall(r"[a-z]{3,}", str(tekst or "").lower()))

    try:
        b = _business_profile()
        for bron in (b.get("region"), b.get("service_area"), b.get("sector"), b.get("address")):
            _neem(bron)
    except Exception:
        pass
    try:
        for p in _pages_index():
            _neem((p.get("slug") or "").replace("-", " ").replace("/", " "))
    except Exception:
        pass
    try:
        for d in (_site_profiel().get("diensten") or []):
            _neem(d.get("zoekterm"))
    except Exception:
        pass
    return woorden


def _zoekwoord_buiten_de_markt(term: str, profiel: dict) -> str:
    """Hoort deze zoekterm bij een andere markt dan deze site bedient?

    Geeft het woord terug dat het verraadt, of "". Bewust op hele woorden: "boek" mag
    "boeken over <dienst>" afwijzen zonder "geboekt" mee te nemen.
    """
    woorden = set(re.findall(r"[a-z0-9]+", (term or "").lower()))
    for slecht in (profiel.get("vermijd") or []):
        if slecht in woorden:
            return slecht
    return ""


def _zoekwoord_zaden(maximaal: int = 4) -> list:
    """Waar we SE Ranking mee bevragen: wat deze site zélf verkoopt.

    De dienstpagina's zijn het eerlijkste vertrekpunt — dat is waar het bedrijf zijn
    geld mee verdient en waar het al content voor heeft. Sector en werkgebied uit het
    bedrijfsprofiel vullen aan als er nog weinig pagina's staan. Bewust zonder AI: een
    taalmodel dat zaadwoorden verzint, verzint ook de branche erbij.
    """
    kandidaten, gezien = [], set()

    def voeg_toe(tekst):
        """Neem één kandidaat op, maar splits een opsomming eerst in losse termen.

        Een sector staat in het bedrijfsprofiel vaak als opsomming ("vloeren: pvc
        leggen, egaliseren, trappenrenovatie"). Die als één zoekterm naar SE Ranking
        sturen levert gegarandeerd nul resultaten op, want zo typt niemand. Splitsen
        op de scheidingstekens geeft wél bruikbare termen. Ryan 2026-08-26: de
        setup-wizard van damhousing strandde hierop met "Suggesties ophalen mislukt".
        """
        rauw = re.sub(r"\s+", " ", str(tekst or "")).strip().lower()
        for deel in re.split(r"[,;:|/]|\bof\b", rauw):
            t = deel.strip(" -\u2013\u2014.")
            t = re.sub(r"^(home|contact|over ons|diensten)$", "", t)
            # Meer dan vijf woorden is een zin, geen zoekopdracht. Zulke termen leveren
            # niets op en verdringen wel de termen die het wél doen.
            if len(t) < 4 or len(t.split()) > 5:
                continue
            kort = t[:60]
            # Ontdubbelen op wat we OPSLAAN, niet op de bron: twee verschillende zinnen
            # die op teken 60 gelijk zijn gaven anders twee identieke zaden.
            if kort in gezien:
                continue
            gezien.add(kort)
            kandidaten.append(kort)

    # De dienstpagina's die de SPA zelf serveert staan niet in de CMS-index. Die zijn
    # hier het eerlijkste vertrekpunt: dat is letterlijk wat het bedrijf verkoopt.
    try:
        for pad in (_scorende_spa_paden() if not kandidaten else []):
            laatste = pad.strip("/").split("/")[-1]
            if laatste:
                voeg_toe(laatste.replace("-", " "))
            # Ruim boven `maximaal` stoppen: we kiezen pas na het spreiden, dus we hebben
            # meer kandidaten nodig dan zaden. Wel een grens — een sitemap kan lang zijn.
            if len(kandidaten) >= 40:
                break
    except Exception:
        pass
    # Eerst het siteprofiel: dat weet wat de dienst ÍS, niet alleen hoe de slug heet.
    # "<dienst>" levert de consumentenkant van die markt op; "zakelijke <dienst>" of
    # "<dienst> laten maken" levert de klanten van deze site op.
    try:
        for d in (_site_profiel().get("diensten") or []):
            voeg_toe(d.get("zoekterm"))
    except Exception:
        pass

    # Geen profiel (geen AI-sleutel, of de site zegt te weinig over zichzelf)? Dan de
    # slugs. Twee lagen, en de eerste wint zodra hij iets oplevert: heeft de site dienstpagina's,
    # dan verkoopt hij dáármee en hoort er niets anders tussen te staan. Zonder die
    # voorrang bepaalt de volgorde van de sitemap wat er aan SE Ranking gevraagd wordt, en
    # verdringen de voorwaarden-, contact- en sjabloonpagina's de dienstpagina's die er wél
    # toe doen. Dat leverde een voorstellenlijst op waarvan de helft over andermans merk
    # ging (live gezien, Ryan 27-08-2026).
    diensten, overig = [], []
    try:
        for p in (_pages_index() if not kandidaten else []):
            if len(diensten) + len(overig) >= 40:
                break                      # ruim boven `maximaal`: we kiezen pas na het spreiden
            slug = (p.get("slug") or "").strip("/")
            if not slug or _niet_scorend_pad(slug):
                continue
            if slug.startswith(("diensten/", "dienst/")):
                diensten.append(slug)
            # Geen dienstenboom? Dan is een eigen slug met meerdere woorden het beste dat
            # er is — maar alleen als terugval.
            elif "-" in slug.split("/")[-1] and slug.count("/") == 0:
                overig.append(slug)
    except Exception:
        pass
    for slug in (diensten or (overig if not kandidaten else [])):
        # De SLUG, niet de titel: die is kort en beschrijft de dienst. Een titel is vaak een
        # meta-titel met merk en verkoopargument erin, en daar blijft na het splitsen vooral
        # merkfragment van over — dat verdringt de termen waar het om gaat.
        voeg_toe(slug.split("/")[-1].replace("-", " "))
    if len(kandidaten) < maximaal:
        try:
            b = _business_profile()
            voeg_toe(b.get("sector"))
            if b.get("sector") and b.get("region"):
                voeg_toe(f"{b['sector']} {b['region']}")
        except Exception:
            pass
    return _zaden_spreiden(kandidaten, maximaal)


def _zaden_spreiden(kandidaten: list, maximaal: int) -> list:
    """Eerst één zaad per kopwoord, dan pas een tweede met hetzelfde kopwoord.

    Drie zaden die met hetzelfde woord beginnen ("vloer egaliseren", "vloer schuren",
    "vloer polijsten") leveren bij SE Ranking vrijwel dezelfde suggesties op en kosten wel
    drie credits. Maar liever een tweede vloer-term dan een leeg zaad, dus het is een
    volgorde en geen filter: de lijst blijft compleet, alleen de kop verandert.
    """
    eerste, rest, koppen = [], [], set()
    for t in kandidaten or []:
        kop = next((w for w in re.findall(r"[a-z0-9]+", str(t).lower())
                    if w not in _KW_VULWOORDEN), str(t).lower())
        (rest if kop in koppen else eerste).append(t)
        koppen.add(kop)
    return (eerste + rest)[:maximaal]


@app.route("/api/seo/gsc/aanmelden", methods=["POST"])
@app.route("/api/seo/gsc/aanmelden/", methods=["POST"])
def api_gsc_aanmelden():
    """Meldt deze site aan bij Search Console en bewijst het eigendom — in één klik.

    Met de hand is dit: property aanmaken, verificatiemethode kiezen, bestand plaatsen,
    verifiëren, property selecteren. Wij bezitten de site, dus dat kan de site zelf doen.
    Elke stap geeft zijn eigen foutmelding terug: bij 'insufficient permission' weet je
    dat de koppeling nog op de oude leesscope staat en opnieuw gelegd moet worden.
    """
    a = _require_agency()
    if a:
        return a
    basis = (_public_base() or "").rstrip("/")
    if not basis.startswith("http"):
        return jsonify({"ok": False, "error": "Geen publieke site-URL bekend (PUBLIC_SITE_URL)"}), 400
    site_url = basis + "/"

    # Geen eigen Google-koppeling? Dan via het teamaccount bij MAIHS — dat is de normale
    # weg geworden; een eigen koppeling per site is alleen nog de uitzondering.
    if not google_access_token("search_console") and _gateway_origin() and _gateway_key():
        tok, err = _gsc_gateway("verificatietoken")
        if err:
            return jsonify({"ok": False, "stap": "token", "error": err}), 502
        bestand = str((tok or {}).get("bestand") or "")
        if not bestand:
            return jsonify({"ok": False, "stap": "token", "error": "Geen verificatiebestand ontvangen"}), 502
        # Eerst bewaren (de route hierboven serveert 'm meteen), pas dan laten controleren.
        kv_set(GSC_VERIFY_KEY, bestand)
        data, err = _gsc_gateway("aanmelden")
        if err:
            return jsonify({"ok": False, "stap": "verificatie", "error": err, "bestand": "/" + bestand}), 502
        prop = str((data or {}).get("property") or site_url)
        bestaand = kv_get("settings", {}) or {}
        sc = dict(bestaand.get("search_console") or {})
        sc["site"] = prop
        bestaand["search_console"] = sc
        kv_set("settings", bestaand)
        try:
            _gsc_gateway("sitemap", sitemap=prop.rstrip("/") + "/sitemap.xml")
        except Exception:
            pass
        audit_log("seo.gsc.aangemeld", "seo", prop + " (via gateway)")
        return jsonify({"ok": True, "site": prop, "via": "gateway"})

    # 1. Verificatietoken opvragen (FILE: een bestandsnaam die wij gaan serveren).
    tok, err = _google_api("https://www.googleapis.com/siteVerification/v1/token",
                           {"site": {"type": "SITE", "identifier": site_url},
                            "verificationMethod": "FILE"}, "search_console", timeout=20)
    if err:
        hint = " — herverbind Search Console: de koppeling heeft alleen leesrechten" if "insufficient" in err.lower() or "403" in err else ""
        return jsonify({"ok": False, "stap": "token", "error": err + hint}), 502
    bestand = str((tok or {}).get("token") or "")
    if not bestand:
        return jsonify({"ok": False, "stap": "token", "error": "Google gaf geen verificatietoken terug"}), 502
    kv_set(GSC_VERIFY_KEY, bestand)

    # 2. Google laten controleren. Het bestand staat er nu, want stap 1 heeft het bewaard
    #    en de route hierboven serveert het meteen.
    _, err = _google_api("https://www.googleapis.com/siteVerification/v1/webResource?verificationMethod=FILE",
                         {"site": {"type": "SITE", "identifier": site_url}}, "search_console", timeout=25)
    if err:
        return jsonify({"ok": False, "stap": "verificatie", "error": err,
                        "bestand": "/" + bestand}), 502

    # 3. Property toevoegen. PUT, dus niet via _google_api (die doet GET/POST).
    tokend = google_access_token("search_console")
    put = urllib.request.Request(
        "https://www.googleapis.com/webmasters/v3/sites/" + urllib.parse.quote(site_url, safe=""),
        method="PUT", headers={"Authorization": "Bearer " + (tokend or "")})
    try:
        with urllib.request.urlopen(put, timeout=20) as r:
            r.read()
    except urllib.error.HTTPError as e:
        return jsonify({"ok": False, "stap": "toevoegen",
                        "error": f"{e.code}: {e.read().decode('utf-8', 'replace')[:200]}"}), 502
    except Exception as e:
        return jsonify({"ok": False, "stap": "toevoegen", "error": str(e)}), 502

    # 4. Meteen selecteren: een property die nergens is ingesteld levert nog steeds
    #    geen data aan de autopilot.
    bestaand = kv_get("settings", {}) or {}
    sc = dict(bestaand.get("search_console") or {})
    sc["site"] = site_url
    bestaand["search_console"] = sc
    kv_set("settings", bestaand)
    # En meteen de sitemap indienen: koppelen zonder sitemap betekent dat Google je
    # pagina's zelf maar moet vinden.
    sitemap_ok, sitemap_melding = _gsc_sitemap_indienen()
    audit_log("seo.gsc.aangemeld", "seo", site_url)
    return jsonify({"ok": True, "site": site_url, "bestand": "/" + bestand,
                    "sitemap": {"ingediend": sitemap_ok, "melding": sitemap_melding}})


@app.route("/api/report/img", methods=["GET"])
@app.route("/api/report/img/", methods=["GET"])
def api_report_img():
    """Zelfde-domein-doorgeefluik voor rapportbeelden (logo, profielfoto): html2canvas
    laat cross-origin beelden zonder CORS-header stil uit de PDF vallen, en op het
    eigen domein bestaat dat probleem niet. Bewust geen open proxy: alleen beelden
    van de eigen MAIHS-host, en het content-type komt uit de extensie, niet van de
    bron. Bij een storing 302 naar het origineel: de webversie toont het beeld dan
    alsnog, alleen de PDF mist het."""
    src = str(request.args.get("src") or "").strip()
    typen = {"png": "image/png", "jpg": "image/jpeg", "jpeg": "image/jpeg",
             "webp": "image/webp", "gif": "image/gif"}
    ext = src.rsplit("/", 1)[-1].rsplit(".", 1)[-1].lower() if "." in src.rsplit("/", 1)[-1] else ""
    if not src.startswith(_RAPPORT_BEELD_HOST) or ext not in typen:
        return jsonify({"error": "invalid src"}), 400
    data = _rapport_img_ophalen(src)
    if not data:
        return redirect(src, code=302)
    resp = Response(data, mimetype=typen[ext])
    resp.headers["Cache-Control"] = "public, max-age=86400"
    return resp


