@app.route("/api/seo/agent/keyword-suggesties", methods=["POST"])
@app.route("/api/seo/agent/keyword-suggesties/", methods=["POST"])
def api_seo_agent_keyword_suggesties():
    """Focus-zoekwoorden voorstellen op basis van SE Ranking-data.

    De suggesties komen uit SE Ranking en niet uit een taalmodel: daar staan echte
    zoekvolumes, moeilijkheidsgraden en zoekintenties achter. Een AI kan die cijfers
    niet weten en zou ze invullen met iets dat plausibel klinkt — precies het soort
    getal waar je later beslissingen op baseert.

    Wat de site aanlevert zijn de zaadwoorden (zijn eigen dienstpagina's); wat
    terugkomt zijn de zoekwoorden die mensen daar werkelijk omheen intypen.
    """
    a = _require_agency()
    if a:
        return a
    # "Opnieuw" leest ook de site opnieuw: is er een dienstpagina bijgekomen of herschreven,
    # dan hoort het onderzoek daarop te veranderen in plaats van op de oude lezing te blijven.
    if bool((request.get_json(silent=True) or {}).get("vers")):
        _site_profiel(vers=True)
    # Zoveel zaden als er onderwerpen nodig zijn. Met hoogstens twee voorstellen per
    # onderwerp (ONDERWERP_MAX) haal je uit drie zaden nooit twintig bruikbare zoekwoorden:
    # dan wint één dienst de hele lijst, of er blijven er vier over. Reken dus terug van
    # het doel — twintig zoekwoorden vraagt om een stuk of tien onderwerpen, en dus om
    # tien zaden (Ryan 27-08-2026: "wederom is het allemaal <één dienst>").
    _adv_zaden = _zoekwoord_advies()
    _doel_kw = int(_adv_zaden.get("doel") or _adv_zaden.get("max") or 0) or 8
    zaden = _zoekwoord_zaden(max(3, min(10, -(-_doel_kw // 2))))
    if not zaden:
        return jsonify({"ok": False, "error": "Deze site heeft nog geen dienstpagina's om op te zoeken"}), 400
    try:
        # Zoveel voorstellen als er te kiezen valt: ruim twee keer het aantal dat bij deze
        # site past, zodat er echt iets te vergelijken is. 14 was een getal uit de lucht.
        _adv = _zoekwoord_advies()
        ideeen = _seranking_keyword_ideeen(zaden, maximaal=max(20, int(_adv.get("max") or 0) * 2),
                                           vers=bool((request.get_json(silent=True) or {}).get("vers")))
    except Exception as e:
        print(f"[keyword-suggesties] SE Ranking mislukt: {e}")
        ideeen = []
    if not ideeen:
        # Zeg wát er misging. "Controleer of het project gekoppeld is" was de enige melding
        # die hier ooit uitkwam, ook als de gateway 402 gaf omdat het SE Ranking-tegoed op
        # was — dan ga je een koppeling nakijken die niets mankeert.
        reden = _seranking_fout_reden()
        return jsonify({"ok": False, "zaden": zaden,
                        "error": reden or ("SE Ranking kent geen zoekwoorden bij "
                                           + ", ".join("\u201c%s\u201d" % z for z in zaden[:3])
                                           + ". Dat zijn de zoektermen die uit je dienstpagina's "
                                             "of je bedrijfsprofiel komen; pas die aan, of typ "
                                             "hieronder zelf een zoekwoord.")}), 502
    gekozen = _agent_config().get("focus_keywords") or []
    # Gekozen termen die niet in de voorstellen zitten (zelf getypt, of van eerder) krijgen
    # hun cijfers alsnog uit SE Ranking — anders staat de helft van je lijst zonder data.
    bekend = {i["keyword"].lower() for i in ideeen}
    extra = [k for k in gekozen if k.lower() not in bekend]
    for term, cijfers in (_seranking_keyword_cijfers(extra) or {}).items():
        ideeen.append({"keyword": term, "bron": "seranking", "eigen_keuze": True, **cijfers})
    # Termen waar SE Ranking niets over weet komen NIET als voorstel terug: dan zou je ze
    # na het weghalen elke keer opnieuw in de lijst zien staan, zonder ze kwijt te kunnen.
    # Ze blijven wel gewoon jouw keuze zolang je ze aangevinkt hebt (zie kwRijen).
    for idee in ideeen:
        # De onderbouwing is een feit en geen mening: dit staat in de data.
        # Voluit, en met wat de intentie betékent: "commercieel" zegt een ondernemer weinig,
        # "vergelijkt nog" wel. De vorige versie plakte een 'e' achter het zelfstandig
        # naamwoord; dat gaf alleen bij 'transactioneel' toevallig een bestaand woord.
        # (bijvoeglijk voor in de zin, zelfstandig voor in een opsomming, en de betekenis)
        # De intentie komt sinds 2026-08-25 al als NL-woord binnen (_seranking_intent_labels);
        # de lettercodes blijven als terugval voor oude cache-inhoud.
        intentie = {"commercieel": ("commerciële", "commercieel", "vergelijkt nog, oriënteert zich"),
                    "transactioneel": ("transactionele", "transactioneel", "wil nu iets afnemen"),
                    "informatief": ("informatieve", "informatief", "zoekt uitleg"),
                    "lokaal": ("lokale", "lokaal", "zoekt een bedrijf in de buurt"),
                    "navigatie": ("navigatie-", "navigatie", "zoekt een specifiek merk"),
                    "C": ("commerciële", "commercieel", "vergelijkt nog, oriënteert zich"),
                    "T": ("transactionele", "transactioneel", "wil nu iets afnemen"),
                    "I": ("informatieve", "informatief", "zoekt uitleg"),
                    "L": ("lokale", "lokaal", "zoekt een bedrijf in de buurt"),
                    "N": ("navigatie-", "navigatie", "zoekt een specifiek merk")}.get(
                        (idee.get("intentie") or "").split(",")[0].strip(), ())
        idee["waarom"] = (f"{idee['volume']} zoekopdrachten per maand"
                          + (f" · moeilijkheid {idee['moeilijkheid']} van 100 (hoe zwaar de "
                             f"concurrentie op deze term is)" if idee.get("moeilijkheid") else "")
                          + (f" · {intentie[0]} zoekintentie: de zoeker {intentie[2]}"
                             if intentie else ""))
        # Ook los, zodat het scherm er regels van kan maken in plaats van één lange zin.
        idee["intentie_label"] = intentie[1] if intentie else ""
        idee["intentie_uitleg"] = intentie[2] if intentie else ""
    # Het siteprofiel weet ook wat deze site NIET doet. Een zoekterm uit een andere markt
    # (de consumentenvariant van dezelfde dienst, of een winkelketen) hoort niet in de lijst.
    _profiel = _site_profiel()
    if _profiel.get("vermijd"):
        _schoon = [i for i in ideeen if i.get("eigen_keuze")
                   or not _zoekwoord_buiten_de_markt(i.get("keyword"), _profiel)]
        # Vangnet: een te ruime vermijd-lijst mag de lijst niet leegvegen. Dan liever
        # ongefilterd tonen dan een leeg scherm met een onverklaarbare oorzaak.
        if len(_schoon) >= max(8, len(ideeen) // 3):
            ideeen = _schoon
    # Een navigatie-zoekopdracht is een zoekopdracht naar een BEDRIJF ("<merk> contact
    # opnemen"). Daar kun je niet op winnen en dat wil je ook niet: die zoeker is op weg
    # naar iemand anders. Ze wogen alleen lichter mee in de aanbeveling, maar vulden de
    # lijst wél — tien van de veertig voorstellen gingen over andermans merk (Ryan
    # 27-08-2026). Zelf gekozen termen blijven staan: dat is jouw keuze, niet ons advies.
    ideeen = [i for i in ideeen
              if i.get("eigen_keuze") or i.get("intentie_label") != "navigatie"] or ideeen
    # Welke hij zélf zou kiezen, en hoeveel: een lijst van veertien is nog geen keuze.
    _zoekwoord_aanbevelen(ideeen, gekozen)
    ideeen = _zoekwoord_sorteren(ideeen)
    # De grenzen gaan mee terug: het scherm rekent de aanbeveling bij elke klik opnieuw uit en
    # hoort dat met DEZELFDE regels te doen als hierboven, niet met een nagetikt getal.
    return jsonify({"ok": True, "suggesties": ideeen, "zaden": zaden, "bron": "seranking",
                    "regels": {"onderwerp_max": ZOEKWOORD_ONDERWERP_MAX}})


@app.route("/api/seo/agent/pad-check", methods=["GET"])
@app.route("/api/seo/agent/pad-check/", methods=["GET"])
def api_seo_agent_pad_check():
    """Bestaat dit pad op de site? Eerst de CMS-index, anders echt ophalen.

    Een uitsluiting op een pad dat niet bestaat doet niets en valt nooit op — de agent
    slaat dan een pagina over die er niet is, terwijl degene die je wilde beschermen
    gewoon aangeraakt wordt. Vandaar de controle bij het invoeren.
    """
    a = _require_agency()
    if a:
        return a
    p = (request.args.get("pad") or "").strip()
    if not p.startswith("/"):
        p = "/" + p
    if p in _agent_known_paths():
        return jsonify({"ok": True, "bestaat": True, "bron": "cms"})
    url = (_public_base() or "").rstrip("/") + p
    try:
        req = urllib.request.Request(url, method="HEAD", headers={"User-Agent": "MAIHS-PadCheck/1.0"})
        with urllib.request.urlopen(req, timeout=8) as r:
            status = r.status
    except urllib.error.HTTPError as e:
        status = e.code
    except Exception as e:
        # Netwerkfout is geen bewijs dat het pad niet bestaat; dan liever niets beweren.
        return jsonify({"ok": True, "bestaat": None, "bron": "onbereikbaar", "melding": str(e)[:120]})
    return jsonify({"ok": True, "bestaat": bool(200 <= status < 400), "status": status, "bron": "http"})


