@app.route("/api/seo/audit/recheck", methods=["POST"])
@app.route("/api/seo/audit/recheck/", methods=["POST"])
def api_seo_audit_recheck():
    """Start een nieuwe site-audit bij SE Ranking (Ryan 2026-08-24).

    Bureauwerk: credits per gecrawlde pagina, dus agency-only én een cooldown.
    Loopt via de enige POST die de MAIHS-gateway toestaat (recheck/standard); een
    gateway die de wijziging nog niet heeft geeft een eerlijke release-melding."""
    a = _require_agency()
    if a:
        return a
    vorige = kv_get("seo:audit:recheck") or {}
    rest = int(AUDIT_RECHECK_COOLDOWN_S - (time.time() - float(vorige.get("t", 0) or 0)))
    if rest > 0:
        return jsonify({"ok": False, "error": "Er is net een audit gestart — probeer het over "
                                              f"~{max(1, (rest + 3599) // 3600)} uur opnieuw."}), 429
    try:
        audit = _seranking_audit() or {}
    except Exception:
        audit = {}
    audit_id = str(audit.get("audit_id") or "")
    if not audit_id:
        return jsonify({"ok": False, "error": "Geen bestaande audit gevonden — koppel SE Ranking "
                                              "eerst (of wacht tot de eerste audit is gedraaid)."}), 400
    status, _data = _seranking_post("/v1/site-audit/audits/recheck/standard", {"audit_id": audit_id})
    if status in (401, 403, 405):
        # 403 = path_not_allowed, 405 = geen POST-handler: de gateway-wijziging staat
        # nog niet op productie. Dat is release-volgorde, geen storing.
        return jsonify({"ok": False, "error": "De centrale gateway staat het starten van een audit "
                                              "nog niet toe — release de MAIHS-wijziging eerst."}), 502
    if not (200 <= status < 300):
        return jsonify({"ok": False, "error": "SE Ranking kon de audit niet starten — "
                                              "probeer het later opnieuw."}), 502
    kv_set("seo:audit:recheck", {"t": int(time.time()), "audit_id": audit_id})
    # De oude samenvatting (score, datum) staat anders nog uren in de lokale cache.
    _seranking_cache_vergeet("/v1/site-audit/audits")
    audit_log("seo.audit.recheck", "seo", f"nieuwe site-audit gestart (audit {audit_id})")
    return jsonify({"ok": True, "melding": "Nieuwe audit gestart — SE Ranking crawlt de site nu. "
                                           "De uitkomst verschijnt hier zodra hij klaar is "
                                           "(enkele minuten tot een uur)."})


@app.route("/api/seo/report/delete", methods=["POST"])
@app.route("/api/seo/report/delete/", methods=["POST"])
def api_seo_report_delete():
    """Verwijder een rapport: uit de historie én uit de opslag, zodat de deel-link
    (view/PDF) daarna echt dood is. De bevestiging zit in de admin (uiConfirm)."""
    a = _require_agency()
    if a:
        return a
    rid = str((request.get_json(silent=True) or {}).get("id") or "").strip()
    rep = kv_get(f"seo:report:{rid}") if rid else None
    hist = kv_get("seo:report:history", []) or []
    in_historie = any(h.get("id") == rid for h in hist)
    if not rid or not (rep or in_historie):
        return jsonify({"ok": False, "error": "Rapport niet gevonden."}), 404
    kv_delete(f"seo:report:{rid}")
    if in_historie:
        kv_set("seo:report:history", [h for h in hist if h.get("id") != rid])
    audit_log("seo.report.delete", rid, "Rapport verwijderd")
    return jsonify({"ok": True})


@app.route("/api/seo/report/rewrite", methods=["POST"])
@app.route("/api/seo/report/rewrite/", methods=["POST"])
def api_seo_report_rewrite():
    """Herschrijf de AI-teksten van een bestaand rapport, optioneel met een instructie
    van de accountmanager ('maak de intro korter'). Zelfde id en token blijven gelden,
    dus de view-link, PDF en mail volgen automatisch de nieuwe versie."""
    a = _require_perm("seo")
    if a:
        return a
    d = request.get_json(silent=True) or {}
    rid = str(d.get("id") or "").strip()
    instructie = str(d.get("instruction") or "").strip()[:500]
    rep = kv_get(f"seo:report:{rid}") if rid else None
    if not isinstance(rep, dict) or not rep.get("token"):
        return jsonify({"ok": False, "error": "Rapport niet gevonden."}), 404
    if not _ai_configured():
        return jsonify({"ok": False, "error": "AI staat niet aan: koppel eerst de AI-gateway of een "
                                              "Anthropic-sleutel bij Instellingen."}), 400
    teksten = _rapport_ai_teksten(rep, instructie=instructie)
    if not teksten:
        return jsonify({"ok": False, "error": "De teksten konden niet worden herschreven. "
                                              "Probeer het zo nog eens."}), 502
    rep["teksten"] = teksten
    kv_set(f"seo:report:{rid}", rep)
    base = _public_base() or CANONICAL_BASE
    rep["view_url"] = f'{base}/api/report/view?id={rid}&t={rep.get("token", "")}'
    audit_log("seo.report.rewrite", rid, instructie[:120] or "nieuwe versie zonder instructie")
    return jsonify({"ok": True, "report": rep})


