@app.route("/google<code>.html")
def google_verificatiebestand(code):
    """Serveert het verificatiebestand dat Google verwacht bij de FILE-methode.

    Google haalt dit op de root op en wil er letterlijk 'google-site-verification: <naam>'
    in zien. We serveren alléén het bestand dat we zelf hebben aangevraagd, zodat dit geen
    open eindpunt wordt waarmee een willekeurige derde eigendom van deze site zou kunnen
    claimen."""
    bestand = str(kv_get(GSC_VERIFY_KEY) or "")
    if not bestand or bestand != f"google{code}.html":
        abort(404)
    return Response("google-site-verification: " + bestand + "\n", mimetype="text/html")


@app.route("/vendor/<path:sub>")
def vendor_static(sub):
    """Zelf gehoste front-end-bundels (html2pdf). Op Vercel serveert de static-laag
    dit pad en komt deze route nooit aan bod; lokaal draait alleen Flask en zou elke
    PDF-actie anders op de terugval vallen. Publiek: de rapport-view is dat ook."""
    basis = (Path(__file__).resolve().parent.parent / "public" / "vendor").resolve()
    p = (basis / sub).resolve()
    if not str(p).startswith(str(basis)) or not p.is_file():
        abort(404)
    return send_from_directory(p.parent, p.name)


# ==================== SEARCH CONSOLE / ANALYTICS / MARKETING OVERVIEW ====================
def _google_api(url, body=None, service=None, timeout=30):
    tok = google_access_token(service)
    if not tok:
        return None, "Niet (meer) verbonden met Google."
    try:
        data = json.dumps(body).encode() if body is not None else None
        headers = {"Authorization": "Bearer " + tok}
        if body is not None:
            headers["Content-Type"] = "application/json"
        req = urllib.request.Request(url, data=data, headers=headers, method="POST" if body is not None else "GET")
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read() or b"{}"), None
    except urllib.error.HTTPError as e:
        return None, f"{e.code}: {e.read().decode('utf-8', 'replace')[:250]}"
    except Exception as e:
        return None, str(e)


# ---- Search Console ----
@app.route("/api/search-console/sites")
def api_sc_sites():
    a = _auth_or_401()
    if a:
        return a
    data, err = _google_api("https://www.googleapis.com/webmasters/v3/sites", service="search_console")
    if err:
        return jsonify({"ok": False, "error": err}), 400
    sites = [{"id": s["siteUrl"], "name": s["siteUrl"]} for s in (data.get("siteEntry") or [])
             if s.get("permissionLevel") != "siteUnverifiedUser"]
    return jsonify({"ok": True, "sites": sites})


def _sc_query(site, frm, to, dims, timeout=30):
    url = "https://www.googleapis.com/webmasters/v3/sites/" + urllib.parse.quote(site, safe='') + "/searchAnalytics/query"
    return _google_api(url, {"startDate": frm, "endDate": to, "dimensions": dims, "rowLimit": 1000}, "search_console", timeout=timeout)


@app.route("/api/search-console/data")
def api_sc_data():
    a = _auth_or_401()
    if a:
        return a
    site = request.args.get("site") or (get_settings().get("search_console") or {}).get("site", "")
    if not site:
        return jsonify({"ok": False, "error": "Geen Search Console-site gekozen."}), 400
    today = datetime.now()
    frm = request.args.get("from") or (today - timedelta(days=30)).strftime("%Y-%m-%d")
    to = request.args.get("to") or today.strftime("%Y-%m-%d")
    byq, err = _sc_query(site, frm, to, ["query"])
    if err:
        return jsonify({"ok": False, "error": err}), 400
    queries = []
    clicks = impressions = 0
    for row in (byq.get("rows") or []):
        clicks += int(row.get("clicks", 0))
        impressions += int(row.get("impressions", 0))
        queries.append({"query": row["keys"][0], "clicks": int(row.get("clicks", 0)),
                        "impressions": int(row.get("impressions", 0)),
                        "position": round(row.get("position", 0), 1)})
    queries.sort(key=lambda x: x["clicks"], reverse=True)
    return jsonify({"ok": True, "clicks": clicks, "impressions": impressions, "queries": queries[:25]})


# ---- Analytics (GA4) ----
@app.route("/api/analytics/properties")
def api_ga_properties():
    a = _auth_or_401()
    if a:
        return a
    data, err = _google_api("https://analyticsadmin.googleapis.com/v1beta/accountSummaries", service="analytics")
    if err:
        return jsonify({"ok": False, "error": err}), 400
    props = []
    for acc in (data.get("accountSummaries") or []):
        for ps in (acc.get("propertySummaries") or []):
            props.append({"id": ps["property"], "name": ps.get("displayName", ps["property"])})
    return jsonify({"ok": True, "properties": props})


def _ga4_report(prop, body):
    pid = prop.split("/")[-1]
    return _google_api(f"https://analyticsdata.googleapis.com/v1beta/properties/{pid}:runReport", body, "analytics")


# ---- Marketing overview (combineert Ads + SC + GA4 + omzet uit leads) ----
# ---- Kanaal-attributie op EIGEN data (geen GA4/Search Console nodig) --------
# Elke aanvraag is een conversie die we zelf bezitten: de React-site legt de
# first-touch vast (referrer + utm_* + gclid, zie src/lib/track.js) en stuurt die
# mee bij /api/submit. Leads van vóór deze meting hebben geen signaal -> 'onbekend'
# (bewust transparant, niet gokken).

_CHANNEL_LABELS = {
    "seo": "Organisch (SEO)", "ads": "Google Ads", "direct": "Direct",
    "referral": "Verwijzend", "social": "Social", "email": "E-mail",
    "ai": "AI-zoekmachines", "onbekend": "Onbekend",
}
_SOCIAL_HOSTS = ("facebook.", "instagram.", "linkedin.", "x.com", "twitter.", "pinterest.", "tiktok.", "youtube.")
_SEARCH_HOSTS = ("google.", "bing.", "duckduckgo.", "yahoo.", "ecosia.", "startpage.")
_AI_HOSTS = ("chatgpt.com", "chat.openai.com", "perplexity.ai", "claude.ai", "gemini.google.com", "copilot.microsoft.com")


def _classify_channel(lead: dict) -> str:
    """Bepaal het kanaal van een lead uit de first-touch-attributie."""
    a = lead.get("attr") or {}
    if not isinstance(a, dict):
        return "onbekend"
    medium = str(a.get("utm_medium") or "").lower()
    source = str(a.get("utm_source") or "").lower()
    ref = str(a.get("referrer") or "").lower()
    if a.get("gclid") or medium in ("cpc", "ppc", "paid") or source in ("google_ads", "googleads", "adwords"):
        return "ads"
    if medium in ("email", "e-mail", "newsletter"):
        return "email"
    if medium in ("social", "social-media") or any(h in source for h in _SOCIAL_HOSTS):
        return "social"
    if medium in ("organic", "seo"):
        return "seo"
    if source:
        if any(h in source for h in _AI_HOSTS):
            return "ai"
        if any(h in source for h in _SEARCH_HOSTS):
            return "seo"
        return "referral"
    if ref:
        host = re.sub(r"^https?://", "", ref).split("/")[0]
        if any(h in host for h in _AI_HOSTS):
            return "ai"
        if any(h in host for h in _SEARCH_HOSTS):
            return "seo"
        if any(h in host for h in _SOCIAL_HOSTS):
            return "social"
        return "referral"
    if a.get("direct"):
        return "direct"
    return "onbekend"


def _channel_breakdown(frm: str, to: str) -> dict:
    """Conversies (leads) + omzet uit BETAALDE facturen, gegroepeerd per kanaal."""
    try:
        paid = {}
        for inv in get_invoices_index():
            if inv.get("status") == "betaald" and inv.get("lead_id"):
                paid[inv["lead_id"]] = paid.get(inv["lead_id"], 0.0) + float(inv.get("total") or 0)
    except Exception:
        paid = {}
    agg: dict = {}
    total = 0
    for l in get_leads():
        day = (l.get("created") or "")[:10]
        if not day or day < frm or day > to:
            continue
        ch = _classify_channel(l)
        row = agg.setdefault(ch, {"channel": ch, "label": _CHANNEL_LABELS.get(ch, ch), "leads": 0, "revenue": 0.0})
        row["leads"] += 1
        row["revenue"] += paid.get(l.get("id"), 0.0)
        total += 1
    rows = sorted(agg.values(), key=lambda r: (-r["leads"], r["label"]))
    for r in rows:
        r["revenue"] = round(r["revenue"], 2)
        r["share"] = round(100.0 * r["leads"] / total, 1) if total else 0.0
    return {"channels": rows, "total_leads": total, "from": frm, "to": to}


def _range_dates(rng: str) -> tuple:
    """'7d'/'30d'/'90d'/'month' -> (van, tot) als YYYY-MM-DD."""
    today = datetime.now()
    if rng == "month":
        return today.replace(day=1).strftime("%Y-%m-%d"), today.strftime("%Y-%m-%d")
    days = {"7d": 7, "30d": 30, "90d": 90, "365d": 365}.get((rng or "").lower(), 30)
    return (today - timedelta(days=days - 1)).strftime("%Y-%m-%d"), today.strftime("%Y-%m-%d")


@app.route("/api/marketing/channels", methods=["GET"])
@app.route("/api/marketing/channels/", methods=["GET"])
def api_marketing_channels():
    a = _auth_or_401()
    if a:
        return a
    frm = request.args.get("from")
    to = request.args.get("to")
    if not (frm and to):
        frm, to = _range_dates(request.args.get("range") or "30d")
    return jsonify(_channel_breakdown(frm, to))


@app.route("/api/marketing/overview")
def api_marketing_overview():
    a = _auth_or_401()
    if a:
        return a
    today = datetime.now()
    frm = request.args.get("from") or (today - timedelta(days=29)).strftime("%Y-%m-%d")
    to = request.args.get("to") or today.strftime("%Y-%m-%d")
    d0 = datetime.strptime(frm, "%Y-%m-%d")
    d1 = datetime.strptime(to, "%Y-%m-%d")
    days = []
    d = d0
    while d <= d1:
        days.append(d.strftime("%Y-%m-%d"))
        d += timedelta(days=1)
    seo = {x: 0 for x in days}
    sea_clicks = {x: 0 for x in days}
    sea_cost = {x: 0.0 for x in days}
    s = get_settings()
    conn = {"ads": False, "search_console": False, "analytics": False}
    errors = {}
    totals = {"seo_clicks": 0, "seo_impressions": 0, "sea_clicks": 0, "sea_cost": 0.0,
              "sea_conversions": 0.0, "sessions": 0, "users": 0, "ga_conversions": 0.0}

    # Google Ads (per dag)
    ga = s.get("google_ads") or {}
    if ga.get("customer_id"):
        q = ("SELECT segments.date, metrics.clicks, metrics.cost_micros, metrics.conversions "
             f"FROM campaign WHERE segments.date BETWEEN '{frm}' AND '{to}'")
        rows, err = _ads_search(ga["customer_id"], q, login_customer_id=ga.get("login_customer_id", ""))
        if rows is not None:
            conn["ads"] = True
            for r in rows:
                dt = (r.get("segments") or {}).get("date", "")
                m = r.get("metrics") or {}
                if dt in sea_clicks:
                    sea_clicks[dt] += int(m.get("clicks", 0))
                    sea_cost[dt] += int(m.get("costMicros", 0)) / 1e6
                    totals["sea_conversions"] += float(m.get("conversions", 0))
        else:
            errors["ads"] = err

    # Search Console (per dag)
    sc = s.get("search_console") or {}
    if sc.get("site"):
        data, err = _sc_query(sc["site"], frm, to, ["date"])
        if data is not None:
            conn["search_console"] = True
            for row in (data.get("rows") or []):
                dt = row["keys"][0]
                if dt in seo:
                    seo[dt] += int(row.get("clicks", 0))
                totals["seo_clicks"] += int(row.get("clicks", 0))
                totals["seo_impressions"] += int(row.get("impressions", 0))
        else:
            errors["search_console"] = err

    # Analytics (GA4) — sessies + conversies
    conversions = []
    an = s.get("analytics") or {}
    if an.get("property"):
        rep, err = _ga4_report(an["property"], {
            "dateRanges": [{"startDate": frm, "endDate": to}],
            "metrics": [{"name": "sessions"}, {"name": "totalUsers"}, {"name": "conversions"}]})
        if rep is not None:
            conn["analytics"] = True
            for row in (rep.get("rows") or []):
                mv = row.get("metricValues", [])
                totals["sessions"] += int(float(mv[0]["value"])) if len(mv) > 0 else 0
                totals["users"] += int(float(mv[1]["value"])) if len(mv) > 1 else 0
                totals["ga_conversions"] += float(mv[2]["value"]) if len(mv) > 2 else 0
            crep, _ = _ga4_report(an["property"], {
                "dateRanges": [{"startDate": frm, "endDate": to}],
                "dimensions": [{"name": "eventName"}], "metrics": [{"name": "conversions"}],
                "orderBys": [{"metric": {"metricName": "conversions"}, "desc": True}], "limit": 10})
            if crep:
                for row in (crep.get("rows") or []):
                    nm = (row.get("dimensionValues") or [{}])[0].get("value", "")
                    cnt = float((row.get("metricValues") or [{}])[0].get("value", 0) or 0)
                    if cnt > 0:
                        conversions.append({"name": nm, "count": round(cnt, 1)})
        else:
            errors["analytics"] = err

    totals["sea_clicks"] = sum(sea_clicks.values())
    totals["sea_cost"] = round(sum(sea_cost.values()), 2)
    totals["sea_conversions"] = round(totals["sea_conversions"], 1)

    # Omzet = ALLEEN betaalde facturen (niet het speculatieve omzet-veld op leads).
    paid_invoices = [i for i in (get_invoices_index() or []) if i.get("status") == "betaald"]
    lead_revenue = round(sum(float(i.get("total", 0) or 0) for i in paid_invoices), 2)
    closed = paid_invoices

    series_seo = [seo[x] for x in days]
    series_sea = [sea_clicks[x] for x in days]
    series_total = [seo[x] + sea_clicks[x] for x in days]
    labels = [datetime.strptime(x, "%Y-%m-%d").strftime("%d-%m") for x in days]

    return jsonify({"ok": True, "from": frm, "to": to, "labels": labels,
                    "series": {"seo": series_seo, "sea": series_sea, "total": series_total},
                    "totals": totals, "conversions": conversions,
                    "revenue": {"deals": len(closed), "lead_revenue": lead_revenue},
                    "connected": conn, "errors": errors})


