@app.route("/api/review-feedback", methods=["POST"])
def api_review_feedback():
    d = request.get_json(silent=True) or request.form.to_dict()
    if (d.get("hp_url") or "").strip():
        return jsonify({"ok": True})
    try:
        stars = int(d.get("stars", 0) or 0)
    except Exception:
        stars = 0
    fb = {"id": uuid.uuid4().hex[:10], "stars": stars, "name": (d.get("name") or "").strip(),
          "email": (d.get("email") or "").strip(), "reason": (d.get("reason") or "").strip(),
          "ts": _now_iso()}
    lst = kv_get("review_feedback") or []
    lst.insert(0, fb)
    kv_set("review_feedback", lst[:500])
    s = get_settings()
    rv = s.get("review") or {}
    to = (rv.get("feedback_email") or s.get("company_email") or "").strip()
    if to:
        try:
            send_email(to, f"Nieuwe review-feedback ({stars} ster)",
                       f"Een klant heeft een review achtergelaten via de reviewpagina:\n\n"
                       f"Sterren: {stars}\nNaam: {fb['name'] or '-'}\nE-mail: {fb['email'] or '-'}\n\n{fb['reason'] or '(geen toelichting)'}",
                       content_type="plain")
        except Exception:
            pass
    return jsonify({"ok": True})


