# ==================== ACTIEBALK (publiek) ====================
@app.route("/api/site/actiebalk", methods=["GET"])
def api_site_actiebalk():
    """De actiebalk voor de bezoeker. Publiek en bewust kaal: alleen de vier velden
    die op het scherm komen, zodat een fout in dit endpoint nooit een instelling
    lekt die er niets mee te maken heeft."""
    b = (get_settings().get("actiebalk") or {})
    tekst = (b.get("tekst") or "").strip()
    tot = (b.get("tot") or "").strip()
    verlopen = bool(re.match(r"^\d{4}-\d{2}-\d{2}$", tot)) and tot < datetime.now().strftime("%Y-%m-%d")
    aan = bool(b.get("aan")) and bool(tekst) and not verlopen
    data = {"aan": aan}
    if aan:
        weergave = (b.get("weergave") or "balk").strip()
        data.update({"tekst": tekst,
                     "knop_tekst": (b.get("knop_tekst") or "").strip(),
                     "knop_link": (b.get("knop_link") or "").strip(),
                     # Onbekende waarde -> de balk. Een typefout in de database mag
                     # geen pagina opleveren waar niets meer verschijnt.
                     "weergave": weergave if weergave in ("balk", "blok") else "balk"})
    # Kort cachen: de balk mag binnen een paar minuten na het omzetten weg zijn,
    # maar hoeft niet bij elke paginaweergave opnieuw uit de database te komen.
    return jsonify(data), 200, {"Cache-Control": "public, max-age=120"}


# ==================== SITEMAP + ROBOTS (dynamisch) ====================
# De React-SPA had een STATISCHE public/sitemap.xml met alleen de vaste routes;
# die kan per definitie geen CMS-pagina's of blogartikelen bevatten (nieuwe
# content zou nooit geïndexeerd worden). Daarom serveert Flask ze nu dynamisch:
# de vaste React-routes + alles wat in het CMS gepubliceerd is.
# LET OP: zet hier NOOIT weer een statisch bestand op public/ neer — een
# statisch bestand wint van de rewrite en schaduwt deze routes.


# Vaste routes van de React-SPA (src/App.jsx + src/lib/diensten.js).
#
# ALLEEN routes die de site ook echt serveert. DAM Housing heeft geen /diensten- en
# geen /contact-pagina: diensten staan als sectie op de homepagina (#diensten) en
# contact is het formulier onderaan (#contact). Die twee stonden hier wél in en
# gingen zo als 404 de sitemap in. /voorstel blijft eruit: dat is een offerte voor
# één klant, geen indexeerbare pagina.
_SPA_ROUTES = [
    ("/", "1.0", "monthly"),
    ("/projecten", "0.8", "monthly"),
    ("/diensten/pvc-vloeren", "0.9", "monthly"),
    ("/diensten/vloeren-egaliseren", "0.9", "monthly"),
    ("/diensten/trappenrenovatie", "0.9", "monthly"),
    ("/diensten/vloerverwarming", "0.9", "monthly"),
]


# De collectie (192 pvc-vloeren) leeft in de React-bundel, en `src/` zit niet in
# deze function (excludeFiles in vercel.json). De import schrijft daarom dezelfde
# slugs naar api/collectie_slugs.json; alleen die lijst is hier nodig.
_COLLECTIE_CACHE: dict | None = None


def _collectie_slugs() -> tuple[list[str], str]:
    """(slugs, datum van de laatste import). Ontbreekt het bestand, dan geen collectie
    in de sitemap — nooit een fout: een sitemap zonder die pagina's is beter dan geen."""
    global _COLLECTIE_CACHE
    if _COLLECTIE_CACHE is None:
        try:
            with open(ROOT / "api" / "collectie_slugs.json", encoding="utf-8") as fh:
                data = json.load(fh)
            _COLLECTIE_CACHE = {"slugs": [str(x) for x in data.get("slugs") or []],
                                "bijgewerkt": str(data.get("bijgewerkt") or "")}
        except Exception as e:
            print(f"collectie slugs error: {e}")
            _COLLECTIE_CACHE = {"slugs": [], "bijgewerkt": ""}
    return _COLLECTIE_CACHE["slugs"], _COLLECTIE_CACHE["bijgewerkt"]


def _sitemap_urls() -> list[tuple]:
    """(loc, priority, changefreq, lastmod) voor alle indexeerbare URL's."""
    urls = [(CANONICAL_BASE + p, prio, freq, "") for p, prio, freq in _SPA_ROUTES]
    seen = {u[0] for u in urls}

    def add(path: str, prio: str, freq: str, lastmod: str = ""):
        kaal = CANONICAL_BASE + "/" + path.strip("/")
        # Een route die de SPA zelf serveert staat hierboven al ZONDER slash, en dat
        # is ook de canonical van die pagina. Hem hier nog eens mét slash toevoegen
        # zet elke pagina dubbel in de sitemap, in een vorm die niet de canonical is.
        if kaal in seen:
            return
        loc = kaal + "/"
        if loc not in seen:
            seen.add(loc)
            urls.append((loc, prio, freq, lastmod))

    try:
        for pg in _published_sitemap_pages():
            slug = (pg.get("slug") or (pg.get("url") or "").strip("/")).strip("/")
            if slug:
                add(slug, "0.8", "monthly", (pg.get("updated_at") or "")[:10])
    except Exception as e:
        print(f"sitemap pages error: {e}")
    try:
        posts = [p for p in get_posts_index() if p.get("status") == "published"]
        if posts:
            urls.append((CANONICAL_BASE + "/blog", "0.7", "weekly", ""))
        for po in posts:
            if po.get("slug"):
                add("blog/" + po["slug"], "0.7", "monthly", (po.get("date") or "")[:10])
    except Exception as e:
        print(f"sitemap posts error: {e}")
    try:
        slugs, bijgewerkt = _collectie_slugs()
        if slugs:
            # Zonder afsluitende slash, net als de andere SPA-routes: dat is de
            # canonical die de pagina zelf zet. De datum is die van de import —
            # de vloeren veranderen alleen als Belakos een nieuwe feed levert.
            urls.append((CANONICAL_BASE + "/collectie", "0.8", "monthly", bijgewerkt))
            seen.add(CANONICAL_BASE + "/collectie")
            for slug in slugs:
                loc = CANONICAL_BASE + "/collectie/" + slug
                if loc not in seen:
                    seen.add(loc)
                    urls.append((loc, "0.6", "monthly", bijgewerkt))
    except Exception as e:
        print(f"sitemap collectie error: {e}")
    try:
        for pr in get_projects():
            if pr.get("status", "published") == "published" and pr.get("slug") and not (pr.get("url") or "").strip():
                add("projecten/" + pr["slug"], "0.6", "yearly")
    except Exception as e:
        print(f"sitemap projects error: {e}")
    return urls


@app.route("/sitemap.xml", methods=["GET"])
@app.route("/sitemap_index.xml", methods=["GET"])
def serve_sitemap_xml():
    rows = []
    for loc, prio, freq, lastmod in _sitemap_urls():
        lm = f"<lastmod>{_esc(lastmod)}</lastmod>" if re.match(r"^\d{4}-\d{2}-\d{2}$", lastmod or "") else ""
        rows.append(f"<url><loc>{_esc(loc)}</loc>{lm}"
                    f"<changefreq>{freq}</changefreq><priority>{prio}</priority></url>")
    xml = ('<?xml version="1.0" encoding="UTF-8"?>\n'
           '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n  '
           + "\n  ".join(rows) + "\n</urlset>\n")
    return Response(xml, mimetype="application/xml",
                    headers={"Cache-Control": "public, max-age=0, must-revalidate"})


@app.route("/robots.txt", methods=["GET"])
def serve_robots_txt():
    custom = (kv_get("robots_txt") or "").strip()
    if custom:
        return Response(custom + "\n", mimetype="text/plain")
    body = ("User-agent: *\n"
            "Allow: /\n"
            "Disallow: /admin\n"
            "Disallow: /inloggen\n"
            "Disallow: /factuur/\n"
            "Disallow: /offerte/\n"
            "Disallow: /review\n\n"
            f"Sitemap: {CANONICAL_BASE}/sitemap.xml\n")
    return Response(body, mimetype="text/plain",
                    headers={"Cache-Control": "public, max-age=0, must-revalidate"})


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=int(os.environ.get("PORT", 8080)))
